(window.__APPSRC=window.__APPSRC||{})["xmvkq4zed--s2-2025"]="{\"app\":\"xmvkq4zed\",\"id\":\"s2-2025\",\"titre\":\"S2 : 2025 · Sage-femme (Gynéco-Obstétrique, SSR / PF)\",\"session\":\"S2\",\"annee\":2025,\"nq\":779,\"nsuj\":17,\"origines\":[{\"fichier\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sha256\":\"a67be42ff65006fea375e15e646cdb00b3aa235a3ee369ea210e2159f9e46ca5\"}],\"antennes\":[{\"name\":\"ABENGOUROU (S2 : 2025)\",\"slug\":\"abengourou-2\",\"session\":\"S2\",\"annee\":2025,\"existe\":true,\"sujets\":[{\"name\":\"Gynéco-obstétrique\",\"slug\":\"gynecologie-obstetrique\",\"pages\":\"\",\"count\":50,\"session\":\"S2\",\"annee\":2025,\"source\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"questions\":[{\"id\":\"abengourou-2__gynecologie-obstetrique__0\",\"num\":\"1\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"I. Questions à Choix Double (QCD : Q1 à Q20)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Le fibrome utérin serait l'expression myométriale d'une hyperœstrogénie locale.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Vrai\",\"answerLetters\":[\"A\"],\"explanation\":\"Le fibrome (léiomyome) utérin est une tumeur bénigne hormono-dépendante développée aux dépens des fibres musculaires lisses du myomètre sous l'influence d'une hyperœstrogénie relative locale et générale.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abengourou-2__gynecologie-obstetrique__1\",\"num\":\"2\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"I. Questions à Choix Double (QCD : Q1 à Q20)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Les myomes sous-séreux sont le plus souvent non hémorragiques.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Vrai\",\"answerLetters\":[\"A\"],\"explanation\":\"Les myomes sous-séreux se développent vers l'extérieur de l'utérus (cavité péritonéale) et n'altèrent pas l'endomètre ; ils sont donc généralement asymptomatiques sur le plan hémorragique (contrairement aux myomes sous-muqueux et interstitiels qui provoquent des ménorragies).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abengourou-2__gynecologie-obstetrique__2\",\"num\":\"3\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"I. Questions à Choix Double (QCD : Q1 à Q20)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Le port du préservatif est un moyen de prévention de la rubéole.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"La rubéole est une infection virale à transmission aérienne/respiratoire (gouttelettes de Pflügge) et transplacentaire, et non une infection sexuellement transmissible. Sa prévention repose sur la vaccination (vaccin RR/ROR) en dehors de la grossesse.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abengourou-2__gynecologie-obstetrique__3\",\"num\":\"4\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"I. Questions à Choix Double (QCD : Q1 à Q20)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Le traitement préventif intermittent (TPI-SP) peut débuter à partir de la 16 SA même si la gestante ne ressent pas encore les MAF.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Vrai\",\"answerLetters\":[\"A\"],\"explanation\":\"Selon les directives du PNLP en Côte d'Ivoire, la 1re dose de Sulfadoxine-Pyriméthamine (TPI) est administrée à partir de 16 SA (2e trimestre) OU dès l'apparition des mouvements actifs du fœtus (MAF). (NB : Sur la copie du sujet, la lettre 'F' est annotée si le barème exigeait l'apparition des MAF).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abengourou-2__gynecologie-obstetrique__4\",\"num\":\"5\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"I. Questions à Choix Double (QCD : Q1 à Q20)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Une femme enceinte porteuse du trait AS présente une forme asymptomatique de drépanocytose.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Vrai\",\"answerLetters\":[\"A\"],\"explanation\":\"Le sujet hétérozygote AS est un porteur sain (trait drépanocytaire) généralement asymptomatique, contrairement aux syndromes drépanocytaires majeurs (SS, SC, Sβ-thalassémie).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abengourou-2__gynecologie-obstetrique__5\",\"num\":\"6\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"I. Questions à Choix Double (QCD : Q1 à Q20)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"La bêta-thalassémie présente une hémoglobine anormale de forme S.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"La bêta-thalassémie est une anomalie QUANTITATIVE de synthèse des chaînes bêta de la globine (défaut de production d'HbA avec élévation compensatrice d'HbA2 et d'HbF), tandis que l'hémoglobine S est une anomalie QUALITATIVE (de structure) propre à la drépanocytose.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abengourou-2__gynecologie-obstetrique__6\",\"num\":\"7\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"I. Questions à Choix Double (QCD : Q1 à Q20)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"L'hémoglobine S, responsable de la drépanocytose, est caractérisée par une substitution de la valine par l'acide glutamique.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"Attention au piège d'inversion : dans l'hémoglobine S, c'est l'acide glutamique normal (en position 6 de la chaîne bêta de la globine) qui est remplacé par la valine, et non l'inverse !\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abengourou-2__gynecologie-obstetrique__7\",\"num\":\"8\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"I. Questions à Choix Double (QCD : Q1 à Q20)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Les hémoglobinopathies sont transmises sur un mode autosomique dominant.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"Les hémoglobinopathies (drépanocytose, thalassémies) sont des maladies génétiques à transmission autosomique RÉCESSIVE (il faut hériter de deux allèles mutés, un de chaque parent, pour développer la forme majeure).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abengourou-2__gynecologie-obstetrique__8\",\"num\":\"9\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"I. Questions à Choix Double (QCD : Q1 à Q20)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Les anticorps IgM produits lors d'une réponse immunitaire primaire peuvent traverser la barrière placentaire.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"Les IgM sont des pentamères de haut poids moléculaire qui ne traversent JAMAIS la barrière placentaire (c'est pourquoi la présence d'IgM spécifiques dans le sang du cordon ou du nouveau-né signe formellement une infection congénitale). Seules les IgG traversent le placenta.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abengourou-2__gynecologie-obstetrique__9\",\"num\":\"10\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"I. Questions à Choix Double (QCD : Q1 à Q20)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"La pyélonéphrite aiguë est la forme la plus fréquente d'infection urinaire pendant la grossesse.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"La forme la plus fréquente d'infection urinaire gravidique est la bactériurie asymptomatique (5 à 10 % des grossesses) suivie de la cystite aiguë ; la pyélonéphrite aiguë est la forme la plus grave mais la moins fréquente (1 à 2 %).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abengourou-2__gynecologie-obstetrique__10\",\"num\":\"11\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"I. Questions à Choix Double (QCD : Q1 à Q20)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Dans la réanimation du nouveau-né, le massage cardiaque externe est une étape primordiale lorsque le score d'APGAR est de 6.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"Un score d'Apgar à 6 traduit une souffrance néonatale modérée nécessitant une désobstruction, une stimulation tactile et éventuellement une ventilation au masque. Le massage cardiaque externe n'est indiqué que si la fréquence cardiaque reste < 60 bpm malgré 30 secondes de ventilation efficace en pression positive.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abengourou-2__gynecologie-obstetrique__11\",\"num\":\"12\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"I. Questions à Choix Double (QCD : Q1 à Q20)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Dans l'accouchement de siège, lorsque la tête est descendue en partie basse, l'attitude de Mauriceau est préconisée.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"Lorsque la tête dernière est descendue dans l'excavation pelvienne (partie basse) et que le dos tourne en avant, la manœuvre de 1re intention est la manœuvre de Bracht (bascule du fœtus sur le ventre maternel). La manœuvre de Mauriceau est une manœuvre de recours en cas de rétention de tête dernière dans l'excavation.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abengourou-2__gynecologie-obstetrique__12\",\"num\":\"13\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"I. Questions à Choix Double (QCD : Q1 à Q20)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Le fibrome utérin est une masse pelvienne indépendante de l'utérus.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"Le fibrome utérin fait corps avec l'utérus et mobilise le col utérin sans sillon de séparation au toucher vaginal (sauf le fibrome sous-séreux pédiculé qui peut simuler une masse annexielle indépendante).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abengourou-2__gynecologie-obstetrique__13\",\"num\":\"14\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"I. Questions à Choix Double (QCD : Q1 à Q20)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"La présentation de l'épaule est une complication d'une présentation de l'épaule négligée qui n'a pas été vite prise en charge.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"C'est l'inverse : c'est l'épaule négligée qui est la complication redoutable d'une présentation de l'épaule (transverse) en travail avec membranes rompues et utérus rétracté non prise en charge à temps.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abengourou-2__gynecologie-obstetrique__14\",\"num\":\"15\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"I. Questions à Choix Double (QCD : Q1 à Q20)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Une mère de groupe sanguin A positif et le conjoint de groupe B peuvent donner naissance à un enfant de groupe O.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Vrai\",\"answerLetters\":[\"A\"],\"explanation\":\"Si la mère est hétérozygote AO et le père hétérozygote BO, chacun peut transmettre l'allèle récessif O à l'enfant (probabilité de 25 % d'avoir un enfant de groupe O).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abengourou-2__gynecologie-obstetrique__15\",\"num\":\"16\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"I. Questions à Choix Double (QCD : Q1 à Q20)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"L'accrochage des mentons au cours d'un accouchement gémellaire peut survenir si J1 est en présentation céphalique et J2 en présentation de siège.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"L'accrochage des mentons (dystocie gémellaire exceptionnelle) survient uniquement lorsque J1 est en présentation du SIÈGE et J2 en présentation CÉPHALIQUE (la tête dernière de J1 s'accrochant par son menton au menton de la tête première de J2), et non l'inverse.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abengourou-2__gynecologie-obstetrique__16\",\"num\":\"17\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"I. Questions à Choix Double (QCD : Q1 à Q20)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Dans le diabète gestationnel, le dépistage par HGPO peut se faire à la 26ème Semaine d'Aménorrhée.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Vrai\",\"answerLetters\":[\"A\"],\"explanation\":\"Le dépistage du diabète gestationnel par l'épreuve d'Hyperglycémie Provoquée par Voie Orale (HGPO avec 75 g de glucose) se réalise entre 24 et 28 SA (donc parfaitement à 26 SA).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abengourou-2__gynecologie-obstetrique__17\",\"num\":\"18\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"I. Questions à Choix Double (QCD : Q1 à Q20)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"L'infertilité se définit comme l'absence de survenue d'une grossesse après 1 an de rapports sexuels réguliers sous contraception.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"L'infertilité d'un couple se définit par l'absence de grossesse après 12 mois (1 an) de rapports sexuels complets, réguliers et SANS aucune contraception.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abengourou-2__gynecologie-obstetrique__18\",\"num\":\"19\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"I. Questions à Choix Double (QCD : Q1 à Q20)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"L'urètre sert à acheminer les urines de la vessie vers le méat urétral.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Vrai\",\"answerLetters\":[\"A\"],\"explanation\":\"Les uretères conduisent l'urine des reins à la vessie, tandis que l'urètre est le conduit excréteur qui évacue l'urine de la vessie vers l'extérieur par le méat urétral.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abengourou-2__gynecologie-obstetrique__19\",\"num\":\"20\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"I. Questions à Choix Double (QCD : Q1 à Q20)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"La syphilis est une maladie virale sexuellement transmissible.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"La syphilis est une infection sexuellement transmissible d'origine BACTÉRIENNE (causée par le spirochète Treponema pallidum) et non virale.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abengourou-2__gynecologie-obstetrique__20\",\"num\":\"21\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"II. Questions à Choix Multiples (QCM : Q21 à Q40)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Parmi les causes ci-dessous, laquelle est la plus susceptible d'entraîner une menace d'accouchement prématuré (MAP) ?\",\"options\":[{\"letter\":\"A\",\"text\":\"Les infections urinaires\"},{\"letter\":\"B\",\"text\":\"La salpingite\"},{\"letter\":\"C\",\"text\":\"Un travail sédentaire\"},{\"letter\":\"D\",\"text\":\"Pré-éclampsie\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Les infections urinaires\",\"answerLetters\":[\"A\"],\"explanation\":\"Les infections urinaires constituent la cause infectieuse maternelle la plus fréquente de menace d'accouchement prématuré spontanée (libération de prostaglandines stimulant la contractilité utérine). La pré-éclampsie est surtout cause de prématurité induite (extraction médicale).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abengourou-2__gynecologie-obstetrique__21\",\"num\":\"22\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"II. Questions à Choix Multiples (QCM : Q21 à Q40)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Au cours de l'accouchement chez une patiente PTME (VIH+) : trouvez les deux réponses exactes :\",\"options\":[{\"letter\":\"A\",\"text\":\"Éviter de faire une épisiotomie systématique lors de l'accouchement\"},{\"letter\":\"B\",\"text\":\"Rompre la poche des eaux en fin de travail d'accouchement\"},{\"letter\":\"C\",\"text\":\"Traire le cordon\"},{\"letter\":\"D\",\"text\":\"La césarienne est systématique\"},{\"letter\":\"E\",\"text\":\"Faire la section du cordon sans équipement de protection individuelle\"},{\"letter\":\"F\",\"text\":\"Aspirer le nouveau-né systématiquement\"}],\"mode\":\"mcq\",\"multi\":true,\"answer\":\"A et B\",\"answerLetters\":[\"A\",\"B\"],\"explanation\":\"Pour réduire la transmission mère-enfant du VIH à l'accouchement (pratiques obstétricales à moindre risque), il faut proscrire l'épisiotomie systématique (a), respecter les membranes le plus longtemps possible et ne les rompre qu'en toute fin de travail à dilatation complète (b), éviter de traire le cordon, et proscrire l'aspiration nasopharyngée systématique traumatique.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abengourou-2__gynecologie-obstetrique__22\",\"num\":\"23\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"II. Questions à Choix Multiples (QCM : Q21 à Q40)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Quelle sera la conduite à tenir en cas de procidence du cordon 3ème degré non battant avec mort-né frais en présentation de l'épaule ?\",\"options\":[{\"letter\":\"A\",\"text\":\"Recouvrir le cordon avec des compresses sèches\"},{\"letter\":\"B\",\"text\":\"Installer la patiente en position de Trendelenburg\"},{\"letter\":\"C\",\"text\":\"Privilégier la voie basse\"},{\"letter\":\"D\",\"text\":\"Refouler la présentation\"},{\"letter\":\"E\",\"text\":\"Faire une césarienne en urgence\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"E. Faire une césarienne en urgence\",\"answerLetters\":[\"E\"],\"explanation\":\"Bien que le fœtus soit décédé (cordon non battant), il est en PRÉSENTATION DE L'ÉPAULE (présentation transverse absolument dystocique rendant l'accouchement par voie basse impossible et exposant à la rupture utérine). La césarienne de sauvetage maternel en urgence s'impose donc formellement.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abengourou-2__gynecologie-obstetrique__23\",\"num\":\"24\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"II. Questions à Choix Multiples (QCM : Q21 à Q40)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Parmi les propositions suivantes, une ne fait pas partie des risques fœto-toxiques des anti-inflammatoires non stéroïdiens (AINS) : laquelle ?\",\"options\":[{\"letter\":\"A\",\"text\":\"Hydramnios\"},{\"letter\":\"B\",\"text\":\"Insuffisance rénale\"},{\"letter\":\"C\",\"text\":\"Syndrome hémorragique\"},{\"letter\":\"D\",\"text\":\"Fermeture prématurée du canal artériel\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Hydramnios\",\"answerLetters\":[\"A\"],\"explanation\":\"Les AINS sont formellement contre-indiqués aux 2e/3e trimestres car ils provoquent une insuffisance rénale fœtale entraînant un OLIGOAMNIOS (ou anamnios, et non un hydramnios !), une fermeture prématurée du canal artériel in utero et un risque hémorragique.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abengourou-2__gynecologie-obstetrique__24\",\"num\":\"25\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"II. Questions à Choix Multiples (QCM : Q21 à Q40)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"La GATPA impose la réalisation des gestes suivants : cocher la réponse juste.\",\"options\":[{\"letter\":\"A\",\"text\":\"Révision utérine\"},{\"letter\":\"B\",\"text\":\"Traction du cordon combinée à une pression du fond utérin\"},{\"letter\":\"C\",\"text\":\"Injection intramusculaire de 10 UI de Syntocinon\"},{\"letter\":\"D\",\"text\":\"Toutes les propositions sont fausses\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"C. Injection intramusculaire de 10 UI de Syntocinon\",\"answerLetters\":[\"C\"],\"explanation\":\"Les 3 étapes de la GATPA sont : 1) Administration de 10 UI d'ocytocine (Syntocinon) en IM dans la minute suivant la naissance après avoir vérifié l'absence d'un second jumeau (c) ; 2) Traction contrôlée sur le cordon associée à une CONTRE-PRESSION sus-pubienne (et non une pression sur le fond utérin qui provoquerait une inversion utérine !) ; 3) Massage du fond utérin après délivrance.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abengourou-2__gynecologie-obstetrique__25\",\"num\":\"26\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"II. Questions à Choix Multiples (QCM : Q21 à Q40)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Le syndrome Transfuseur-Transfusé (STT) se retrouve dans deux situations : lesquelles ?\",\"options\":[{\"letter\":\"A\",\"text\":\"Chez des jumeaux de sexes différents\"},{\"letter\":\"B\",\"text\":\"Dans les grossesses gémellaires monochoriales monoamniotiques\"},{\"letter\":\"C\",\"text\":\"Dans toutes les grossesses gémellaires uniovulaires\"},{\"letter\":\"D\",\"text\":\"Dans toutes les grossesses gémellaires biovulaires\"},{\"letter\":\"E\",\"text\":\"Dans la grossesse gémellaire bichoriale biamniotique\"},{\"letter\":\"F\",\"text\":\"Dans les grossesses gémellaires monochoriales biamniotiques\"}],\"mode\":\"mcq\",\"multi\":true,\"answer\":\"B et F\",\"answerLetters\":[\"B\",\"F\"],\"explanation\":\"Le syndrome transfuseur-transfusé résulte d'anastomoses vasculaires artério-veineuses déséquilibrées au sein d'un placenta unique : il ne survient donc que dans les grossesses gémellaires MONOCHORIALES, qu'elles soient monochoriales biamniotiques (f, les plus fréquentes) ou monochoriales monoamniotiques (b).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abengourou-2__gynecologie-obstetrique__26\",\"num\":\"27\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"II. Questions à Choix Multiples (QCM : Q21 à Q40)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"L'examen au spéculum d'une patiente retrouve un col normal chez une patiente de 50 ans. Quelle attitude doit-on adopter ?\",\"options\":[{\"letter\":\"A\",\"text\":\"L'ablation de l'utérus\"},{\"letter\":\"B\",\"text\":\"La biopsie du col utérin\"},{\"letter\":\"C\",\"text\":\"Le frottis cervical\"},{\"letter\":\"D\",\"text\":\"L'ablation du col\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"C. Le frottis cervical\",\"answerLetters\":[\"C\"],\"explanation\":\"Devant un col macroscopiquement sain chez une femme de 50 ans, on réalise un dépistage systématique des lésions précancéreuses par frottis cervico-utérin (FCU) ou inspection visuelle à l'acide acétique (IVA) / test HPV.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abengourou-2__gynecologie-obstetrique__27\",\"num\":\"28\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"II. Questions à Choix Multiples (QCM : Q21 à Q40)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Quel est le germe le plus souvent rencontré dans la flore vaginale normale ?\",\"options\":[{\"letter\":\"A\",\"text\":\"Les lactobacilles\"},{\"letter\":\"B\",\"text\":\"Le Gardnerella vaginalis\"},{\"letter\":\"C\",\"text\":\"Le Candida albicans\"},{\"letter\":\"D\",\"text\":\"L'Escherichia coli\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Les lactobacilles\",\"answerLetters\":[\"A\"],\"explanation\":\"La flore vaginale saprophyte normale est dominée à 95 % par les lactobacilles (bacilles de Döderlein), qui produisent de l'acide lactique et du peroxyde d'hydrogène maintenant un pH vaginal acide protecteur (3,8 à 4,5).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abengourou-2__gynecologie-obstetrique__28\",\"num\":\"29\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"II. Questions à Choix Multiples (QCM : Q21 à Q40)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Parmi les réponses suivantes, une ne fait pas partie des éléments du score de Bishop : laquelle ?\",\"options\":[{\"letter\":\"A\",\"text\":\"La position du col\"},{\"letter\":\"B\",\"text\":\"La longueur du col\"},{\"letter\":\"C\",\"text\":\"L'aspect du liquide amniotique\"},{\"letter\":\"D\",\"text\":\"Le niveau de la présentation fœtale\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"C. L'aspect du liquide amniotique\",\"answerLetters\":[\"C\"],\"explanation\":\"Le score de Bishop évalue la maturité cervicale sur 5 critères (dilatation, longueur/effacement, consistance, position du col et hauteur de la présentation fœtale). L'aspect du liquide amniotique n'en fait pas partie.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abengourou-2__gynecologie-obstetrique__29\",\"num\":\"30\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"II. Questions à Choix Multiples (QCM : Q21 à Q40)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Un geste ne fait pas partie des soins essentiels au nouveau-né. Lequel ?\",\"options\":[{\"letter\":\"A\",\"text\":\"La désinfection oculaire\"},{\"letter\":\"B\",\"text\":\"L'injection de dexaméthasone\"},{\"letter\":\"C\",\"text\":\"Les soins du cordon\"},{\"letter\":\"D\",\"text\":\"L'injection de vitamine K1\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. L'injection de dexaméthasone\",\"answerLetters\":[\"B\"],\"explanation\":\"La dexaméthasone est un corticoïde administré à la MÈRE en anténatal pour la maturation pulmonaire fœtale en cas de MAP entre 24 et 34 SA ; elle ne fait pas partie des soins essentiels au nouveau-né à la naissance.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abengourou-2__gynecologie-obstetrique__30\",\"num\":\"31\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"II. Questions à Choix Multiples (QCM : Q21 à Q40)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Parmi les signes suivants, un ne fait pas partie des complications mammaires des suites de couches :\",\"options\":[{\"letter\":\"A\",\"text\":\"L'abcès du sein\"},{\"letter\":\"B\",\"text\":\"L'adénofibrome du sein\"},{\"letter\":\"C\",\"text\":\"La galactophorite\"},{\"letter\":\"D\",\"text\":\"Les crevasses\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. L'adénofibrome du sein\",\"answerLetters\":[\"B\"],\"explanation\":\"L'adénofibrome (fibroadénome) est une tumeur bénigne conjonctivo-épithéliale du sein de la femme jeune hors allaitement, et non une complication septique ou mécanique de l'allaitement.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abengourou-2__gynecologie-obstetrique__31\",\"num\":\"32\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"II. Questions à Choix Multiples (QCM : Q21 à Q40)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Laquelle de ces propositions est exacte concernant le placenta ?\",\"options\":[{\"letter\":\"A\",\"text\":\"Le cordon ombilical s'insère sur la face fœtale\"},{\"letter\":\"B\",\"text\":\"Il pèse en moyenne 2/6 du poids du fœtus à terme\"},{\"letter\":\"C\",\"text\":\"La face fœtale est charnue et contient des cotylédons\"},{\"letter\":\"D\",\"text\":\"Il permet de maintenir la grossesse dès la fécondation de l'œuf\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Le cordon ombilical s'insère sur la face fœtale\",\"answerLetters\":[\"A\"],\"explanation\":\"Le cordon ombilical s'insère sur la face fœtale (lisse, tapissée par l'amnios) du placenta (a). À terme, le placenta pèse 1/6 du poids fœtal (~500 g, et non 2/6) ; c'est la face maternelle qui est charnue et divisée en cotylédons ; et c'est le corps jaune gravidique qui maintient la grossesse au 1er trimestre avant le relais placentaire.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abengourou-2__gynecologie-obstetrique__32\",\"num\":\"33\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"II. Questions à Choix Multiples (QCM : Q21 à Q40)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Parmi les affections suivantes, une peut être responsable d'embryopathies : laquelle ?\",\"options\":[{\"letter\":\"A\",\"text\":\"La toxoplasmose\"},{\"letter\":\"B\",\"text\":\"La rubéole\"},{\"letter\":\"C\",\"text\":\"La syphilis\"},{\"letter\":\"D\",\"text\":\"Hépatite virale\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. La rubéole\",\"answerLetters\":[\"B\"],\"explanation\":\"Contractée au 1er trimestre (période d'organogenèse), la rubéole provoque une embryopathie malformative grave (syndrome de Gregg : cardiopathie, cataracte, surdité, microcéphalie). Le tréponème de la syphilis ne traverse le placenta qu'à partir de 16-18 SA (donnant une fœtopathie et non une embryopathie), et la toxoplasmose donne essentiellement une fœtopathie.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abengourou-2__gynecologie-obstetrique__33\",\"num\":\"34\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"II. Questions à Choix Multiples (QCM : Q21 à Q40)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Devant une menace d'accouchement prématuré à 34 SA, quelle est, dans la liste ci-dessous, la première prescription à faire ?\",\"options\":[{\"letter\":\"A\",\"text\":\"Maturation pulmonaire\"},{\"letter\":\"B\",\"text\":\"Hospitalisation\"},{\"letter\":\"C\",\"text\":\"Césarienne en urgence\"},{\"letter\":\"D\",\"text\":\"Injection de progestérone\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Hospitalisation\",\"answerLetters\":[\"B\"],\"explanation\":\"Devant toute MAP, la première mesure immédiate est la mise au repos strict par l'hospitalisation de la gestante (b), qui permet ensuite d'instaurer le bilan étiologique, la tocolyse et la corticothérapie de maturation pulmonaire.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abengourou-2__gynecologie-obstetrique__34\",\"num\":\"35\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"II. Questions à Choix Multiples (QCM : Q21 à Q40)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"L'une des propositions suivantes peut faire suspecter une tumeur ovarienne : laquelle ?\",\"options\":[{\"letter\":\"A\",\"text\":\"Un fibrome sous-séreux pédiculé\"},{\"letter\":\"B\",\"text\":\"Un fibrome sous-muqueux\"},{\"letter\":\"C\",\"text\":\"Un fibrome intracavitaire\"},{\"letter\":\"D\",\"text\":\"Un fibrome interstitiel\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Un fibrome sous-séreux pédiculé\",\"answerLetters\":[\"A\"],\"explanation\":\"Le fibrome sous-séreux pédiculé est relié à l'utérus par un fin pédicule et présente un sillon de séparation avec le corps utérin au toucher vaginal, posant le diagnostic différentiel classique avec un kyste ou une tumeur de l'ovaire.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abengourou-2__gynecologie-obstetrique__35\",\"num\":\"36\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"II. Questions à Choix Multiples (QCM : Q21 à Q40)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Deux éléments font partie de la cystite isolée. Lesquels ?\",\"options\":[{\"letter\":\"A\",\"text\":\"Hospitalisation\"},{\"letter\":\"B\",\"text\":\"Traitement par voie orale\"},{\"letter\":\"C\",\"text\":\"Contrôle par l'ECBU\"},{\"letter\":\"D\",\"text\":\"Elle est le plus souvent asymptomatique\"},{\"letter\":\"E\",\"text\":\"C'est l'infection urinaire la plus caractéristique\"},{\"letter\":\"F\",\"text\":\"C'est une infection urinaire haute\"}],\"mode\":\"mcq\",\"multi\":true,\"answer\":\"B et C\",\"answerLetters\":[\"B\",\"C\"],\"explanation\":\"La cystite aiguë gravidique est une infection urinaire basse symptomatique (pollakiurie, brûlures mictionnelles, sans fièvre ni douleur lombaire) qui se traite en ambulatoire par antibiothérapie orale (b) avec un ECBU de contrôle (c) 8 à 10 jours après la fin du traitement puis mensuellement.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abengourou-2__gynecologie-obstetrique__36\",\"num\":\"37\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"II. Questions à Choix Multiples (QCM : Q21 à Q40)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"La Sulfadoxine-Pyriméthamine ne doit pas être prise par lequel des groupes de femmes enceintes ?\",\"options\":[{\"letter\":\"A\",\"text\":\"Prennent de l'acide folique\"},{\"letter\":\"B\",\"text\":\"Prennent le cotrimoxazole\"},{\"letter\":\"C\",\"text\":\"Dorment sous une moustiquaire imprégnée\"},{\"letter\":\"D\",\"text\":\"Infectées par le COVID-19\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Prennent le cotrimoxazole\",\"answerLetters\":[\"B\"],\"explanation\":\"La Sulfadoxine-Pyriméthamine (SP) est formellement contre-indiquée chez les femmes enceintes séropositives au VIH recevant déjà une prophylaxie quotidienne par le Cotrimoxazole (Bactrim), en raison de la redondance de mécanisme antifolate et du risque accru de toxicité cutanée sévère (syndrome de Lyell / Stevens-Johnson) et hématologique.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abengourou-2__gynecologie-obstetrique__37\",\"num\":\"38\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"II. Questions à Choix Multiples (QCM : Q21 à Q40)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Quel facteur favorise la falciformation des hématies ?\",\"options\":[{\"letter\":\"A\",\"text\":\"Hyperthermie (et déshydratation)\"},{\"letter\":\"B\",\"text\":\"Hyperglycémie\"},{\"letter\":\"C\",\"text\":\"Hypoxie\"},{\"letter\":\"D\",\"text\":\"Hypercalcémie\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"C. Hypoxie\",\"answerLetters\":[\"C\"],\"explanation\":\"L'hémoglobine S polymérise à l'état désoxygéné : l'hypoxie (c) est le facteur physico-chimique primaire déclenchant la falciformation des hématies, favorisée secondairement par l'acidose, la déshydratation et la fièvre.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abengourou-2__gynecologie-obstetrique__38\",\"num\":\"39\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"II. Questions à Choix Multiples (QCM : Q21 à Q40)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Quel est le traitement de première intention pour une infection syphilitique chez une femme enceinte ?\",\"options\":[{\"letter\":\"A\",\"text\":\"Spiramycine\"},{\"letter\":\"B\",\"text\":\"Pénicilline G (Benzathine-pénicilline)\"},{\"letter\":\"C\",\"text\":\"Antiviraux\"},{\"letter\":\"D\",\"text\":\"Antifongiques\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Pénicilline G (Benzathine-pénicilline)\",\"answerLetters\":[\"B\"],\"explanation\":\"La Pénicilline G retard (Benzathine-benzylpénicilline / Extencilline 2,4 millions d'UI en IM) est le traitement de référence de la syphilis gravidique car elle traverse le placenta et traite simultanément la mère et le fœtus.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abengourou-2__gynecologie-obstetrique__39\",\"num\":\"40\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"II. Questions à Choix Multiples (QCM : Q21 à Q40)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Durant le cycle menstruel : Cocher la bonne réponse.\",\"options\":[{\"letter\":\"A\",\"text\":\"La durée de la phase lutéale est constante\"},{\"letter\":\"B\",\"text\":\"L'ovulation est précédée d'un pic de progestérone\"},{\"letter\":\"C\",\"text\":\"La phase folliculaire dure toujours 14 jours\"},{\"letter\":\"D\",\"text\":\"Pour un cycle de 32 jours l'ovulation aura lieu le 16ème jour\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. La durée de la phase lutéale est constante\",\"answerLetters\":[\"A\"],\"explanation\":\"La phase lutéale (post-ovulatoire) a une durée fixe et constante de 14 jours (± 1 jour), liée à la durée de vie programmée du corps jaune. L'ovulation est précédée d'un pic de LH (et d'œstradiol), la phase folliculaire est variable, et pour un cycle de 32 jours l'ovulation a lieu au jour 32 − 14 = 18e jour.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abengourou-2__gynecologie-obstetrique__40\",\"num\":\"41\",\"type\":\"CAS_CLINIQUE\",\"typeLabel\":\"Étude de cas / Cas clinique\",\"partieTitle\":\"II. Questions à Choix Multiples (QCM : Q21 à Q40)\",\"caseTitle\":\"Cas clinique — Mme Y (Q41 à Q47)\",\"caseData\":null,\"text\":\"Quel est le diagnostic le plus probable ?\",\"options\":[{\"letter\":\"A\",\"text\":\"Cystite simple\"},{\"letter\":\"B\",\"text\":\"Bactériurie asymptomatique\"},{\"letter\":\"C\",\"text\":\"Pyélonéphrite aiguë\"},{\"letter\":\"D\",\"text\":\"Infection vaginale\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"C. Pyélonéphrite aiguë\",\"answerLetters\":[\"C\"],\"explanation\":\"L'association d'une fièvre élevée à 39°C avec frissons, de signes fonctionnels urinaires (pollakiurie, brûlures mictionnelles), d'une douleur lombaire droite provoquée (point costo-lombaire droit positif) et d'un ECBU positif signe une pyélonéphrite aiguë gravidique droite.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abengourou-2__gynecologie-obstetrique__41\",\"num\":\"42\",\"type\":\"CAS_CLINIQUE\",\"typeLabel\":\"Étude de cas / Cas clinique\",\"partieTitle\":\"II. Questions à Choix Multiples (QCM : Q21 à Q40)\",\"caseTitle\":\"Cas clinique — Mme Y (Q41 à Q47)\",\"caseData\":null,\"text\":\"Quel examen doit-on réaliser pour confirmer le diagnostic ?\",\"options\":[{\"letter\":\"A\",\"text\":\"NFS\"},{\"letter\":\"B\",\"text\":\"Goutte Épaisse\"},{\"letter\":\"C\",\"text\":\"ECBU\"},{\"letter\":\"D\",\"text\":\"CRP\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"C. ECBU\",\"answerLetters\":[\"C\"],\"explanation\":\"L'Examen Cytobactériologique des Urines (ECBU) avec antibiogramme est l'examen de certitude qui confirme l'infection urinaire devant une leucocyturie ≥ 10⁴/ml et une bactériurie significative ≥ 10⁵ UFC/ml.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abengourou-2__gynecologie-obstetrique__42\",\"num\":\"43\",\"type\":\"CAS_CLINIQUE\",\"typeLabel\":\"Étude de cas / Cas clinique\",\"partieTitle\":\"II. Questions à Choix Multiples (QCM : Q21 à Q40)\",\"caseTitle\":\"Cas clinique — Mme Y (Q41 à Q47)\",\"caseData\":null,\"text\":\"Quel est le germe auquel vous vous attendiez le plus ?\",\"options\":[{\"letter\":\"A\",\"text\":\"Streptocoque A\"},{\"letter\":\"B\",\"text\":\"Escherichia coli\"},{\"letter\":\"C\",\"text\":\"Pseudomonas\"},{\"letter\":\"D\",\"text\":\"Candida albicans\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Escherichia coli\",\"answerLetters\":[\"B\"],\"explanation\":\"Le colibacille (Escherichia coli), entérobactérie d'origine digestive, est responsable de 80 à 90 % des infections urinaires et pyélonéphrites aiguës de la femme enceinte.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abengourou-2__gynecologie-obstetrique__43\",\"num\":\"44\",\"type\":\"CAS_CLINIQUE\",\"typeLabel\":\"Étude de cas / Cas clinique\",\"partieTitle\":\"II. Questions à Choix Multiples (QCM : Q21 à Q40)\",\"caseTitle\":\"Cas clinique — Mme Y (Q41 à Q47)\",\"caseData\":null,\"text\":\"Quelle est votre conduite à tenir immédiate ?\",\"options\":[{\"letter\":\"A\",\"text\":\"Traitement ambulatoire\"},{\"letter\":\"B\",\"text\":\"Hospitalisation\"},{\"letter\":\"C\",\"text\":\"Surveillance à domicile\"},{\"letter\":\"D\",\"text\":\"Attendre le résultat de l'examen\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Hospitalisation\",\"answerLetters\":[\"B\"],\"explanation\":\"Toute pyélonéphrite aiguë sur grossesse est une urgence obstétricale qui impose une hospitalisation immédiate pour bilan, réhydratation et antibiothérapie parentérale probabiliste sans attendre les résultats de l'antibiogramme.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abengourou-2__gynecologie-obstetrique__44\",\"num\":\"45\",\"type\":\"CAS_CLINIQUE\",\"typeLabel\":\"Étude de cas / Cas clinique\",\"partieTitle\":\"II. Questions à Choix Multiples (QCM : Q21 à Q40)\",\"caseTitle\":\"Cas clinique — Mme Y (Q41 à Q47)\",\"caseData\":null,\"text\":\"Quel antibiotique est indiqué en première ligne ?\",\"options\":[{\"letter\":\"A\",\"text\":\"Ciprofloxacine\"},{\"letter\":\"B\",\"text\":\"Céphalosporine (C3G injectable)\"},{\"letter\":\"C\",\"text\":\"Pénicilline G\"},{\"letter\":\"D\",\"text\":\"Métronidazole\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Céphalosporine (C3G injectable)\",\"answerLetters\":[\"B\"],\"explanation\":\"Les céphalosporines de 3e génération par voie parentérale (ex. Ceftriaxone 1 à 2 g/j ou Céfotaxime) sont le traitement de première intention de la pyélonéphrite gravidique (les fluoroquinolones comme la ciprofloxacine étant contre-indiquées pendant la grossesse).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abengourou-2__gynecologie-obstetrique__45\",\"num\":\"46\",\"type\":\"CAS_CLINIQUE\",\"typeLabel\":\"Étude de cas / Cas clinique\",\"partieTitle\":\"II. Questions à Choix Multiples (QCM : Q21 à Q40)\",\"caseTitle\":\"Cas clinique — Mme Y (Q41 à Q47)\",\"caseData\":null,\"text\":\"Quelle est la durée totale recommandée du traitement ?\",\"options\":[{\"letter\":\"A\",\"text\":\"3 jours\"},{\"letter\":\"B\",\"text\":\"7 jours\"},{\"letter\":\"C\",\"text\":\"10 jours\"},{\"letter\":\"D\",\"text\":\"21 jours (ou 14 à 21 jours)\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"D. 21 jours (ou 14 à 21 jours)\",\"answerLetters\":[\"D\"],\"explanation\":\"Le traitement antibiotique d'une pyélonéphrite aiguë gravidique est débuté par voie parentérale jusqu'à 48 heures d'apyrexie, puis relayé par voie orale selon l'antibiogramme pour une durée totale de 14 à 21 jours (21 jours, réponse d).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abengourou-2__gynecologie-obstetrique__46\",\"num\":\"47\",\"type\":\"CAS_CLINIQUE\",\"typeLabel\":\"Étude de cas / Cas clinique\",\"partieTitle\":\"II. Questions à Choix Multiples (QCM : Q21 à Q40)\",\"caseTitle\":\"Cas clinique — Mme Y (Q41 à Q47)\",\"caseData\":null,\"text\":\"Quelle est la complication obstétricale la plus redoutée dans ce contexte ?\",\"options\":[{\"letter\":\"A\",\"text\":\"Malformations\"},{\"letter\":\"B\",\"text\":\"Hydramnios\"},{\"letter\":\"C\",\"text\":\"Prématurité (MAP / accouchement prématuré)\"},{\"letter\":\"D\",\"text\":\"Pré-éclampsie\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"C. Prématurité (MAP / accouchement prématuré)\",\"answerLetters\":[\"C\"],\"explanation\":\"La fièvre élevée (39°C) et les endotoxines bactériennes déclenchent des contractions utérines exposant au risque majeur de menace d'accouchement prématuré (MAP) et de prématurité (ainsi que de chorioamniotite et d'infection néonatale).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abengourou-2__gynecologie-obstetrique__47\",\"num\":\"48\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"III. Questions complémentaires d'oncologie et PTME (Q48 à Q50)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Concernant le cancer de l'endomètre : une assertion est fausse : laquelle ?\",\"options\":[{\"letter\":\"A\",\"text\":\"Il est un cancer non sexuellement transmissible\"},{\"letter\":\"B\",\"text\":\"Il est un cancer de la femme ménopausée\"},{\"letter\":\"C\",\"text\":\"Le signe principal se caractérise par des métrorragies de contact\"},{\"letter\":\"D\",\"text\":\"La biopsie de l'endomètre est indispensable pour son diagnostic\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"C. Le signe principal se caractérise par des métrorragies de contact\",\"answerLetters\":[\"C\"],\"explanation\":\"Les métrorragies provoquées (de contact, post-coïtales) sont le signe d'appel classique du cancer du COL de l'utérus. Le cancer de l'endomètre se manifeste quant à lui par des métrorragies SPONTANÉES post-ménopausiques.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abengourou-2__gynecologie-obstetrique__48\",\"num\":\"49\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"III. Questions complémentaires d'oncologie et PTME (Q48 à Q50)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Concernant le cancer du col : une assertion est exacte : laquelle ?\",\"options\":[{\"letter\":\"A\",\"text\":\"Il est un cancer viro-induit sexuellement transmissible\"},{\"letter\":\"B\",\"text\":\"Sa prévention ne peut se faire que par la vaccination\"},{\"letter\":\"C\",\"text\":\"Il est le premier cancer de la femme en Côte d'Ivoire\"},{\"letter\":\"D\",\"text\":\"Son histoire naturelle est courte\"},{\"letter\":\"E\",\"text\":\"Son traitement consiste à une ablation de l'utérus (hystérectomie)\"},{\"letter\":\"F\",\"text\":\"La multiparité n'est pas un facteur de risque\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Il est un cancer viro-induit sexuellement transmissible\",\"answerLetters\":[\"A\"],\"explanation\":\"Le cancer du col de l'utérus est un cancer viro-induit par l'infection persistante à Papillomavirus Humain oncogène (HPV 16 et 18 principalement), transmis par voie sexuelle (a). En Côte d'Ivoire, le 1er cancer féminin en fréquence est désormais le cancer du sein devant le cancer du col, son histoire naturelle est longue (10 à 15 ans), et sa prévention repose à la fois sur la vaccination et le dépistage.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abengourou-2__gynecologie-obstetrique__49\",\"num\":\"50\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"III. Questions complémentaires d'oncologie et PTME (Q48 à Q50)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Dans l'eTME, le risque de transmission du VIH chez le nouveau-né est le moins important dans deux situations : lesquelles ?\",\"options\":[{\"letter\":\"A\",\"text\":\"Charge virale détectable\"},{\"letter\":\"B\",\"text\":\"Au cours de l'accouchement\"},{\"letter\":\"C\",\"text\":\"Un compte de CD4 élevé\"},{\"letter\":\"D\",\"text\":\"Au cours de l'allaitement\"},{\"letter\":\"E\",\"text\":\"Rupture prématurée des membranes au cours de l'accouchement\"},{\"letter\":\"F\",\"text\":\"Début du traitement ARV au premier trimestre de grossesse\"}],\"mode\":\"mcq\",\"multi\":true,\"answer\":\"C et F\",\"answerLetters\":[\"C\",\"F\"],\"explanation\":\"Le risque de transmission mère-enfant du VIH est minimal lorsque l'immunité maternelle est préservée avec un taux de CD4 élevé et une charge virale indétectable (c), et lorsque la trithérapie antirétrovirale (ARV) est débutée précocement dès le 1er trimestre de la grossesse (f). +-----------------------------------------------------------------------+\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null}]},{\"name\":\"SSR / PF\",\"slug\":\"ssr-pf\",\"pages\":\"\",\"count\":50,\"session\":\"S2\",\"annee\":2025,\"source\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"questions\":[{\"id\":\"abengourou-2__ssr-pf__0\",\"num\":\"1\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":null,\"caseTitle\":\"Étude de cas N°1 — Amina et David (Q1 à Q27)\",\"caseData\":null,\"text\":\"La demande principale d'Amina et David est d'empêcher définitivement la survenue d'une grossesse.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"Le couple souhaite différer la grossesse pendant les 3 années d'études d'Amina à l'INFAS puis fonder une famille après : il s'agit donc d'un besoin d'espacement/report temporaire des naissances (méthode réversible) et non d'une limitation définitive.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abengourou-2__ssr-pf__1\",\"num\":\"2\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":null,\"caseTitle\":\"Étude de cas N°1 — Amina et David (Q1 à Q27)\",\"caseData\":null,\"text\":\"Amina est intéressée par la méthode de la température basale du corps (TBC). Cette méthode agit en empêchant les spermatozoïdes d'atteindre l'ovule.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Vrai\",\"answerLetters\":[\"A\"],\"explanation\":\"En observant l'ascension thermique post-ovulatoire (due à la progestérone), la méthode de la TBC identifie la fenêtre de fertilité durant laquelle le couple pratique l'abstinence périodique, évitant ainsi la rencontre des gamètes (NB : sur la feuille scannée, B est coché car la TBC en elle-même est un indicateur d'ovulation et c'est l'abstinence ou le préservatif qui empêche les spermatozoïdes d'atteindre l'ovule).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abengourou-2__ssr-pf__2\",\"num\":\"3\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":null,\"caseTitle\":\"Étude de cas N°1 — Amina et David (Q1 à Q27)\",\"caseData\":null,\"text\":\"La TBC repose sur l'abstinence périodique pendant la période de fertilité de la femme, évitant ainsi que les spermatozoïdes ne soient déposés au niveau du col de l'utérus au bon moment.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Vrai\",\"answerLetters\":[\"A\"],\"explanation\":\"Toutes les méthodes d'auto-observation (TBC, méthode de la glaire cervicale de Billings, méthode symptothermique, collier du cycle) reposent sur l'abstinence sexuelle (ou le port de préservatif) pendant la période féconde du cycle.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abengourou-2__ssr-pf__3\",\"num\":\"4\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":null,\"caseTitle\":\"Étude de cas N°1 — Amina et David (Q1 à Q27)\",\"caseData\":null,\"text\":\"Si Amina était une femme allaitante, il serait pertinent pour elle d'utiliser la méthode MAMA (pour sa formation de 3 ans).\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"La MAMA n'est efficace que pendant les 6 premiers mois post-partum (en allaitement exclusif et aménorrhée). Pour couvrir une formation de 3 ans en école, elle est insuffisante sur la durée ou difficilement compatible avec l'éloignement des cours, mais reste utilisable durant les 6 premiers mois si les 3 conditions sont réunies.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abengourou-2__ssr-pf__4\",\"num\":\"5\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":null,\"caseTitle\":\"Étude de cas N°1 — Amina et David (Q1 à Q27)\",\"caseData\":null,\"text\":\"Certaines méthodes contraceptives ont une efficacité à 100% comme le pense David.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"En dehors de l'abstinence totale et absolue, aucune méthode contraceptive (même les méthodes de longue durée ou chirurgicales) n'offre une efficacité théorique et pratique de 100,0 % absolu (l'implant et le DIU dépassent 99 % d'efficacité, soit un indice de Pearl < 0,1 à 0,5 %).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abengourou-2__ssr-pf__5\",\"num\":\"6\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":null,\"caseTitle\":\"Étude de cas N°1 — Amina et David (Q1 à Q27)\",\"caseData\":null,\"text\":\"À la fin des trois ans, si le couple souhaite avoir un enfant, la qualité essentielle de la méthode qu'ils devront considérer est la réversibilité.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Vrai\",\"answerLetters\":[\"A\"],\"explanation\":\"Puisque le couple désire concevoir à l'issue des 3 ans de formation, la méthode choisie doit impérativement être réversible (retour rapide à la fécondité à l'arrêt).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abengourou-2__ssr-pf__6\",\"num\":\"7\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":null,\"caseTitle\":\"Étude de cas N°1 — Amina et David (Q1 à Q27)\",\"caseData\":null,\"text\":\"Le couple opte finalement pour une méthode hormonale comme la pilule (COP), cette méthode agit principalement en bloquant l'ovulation. Elle rend la glaire cervicale imperméable aux spermatozoïdes et l'endomètre non réceptif à l'implantation de l'œuf.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Vrai\",\"answerLetters\":[\"A\"],\"explanation\":\"Les contraceptifs oraux agissent par un triple verrou : blocage central de l'ovulation (systématique pour les COC et le désogestrel), épaississement de la glaire cervicale la rendant hostile au passage des spermatozoïdes, et atrophie de l'endomètre le rendant impropre à la nidation.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abengourou-2__ssr-pf__7\",\"num\":\"8\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":null,\"caseTitle\":\"Étude de cas N°1 — Amina et David (Q1 à Q27)\",\"caseData\":null,\"text\":\"Le système Max-Min est un système qui veille à ce que les quantités en magasin se situent dans une fourchette préétablie. La borne supérieure de cette fourchette est la quantité minimale et la borne inférieure est la quantité maximum.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"C'est l'inverse : dans le système de contrôle des stocks Maximum-Minimum, la borne SUPÉRIEURE est le niveau de stock MAXIMUM et la borne INFÉRIEURE est le niveau de stock MINIMUM.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abengourou-2__ssr-pf__8\",\"num\":\"9\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":null,\"caseTitle\":\"Étude de cas N°1 — Amina et David (Q1 à Q27)\",\"caseData\":null,\"text\":\"Le point de commande d'urgence est le niveau de stock auquel on doit passer immédiatement une commande pour éviter un surstock de produit.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"Le point de commande d'urgence (PCU) est le seuil critique bas auquel on doit passer immédiatement une commande d'urgence pour éviter une RUPTURE DE STOCK (et non un surstock !).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abengourou-2__ssr-pf__9\",\"num\":\"10\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":null,\"caseTitle\":\"Étude de cas N°1 — Amina et David (Q1 à Q27)\",\"caseData\":null,\"text\":\"La supervision est l'ensemble des mesures visant à s'assurer de ce que le personnel accomplit efficacement et de mieux en mal ses fonctions.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"Piège de formulation : la supervision vise à ce que le personnel accomplisse ses fonctions efficacement et de MIEUX EN MIEUX (et non 'de mieux en mal' !).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abengourou-2__ssr-pf__10\",\"num\":\"11\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":null,\"caseTitle\":\"Étude de cas N°1 — Amina et David (Q1 à Q27)\",\"caseData\":null,\"text\":\"Le suivi des activités est l'ensemble des mesures visant à s'assurer que les activités prévues sont réalisées et bien réalisées.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Vrai\",\"answerLetters\":[\"A\"],\"explanation\":\"Le suivi (monitoring continu) est le processus systématique qui permet de vérifier que les activités planifiées se déroulent conformément au programme prévu.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abengourou-2__ssr-pf__11\",\"num\":\"12\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":null,\"caseTitle\":\"Étude de cas N°1 — Amina et David (Q1 à Q27)\",\"caseData\":null,\"text\":\"Le droit se définit comme étant l'ensemble des avantages reconnus à un individu pour lui permettre de bien vivre.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"Le droit objectif est l'ensemble des règles juridiques obligatoires régissant la vie en société et sanctionnées par la puissance publique, tandis que les droits subjectifs sont des prérogatives reconnues par la loi (et non de simples 'avantages pour bien vivre').\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abengourou-2__ssr-pf__12\",\"num\":\"13\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":null,\"caseTitle\":\"Étude de cas N°1 — Amina et David (Q1 à Q27)\",\"caseData\":null,\"text\":\"L'équité est essentielle car elle reconnaît que hommes et femmes ont des besoins différents et nécessitent des approches adaptées pour atteindre l'égalité réelle.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Vrai\",\"answerLetters\":[\"A\"],\"explanation\":\"En matière de genre et santé, l'équité de genre consiste en un traitement juste tenant compte des besoins spécifiques et des disparités entre les femmes et les hommes afin d'aboutir à l'égalité réelle des droits et des chances.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abengourou-2__ssr-pf__13\",\"num\":\"14\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":null,\"caseTitle\":\"Étude de cas N°1 — Amina et David (Q1 à Q27)\",\"caseData\":null,\"text\":\"L'accès et le contrôle des ressources est crucial pour l'autonomisation économique des femmes.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Vrai\",\"answerLetters\":[\"A\"],\"explanation\":\"L'accès aux ressources (terre, crédit, éducation, revenus) et leur contrôle effectif par les femmes constituent le levier fondamental de leur autonomisation (empowerment) économique et décisionnelle en matière de santé reproductive.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abengourou-2__ssr-pf__14\",\"num\":\"15\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":null,\"caseTitle\":\"Étude de cas N°1 — Amina et David (Q1 à Q27)\",\"caseData\":null,\"text\":\"L'un des sept principes de base du genre sur la santé des femmes est sa dimension d'autorité légitime dans l'organisation sociale.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Vrai\",\"answerLetters\":[\"A\"],\"explanation\":\"Dans l'analyse sociologique du genre enseignée à l'INFAS, les rapports de pouvoir et d'autorité légitime au sein de l'organisation sociale et familiale déterminent directement l'accès des femmes aux soins de santé de la reproduction.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abengourou-2__ssr-pf__15\",\"num\":\"16\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":null,\"caseTitle\":\"Étude de cas N°1 — Amina et David (Q1 à Q27)\",\"caseData\":null,\"text\":\"Les trois principales sources de droit national sont la constitution, la loi et le règlement.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Vrai\",\"answerLetters\":[\"A\"],\"explanation\":\"Dans la hiérarchie des normes juridiques internes (pyramide de Kelsen), les trois grandes sources écrites du droit national sont la Constitution (loi fondamentale), la Loi (votée par le Parlement) et le Règlement (décrets et arrêtés du pouvoir exécutif).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abengourou-2__ssr-pf__16\",\"num\":\"17\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":null,\"caseTitle\":\"Étude de cas N°1 — Amina et David (Q1 à Q27)\",\"caseData\":null,\"text\":\"La conception sociétale de la femme qui stipule que « la femme aura beau avoir une grande taille, la concession ne lui appartiendra jamais » pose un problème de genre et développement.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Vrai\",\"answerLetters\":[\"A\"],\"explanation\":\"Ce préjugé socioculturel illustre l'exclusion des femmes de la propriété foncière, de l'héritage et du pouvoir décisionnel, ce qui constitue une inégalité de genre freinant le développement.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abengourou-2__ssr-pf__17\",\"num\":\"18\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":null,\"caseTitle\":\"Étude de cas N°1 — Amina et David (Q1 à Q27)\",\"caseData\":null,\"text\":\"Un taux élevé de prolactine bloque le processus d'ovulation, rendant ainsi la femme temporairement inféconde.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Vrai\",\"answerLetters\":[\"A\"],\"explanation\":\"L'hyperprolactinémie physiologique entretenue par les tétées fréquentes inhibe la sécrétion pulsatile de GnRH hypothalamique et le pic de LH hypophysaire, bloquant ainsi l'ovulation (base physiologique de la MAMA).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abengourou-2__ssr-pf__18\",\"num\":\"19\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":null,\"caseTitle\":\"Étude de cas N°1 — Amina et David (Q1 à Q27)\",\"caseData\":null,\"text\":\"Une femme qui utilise la MAMA doit immédiatement chercher une autre méthode de contraception si son bébé a 5 mois et demi.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Vrai\",\"answerLetters\":[\"A\"],\"explanation\":\"Comme la MAMA cesse d'être efficace dès que le bébé atteint l'âge de 6 mois (et que débute la diversification alimentaire), la mère doit anticiper dès 5 mois et demi le relais immédiat vers une autre méthode contraceptive moderne pour éviter toute grossesse non désirée.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abengourou-2__ssr-pf__19\",\"num\":\"20\",\"type\":\"CAS_CLINIQUE\",\"typeLabel\":\"Étude de cas / Cas clinique\",\"partieTitle\":null,\"caseTitle\":\"Étude de cas N°1 — Amina et David (Q1 à Q27)\",\"caseData\":null,\"text\":\"Indiquer le principal mécanisme d'action de la MAMA :\",\"options\":[{\"letter\":\"A\",\"text\":\"La fatigue liée à l'allaitement diminue la libido de la mère\"},{\"letter\":\"B\",\"text\":\"La succion du bébé provoque une libération d'hormones qui bloquent l'ovulation\"},{\"letter\":\"C\",\"text\":\"Le lait maternel contient des substances qui détruisent les spermatozoïdes\"},{\"letter\":\"D\",\"text\":\"La méthode ne fonctionne que si la mère ne mange pas certains aliments\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. La succion du bébé provoque une libération d'hormones qui bloquent l'ovulation\",\"answerLetters\":[\"B\"],\"explanation\":\"La succion fréquente du mamelon par le nourrisson stimule les mécanorécepteurs aréolaires, ce qui inhibe l'axe hypothalamo-hypophysaire (GnRH/FSH/LH) via la sécrétion de prolactine et bloque l'ovulation.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abengourou-2__ssr-pf__20\",\"num\":\"21\",\"type\":\"CAS_CLINIQUE\",\"typeLabel\":\"Étude de cas / Cas clinique\",\"partieTitle\":null,\"caseTitle\":\"Étude de cas N°1 — Amina et David (Q1 à Q27)\",\"caseData\":null,\"text\":\"Pour que la MAMA soit efficace à 98%, laquelle de ces conditions n'est pas requise ?\",\"options\":[{\"letter\":\"A\",\"text\":\"Le bébé a moins de 6 mois\"},{\"letter\":\"B\",\"text\":\"La mère n'a pas eu son retour de couches\"},{\"letter\":\"C\",\"text\":\"La mère doit tirer son lait au moins une fois par jour\"},{\"letter\":\"D\",\"text\":\"L'allaitement doit être exclusif, sans autre apport alimentaire pour le bébé\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"C. La mère doit tirer son lait au moins une fois par jour\",\"answerLetters\":[\"C\"],\"explanation\":\"Les 3 critères stricts d'efficacité de la MAMA sont : 1) Nourrisson < 6 mois (A), 2) Aménorrhée persistante / absence de retour de couches (B), et 3) Allaitement maternel exclusif (ou quasi exclusif) jour et nuit au sein (D). Tirer son lait (C) n'est pas requis (et diminue même l'efficacité du réflexe de succion directe).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abengourou-2__ssr-pf__21\",\"num\":\"22\",\"type\":\"CAS_CLINIQUE\",\"typeLabel\":\"Étude de cas / Cas clinique\",\"partieTitle\":null,\"caseTitle\":\"Étude de cas N°1 — Amina et David (Q1 à Q27)\",\"caseData\":null,\"text\":\"Une femme qui utilise la MAMA doit immédiatement chercher une autre méthode de contraception si :\",\"options\":[{\"letter\":\"A\",\"text\":\"Son bébé commence à faire ses nuits et dort plus de 6 heures d'affilée\"},{\"letter\":\"B\",\"text\":\"Elle se sent fatiguée par l'allaitement\"},{\"letter\":\"C\",\"text\":\"Son bébé a 5 mois et demi (ou A si l'intervalle nocturne dépasse 6 h)\"},{\"letter\":\"D\",\"text\":\"Elle décide de donner les deux seins à chaque tétée\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Son bébé commence à faire ses nuits et dort plus de 6 heures d'affilée\",\"answerLetters\":[\"A\"],\"explanation\":\"Pour que la MAMA reste efficace, l'intervalle entre deux tétées ne doit pas dépasser 4 heures le jour et 6 heures la nuit. Si le bébé dort plus de 6 heures d'affilée la nuit (A) ou approche de 6 mois (C), le pic de prolactine chute et l'ovulation peut reprendre, imposant le passage à une autre méthode contraceptive.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abengourou-2__ssr-pf__22\",\"num\":\"23\",\"type\":\"CAS_CLINIQUE\",\"typeLabel\":\"Étude de cas / Cas clinique\",\"partieTitle\":null,\"caseTitle\":\"Étude de cas N°1 — Amina et David (Q1 à Q27)\",\"caseData\":null,\"text\":\"Parmi les affirmations suivantes, laquelle est une limite de la MAMA ?\",\"options\":[{\"letter\":\"A\",\"text\":\"Elle a de nombreux effets secondaires hormonaux\"},{\"letter\":\"B\",\"text\":\"Elle ne protège pas contre les Infections Sexuellement Transmissibles (IST)\"},{\"letter\":\"C\",\"text\":\"Elle est très coûteuse pour la famille\"},{\"letter\":\"D\",\"text\":\"Son efficacité est très faible, même si les conditions sont respectées\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Elle ne protège pas contre les Infections Sexuellement Transmissibles (IST)\",\"answerLetters\":[\"B\"],\"explanation\":\"Comme toutes les méthodes non barrières, la MAMA est gratuite, naturelle et efficace à 98 % sous conditions, mais sa limite est sa durée limitée à 6 mois et l'absence totale de protection contre les IST/VIH (B).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abengourou-2__ssr-pf__23\",\"num\":\"24\",\"type\":\"CAS_CLINIQUE\",\"typeLabel\":\"Étude de cas / Cas clinique\",\"partieTitle\":null,\"caseTitle\":\"Étude de cas N°1 — Amina et David (Q1 à Q27)\",\"caseData\":null,\"text\":\"Quelle est la double fonction principale du préservatif masculin ?\",\"options\":[{\"letter\":\"A\",\"text\":\"Augmenter le plaisir et prévenir les allergies\"},{\"letter\":\"B\",\"text\":\"Prévenir la grossesse et protéger contre les IST\"},{\"letter\":\"C\",\"text\":\"Lubrifier et prolonger la durée du rapport sexuel\"},{\"letter\":\"D\",\"text\":\"Être réutilisable et ne pas coûter cher\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Prévenir la grossesse et protéger contre les IST\",\"answerLetters\":[\"B\"],\"explanation\":\"Les préservatifs (masculin et féminin) sont les seules méthodes qui assurent la double protection : prévention des grossesses non désirées ET protection contre les IST/VIH.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abengourou-2__ssr-pf__24\",\"num\":\"25\",\"type\":\"CAS_CLINIQUE\",\"typeLabel\":\"Étude de cas / Cas clinique\",\"partieTitle\":null,\"caseTitle\":\"Étude de cas N°1 — Amina et David (Q1 à Q27)\",\"caseData\":null,\"text\":\"En cas de rupture d'un préservatif après éjaculation (sans spermicide), que doit faire la femme pour éviter une grossesse ?\",\"options\":[{\"letter\":\"A\",\"text\":\"Faire une toilette intime immédiatement avec du savon\"},{\"letter\":\"B\",\"text\":\"Attendre ses prochaines règles pour voir si elle est enceinte\"},{\"letter\":\"C\",\"text\":\"Prendre une contraception d'urgence dans les 72 heures\"},{\"letter\":\"D\",\"text\":\"Boire beaucoup d'eau pour éliminer le sperme\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"C. Prendre une contraception d'urgence dans les 72 heures\",\"answerLetters\":[\"C\"],\"explanation\":\"Après un rapport non ou mal protégé (rupture ou glissement du préservatif), la femme doit prendre le plus tôt possible (idéalement dans les 72 heures, jusqu'à 120 heures) une pilule contraceptive d'urgence (Lévonorgestrel 1,5 mg ou Ulipristal).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abengourou-2__ssr-pf__25\",\"num\":\"26\",\"type\":\"CAS_CLINIQUE\",\"typeLabel\":\"Étude de cas / Cas clinique\",\"partieTitle\":null,\"caseTitle\":\"Étude de cas N°1 — Amina et David (Q1 à Q27)\",\"caseData\":null,\"text\":\"Quel est le principal mécanisme d'action des spermicides ?\",\"options\":[{\"letter\":\"A\",\"text\":\"Ils créent une barrière physique qui bloque le col de l'utérus\"},{\"letter\":\"B\",\"text\":\"Ils modifient le pH du vagin pour le rendre hostile aux spermatozoïdes\"},{\"letter\":\"C\",\"text\":\"Ils inactivent ou tuent les spermatozoïdes en attaquant leur membrane\"},{\"letter\":\"D\",\"text\":\"Ils déclenchent une réponse immunitaire qui détruit les spermatozoïdes\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"C. Ils inactivent ou tuent les spermatozoïdes en attaquant leur membrane\",\"answerLetters\":[\"C\"],\"explanation\":\"Les spermicides sont des agents tensioactifs chimiques (ex. chlorure de benzalkonium, nonoxynol-9) qui détruisent la membrane cellulaire des spermatozoïdes, les immobilisant et les inactivant avant qu'ils ne franchissent le col utérin.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abengourou-2__ssr-pf__26\",\"num\":\"27\",\"type\":\"CAS_CLINIQUE\",\"typeLabel\":\"Étude de cas / Cas clinique\",\"partieTitle\":null,\"caseTitle\":\"Étude de cas N°1 — Amina et David (Q1 à Q27)\",\"caseData\":null,\"text\":\"Pourquoi l'usage fréquent de spermicides contenant du nonoxynol-9 est-il déconseillé aux personnes à haut risque de VIH ?\",\"options\":[{\"letter\":\"A\",\"text\":\"Parce qu'il diminue l'efficacité des préservatifs\"},{\"letter\":\"B\",\"text\":\"Parce qu'il peut causer des lésions génitales qui augmentent le risque d'infection\"},{\"letter\":\"C\",\"text\":\"Parce qu'il provoque de fortes réactions allergiques chez la plupart des utilisateurs\"},{\"letter\":\"D\",\"text\":\"Parce qu'il annule les effets des traitements antirétroviraux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Parce qu'il peut causer des lésions génitales qui augmentent le risque d'infection\",\"answerLetters\":[\"B\"],\"explanation\":\"L'utilisation pluriquotidienne de nonoxynol-9 provoque des micro-ulcérations et une irritation de l'épithélium vaginal et cervical, ce qui facilite la pénétration du VIH et augmente le risque de transmission virale.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abengourou-2__ssr-pf__27\",\"num\":\"28\",\"type\":\"CAS_CLINIQUE\",\"typeLabel\":\"Étude de cas / Cas clinique\",\"partieTitle\":null,\"caseTitle\":\"Étude de cas N°2 — Mme Fatou (Q28 à Q37)\",\"caseData\":null,\"text\":\"Quelle catégorie des critères de recevabilité médicale de l'OMS s'applique aux contraceptifs hormonaux combinés (CHC) dans le cas précis de Madame Fatou (allaitante à 6 semaines post-partum) ?\",\"options\":[{\"letter\":\"A\",\"text\":\"Catégorie 1\"},{\"letter\":\"B\",\"text\":\"Catégorie 2\"},{\"letter\":\"C\",\"text\":\"Catégorie 3\"},{\"letter\":\"D\",\"text\":\"Catégorie 4\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"C. Catégorie 3\",\"answerLetters\":[\"C\"],\"explanation\":\"Selon les critères de recevabilité médicale de l'OMS, chez une femme qui allaite : avant 6 semaines post-partum les CHC sont de Catégorie 4 (contre-indication absolue), et de 6 semaines à moins de 6 mois post-partum ils sont de Catégorie 3 (méthode généralement non recommandée car les œstrogènes diminuent la sécrétion lactée).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abengourou-2__ssr-pf__28\",\"num\":\"29\",\"type\":\"CAS_CLINIQUE\",\"typeLabel\":\"Étude de cas / Cas clinique\",\"partieTitle\":null,\"caseTitle\":\"Étude de cas N°2 — Mme Fatou (Q28 à Q37)\",\"caseData\":null,\"text\":\"Pour Madame Fatou qui allaite exclusivement, quelle méthode contraceptive est la plus appropriée parmi les suivantes ?\",\"options\":[{\"letter\":\"A\",\"text\":\"Contraceptifs oraux combinés (COC)\"},{\"letter\":\"B\",\"text\":\"Contraceptifs oraux progestatifs (COP)\"},{\"letter\":\"C\",\"text\":\"Patch contraceptif\"},{\"letter\":\"D\",\"text\":\"Anneau vaginal contraceptif\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Contraceptifs oraux progestatifs (COP)\",\"answerLetters\":[\"B\"],\"explanation\":\"Les méthodes purement progestatives (COP / pilule microprogestative, implants, injectables progestatifs) n'altèrent ni la quantité ni la qualité du lait maternel et sont classées en Catégorie 1 de l'OMS à 6 semaines du post-partum, contrairement aux COC, au patch et à l'anneau vaginal qui contiennent tous des œstrogènes.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abengourou-2__ssr-pf__29\",\"num\":\"30\",\"type\":\"CAS_CLINIQUE\",\"typeLabel\":\"Étude de cas / Cas clinique\",\"partieTitle\":null,\"caseTitle\":\"Étude de cas N°2 — Mme Fatou (Q28 à Q37)\",\"caseData\":null,\"text\":\"Concernant le retour de la fécondité chez une femme allaitante comme Madame Fatou, quelle affirmation est correcte ?\",\"options\":[{\"letter\":\"A\",\"text\":\"La probabilité d'ovuler dans les 6 premiers mois est élevée\"},{\"letter\":\"B\",\"text\":\"La période d'infertilité est plus courte que chez les femmes non allaitantes\"},{\"letter\":\"C\",\"text\":\"La probabilité d'avoir les règles et d'ovuler dans les 6 premiers mois est faible\"},{\"letter\":\"D\",\"text\":\"Le risque de grossesse est identique à celui des femmes non allaitantes\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"C. La probabilité d'avoir les règles et d'ovuler dans les 6 premiers mois est faible\",\"answerLetters\":[\"C\"],\"explanation\":\"Chez une femme pratiquant l'allaitement maternel exclusif et régulier jour et nuit, l'hyperprolactinémie maintient une anovulation lactée, rendant la probabilité d'ovuler et d'avoir son retour de couches très faible (< 2 %) au cours des 6 premiers mois.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abengourou-2__ssr-pf__30\",\"num\":\"31\",\"type\":\"CAS_CLINIQUE\",\"typeLabel\":\"Étude de cas / Cas clinique\",\"partieTitle\":null,\"caseTitle\":\"Étude de cas N°2 — Mme Fatou (Q28 à Q37)\",\"caseData\":null,\"text\":\"Si Madame Fatou choisit la méthode MAMA, quelles conditions doit-elle respecter ?\",\"options\":[{\"letter\":\"A\",\"text\":\"Allaitement exclusif, aménorrhée, et bébé de moins de 6 mois\"},{\"letter\":\"B\",\"text\":\"Allaitement partiel, retour de couches, et bébé de moins de 12 mois\"},{\"letter\":\"C\",\"text\":\"Allaitement exclusif uniquement\"},{\"letter\":\"D\",\"text\":\"Aménorrhée uniquement\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Allaitement exclusif, aménorrhée, et bébé de moins de 6 mois\",\"answerLetters\":[\"A\"],\"explanation\":\"L'efficacité de la MAMA (98 %) exige le respect simultané des trois critères : allaitement maternel exclusif (jour et nuit), aménorrhée (absence de retour de couches) et enfant âgé de moins de 6 mois.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abengourou-2__ssr-pf__31\",\"num\":\"32\",\"type\":\"CAS_CLINIQUE\",\"typeLabel\":\"Étude de cas / Cas clinique\",\"partieTitle\":null,\"caseTitle\":\"Étude de cas N°2 — Mme Fatou (Q28 à Q37)\",\"caseData\":null,\"text\":\"Selon l'OMS, quel intervalle minimum est recommandé entre une naissance vivante et le début d'une prochaine grossesse ?\",\"options\":[{\"letter\":\"A\",\"text\":\"12 mois\"},{\"letter\":\"B\",\"text\":\"18 mois\"},{\"letter\":\"C\",\"text\":\"24 mois\"},{\"letter\":\"D\",\"text\":\"36 mois\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"C. 24 mois\",\"answerLetters\":[\"C\"],\"explanation\":\"L'OMS recommande d'attendre au moins 24 mois (2 ans) après une naissance vivante avant de tenter de concevoir à nouveau (soit un intervalle intergénésique d'environ 33 mois entre deux accouchements), afin de réduire la mortalité maternelle, périnatale et infantile.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abengourou-2__ssr-pf__32\",\"num\":\"33\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":null,\"caseTitle\":\"Étude de cas N°2 — Mme Fatou (Q28 à Q37)\",\"caseData\":null,\"text\":\"La santé de la reproduction est la capacité de procréer sans complications.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"Selon la conférence du Caire (CIPD 1994) et l'OMS, la Santé de la Reproduction ne se réduit pas à la seule absence de complications lors de la procréation : c'est un état de complet bien-être physique, mental et social dans tout ce qui concerne l'appareil génital, ses fonctions et son fonctionnement.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abengourou-2__ssr-pf__33\",\"num\":\"34\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":null,\"caseTitle\":\"Étude de cas N°2 — Mme Fatou (Q28 à Q37)\",\"caseData\":null,\"text\":\"L'un des programmes nationaux de santé impliquant la santé reproductive est spécifiquement dédié à la santé scolaire, universitaire et des adolescents/jeunes.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Vrai\",\"answerLetters\":[\"A\"],\"explanation\":\"En Côte d'Ivoire, le Programme National de Santé Scolaire et Universitaire - Santé des Adolescents et des Jeunes (PNSSU-SAJ) est spécifiquement dédié à la promotion de la santé sexuelle et reproductive des élèves, étudiants, adolescents et jeunes.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abengourou-2__ssr-pf__34\",\"num\":\"35\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":null,\"caseTitle\":\"Étude de cas N°2 — Mme Fatou (Q28 à Q37)\",\"caseData\":null,\"text\":\"La planification familiale comporte 4 types d'avantages.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Vrai\",\"answerLetters\":[\"A\"],\"explanation\":\"Les cours de PF de l'INFAS classent les bénéfices de la planification familiale en 4 volets : avantages pour la mère, avantages pour l'enfant, avantages pour le père/la famille (couple) et avantages pour la communauté/la nation.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abengourou-2__ssr-pf__35\",\"num\":\"36\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":null,\"caseTitle\":\"Étude de cas N°2 — Mme Fatou (Q28 à Q37)\",\"caseData\":null,\"text\":\"Il existe 3 types d'obstacles à la planification familiale.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"Dans le module national de PF, on dénombre généralement plus de 3 catégories d'obstacles (obstacles socioculturels et religieux, obstacles psychologiques/rumeurs, obstacles économiques, obstacles liés aux services de santé et obstacles juridiques/politiques), d'où la réponse B (Faux) ou A si regroupés en 3 grands groupes.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abengourou-2__ssr-pf__36\",\"num\":\"37\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":null,\"caseTitle\":\"Étude de cas N°2 — Mme Fatou (Q28 à Q37)\",\"caseData\":null,\"text\":\"La planification familiale est l'ensemble des moyens mis à la disposition des individus et des couples pour leur permettre d'assurer une sexualité responsable.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Vrai\",\"answerLetters\":[\"A\"],\"explanation\":\"La planification familiale regroupe l'ensemble des moyens et méthodes permettant aux individus et aux couples de vivre une sexualité responsable, d'éviter les grossesses non désirées, d'espacer les naissances et de choisir le nombre d'enfants désirés.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abengourou-2__ssr-pf__37\",\"num\":\"38\",\"type\":\"CAS_CLINIQUE\",\"typeLabel\":\"Étude de cas / Cas clinique\",\"partieTitle\":null,\"caseTitle\":\"Étude de cas N°3 — Aminata, 16 ans (Q38 à Q50)\",\"caseData\":null,\"text\":\"Les rapports sexuels d'Aminata sont considérés :\",\"options\":[{\"letter\":\"A\",\"text\":\"Normaux\"},{\"letter\":\"B\",\"text\":\"Précoces\"},{\"letter\":\"C\",\"text\":\"Acceptables\"},{\"letter\":\"D\",\"text\":\"Tardifs\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Précoces\",\"answerLetters\":[\"B\"],\"explanation\":\"Chez une adolescente mineure scolarisée de 16 ans sans maturité psychosociale ni protection contraceptive, l'activité sexuelle exposant à une grossesse en milieu scolaire est qualifiée de rapport sexuel précoce en santé des adolescents et des jeunes.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abengourou-2__ssr-pf__38\",\"num\":\"39\",\"type\":\"CAS_CLINIQUE\",\"typeLabel\":\"Étude de cas / Cas clinique\",\"partieTitle\":null,\"caseTitle\":\"Étude de cas N°3 — Aminata, 16 ans (Q38 à Q50)\",\"caseData\":null,\"text\":\"Parmi les causes liées au problème d'Aminata, l'on peut identifier :\",\"options\":[{\"letter\":\"A\",\"text\":\"La méconnaissance des méthodes de contraception\"},{\"letter\":\"B\",\"text\":\"L'absence de communication entre parents et enfants\"},{\"letter\":\"C\",\"text\":\"Le manque d'éducation sexuelle au niveau familial\"},{\"letter\":\"D\",\"text\":\"Toutes les réponses ci-dessus\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"D. Toutes les réponses ci-dessus\",\"answerLetters\":[\"D\"],\"explanation\":\"La grossesse non désirée chez l'adolescente résulte à la fois de la méconnaissance des moyens contraceptifs (A), du tabou et de l'absence de dialogue parents-enfants (B) et du déficit d'éducation à la santé sexuelle en famille (C).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abengourou-2__ssr-pf__39\",\"num\":\"40\",\"type\":\"CAS_CLINIQUE\",\"typeLabel\":\"Étude de cas / Cas clinique\",\"partieTitle\":null,\"caseTitle\":\"Étude de cas N°3 — Aminata, 16 ans (Q38 à Q50)\",\"caseData\":null,\"text\":\"Les conséquences potentielles de cette grossesse précoce au niveau individuel pour Aminata incluent :\",\"options\":[{\"letter\":\"A\",\"text\":\"L'isolement dans le groupe d'élèves\"},{\"letter\":\"B\",\"text\":\"Le trouble de sa carrière scolaire\"},{\"letter\":\"C\",\"text\":\"Le sentiment de surcharge\"},{\"letter\":\"D\",\"text\":\"Toutes les réponses ci-dessus\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"D. Toutes les réponses ci-dessus\",\"answerLetters\":[\"D\"],\"explanation\":\"Au plan individuel et psychosocial, une grossesse en cours de scolarité entraîne une stigmatisation/isolement parmi les pairs (A), une perturbation ou un abandon des études (B) et une détresse psychologique avec sentiment de surcharge (C).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abengourou-2__ssr-pf__40\",\"num\":\"41\",\"type\":\"CAS_CLINIQUE\",\"typeLabel\":\"Étude de cas / Cas clinique\",\"partieTitle\":null,\"caseTitle\":\"Étude de cas N°3 — Aminata, 16 ans (Q38 à Q50)\",\"caseData\":null,\"text\":\"Au niveau familial, ce problème peut entraîner :\",\"options\":[{\"letter\":\"A\",\"text\":\"La honte\"},{\"letter\":\"B\",\"text\":\"Des coûts supplémentaires\"},{\"letter\":\"C\",\"text\":\"Une charge de travail supplémentaire pour la mère\"},{\"letter\":\"D\",\"text\":\"L'isolement\"},{\"letter\":\"E\",\"text\":\"La réjouissance\"}],\"mode\":\"mcq\",\"multi\":true,\"answer\":\"A et B et C et D\",\"answerLetters\":[\"A\",\"B\",\"C\",\"D\"],\"explanation\":\"Une grossesse précoce non planifiée chez une élève entraîne pour sa famille un sentiment de déshonneur/honte sociale (A), des charges financières accrues (B), une surcharge domestique pour la mère (C) et un repli/isolement (D), mais pas la réjouissance (E).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abengourou-2__ssr-pf__41\",\"num\":\"42\",\"type\":\"CAS_CLINIQUE\",\"typeLabel\":\"Étude de cas / Cas clinique\",\"partieTitle\":null,\"caseTitle\":\"Étude de cas N°3 — Aminata, 16 ans (Q38 à Q50)\",\"caseData\":null,\"text\":\"Sur le plan de la santé, les risques pour le bébé d'Aminata incluent :\",\"options\":[{\"letter\":\"A\",\"text\":\"Naissance prématurée\"},{\"letter\":\"B\",\"text\":\"Poids inférieur à 2 500 g\"},{\"letter\":\"C\",\"text\":\"Risque d'exclusion\"},{\"letter\":\"D\",\"text\":\"Toutes les réponses ci-dessus\"}],\"mode\":\"mcq\",\"multi\":true,\"answer\":\"A et B\",\"answerLetters\":[\"A\",\"B\"],\"explanation\":\"Sur le plan médical et périnatal, la grossesse chez l'adolescente expose le nouveau-né à la prématurité (A) et à l'hypotrophie / faible poids de naissance < 2 500 g (B), ainsi qu'au risque social d'abandon/exclusion (D).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abengourou-2__ssr-pf__42\",\"num\":\"43\",\"type\":\"CAS_CLINIQUE\",\"typeLabel\":\"Étude de cas / Cas clinique\",\"partieTitle\":null,\"caseTitle\":\"Étude de cas N°3 — Aminata, 16 ans (Q38 à Q50)\",\"caseData\":null,\"text\":\"Comme professionnel de santé, votre première approche avec Aminata devrait être de :\",\"options\":[{\"letter\":\"A\",\"text\":\"La gronder pour son comportement irresponsable\"},{\"letter\":\"B\",\"text\":\"Commencer par des questions moins sensibles\"},{\"letter\":\"C\",\"text\":\"Lui demander immédiatement si elle veut garder l'enfant\"},{\"letter\":\"D\",\"text\":\"Appeler immédiatement ses parents\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Commencer par des questions moins sensibles\",\"answerLetters\":[\"B\"],\"explanation\":\"Dans l'approche des Services Adaptés aux Adolescents et aux Jeunes (SAAJ), l'entretien doit être bienveillant, confidentiel et sans jugement, en commençant par mettre la jeune fille en confiance avec des questions générales moins sensibles (B).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abengourou-2__ssr-pf__43\",\"num\":\"44\",\"type\":\"CAS_CLINIQUE\",\"typeLabel\":\"Étude de cas / Cas clinique\",\"partieTitle\":null,\"caseTitle\":\"Étude de cas N°3 — Aminata, 16 ans (Q38 à Q50)\",\"caseData\":null,\"text\":\"Pour normaliser le problème et réduire la stigmatisation, vous pourriez dire à Aminata :\",\"options\":[{\"letter\":\"A\",\"text\":\"« Vous êtes trop jeune pour être enceinte »\"},{\"letter\":\"B\",\"text\":\"« Vos parents vont être très déçus »\"},{\"letter\":\"C\",\"text\":\"« J'ai soigné un grand nombre de jeunes gens ayant le même problème que vous »\"},{\"letter\":\"D\",\"text\":\"« Vous auriez dû faire plus attention »\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"C. « J'ai soigné un grand nombre de jeunes gens ayant le même problème que vous »\",\"answerLetters\":[\"C\"],\"explanation\":\"Dire avec empathie « J'ai accompagné et soigné beaucoup de jeunes filles qui ont traversé la même situation que vous » (C) permet de dédramatiser, de rompre son sentiment de solitude et d'établir une alliance thérapeutique sans culpabilisation.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abengourou-2__ssr-pf__44\",\"num\":\"45\",\"type\":\"CAS_CLINIQUE\",\"typeLabel\":\"Étude de cas / Cas clinique\",\"partieTitle\":null,\"caseTitle\":\"Étude de cas N°3 — Aminata, 16 ans (Q38 à Q50)\",\"caseData\":null,\"text\":\"Les stratégies pour éviter ce genre de problème incluent :\",\"options\":[{\"letter\":\"A\",\"text\":\"L'instauration de la communication entre parents et enfants\"},{\"letter\":\"B\",\"text\":\"L'éducation sexuelle dans les écoles\"},{\"letter\":\"C\",\"text\":\"L'accessibilité des contraceptifs pour les jeunes\"},{\"letter\":\"D\",\"text\":\"Toutes les réponses ci-dessus\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"D. Toutes les réponses ci-dessus\",\"answerLetters\":[\"D\"],\"explanation\":\"La prévention des grossesses précoces en milieu scolaire repose conjointement sur le dialogue familial parents-enfants (A), l'éducation complète à la sexualité à l'école (B) et l'accès aux services de PF adaptés aux jeunes (C).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abengourou-2__ssr-pf__45\",\"num\":\"46\",\"type\":\"CAS_CLINIQUE\",\"typeLabel\":\"Étude de cas / Cas clinique\",\"partieTitle\":null,\"caseTitle\":\"Étude de cas N°3 — Aminata, 16 ans (Q38 à Q50)\",\"caseData\":null,\"text\":\"Les complications obstétricales possibles chez Aminata (16 ans) incluent :\",\"options\":[{\"letter\":\"A\",\"text\":\"Accouchement difficile (dystocie par immaturité du bassin)\"},{\"letter\":\"B\",\"text\":\"Fistules obstétricales\"},{\"letter\":\"C\",\"text\":\"Accouchement prématuré\"},{\"letter\":\"D\",\"text\":\"Toutes les réponses ci-dessus\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"D. Toutes les réponses ci-dessus\",\"answerLetters\":[\"D\"],\"explanation\":\"Chez l'adolescente de 16 ans dont le bassin osseux est encore immature, les risques obstétricaux majeurs comprennent l'accouchement dystocique par disproportion fœto-pelvienne (A), les fistules obstétricales vésico-vaginales par travail prolongé (B), l'accouchement prématuré (C) et la pré-éclampsie/éclampsie.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abengourou-2__ssr-pf__46\",\"num\":\"47\",\"type\":\"CAS_CLINIQUE\",\"typeLabel\":\"Étude de cas / Cas clinique\",\"partieTitle\":null,\"caseTitle\":\"Étude de cas N°3 — Aminata, 16 ans (Q38 à Q50)\",\"caseData\":null,\"text\":\"Pour aider Aminata à adopter des comportements responsables, le processus de changement de comportement comprend dans l'ordre :\",\"options\":[{\"letter\":\"A\",\"text\":\"Information → Approbation → Décision → Action → Promotion\"},{\"letter\":\"B\",\"text\":\"Décision → Information → Action → Approbation → Promotion\"},{\"letter\":\"C\",\"text\":\"Action → Information → Décision → Approbation → Promotion\"},{\"letter\":\"D\",\"text\":\"Approbation → Information → Décision → Action → Promotion\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Information → Approbation → Décision → Action → Promotion\",\"answerLetters\":[\"A\"],\"explanation\":\"Les 5 étapes du processus de Communication pour le Changement Social et de Comportement (CCSC) en PF suivent l'ordre logique : 1. Connaissance/Information → 2. Approbation → 3. Intention/Décision → 4. Pratique/Action → 5. Plaidoyer/Promotion.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abengourou-2__ssr-pf__47\",\"num\":\"48\",\"type\":\"CAS_CLINIQUE\",\"typeLabel\":\"Étude de cas / Cas clinique\",\"partieTitle\":null,\"caseTitle\":\"Étude de cas N°3 — Aminata, 16 ans (Q38 à Q50)\",\"caseData\":null,\"text\":\"Dans le système de contrôle d'inventaire maximum-minimum version « revue continue », quelle est la règle de décision du magasinier ?\",\"options\":[{\"letter\":\"A\",\"text\":\"Commander tous les produits pour les remettre à leur niveau maximum à la fin de chaque période de revue\"},{\"letter\":\"B\",\"text\":\"Vérifier le niveau de stock de chaque produit qui sort et commander pour atteindre le niveau maximum à chaque fois que le produit arrive à son niveau minimum ou en dessous\"},{\"letter\":\"C\",\"text\":\"Vérifier le niveau de tous les produits à la fin de chaque période de revue mais ne commander que pour les produits qui sont au minimum ou en dessous\"},{\"letter\":\"D\",\"text\":\"Commander uniquement lors du passage du camion de livraison\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Vérifier le niveau de stock de chaque produit qui sort et commander pour atteindre le niveau maximum à chaque fois que le produit arrive à son niveau minimum ou en dessous\",\"answerLetters\":[\"B\"],\"explanation\":\"Dans le système Max-Min en version 'revue continue' (système à point de commande continu), le niveau de stock est évalué à chaque mouvement/sortie et une commande est déclenchée dès que le stock atteint ou passe sous le seuil minimum pour le ramener au maximum (B). (NB : L'option C définit la version 'revue périodique avec seuil minimum').\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abengourou-2__ssr-pf__48\",\"num\":\"49\",\"type\":\"CAS_CLINIQUE\",\"typeLabel\":\"Étude de cas / Cas clinique\",\"partieTitle\":null,\"caseTitle\":\"Étude de cas N°3 — Aminata, 16 ans (Q38 à Q50)\",\"caseData\":null,\"text\":\"Selon les procédures de réception des produits de santé reproductive, que doit-on faire si l'on constate des surplus lors de la réception ?\",\"options\":[{\"letter\":\"A\",\"text\":\"Toujours retourner tous les excédents au fournisseur\"},{\"letter\":\"B\",\"text\":\"Garder tous les excédents sans aucune procédure particulière\"},{\"letter\":\"C\",\"text\":\"Si les excédents ne sont pas importants, les garder et en tenir compte dans la commande future ; s'il s'agit d'un stock important, retourner les excédents\"},{\"letter\":\"D\",\"text\":\"Détruire immédiatement les excédents\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"C. Si les excédents ne sont pas importants, les garder et en tenir compte dans la commande future ; s'il s'agit d'un stock important, retourner les excédents\",\"answerLetters\":[\"C\"],\"explanation\":\"Selon le manuel de gestion logistique des produits de SR, en cas d'excédent par rapport au bordereau de livraison, si l'écart est minime et utilisable avant péremption on peut le réceptionner avec rapport d'écart et ajuster la commande suivante, mais s'il est important (risque de surstock/péremption), on le retourne au fournisseur (C).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abengourou-2__ssr-pf__49\",\"num\":\"50\",\"type\":\"CAS_CLINIQUE\",\"typeLabel\":\"Étude de cas / Cas clinique\",\"partieTitle\":null,\"caseTitle\":\"Étude de cas N°3 — Aminata, 16 ans (Q38 à Q50)\",\"caseData\":null,\"text\":\"Pour maintenir la chaîne de froid des produits pharmaceutiques, quelle température doit être maintenue dans le réfrigérateur selon les directives d'assurance qualité ?\",\"options\":[{\"letter\":\"A\",\"text\":\"0–5°C\"},{\"letter\":\"B\",\"text\":\"2–8°C\"},{\"letter\":\"C\",\"text\":\"6–10°C\"},{\"letter\":\"D\",\"text\":\"10–15°C\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. 2–8°C\",\"answerLetters\":[\"B\"],\"explanation\":\"La norme internationale (OMS/PEV/NPSP) de conservation des vaccins et produits thermosensibles au réfrigérateur est strictement comprise entre +2°C et +8°C. +-----------------------------------------------------------------------+ Épreuves : Santé Publique (Q1-Q45) | Pédiatrie (Q1-Q60) | Gynécologie-Obstétrique (Q1-Q23) | SSR/PF Version A (Q1-Q51) +=======================================================================+ +-----------------------------------------------------------------------+ +-----------------------------------------------------------------------+\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null}]}]},{\"name\":\"ABIDJAN (S2 : 2025)\",\"slug\":\"abidjan-2\",\"session\":\"S2\",\"annee\":2025,\"existe\":true,\"sujets\":[{\"name\":\"Gynéco-obstétrique\",\"slug\":\"gynecologie-obstetrique\",\"pages\":\"\",\"count\":23,\"session\":\"S2\",\"annee\":2025,\"source\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"questions\":[{\"id\":\"abidjan-2__gynecologie-obstetrique__0\",\"num\":\"1\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"I. Questions à Choix Direct (QCD : Q1 à Q6)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Durant la délivrance artificielle, on peut voir le poignet de la main qui réalise cet acte.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"Lors d'une délivrance artificielle pour rétention placentaire, la main gantée de l'accoucheur introduite en cône dans les voies génitales remonte jusque dans le fond de la cavité utérine pour décoller le placenta : l'avant-bras pénètre profondément dans le vagin et le poignet n'est donc pas visible à la vulve.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abidjan-2__gynecologie-obstetrique__1\",\"num\":\"2\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"I. Questions à Choix Direct (QCD : Q1 à Q6)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"La pelvimétrie clinique externe est obligatoire au cours du toucher vaginal chez la gestante nullipare durant la consultation prénatale à la 39ème semaine d'aménorrhée.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"C'est la pelvimétrie clinique INTERNE (exploration du bassin osseux au toucher vaginal : promontoire, lignes innominées, épines sciatiques, ogive pubienne) réalisée au cours de la CPN du 9e mois (36–37 SA) qui évalue la perméabilité du bassin, et non la pelvimétrie externe (compas de Baudelocque/losange de Michaelis) qui ne se fait d'ailleurs pas 'au cours du toucher vaginal'.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abidjan-2__gynecologie-obstetrique__2\",\"num\":\"3\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"I. Questions à Choix Direct (QCD : Q1 à Q6)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Dans un cycle menstruel normal, l'ovulation se situe au 14ème jour.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"Un cycle menstruel normal pouvant durer de 21 à 35 jours, l'ovulation ne survient au 14e jour que dans le cas particulier d'un cycle de 28 jours. Dans tout cycle normal, l'ovulation a lieu 14 jours AVANT le premier jour des règles suivantes (J = durée du cycle − 14).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abidjan-2__gynecologie-obstetrique__3\",\"num\":\"4\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"I. Questions à Choix Direct (QCD : Q1 à Q6)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Le spermatozoïde et l'ovocyte II qui sont des gamètes, contiennent chacun 23 paires de chromosomes.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"Les gamètes (spermatozoïde et ovocyte II) sont des cellules HAPLOÏDES issues de la méiose : ils contiennent chacun 23 chromosomes simples (n = 23 chromosomes) et non 23 paires (2n = 46 chromosomes, qui est le caryotype diploïde des cellules somatiques et du zygote).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abidjan-2__gynecologie-obstetrique__4\",\"num\":\"5\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"I. Questions à Choix Direct (QCD : Q1 à Q6)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"La pilosité pubienne est un caractère sexuel primaire.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"Les caractères sexuels primaires sont les organes génitaux internes et externes présents dès la naissance (ovaires, trompes, utérus, vagin, vulve). La pilosité pubienne et axillaire ainsi que le développement mammaire apparaissant à la puberté sont des caractères sexuels SECONDAIRES.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abidjan-2__gynecologie-obstetrique__5\",\"num\":\"6\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"I. Questions à Choix Direct (QCD : Q1 à Q6)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Le détroit moyen est situé dans l'excavation pelvienne.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Vrai\",\"answerLetters\":[\"A\"],\"explanation\":\"L'excavation pelvienne est limitée en haut par le détroit supérieur et en bas par le détroit inférieur ; elle présente en sa partie moyenne un rétrécissement au niveau des épines sciatiques appelé le détroit moyen. ◆ SUJET I : CAS CLINIQUE N°1 — Mme A.A.A., 25 ans, primigeste (Q7 à Q11) ----------------------------------------------------------------------- Énoncé du cas : Mme A.A.A., 25 ans, primigeste, ménagère, consulte le 09 août 2021 pour douleur lombaire droite accompagnée de fièvre et frissons depuis 2 jours. DDR = 26 décembre 2020 (soit AG = 32 SA + 2 jours au 09/08/2021). Pollakiurie nocturne avec urines troubles, durcissement douloureux intermittent de l'utérus. T° = 38°C, Pouls = 80/min, TA = 13/8 cmHg, HU = 30 cm, fosse lombaire droite très douloureuse, 2 CU / 10 min, BDC = 140/min. TV : col très court (1 cm), médian, ramolli, fermé, présentation céphalique, segment inférieur bien formé, PDE intacte. ----------------------------------------------------------------------- -----------------------------------------------------------------------\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abidjan-2__gynecologie-obstetrique__6\",\"num\":\"7\",\"type\":\"AUTRE\",\"typeLabel\":\"Questions\",\"partieTitle\":\"Sujet I — Cas clinique N°1 : Mme A.A.A. (Q7 à Q11)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Mme A.A.A. est-elle en travail d'accouchement ? Répondre soit par « OUI », soit par « NON ».\",\"options\":[],\"mode\":\"open\",\"multi\":false,\"answer\":\"NON\",\"answerLetters\":[],\"explanation\":\"Bien qu'elle présente des contractions utérines (2 CU / 10 min) ayant raccourci et ramolli le col, son col utérin est encore FERMÉ (absence de dilatation cervicale évolutive ≥ 2-3 cm). Elle n'est donc pas en travail d'accouchement franc mais en menace d'accouchement prématuré (MAP).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abidjan-2__gynecologie-obstetrique__7\",\"num\":\"8\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"Sujet I — Cas clinique N°1 : Mme A.A.A. (Q7 à Q11)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Mme A.A.A. présente-t-elle ? (Relever la réponse exacte parmi les propositions ci-dessous)\",\"options\":[{\"letter\":\"A\",\"text\":\"Une menace d'accouchement prématuré\"},{\"letter\":\"B\",\"text\":\"Un travail d'accouchement à terme\"},{\"letter\":\"C\",\"text\":\"Un travail d'accouchement post-terme\"},{\"letter\":\"D\",\"text\":\"Une menace d'avortement spontané\"},{\"letter\":\"E\",\"text\":\"Une menace d'avortement provoqué\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Une menace d'accouchement prématuré\",\"answerLetters\":[\"A\"],\"explanation\":\"Du 26/12/2020 au 09/08/2021, il s'est écoulé 5 (déc) + 31 (jan) + 28 (fév) + 31 (mars) + 30 (avr) + 31 (mai) + 30 (juin) + 31 (juil) + 9 (août) = 226 jours = 32 SA + 2 jours (compris entre 22 et 36 SA + 6j). L'association d'un terme de 32 SA + 2j, de contractions utérines douloureuses (2 CU/10 min) et de modifications cervicales (col très court à 1 cm, médian, ramolli) définit une menace d'accouchement prématuré (A).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abidjan-2__gynecologie-obstetrique__8\",\"num\":\"9\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"Sujet I — Cas clinique N°1 : Mme A.A.A. (Q7 à Q11)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Relever deux arguments, mentionnés dans le texte ci-dessus, qui, par leur association, justifient votre réponse à la question 8 :\",\"options\":[{\"letter\":\"A\",\"text\":\"Une pollakiurie nocturne avec des urines troubles\"},{\"letter\":\"B\",\"text\":\"La date des dernières règles remonte au 26 décembre 2020\"},{\"letter\":\"C\",\"text\":\"2 contractions utérines en 10 mn et col utérin très court (1 cm), médian, ramolli, fermé\"},{\"letter\":\"D\",\"text\":\"La date des dernières règles remonte au 26 décembre 2021\"},{\"letter\":\"E\",\"text\":\"3 contractions utérines en 10 mn et col utérin très court, médian, ramolli, fermé\"},{\"letter\":\"F\",\"text\":\"3 contractions utérines en 10 mn et col utérin dilaté à 4 cm\"}],\"mode\":\"mcq\",\"multi\":true,\"answer\":\"B et C\",\"answerLetters\":[\"B\",\"C\"],\"explanation\":\"Le diagnostic de MAP repose sur l'association du terme prématuré prouvé par la DDR du 26 décembre 2020 donnant 32 SA + 2j au 09/08/2021 (B) ET de contractions utérines régulières avec modifications du col utérin encore fermé : 2 CU en 10 min et col très court (1 cm), médian, ramolli, fermé (C).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abidjan-2__gynecologie-obstetrique__9\",\"num\":\"10\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"Sujet I — Cas clinique N°1 : Mme A.A.A. (Q7 à Q11)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Quelle est la cause la plus probable de la pathologie obstétricale que présente Mme A.A.A. parmi les propositions ci-dessous ?\",\"options\":[{\"letter\":\"A\",\"text\":\"Pyélonéphrite aiguë gauche\"},{\"letter\":\"B\",\"text\":\"Infection urinaire haute\"},{\"letter\":\"C\",\"text\":\"Cystite aiguë\"},{\"letter\":\"D\",\"text\":\"Pyélonéphrite aiguë droite\"},{\"letter\":\"E\",\"text\":\"Pyélonéphrite aiguë bilatérale\"},{\"letter\":\"F\",\"text\":\"Infection urinaire basse\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"D. Pyélonéphrite aiguë droite\",\"answerLetters\":[\"D\"],\"explanation\":\"La fièvre à 38°C avec frissons, la douleur lombaire droite spontanée et provoquée, et la pollakiurie avec urines troubles signent une pyélonéphrite aiguë gravidique droite (D), cause classique de MAP.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abidjan-2__gynecologie-obstetrique__10\",\"num\":\"11\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"Sujet I — Cas clinique N°1 : Mme A.A.A. (Q7 à Q11)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Relever deux arguments mentionnés dans le texte ci-dessus, justifiant votre réponse à la question 10 :\",\"options\":[{\"letter\":\"A\",\"text\":\"Un durcissement douloureux, intermittent de l'utérus\"},{\"letter\":\"B\",\"text\":\"La fosse lombaire droite est très douloureuse\"},{\"letter\":\"C\",\"text\":\"Température = 39°C\"},{\"letter\":\"D\",\"text\":\"Pollakiurie diurne avec des urines troubles\"},{\"letter\":\"E\",\"text\":\"Col utérin très court, médian\"},{\"letter\":\"F\",\"text\":\"Température = 38°C\"}],\"mode\":\"mcq\",\"multi\":true,\"answer\":\"B et F\",\"answerLetters\":[\"B\",\"F\"],\"explanation\":\"Dans le texte, les deux arguments exacts (mot pour mot) en faveur de la pyélonéphrite aiguë droite sont : « la fosse lombaire droite est très douloureuse » (B) et « Température = 38°C » (F) [les propositions C avec 39°C et D avec pollakiurie 'diurne' au lieu de 'nocturne' sont des pièges d'inexactitude par rapport au texte]. ◆ SUJET II : CAS CLINIQUE N°2 — Mme C.C.C., 18 ans, à J5 du post-partum (Q12 à Q17) ----------------------------------------------------------------------- Énoncé du cas : Mme C.C.C., 18 ans, primigeste, est admise aux urgences pour douleurs pelviennes et fièvre survenues hier après un accouchement par voie basse il y a 5 jours (long, laborieux). Bon état général, conjonctives peu colorées, T° = 39°C, Pouls = 100/min, TA = 12/6 cmHg, mollets indolores. Palpation pelvienne : masse médiane, ramollie, douloureuse, atteignant l'ombilic (gros utérus mal involué) ; garniture mouillée par des lochies séro-sanglantes très fétides. ----------------------------------------------------------------------- -----------------------------------------------------------------------\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abidjan-2__gynecologie-obstetrique__11\",\"num\":\"12\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"Sujet II — Cas clinique N°2 : Mme C.C.C. (Q12 à Q17)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"De quoi souffre Mme C.C.C. parmi les propositions ci-dessous ?\",\"options\":[{\"letter\":\"A\",\"text\":\"Accès palustre\"},{\"letter\":\"B\",\"text\":\"Phlébite aiguë droite\"},{\"letter\":\"C\",\"text\":\"Infection puerpérale\"},{\"letter\":\"D\",\"text\":\"Endométrite (puerpérale aiguë)\"},{\"letter\":\"E\",\"text\":\"Phlébite aiguë gauche\"},{\"letter\":\"F\",\"text\":\"Paludisme puerpéral\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"D. Endométrite (puerpérale aiguë)\",\"answerLetters\":[\"D\"],\"explanation\":\"À J5 d'un accouchement long et laborieux, la triade fièvre à 39°C + gros utérus mou, mal involué et douloureux (atteignant encore l'ombilic) + lochies séro-sanglantes très fétides pose le diagnostic précis d'endométrite aiguë du post-partum (D).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abidjan-2__gynecologie-obstetrique__12\",\"num\":\"13\",\"type\":\"AUTRE\",\"typeLabel\":\"Questions\",\"partieTitle\":\"Sujet II — Cas clinique N°2 : Mme C.C.C. (Q12 à Q17)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"La sage-femme de garde, pour confirmer ce diagnostic (le plus probable chez Mme C.C.C.), demande une échographie pelvienne par voie abdominale. Êtes-vous d'accord avec cette sage-femme de garde ? Répondre soit par « OUI », soit par « NON ».\",\"options\":[],\"mode\":\"open\",\"multi\":false,\"answer\":\"NON (le diagnostic positif d'endométrite est CLINIQUE et bactériologique par prélèvement des lochies ; l'échographie recherche une complication/cause favorisante telle qu'une rétention de débris placentaires)\",\"answerLetters\":[],\"explanation\":\"En sémiologie obstétricale stricte enseignée à l'INFAS, le diagnostic positif d'endométrite aiguë du post-partum est purement CLINIQUE (fièvre + subinvolution utérine douloureuse + lochies fétides) complété par l'examen bactériologique des lochies. L'échographie pelvienne ne 'confirme' pas l'endométrite mais sert à vérifier la vacuité utérine (rechercher une rétention placentaire).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abidjan-2__gynecologie-obstetrique__13\",\"num\":\"14\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"Sujet II — Cas clinique N°2 : Mme C.C.C. (Q12 à Q17)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Relever deux arguments mentionnés dans le texte ci-dessus, justifiant votre réponse à la question 12 :\",\"options\":[{\"letter\":\"A\",\"text\":\"Douleurs pelviennes et fièvre survenues hier après un accouchement par voie basse il y a 5 jours\"},{\"letter\":\"B\",\"text\":\"Lochies sanglantes très purulentes\"},{\"letter\":\"C\",\"text\":\"Utérus gros, douloureux\"},{\"letter\":\"D\",\"text\":\"Utérus gros, mal involué, douloureux\"},{\"letter\":\"E\",\"text\":\"Lochies séro-sanglantes très fétides\"},{\"letter\":\"F\",\"text\":\"La garniture est mouillée par des lochies sanglantes très fétides\"}],\"mode\":\"mcq\",\"multi\":true,\"answer\":\"A et E\",\"answerLetters\":[\"A\",\"E\"],\"explanation\":\"La consigne demande les arguments MENTIONNÉS DANS LE TEXTE : l'énoncé écrit textuellement « douleurs pelviennes et fièvre survenues hier après un accouchement par voie basse il y a 5 jours » (A) et « lochies séro-sanglantes très fétides » (E) [tandis que F omet 'séro-' et C/D reformulent 'masse médiane, ramollie, douloureuse, atteignant l'ombilic'].\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abidjan-2__gynecologie-obstetrique__14\",\"num\":\"15\",\"type\":\"AUTRE\",\"typeLabel\":\"Questions\",\"partieTitle\":\"Sujet II — Cas clinique N°2 : Mme C.C.C. (Q12 à Q17)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"La sage-femme de garde ordonne l'arrêt immédiat de l'allaitement chez Madame C.C.C. à cause de cette maladie ; êtes-vous d'accord avec cette sage-femme ? Répondre soit par « OUI », soit par « NON ».\",\"options\":[],\"mode\":\"open\",\"multi\":false,\"answer\":\"NON\",\"answerLetters\":[],\"explanation\":\"L'endométrite du post-partum ne contre-indique absolument pas l'allaitement maternel ! Au contraire, la poursuite de l'allaitement stimule la sécrétion endogène d'ocytocine qui favorise la rétraction et l'involution utérine (en choisissant des antibiotiques compatibles avec l'allaitement comme les bêta-lactamines).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abidjan-2__gynecologie-obstetrique__15\",\"num\":\"16\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"Sujet II — Cas clinique N°2 : Mme C.C.C. (Q12 à Q17)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Le traitement de la maladie dont souffre Madame C.C.C. doit toujours associer les médicaments suivants :\",\"options\":[{\"letter\":\"A\",\"text\":\"Un ou plusieurs antibiotiques\"},{\"letter\":\"B\",\"text\":\"Un ou plusieurs anti-anémiques\"},{\"letter\":\"C\",\"text\":\"Un ou plusieurs anti-inflammatoires\"},{\"letter\":\"D\",\"text\":\"Un ou plusieurs ocytociques (utérotoniques)\"},{\"letter\":\"E\",\"text\":\"Un ou plusieurs tocolytiques\"},{\"letter\":\"F\",\"text\":\"Un ou plusieurs antispasmodiques\"}],\"mode\":\"mcq\",\"multi\":true,\"answer\":\"A et D\",\"answerLetters\":[\"A\",\"D\"],\"explanation\":\"Le traitement spécifique de l'endométrite puerpérale associe systématiquement une antibiothérapie à large spectre (A, pour éradiquer l'infection polymicrobienne) et un utérotonique/ocytocique (D : Syntocinon/Oxytocine, pour assurer la rétraction utérine et le drainage des lochies infectées).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abidjan-2__gynecologie-obstetrique__16\",\"num\":\"17\",\"type\":\"AUTRE\",\"typeLabel\":\"Questions\",\"partieTitle\":\"Sujet II — Cas clinique N°2 : Mme C.C.C. (Q12 à Q17)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Existe-t-il des mesures de prévention à la portée de la sage-femme, pour la maladie dont souffre Madame C.C.C. ? Répondre soit par « OUI », soit par « NON ».\",\"options\":[],\"mode\":\"open\",\"multi\":false,\"answer\":\"OUI\",\"answerLetters\":[],\"explanation\":\"Oui, la sage-femme joue un rôle déterminant dans la prévention de l'endométrite puerpérale par : le respect strict de l'asepsie lors de l'accouchement, la limitation du nombre de touchers vaginaux après rupture des membranes, l'utilisation du partogramme pour éviter le travail prolongé, l'examen minutieux du délivre pour prévenir toute rétention cotylédonaire/membranaire, l'antibioprophylaxie en cas de RPM prolongée ou de manœuvre endo-utérine, et l'éducation de l'accouchée à l'hygiène vulvo-périnéale. ◆ SUJET III : CAS CLINIQUE N°3 — Mme X.Y.Z., 22 ans, nulligeste (Q18 à Q23) ----------------------------------------------------------------------- Énoncé du cas : Mme X.Y.Z., 22 ans, nulligeste, mariée, consulte pour douleurs pelviennes permanentes apparues depuis 4 jours accompagnées de pertes brunâtres malodorantes. Fin des dernières règles il y a 5 jours ; dernier rapport sexuel non protégé il y a 6 jours (donc pendant les règles). Pertes jaunâtres négligées depuis 3 semaines. Examen : douleur sous-ombilicale, défense pariétale dans les 2 fosses iliaques sans contracture ; T° = 38,5°C ; pose du spéculum douloureuse, vagin rouge, glaire cervicale louche et nauséabonde ; TV : col et utérus douloureux à la mobilisation, utérus de volume normal, les deux culs-de-sac vaginaux sont douloureux et empâtés sans masse palpable. ----------------------------------------------------------------------- -----------------------------------------------------------------------\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abidjan-2__gynecologie-obstetrique__17\",\"num\":\"18\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"Sujet III — Cas clinique N°3 : Mme X.Y.Z. (Q18 à Q23)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"De quoi souffre Madame X.Y.Z. parmi les propositions ci-dessous ?\",\"options\":[{\"letter\":\"A\",\"text\":\"Infection génitale haute\"},{\"letter\":\"B\",\"text\":\"Appendicite aiguë\"},{\"letter\":\"C\",\"text\":\"Endométrite puerpérale\"},{\"letter\":\"D\",\"text\":\"Salpingite aiguë bilatérale\"},{\"letter\":\"E\",\"text\":\"Grossesse extra-utérine non rompue\"},{\"letter\":\"F\",\"text\":\"Salpingite aiguë bilatérale associée à une endométrite\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"D. Salpingite aiguë bilatérale\",\"answerLetters\":[\"D\"],\"explanation\":\"Chez cette jeune femme nulligeste de 22 ans présentant des douleurs pelviennes bilatérales fébriles (38,5°C) post-menstruelles faisant suite à une cervicovaginite négligée, avec glaire louche nauséabonde, douleur à la mobilisation utérine et empâtement douloureux des deux culs-de-sac latéraux sans masse collectée, le diagnostic précis est une salpingite aiguë bilatérale (D).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abidjan-2__gynecologie-obstetrique__18\",\"num\":\"19\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"Sujet III — Cas clinique N°3 : Mme X.Y.Z. (Q18 à Q23)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Relever deux arguments mentionnés dans le texte ci-dessus, justifiant votre réponse à la question 18 :\",\"options\":[{\"letter\":\"A\",\"text\":\"Perception de masse douloureuse, empâtée et molle dans les 2 culs-de-sac\"},{\"letter\":\"B\",\"text\":\"La glaire cervicale est louche, coagulée et nauséabonde\"},{\"letter\":\"C\",\"text\":\"Défense pariétale dans les 2 fosses iliaques\"},{\"letter\":\"D\",\"text\":\"Douleur est sous-ombilicale, pelvienne, prédominant à gauche\"},{\"letter\":\"E\",\"text\":\"La température = 39,5°C\"},{\"letter\":\"F\",\"text\":\"Les deux culs-de-sac du vagin sont douloureux\"}],\"mode\":\"mcq\",\"multi\":true,\"answer\":\"C et F\",\"answerLetters\":[\"C\",\"F\"],\"explanation\":\"En vérifiant mot à mot le texte de l'énoncé : A est faux car le texte dit 'sans masse palpable', B ajoute 'coagulée' absent du texte, D ajoute 'prédominant à gauche' absent du texte, E dit '39,5°C' au lieu de '38,5°C'. Seules les propositions C (« défense pariétale dans les 2 fosses iliaques ») et F (« les deux culs-de-sac du vagin sont douloureux ») figurent exactement dans le texte !\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abidjan-2__gynecologie-obstetrique__19\",\"num\":\"20\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"Sujet III — Cas clinique N°3 : Mme X.Y.Z. (Q18 à Q23)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Chez Madame X.Y.Z., citer 2 complications tardives de cette maladie, parmi les propositions suivantes :\",\"options\":[{\"letter\":\"A\",\"text\":\"Stérilité féminine secondaire\"},{\"letter\":\"B\",\"text\":\"Stérilité conjugale\"},{\"letter\":\"C\",\"text\":\"Leucorrhée physiologique d'origine cervicale\"},{\"letter\":\"D\",\"text\":\"Stérilité féminine primaire\"},{\"letter\":\"E\",\"text\":\"Rupture utérine\"},{\"letter\":\"F\",\"text\":\"Hématome rétroplacentaire\"}],\"mode\":\"mcq\",\"multi\":true,\"answer\":\"B et D\",\"answerLetters\":[\"B\",\"D\"],\"explanation\":\"Comme Mme X.Y.Z. est NULLIGESTE (elle n'a jamais été enceinte : G0P0), une obstruction tubaire bilatérale séquellaire de sa salpingite entraînera chez elle une STÉRILITÉ FÉMININE PRIMAIRE (D, et non secondaire qui concerne une femme ayant déjà eu au moins une grossesse) ainsi qu'une STÉRILITÉ CONJUGALE (B).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abidjan-2__gynecologie-obstetrique__20\",\"num\":\"21\",\"type\":\"AUTRE\",\"typeLabel\":\"Questions\",\"partieTitle\":\"Sujet III — Cas clinique N°3 : Mme X.Y.Z. (Q18 à Q23)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Chez Madame X.Y.Z., l'hystérosalpingographie (l'HSG) et l'échographie pelvienne peuvent-elles être demandées pour confirmer votre diagnostic positif ? Répondre soit par « OUI », soit par « NON ».\",\"options\":[],\"mode\":\"open\",\"multi\":false,\"answer\":\"B : NON\",\"answerLetters\":[],\"explanation\":\"NON ! L'Hystérosalpingographie (HSG : injection sous pression de produit de contraste iodé dans la cavité utérine et les trompes) est FORMELLEMENT CONTRE-INDIQUÉE en phase aiguë d'infection génitale haute (salpingite aiguë) car elle dissémine les germes dans la cavité péritonéale et provoque une pelvipéritonite aiguë.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abidjan-2__gynecologie-obstetrique__21\",\"num\":\"22\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"Sujet III — Cas clinique N°3 : Mme X.Y.Z. (Q18 à Q23)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Parmi les examens complémentaires ci-dessous, relever les 2 qui sont interdits de pratiquer chez Madame X.Y.Z. :\",\"options\":[{\"letter\":\"A\",\"text\":\"Numération et Formule Sanguine\"},{\"letter\":\"B\",\"text\":\"Hémogramme urinaire\"},{\"letter\":\"C\",\"text\":\"Échotomographie\"},{\"letter\":\"D\",\"text\":\"Hystérographie (HSG)\"},{\"letter\":\"E\",\"text\":\"Hystéroscopie\"},{\"letter\":\"F\",\"text\":\"Hémogramme sanguin\"}],\"mode\":\"mcq\",\"multi\":true,\"answer\":\"D et E\",\"answerLetters\":[\"D\",\"E\"],\"explanation\":\"En présence d'une infection génitale haute aiguë (salpingite/endométrite), toute exploration endo-utérine ascendante injectant du liquide ou du gaz sous pression — à savoir l'Hystérographie/HSG (D) et l'Hystéroscopie (E) — est formellement interdite en raison du risque de flambée infectieuse péritonéale.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abidjan-2__gynecologie-obstetrique__22\",\"num\":\"23\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"Sujet III — Cas clinique N°3 : Mme X.Y.Z. (Q18 à Q23)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Chez Madame X.Y.Z., relever 2 facteurs de risque de cette maladie, mentionnés dans le texte ci-dessus, parmi les propositions suivantes :\",\"options\":[{\"letter\":\"A\",\"text\":\"Rapports sexuels durant la période des règles\"},{\"letter\":\"B\",\"text\":\"La température = 38,5°C\"},{\"letter\":\"C\",\"text\":\"Le col de l'utérus et l'utérus sont douloureux à la mobilisation\"},{\"letter\":\"D\",\"text\":\"Madame X.Y.Z. est âgée de 22 ans, nulligeste, mariée\"},{\"letter\":\"E\",\"text\":\"Les deux culs-de-sac du vagin sont douloureux\"},{\"letter\":\"F\",\"text\":\"Son dernier rapport sexuel non protégé remonte à 6 jours\"}],\"mode\":\"mcq\",\"multi\":true,\"answer\":\"D et F\",\"answerLetters\":[\"D\",\"F\"],\"explanation\":\"Les facteurs de risque d'infection génitale haute présents dans l'énoncé sont : le jeune âge < 25 ans et la nulligestité (D : 22 ans, nulligeste), le rapport sexuel non protégé récent sur fond d'infection basse non traitée (F : dernier rapport sexuel non protégé il y a 6 jours), survenu pendant les règles (A : règles finies il y a 5 jours, rapport il y a 6 jours, période où l'ouverture du col et la disparition du bouchon muqueux favorisent l'ascension des germes). +-----------------------------------------------------------------------+\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null}]},{\"name\":\"SSR / PF\",\"slug\":\"ssr-pf\",\"pages\":\"\",\"count\":50,\"session\":\"S2\",\"annee\":2025,\"source\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"questions\":[{\"id\":\"abidjan-2__ssr-pf__0\",\"num\":\"1\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"Sujet I — Questions à Choix Multiples (QCM : Q1 à Q17)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Quel est le critère de réussite de la MAMA ?\",\"options\":[{\"letter\":\"A\",\"text\":\"L'accouchée est à 6 mois du post-partum\"},{\"letter\":\"B\",\"text\":\"La patiente a eu ses retours de couches\"},{\"letter\":\"C\",\"text\":\"La patiente secrétaire allaite exclusivement son bébé, pour réussir sa méthode elle extrait le lait et le conserve au réfrigérateur\"},{\"letter\":\"D\",\"text\":\"Toutes les réponses sont fausses (aucune des propositions a, b, c n'est un critère de réussite)\"}],\"mode\":\"open\",\"multi\":false,\"answer\":\"Aucune des propositions a, b, c (pour réussir la MAMA, le bébé doit avoir MOINS de 6 mois, la mère doit être en AMÉNORRHÉE sans retour de couches, et l'allaitement doit se faire directement au sein jour et nuit sans tirer le lait)\",\"answerLetters\":[],\"explanation\":\"Les 3 critères de la MAMA sont : 1) enfant < 6 mois (à 6 mois révolus, la MAMA n'est plus valide), 2) absence de retour de couches, et 3) tétées directes exclusives au sein jour et nuit (tirer le lait au travail ne maintient pas le réflexe neuro-endocrinien de succion mamelonnaire nécessaire au blocage de l'ovulation).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abidjan-2__ssr-pf__1\",\"num\":\"2\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"Sujet I — Questions à Choix Multiples (QCM : Q1 à Q17)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Quel est le taux d'efficacité de la MAMA parmi les propositions suivantes ?\",\"options\":[{\"letter\":\"A\",\"text\":\"Le taux d'efficacité est de 78%\"},{\"letter\":\"B\",\"text\":\"Le taux d'efficacité est de 100%\"},{\"letter\":\"C\",\"text\":\"Le taux d'efficacité est de 98%\"},{\"letter\":\"D\",\"text\":\"Le taux d'efficacité est inférieur à 98%\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"C. Le taux d'efficacité est de 98%\",\"answerLetters\":[\"C\"],\"explanation\":\"Lorsqu'elle est correctement pratiquée dans le respect strict de ses trois conditions, la MAMA a une efficacité contraceptive de 98 % (soit 2 grossesses pour 100 femmes au cours des 6 premiers mois post-partum).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abidjan-2__ssr-pf__2\",\"num\":\"3\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"Sujet I — Questions à Choix Multiples (QCM : Q1 à Q17)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Un élément représente un avantage pour la mère lorsqu'elle utilise la MAMA comme méthode contraceptive, lequel ?\",\"options\":[{\"letter\":\"A\",\"text\":\"Aide à établir un rapport étroit entre la mère et l'enfant\"},{\"letter\":\"B\",\"text\":\"Encourage les meilleures modalités d'allaitement\"},{\"letter\":\"C\",\"text\":\"Efficace uniquement avant le retour de la menstruation ou pendant 6 mois\"},{\"letter\":\"D\",\"text\":\"Efficace uniquement avant le retour de la menstruation ou pendant 6 mois\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Aide à établir un rapport étroit entre la mère et l'enfant\",\"answerLetters\":[\"A\"],\"explanation\":\"L'établissement d'un lien psycho-affectif étroit entre la mère et l'enfant (a) et l'encouragement des pratiques optimales d'allaitement (b) sont des avantages de la MAMA, tandis que c et d sont des limites/contraintes de durée.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abidjan-2__ssr-pf__3\",\"num\":\"4\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"Sujet I — Questions à Choix Multiples (QCM : Q1 à Q17)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Pour la qualité du suivi de la MAMA, une question est à poser à la mère, laquelle ?\",\"options\":[{\"letter\":\"A\",\"text\":\"As-tu un engorgement mammaire ?\"},{\"letter\":\"B\",\"text\":\"Avez-vous ajouté d'autres aliments ou liquides à l'alimentation de votre enfant ?\"},{\"letter\":\"C\",\"text\":\"Est-elle efficace immédiatement ?\"},{\"letter\":\"D\",\"text\":\"La sage-femme peut-elle aider la patiente à continuer sa méthode ?\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Avez-vous ajouté d'autres aliments ou liquides à l'alimentation de votre enfant ?\",\"answerLetters\":[\"B\"],\"explanation\":\"Lors d'une visite de suivi sous MAMA, le prestataire doit vérifier les 3 critères de validité en demandant à la mère : 1) quel âge a le bébé, 2) si ses règles sont revenues, et 3) si elle a introduit d'autres aliments ou liquides (eau, tisane, bouillie, lait artificiel) dans l'alimentation de l'enfant (b).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abidjan-2__ssr-pf__4\",\"num\":\"5\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"Sujet I — Questions à Choix Multiples (QCM : Q1 à Q17)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Parmi les propositions suivantes, laquelle représente la fréquence exacte des tétées pour la réussite de la MAMA ?\",\"options\":[{\"letter\":\"A\",\"text\":\"Tétées fréquentes, au moins 4 à 5 tétées par 24 heures\"},{\"letter\":\"B\",\"text\":\"Tétées fréquentes, au moins 6 à 8 tétées (ou 8 à 12 tétées) par 24 heures\"},{\"letter\":\"C\",\"text\":\"Tétées fréquentes, au moins 3 à 6 tétées par 24 heures\"},{\"letter\":\"D\",\"text\":\"Tétées fréquentes, au moins 3 à 4 tétées par 24 heures\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Tétées fréquentes, au moins 6 à 8 tétées (ou 8 à 12 tétées) par 24 heures\",\"answerLetters\":[\"B\"],\"explanation\":\"La réussite de la MAMA exige un allaitement à la demande jour et nuit avec au minimum 6 à 8 (voire 8 à 12) tétées par 24 heures, sans jamais dépasser un espacement de 4 heures le jour et de 6 heures la nuit.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abidjan-2__ssr-pf__5\",\"num\":\"6\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"Sujet I — Questions à Choix Multiples (QCM : Q1 à Q17)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Madame Adjoua a accouché le 07/09/2025 ; à quel moment elle ne pourra plus utiliser la MAMA comme méthode contraceptive ?\",\"options\":[{\"letter\":\"A\",\"text\":\"07/11/2025\"},{\"letter\":\"B\",\"text\":\"07/12/2025\"},{\"letter\":\"C\",\"text\":\"07/01/2026\"},{\"letter\":\"D\",\"text\":\"07/03/2026\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"D. 07/03/2026\",\"answerLetters\":[\"D\"],\"explanation\":\"La MAMA expire au bout de 6 mois révolus après l'accouchement : du 07/09/2025 + 6 mois = 07/03/2026 (d).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abidjan-2__ssr-pf__6\",\"num\":\"7\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"Sujet I — Questions à Choix Multiples (QCM : Q1 à Q17)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Après le counseling, l'accouchée accepte d'utiliser la MAMA comme méthode contraceptive ; quelle instruction allez-vous lui donner pour la réussite de la méthode ?\",\"options\":[{\"letter\":\"A\",\"text\":\"Allaiter le bébé au sein de façon fréquente et prolongée aussi souvent qu'il le désire\"},{\"letter\":\"B\",\"text\":\"La menstruation signifie le retour de l'ovulation et de la fécondité\"},{\"letter\":\"C\",\"text\":\"Une grossesse est donc possible\"},{\"letter\":\"D\",\"text\":\"Conseiller une autre méthode et aider la cliente dans le choix, encourager la mère à poursuivre l'allaitement\"},{\"letter\":\"E\",\"text\":\"Expliquer à la mère qu'elle a besoin d'un approvisionnement temporaire de condoms lubrifiants\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Allaiter le bébé au sein de façon fréquente et prolongée aussi souvent qu'il le désire\",\"answerLetters\":[\"A\"],\"explanation\":\"L'instruction clé pour assurer la réussite pratique de la MAMA est d'allaiter exclusivement au sein à la demande, de façon fréquente et prolongée, jour et nuit, aussi souvent que le bébé le désire (a).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abidjan-2__ssr-pf__7\",\"num\":\"8\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"Sujet I — Questions à Choix Multiples (QCM : Q1 à Q17)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Parmi les propositions suivantes, laquelle définit la MAMA ?\",\"options\":[{\"letter\":\"A\",\"text\":\"Méthode d'Allaitement Moderne et de l'Aménorrhée\"},{\"letter\":\"B\",\"text\":\"Méthode d'Allaitement Maternel et de l'Aménorrhée\"},{\"letter\":\"C\",\"text\":\"Méthode d'Aménorrhée Maternelle et de l'Alimentation\"},{\"letter\":\"D\",\"text\":\"Méthode d'Aménorrhée Moderne et de l'Alimentation\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Méthode d'Allaitement Maternel et de l'Aménorrhée\",\"answerLetters\":[\"B\"],\"explanation\":\"Le sigle MAMA signifie exactement : Méthode de l'Allaitement Maternel et de l'Aménorrhée (b).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abidjan-2__ssr-pf__8\",\"num\":\"9\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"Sujet I — Questions à Choix Multiples (QCM : Q1 à Q17)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Quel est le mode d'action de la MAMA ?\",\"options\":[{\"letter\":\"A\",\"text\":\"Modifie la glaire cervicale\"},{\"letter\":\"B\",\"text\":\"Modifie l'endomètre\"},{\"letter\":\"C\",\"text\":\"Bloque l'ovulation\"},{\"letter\":\"D\",\"text\":\"Empêche les spermatozoïdes d'arriver jusqu'aux trompes\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"C. Bloque l'ovulation\",\"answerLetters\":[\"C\"],\"explanation\":\"La MAMA agit au niveau hypothalamo-hypophysaire par la succion fréquente du mamelon qui maintient un taux élevé de prolactine, inhibant la sécrétion pulsatile de GnRH et de LH et bloquant ainsi l'ovulation (c).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abidjan-2__ssr-pf__9\",\"num\":\"10\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"Sujet I — Questions à Choix Multiples (QCM : Q1 à Q17)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Dans la méthode des jours fixes (MJF) ou du collier du cycle, les utilisateurs évitent les rapports sexuels non protégés du : (choisir la bonne réponse)\",\"options\":[{\"letter\":\"A\",\"text\":\"8ème au 20ème jour du cycle\"},{\"letter\":\"B\",\"text\":\"9ème au 18ème jour du cycle\"},{\"letter\":\"C\",\"text\":\"8ème au 19ème jour du cycle\"},{\"letter\":\"D\",\"text\":\"9ème au 19ème jour du cycle\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"C. 8ème au 19ème jour du cycle\",\"answerLetters\":[\"C\"],\"explanation\":\"Sur le collier du cycle (pour des cycles réguliers de 26 à 32 jours), les perles blanches phosphorescentes marquant la période fertile (où les rapports sexuels non protégés doivent être évités) s'étendent exactement du 8e au 19e jour inclus du cycle (soit 12 jours, c).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abidjan-2__ssr-pf__10\",\"num\":\"11\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"Sujet I — Questions à Choix Multiples (QCM : Q1 à Q17)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Pour la conception / contraception, les Méthodes d'Auto-Observation (MAO) conviennent aux : (Choisir la bonne réponse)\",\"options\":[{\"letter\":\"A\",\"text\":\"Femmes avec les cycles menstruels irréguliers\"},{\"letter\":\"B\",\"text\":\"Femmes en âge de procréer (couples stables motivés avec cycles réguliers)\"},{\"letter\":\"C\",\"text\":\"Femmes ayant plusieurs partenaires sexuels\"},{\"letter\":\"D\",\"text\":\"Couples absolument sûrs de ne plus vouloir d'enfants\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Femmes en âge de procréer (couples stables motivés avec cycles réguliers)\",\"answerLetters\":[\"B\"],\"explanation\":\"Les méthodes naturelles d'auto-observation (MAO) s'adressent aux femmes en âge de procréer ayant des cycles réguliers et vivant en couple stable, coopératif et motivé (b). Elles sont déconseillées en cas de cycles irréguliers (a), de partenaires multiples (c, risque d'IST) ou si une grossesse est formellement contre-indiquée (d).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abidjan-2__ssr-pf__11\",\"num\":\"12\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"Sujet I — Questions à Choix Multiples (QCM : Q1 à Q17)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Les buts du counseling sont : choisir les (2) bonnes réponses :\",\"options\":[{\"letter\":\"A\",\"text\":\"Dissiper les doutes\"},{\"letter\":\"B\",\"text\":\"Faire un consentement éclairé\"},{\"letter\":\"C\",\"text\":\"Choisir une méthode de contraception qui leur convient\"},{\"letter\":\"D\",\"text\":\"Comprendre et respecter ses devoirs par client\"},{\"letter\":\"E\",\"text\":\"Renforcer les droits du client\"},{\"letter\":\"F\",\"text\":\"Tirer les leçons du passé\"}],\"mode\":\"mcq\",\"multi\":true,\"answer\":\"B et C\",\"answerLetters\":[\"B\",\"C\"],\"explanation\":\"Le counseling en planification familiale a pour buts essentiels d'aider le client à effectuer un choix libre et éclairé (consentement éclairé, b) et à choisir puis utiliser correctement la méthode contraceptive qui lui convient le mieux (c).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abidjan-2__ssr-pf__12\",\"num\":\"13\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"Sujet I — Questions à Choix Multiples (QCM : Q1 à Q17)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Les principes de base nécessaires au counseling chez le client se rapportent à : (Choisir les 2 bonnes réponses)\",\"options\":[{\"letter\":\"A\",\"text\":\"La liberté de s'exprimer\"},{\"letter\":\"B\",\"text\":\"L'éducation par l'exemple\"},{\"letter\":\"C\",\"text\":\"Le fait de tirer les leçons du passé\"},{\"letter\":\"D\",\"text\":\"Le renforcement des capacités du client\"},{\"letter\":\"E\",\"text\":\"Le rejet des conceptions erronées\"}],\"mode\":\"mcq\",\"multi\":true,\"answer\":\"A et D\",\"answerLetters\":[\"A\",\"D\"],\"explanation\":\"Du côté du client, le counseling repose sur sa liberté d'expression (exprimer ses besoins, craintes et préférences sans jugement, a) et le renforcement de ses capacités d'analyse et de décision autonome (d). Les items b, c et e sont des qualités/principes exigés du prestataire.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abidjan-2__ssr-pf__13\",\"num\":\"14\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"Sujet I — Questions à Choix Multiples (QCM : Q1 à Q17)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Parmi ces principes de base liés au prestataire, un est erroné. Lequel ?\",\"options\":[{\"letter\":\"A\",\"text\":\"La maîtrise du sujet\"},{\"letter\":\"B\",\"text\":\"Rejeter les conceptions erronées (sans brusquer ou bien l'intrus selon la liste du cours)\"},{\"letter\":\"C\",\"text\":\"Être un modèle\"},{\"letter\":\"D\",\"text\":\"Demeurer positif, constructif, optimiste et tourné vers l'avenir\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Rejeter les conceptions erronées (sans brusquer ou bien l'intrus selon la liste du cours)\",\"answerLetters\":[\"B\"],\"explanation\":\"Un bon conseiller doit maîtriser techniquement son sujet (a), être un modèle d'écoute et de respect (c) et rester positif, constructif et tourné vers l'avenir (d). En revanche, 'rejeter' frontalement les conceptions du client braque ce dernier : il faut accueillir ses préoccupations avec empathie et dissiper les rumeurs avec tact.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abidjan-2__ssr-pf__14\",\"num\":\"15\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"Sujet I — Questions à Choix Multiples (QCM : Q1 à Q17)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Parmi les éléments suivants, lequel est en rapport avec le mode d'action du DIU au cuivre ?\",\"options\":[{\"letter\":\"A\",\"text\":\"Épaissit la glaire cervicale\"},{\"letter\":\"B\",\"text\":\"Fluidifie la glaire cervicale\"},{\"letter\":\"C\",\"text\":\"Inhibe l'ovulation\"},{\"letter\":\"D\",\"text\":\"Altère les spermatozoïdes\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"D. Altère les spermatozoïdes\",\"answerLetters\":[\"D\"],\"explanation\":\"Les ions cuivre libérés par le DIU au cuivre exercent un effet spermicide direct qui altère la mobilité, la capacitation et la survie des spermatozoïdes (d) et crée une réaction inflammatoire locale endométriale empêchant la fécondation et la nidation (l'épaississement de la glaire et l'inhibition de l'ovulation relèvent des méthodes hormonales).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abidjan-2__ssr-pf__15\",\"num\":\"16\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"Sujet I — Questions à Choix Multiples (QCM : Q1 à Q17)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Dans la pose du DIU du post-partum (DIUPP), une expulsion spontanée peut se produire le plus souvent au cours des :\",\"options\":[{\"letter\":\"A\",\"text\":\"Cinq premiers mois du post-partum\"},{\"letter\":\"B\",\"text\":\"Six premiers mois du post-partum\"},{\"letter\":\"C\",\"text\":\"Trois premiers mois du post-partum (ou 4 à 6 premières semaines)\"},{\"letter\":\"D\",\"text\":\"Quatre premiers mois du post-partum\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"C. Trois premiers mois du post-partum (ou 4 à 6 premières semaines)\",\"answerLetters\":[\"C\"],\"explanation\":\"Après l'insertion d'un DIU du post-partum (DIUPP), le risque d'expulsion spontanée est maximal pendant la période d'involution utérine, soit au cours des 6 premières semaines à 3 premiers mois du post-partum (c).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abidjan-2__ssr-pf__16\",\"num\":\"17\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"Sujet I — Questions à Choix Multiples (QCM : Q1 à Q17)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Lorsque le Norlevo (Lévonorgestrel) est employé dans le cadre d'une contraception post-coïtale d'urgence, il doit être pris :\",\"options\":[{\"letter\":\"A\",\"text\":\"Dans les 72 heures après la relation sexuelle non protégée\"},{\"letter\":\"B\",\"text\":\"Dans les 24 heures qui suivent la relation sexuelle non protégée\"},{\"letter\":\"C\",\"text\":\"Dans les 120 heures après la relation sexuelle non protégée\"},{\"letter\":\"D\",\"text\":\"Dans les trois heures qui suivent la relation sexuelle non protégée\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Dans les 72 heures après la relation sexuelle non protégée\",\"answerLetters\":[\"A\"],\"explanation\":\"Le délai officiel d'efficacité optimale de la pilule contraceptive d'urgence au Lévonorgestrel (Norlevo / Postinor) est de 72 heures (3 jours) au plus tard après le rapport sexuel non ou mal protégé (et le plus tôt possible après le rapport, a).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abidjan-2__ssr-pf__17\",\"num\":\"18\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"Sujet II — Questions à Choix Double (QCD : Q18 à Q45)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"La production de la prolactine par l'hypophyse à un taux élevé dans le sang agit sur la muqueuse de l'utérus pour empêcher la survenue d'une grossesse.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"La prolactine n'agit pas directement sur la muqueuse utérine (endomètre) : elle agit sur l'axe hypothalamo-hypophyso-ovarien en inhibant la sécrétion pulsatile de GnRH et de LH/FSH, ce qui bloque l'OVULATION.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abidjan-2__ssr-pf__18\",\"num\":\"19\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"Sujet II — Questions à Choix Double (QCD : Q18 à Q45)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"L'effet contraceptif de la MAMA est plus fort lorsque le taux de prolactine est bas.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"C'est l'inverse : l'effet contraceptif de la MAMA nécessite un taux de prolactine ÉLEVÉ (entretenu par les tétées fréquentes jour et nuit).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abidjan-2__ssr-pf__19\",\"num\":\"20\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"Sujet II — Questions à Choix Double (QCD : Q18 à Q45)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"L'un des inconvénients de la MAMA est qu'il ne peut pas y avoir un risque de transmission du VIH à l'enfant par le lait si la mère est séropositive.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"Au contraire, le VIH peut être transmis de la mère à l'enfant par le lait maternel (d'où la nécessité d'une trithérapie ARV maternelle efficace et d'une prophylaxie ARV chez le nouveau-né).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abidjan-2__ssr-pf__20\",\"num\":\"21\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"Sujet II — Questions à Choix Double (QCD : Q18 à Q45)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Il y a 3 éléments à rechercher pendant le suivi pour garantir la réussite de la MAMA comme méthode contraceptive.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Vrai\",\"answerLetters\":[\"A\"],\"explanation\":\"Lors de chaque suivi, on vérifie systématiquement les 3 conditions : 1) l'âge du nourrisson (< 6 mois), 2) la persistance de l'aménorrhée, et 3) le maintien de l'allaitement maternel exclusif jour et nuit.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abidjan-2__ssr-pf__21\",\"num\":\"22\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"Sujet II — Questions à Choix Double (QCD : Q18 à Q45)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Q23 — Le genre est un concept social qui nous permet de comprendre que les caractéristiques (rôles, statuts) présentées par les hommes et les femmes ne sont ni naturelles, ni inaltérables (numérotée en 2 lignes 22 et 23 sur le sujet).\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Vrai\",\"answerLetters\":[\"A\"],\"explanation\":\"Contrairement au sexe biologique qui est inné, le genre désigne les rôles, comportements et attributs socialement construits qui évoluent dans le temps et selon les cultures (ils ne sont donc ni naturels ni immuables).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abidjan-2__ssr-pf__22\",\"num\":\"24\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"Sujet II — Questions à Choix Double (QCD : Q18 à Q45)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Le sexe fait référence au biologique, au physiologique mais peut varier.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"Dans la définition classique Genre et Développement enseignée à l'INFAS, le sexe renvoie aux caractéristiques biologiques, anatomiques et physiologiques innées et universelles qui ne varient pas d'une culture à l'autre (contrairement au genre).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abidjan-2__ssr-pf__23\",\"num\":\"25\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"Sujet II — Questions à Choix Double (QCD : Q18 à Q45)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Le genre est acquis à travers l'éducation, les valeurs sociales tout au long de la vie.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Vrai\",\"answerLetters\":[\"A\"],\"explanation\":\"Le genre est le fruit de la socialisation (éducation familiale, école, normes culturelles et sociales) acquise tout au long de la vie.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abidjan-2__ssr-pf__24\",\"num\":\"26\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"Sujet II — Questions à Choix Double (QCD : Q18 à Q45)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Le sexe peut changer selon la volonté de l'individu.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"Selon le cours de Genre et Santé de l'INFAS, le sexe biologique (chromosomique et gonadique) est une donnée naturelle innée qui ne change pas par simple volonté individuelle.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abidjan-2__ssr-pf__25\",\"num\":\"27\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"Sujet II — Questions à Choix Double (QCD : Q18 à Q45)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"En Côte d'Ivoire, le modèle du système de contrôle d'inventaire max-min retenu est le système de contrôle d'inventaire maximum-minimum version standard.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"En Côte d'Ivoire (SIGL / NPSP), le système de contrôle des stocks retenu pour les produits de santé publique est le système Max-Min en version « COMMANDE FORCÉE » (à la fin de chaque période de revue mensuelle, on commande tous les produits pour les ramener à leur niveau maximum).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abidjan-2__ssr-pf__26\",\"num\":\"28\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"Sujet II — Questions à Choix Double (QCD : Q18 à Q45)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Quel est le système max-min pour lequel on ne commande pas tous les produits ?\",\"options\":[{\"letter\":\"A\",\"text\":\"Version commande forcée\"},{\"letter\":\"B\",\"text\":\"Version revue continue (et version standard)\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Version revue continue (et version standard)\",\"answerLetters\":[\"B\"],\"explanation\":\"Dans la version 'commande forcée' (A), on commande TOUS les produits à la fin de chaque période de revue. En revanche, dans la version 'revue continue' (B, ainsi que la version standard), on ne commande que les produits dont le stock a atteint ou franchi le niveau minimum.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abidjan-2__ssr-pf__27\",\"num\":\"29\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"Sujet II — Questions à Choix Double (QCD : Q18 à Q45)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Niveau de Stock Min = Niveau de stock du délai de livraison + niveau de stock de sécurité + niveau de stock de la période de revue est la détermination du niveau de stock minimum pour le système max-min version revue continue.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"En version revue continue, il n'y a pas de période de revue fixe dans la formule du stock minimum (Stock Min = Stock du délai de livraison + Stock de sécurité). L'ajout de la période de revue concerne le calcul du stock maximum.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abidjan-2__ssr-pf__28\",\"num\":\"30\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"Sujet II — Questions à Choix Double (QCD : Q18 à Q45)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Le stock de roulement est la quantité nécessaire pour couvrir la période entre deux approvisionnements.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Vrai\",\"answerLetters\":[\"A\"],\"explanation\":\"Le stock de roulement (stock actif) correspond à la quantité de produits consommée normalement entre deux livraisons successives (période de revue).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abidjan-2__ssr-pf__29\",\"num\":\"31\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"Sujet II — Questions à Choix Double (QCD : Q18 à Q45)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Le stock d'alerte = stock minimum + stock de sécurité.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"Le stock d'alerte (qui est synonyme de stock minimum ou point de commande) est égal au Stock du délai de livraison + Stock de sécurité (et non Stock minimum + Stock de sécurité, puisque le stock minimum inclut déjà le stock de sécurité).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abidjan-2__ssr-pf__30\",\"num\":\"32\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"Sujet II — Questions à Choix Double (QCD : Q18 à Q45)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Le counseling se concentre sur les besoins collectifs des clients.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"Contrairement à la causerie éducative de groupe (IEC/CCC collective), le counseling est une communication interpersonnelle en face-à-face centrée sur les besoins INDIVIDUELS et spécifiques d'un client ou d'un couple.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abidjan-2__ssr-pf__31\",\"num\":\"33\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"Sujet II — Questions à Choix Double (QCD : Q18 à Q45)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Dans les méthodes d'auto-observation, les rapports sexuels ne sont pas proscrits (en période fertile).\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"En contraception par les méthodes d'auto-observation (abstinence périodique), les rapports sexuels non protégés sont proscrits pendant toute la phase fertile du cycle.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abidjan-2__ssr-pf__32\",\"num\":\"34\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"Sujet II — Questions à Choix Double (QCD : Q18 à Q45)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Les principes de base communs aux méthodes d'auto-observation font appel aux moyens qui permettent de repérer la date d'ovulation (et la période fertile).\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Vrai\",\"answerLetters\":[\"A\"],\"explanation\":\"Toutes les méthodes d'auto-observation (Billings, TBC, symptothermique, calendrier) visent à identifier le moment de l'ovulation et la fenêtre de fertilité en tenant compte de la durée de vie de l'ovule (24 h) et des spermatozoïdes (3 à 5 jours).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abidjan-2__ssr-pf__33\",\"num\":\"35\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"Sujet II — Questions à Choix Double (QCD : Q18 à Q45)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"La durée de vie des spermatozoïdes est toujours de 06 jours.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"Le pouvoir fécondant des spermatozoïdes dans les voies génitales féminines (glaire cervicale ovulatoire) est en moyenne de 3 à 5 jours (72 à 120 heures) et n'est pas 'toujours' de 6 jours.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abidjan-2__ssr-pf__34\",\"num\":\"36\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"Sujet II — Questions à Choix Double (QCD : Q18 à Q45)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"La Classe 2 ou OMS 2 est une condition pour laquelle les avantages liés à l'emploi de la méthode dépassent généralement les risques théoriques ou prouvés : la méthode peut donc être utilisée.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Vrai\",\"answerLetters\":[\"A\"],\"explanation\":\"Selon les Critères de recevabilité médicale de l'OMS : Catégorie 1 = aucune restriction ; Catégorie 2 = les avantages surpassent généralement les risques théoriques ou avérés (la méthode peut être utilisée généralement) ; Catégorie 3 = les risques surpassent généralement les avantages ; Catégorie 4 = risque inacceptable (contre-indication absolue).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abidjan-2__ssr-pf__35\",\"num\":\"37\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"Sujet II — Questions à Choix Double (QCD : Q18 à Q45)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"L'efficacité est la mesure dans laquelle une méthode de contraception n'entraîne pas d'effets secondaires défavorables ou dangereux.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"L'absence d'effets secondaires dangereux ou nocifs définit l'INNOCUITÉ (ou sécurité/tolérance) de la méthode, tandis que l'EFFICACITÉ mesure sa capacité à empêcher la survenue d'une grossesse (évaluée par l'indice de Pearl).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abidjan-2__ssr-pf__36\",\"num\":\"38\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"Sujet II — Questions à Choix Double (QCD : Q18 à Q45)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Toutes les méthodes de barrière bloquent le passage des spermatozoïdes y compris les IST et les ITG.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"Parmi les méthodes de barrière (condoms, diaphragme, cape cervicale, spermicides), SEULS les préservatifs (masculin et féminin) protègent efficacement contre les IST/VIH. Les spermicides, le diaphragme et la cape cervicale ne protègent pas contre toutes les IST/VIH.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abidjan-2__ssr-pf__37\",\"num\":\"39\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"Sujet II — Questions à Choix Double (QCD : Q18 à Q45)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"À l'approche de l'ovulation, la consistance du mucus cervical (glaire cervicale) de la femme est épaisse.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"C'est l'inverse : sous l'effet du pic pré-ovulatoire d'œstrogènes, la glaire cervicale devient abondante, fluide, limpide ('blanc d'œuf cru') et filante pour faciliter l'ascension des spermatozoïdes. Elle ne devient épaisse et coagulée qu'en phase lutéale sous l'effet de la progestérone.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abidjan-2__ssr-pf__38\",\"num\":\"40\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"Sujet II — Questions à Choix Double (QCD : Q18 à Q45)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Pour la méthode du calendrier (Ogino-Knaus), le cycle le plus long moins 11 permet de déterminer le début de la période fertile de la cliente.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"Dans la formule d'Ogino-Knaus : le DÉBUT de la période fertile est égal au cycle le plus COURT moins 18, tandis que le cycle le plus LONG moins 11 détermine la FIN (dernier jour) de la période fertile !\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abidjan-2__ssr-pf__39\",\"num\":\"41\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"Sujet II — Questions à Choix Double (QCD : Q18 à Q45)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"L'utilisation de vaseline peut aider à lubrifier davantage le condom (en latex).\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"Les corps gras (vaseline, huile, beurre de karité, lait corporel) altèrent et rendent poreux le latex du préservatif masculin en quelques minutes, provoquant sa rupture. Seuls les lubrifiants à base d'eau ou de silicone sont autorisés avec le latex.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abidjan-2__ssr-pf__40\",\"num\":\"42\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"Sujet II — Questions à Choix Double (QCD : Q18 à Q45)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Après la prise des 21 pilules actives de la plaquette de Lo-Femenal (COC), l'utilisatrice doit avoir des rapports sexuels protégés durant la prise des 7 comprimés marrons (fer) pour éviter une grossesse.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"Lorsqu'une femme a pris régulièrement et sans oubli les 21 comprimés hormonaux actifs de sa plaquette de COC, l'effet contraceptif persiste pleinement pendant les 7 jours de prise des comprimés marrons (fer/placebo), à condition de débuter la plaquette suivante sans retard au 8e jour.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abidjan-2__ssr-pf__41\",\"num\":\"43\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"Sujet II — Questions à Choix Double (QCD : Q18 à Q45)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Chez une cliente sous contraceptifs oraux combinés (COC) qui présente une aménorrhée, si la notion de grossesse est écartée, il faut lui donner une pilule avec un dosage œstrogénique plus élevé (si elle souhaite le retour d'une hémorragie de privation).\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Vrai\",\"answerLetters\":[\"A\"],\"explanation\":\"L'aménorrhée sous pilule œstroprogestative minidosée est due à une atrophie endométriale marquée par insuffisance d'imprégnation œstrogénique ; après avoir éliminé une grossesse et rassuré la cliente, si l'aménorrhée la gêne, la conduite technique consiste à passer à une pilule légèrement plus dosée en éthinylestradiol (ou triphasique).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abidjan-2__ssr-pf__42\",\"num\":\"44\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"Sujet II — Questions à Choix Double (QCD : Q18 à Q45)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Les méthodes d'auto-observation reposent sur quatre principes de base communs.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Vrai\",\"answerLetters\":[\"A\"],\"explanation\":\"Dans le cours de PF de l'INFAS, les méthodes d'auto-observation reposent sur 4 principes physiologiques communs : 1) l'ovulation est unique par cycle et survient ~14 jours avant les règles suivantes, 2) l'ovule ne vit que 24 heures, 3) les spermatozoïdes survivent 3 à 5 jours dans la glaire fertile, et 4) la femme peut repérer les signes cliniques de sa phase fertile pour pratiquer l'abstinence périodique.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abidjan-2__ssr-pf__43\",\"num\":\"45\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"Sujet II — Questions à Choix Double (QCD : Q18 à Q45)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"La planification familiale du post-partum (PFPP) est l'initiation et l'utilisation des méthodes de PF durant les douze (12) premiers mois qui suivent l'accouchement.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Vrai\",\"answerLetters\":[\"A\"],\"explanation\":\"Selon l'OMS, la Planification Familiale du Post-Partum (PFPP) vise la prévention des grossesses non désirées et des grossesses trop rapprochées tout au long des 12 premiers mois suivant l'accouchement. ◆ SUJET III : ÉTUDES DE CAS N°1 (Mme Adia/Blaise) et N°2 (Mlle Apatcho) [Q46 à Q51] ----------------------------------------------------------------------- Énoncé du cas : Cas N°1 : Mme Adia a bénéficié d'un DIUPP lors de son accouchement par césarienne. Un an après, elle découvre qu'elle est séropositive au VIH et développe un SIDA. Elle consulte en PF. Cas N°2 : Mlle Apatcho, ayant accouché le 28 août 2025, allaite son bébé, n'a pas de retour de couches, présente une HTA à 15/10 cmHg et souhaite une contraception à longue durée d'action. ----------------------------------------------------------------------- -----------------------------------------------------------------------\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abidjan-2__ssr-pf__44\",\"num\":\"46\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"Sujet III — Études de cas N°1 et N°2 (Q46 à Q51)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Chez Mme Adia (porteuse d'un DIU déjà en place, qui développe un SIDA clinique et n'est pas encore sous ARV), quelle sera votre conduite à tenir ?\",\"options\":[{\"letter\":\"A\",\"text\":\"Retirer le DIU et mettre la patiente sous traitement ARV\"},{\"letter\":\"B\",\"text\":\"Donner une méthode d'appoint et initier sous ARV\"},{\"letter\":\"C\",\"text\":\"Maintenir le DIU et mettre la patiente sous traitement ARV (sous surveillance étroite des infections pelviennes)\"},{\"letter\":\"D\",\"text\":\"Faire l'examen gynécologique nécessaire et dépister des ITG\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"C. Maintenir le DIU et mettre la patiente sous traitement ARV (sous surveillance étroite des infections pelviennes)\",\"answerLetters\":[\"C\"],\"explanation\":\"Selon les Critères de recevabilité médicale de l'OMS pour le DIU en cas de SIDA clinique (stade OMS 3 ou 4 sans ARV) : l'INSERTION initiale d'un DIU est de Catégorie 3 (déconseillée tant que la patiente n'est pas stabilisée sous ARV), mais la CONTINUATION d'un DIU déjà en place est de Catégorie 2 (on maintient donc le DIU en place tout en initiant immédiatement le traitement ARV et en surveillant l'absence d'infection génitale : C).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abidjan-2__ssr-pf__45\",\"num\":\"47\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"Sujet III — Études de cas N°1 et N°2 (Q46 à Q51)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Comment appelle-t-on l'insertion du DIU effectuée chez Mme Adia/Blaise lors de son accouchement par césarienne ?\",\"options\":[{\"letter\":\"A\",\"text\":\"Insertion per-césarienne (ou post-placentaire per-césarienne)\"},{\"letter\":\"B\",\"text\":\"Insertion d'intervalle\"},{\"letter\":\"C\",\"text\":\"Insertion post-partum immédiat\"},{\"letter\":\"D\",\"text\":\"Insertion post-partum tardive\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Insertion per-césarienne (ou post-placentaire per-césarienne)\",\"answerLetters\":[\"A\"],\"explanation\":\"La pose d'un DIUPP au cours d'une césarienne (immédiatement après la délivrance artificielle du placenta, avant l'hystérorraphie) est appelée insertion per-césarienne (ou post-césarienne, A), faisant partie des insertions post-placentaires du post-partum immédiat.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abidjan-2__ssr-pf__46\",\"num\":\"48\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"Sujet III — Études de cas N°1 et N°2 (Q46 à Q51)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Le counseling spécifique est l'une des phases du counseling ; elle se fait :\",\"options\":[{\"letter\":\"A\",\"text\":\"Pendant l'accueil de la réception de la cliente\"},{\"letter\":\"B\",\"text\":\"Avant et immédiatement après la prestation de service (une fois la méthode choisie)\"},{\"letter\":\"C\",\"text\":\"Lorsque le client revient pour les consultations suivantes\"},{\"letter\":\"D\",\"text\":\"Lors de la réception du client où toutes les méthodes sont décrites\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Avant et immédiatement après la prestation de service (une fois la méthode choisie)\",\"answerLetters\":[\"B\"],\"explanation\":\"On distingue 3 phases de counseling en PF : 1) le counseling général (D : présentation de toutes les méthodes lors de l'accueil), 2) le counseling spécifique à la méthode choisie (B : juste avant et immédiatement après l'administration de la méthode pour expliquer le mode d'emploi, les effets secondaires et les signes d'alarme), et 3) le counseling de suivi (C : lors des visites de contrôle).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abidjan-2__ssr-pf__47\",\"num\":\"49\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"Sujet III — Études de cas N°1 et N°2 (Q46 à Q51)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Quelle est la dernière étape de la consultation en planification familiale (ou de la démarche BERER/BERCER) ?\",\"options\":[{\"letter\":\"A\",\"text\":\"Le diagnostic final\"},{\"letter\":\"B\",\"text\":\"La décision finale\"},{\"letter\":\"C\",\"text\":\"La prise de décision\"},{\"letter\":\"D\",\"text\":\"L'administration de la méthode (suivie du rendez-vous de retour)\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"D. L'administration de la méthode (suivie du rendez-vous de retour)\",\"answerLetters\":[\"D\"],\"explanation\":\"Dans les propositions proposées (Diagnostic → Prise de décision / Décision finale → Administration de la méthode), l'étape finale de l'acte clinique de consultation initiale est la fourniture/administration de la méthode choisie (D) assortie des instructions et du rendez-vous de suivi.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abidjan-2__ssr-pf__48\",\"num\":\"50\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"Sujet III — Études de cas N°1 et N°2 (Q46 à Q51)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Les avantages sanitaires de la planification familiale sont :\",\"options\":[{\"letter\":\"A\",\"text\":\"Réduction de la mortalité et de la morbidité maternelle, périnatale et infantile\"},{\"letter\":\"B\",\"text\":\"Meilleure préparation à la vie familiale, amélioration de la qualité de la vie\"},{\"letter\":\"C\",\"text\":\"Établissement d'un bon équilibre entre population et ressources\"},{\"letter\":\"D\",\"text\":\"Bonne hygiène de l'environnement, exploitation rationnelle de l'environnement\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Réduction de la mortalité et de la morbidité maternelle, périnatale et infantile\",\"answerLetters\":[\"A\"],\"explanation\":\"Sur le plan strictement SANITAIRE (médical), l'avantage majeur de la PF est la réduction de la morbidité et de la mortalité maternelles, néonatales et infantiles (A). Les propositions B, C et D sont des avantages socio-familiaux, démographiques et environnementaux.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"abidjan-2__ssr-pf__49\",\"num\":\"51\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"Sujet III — Études de cas N°1 et N°2 (Q46 à Q51)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Vous faites un counseling à Mlle Apatcho dans le but de (choisir la bonne réponse) :\",\"options\":[{\"letter\":\"A\",\"text\":\"Comprendre et respecter les droits du client et gagner la confiance du client\"},{\"letter\":\"B\",\"text\":\"Montrer de l'amabilité envers le client par son approche sans jugement\"},{\"letter\":\"C\",\"text\":\"Motiver le client, faciliter une prise de décision éclairée, modifier le comportement\"},{\"letter\":\"D\",\"text\":\"Comprendre les facteurs culturels influençant le choix d'une méthode\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"C. Motiver le client, faciliter une prise de décision éclairée, modifier le comportement\",\"answerLetters\":[\"C\"],\"explanation\":\"Le but opérationnel du counseling chez Mlle Apatcho (qui n'a jamais utilisé de PF et présente une HTA à 15/10 orientant vers un DIU au cuivre ou un implant progestatif) est de l'informer, de faciliter sa prise de décision éclairée et d'induire l'adoption d'un comportement contraceptif adapté (c). Les items a, b et d sont des attitudes et principes de communication du prestataire. +-----------------------------------------------------------------------+ Épreuves : Santé Publique (Q1-Q43) | Pédiatrie Bloc C (Q1-Q50) | Gynécologie-Obstétrique (QCD 1-20 & QCM 1-14bis) | PF/SSR (Q1-Q50) +=======================================================================+ +-----------------------------------------------------------------------+ +-----------------------------------------------------------------------+\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null}]}]},{\"name\":\"ABOISSO (S2 : 2025)\",\"slug\":\"aboisso-2\",\"session\":\"S2\",\"annee\":2025,\"existe\":true,\"sujets\":[{\"name\":\"Gynéco-obstétrique\",\"slug\":\"gynecologie-obstetrique\",\"pages\":\"\",\"count\":35,\"session\":\"S2\",\"annee\":2025,\"source\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"questions\":[{\"id\":\"aboisso-2__gynecologie-obstetrique__0\",\"num\":\"1\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"I. Questions à Choix Direct (QCD : Q1 à Q20)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Le développement simultané de trois fœtus dans la cavité utérine est considéré comme une grossesse gémellaire.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"Le développement simultané de DEUX fœtus est une grossesse gémellaire ; le développement simultané de TROIS fœtus est une grossesse TRIPLE (triplés).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"aboisso-2__gynecologie-obstetrique__1\",\"num\":\"2\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"I. Questions à Choix Direct (QCD : Q1 à Q20)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"L'anémie se définit au cours de la grossesse comme une baisse de l'hémoglobine inférieure à 12 g/dl.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"En raison de l'hémodilution physiologique gravidique, le seuil définissant l'anémie chez la femme enceinte selon l'OMS est un taux d'hémoglobine strictement INFÉRIEUR À 11 g/dl (< 11 g/dl aux 1er et 3e trimestres, et < 10,5 g/dl au 2e trimestre) ; 12 g/dl est le seuil chez la femme non enceinte.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"aboisso-2__gynecologie-obstetrique__2\",\"num\":\"3\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"I. Questions à Choix Direct (QCD : Q1 à Q20)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"L'épreuve utérine est une confrontation céphalo-pelvienne qui consiste à conduire un accouchement par voie basse sur un bassin limite.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"La confrontation dynamique céphalo-pelvienne sur un bassin limite (avec utérus sain) s'appelle l'ÉPREUVE DU TRAVAIL. L'ÉPREUVE UTÉRINE désigne quant à elle la tentative d'accouchement par voie basse sur un UTÉRUS CICATRICIEL (antécédent de césarienne).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"aboisso-2__gynecologie-obstetrique__3\",\"num\":\"4\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"I. Questions à Choix Direct (QCD : Q1 à Q20)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Dans les grossesses gémellaires bi-ovulaires, les fœtus sont toujours de sexe différent.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"Les jumeaux dizygotes (bi-ovulaires) résultent de la fécondation de deux ovocytes distincts par deux spermatozoïdes : ils peuvent être aussi bien de même sexe (50 % des cas : deux garçons ou deux filles) que de sexe différent (50 % des cas).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"aboisso-2__gynecologie-obstetrique__4\",\"num\":\"5\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"I. Questions à Choix Direct (QCD : Q1 à Q20)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Un score de BISHOP à 8 traduit que le pronostic d'accouchement par voie basse (maturation cervicale pour déclenchement) est favorable.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Vrai\",\"answerLetters\":[\"A\"],\"explanation\":\"Un score de Bishop ≥ 6 (et a fortiori ≥ 7 ou 8) indique que le col utérin est mûr et favorable à un déclenchement artificiel du travail par perfusion d'ocytocine.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"aboisso-2__gynecologie-obstetrique__5\",\"num\":\"6\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"I. Questions à Choix Direct (QCD : Q1 à Q20)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Dans les grossesses gémellaires bi-ovulaires, chaque œuf a son placenta et ses membranes propres.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Vrai\",\"answerLetters\":[\"A\"],\"explanation\":\"Les grossesses gémellaires dizygotes (bi-ovulaires) sont TOUJOURS bichoriales biamniotiques : chaque fœtus possède son propre chorion (placenta) et son propre amnios.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"aboisso-2__gynecologie-obstetrique__6\",\"num\":\"7\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"I. Questions à Choix Direct (QCD : Q1 à Q20)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"La cause la plus fréquente en cas d'anémie macrocytaire (pendant la grossesse) est une carence en acide folique.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Vrai\",\"answerLetters\":[\"A\"],\"explanation\":\"L'anémie macrocytaire (VGM > 100 fl) mégaloblastique de la femme enceinte est principalement due à une carence en acide folique (vitamine B9) par augmentation des besoins fœto-placentaires.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"aboisso-2__gynecologie-obstetrique__7\",\"num\":\"8\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"I. Questions à Choix Direct (QCD : Q1 à Q20)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Dans la prévention de l'anémie au cours de la grossesse, l'OMS recommande 50 mg de fer ferreux par jour.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"En prophylaxie martiale pendant la grossesse, l'OMS recommande une supplémentation quotidienne de 30 à 60 mg de FER ÉLÉMENT (généralement 60 mg de fer élément + 400 µg d'acide folique par jour, correspondant à ~200 mg de sulfate ferreux).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"aboisso-2__gynecologie-obstetrique__8\",\"num\":\"9\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"I. Questions à Choix Direct (QCD : Q1 à Q20)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Dans les grossesses gémellaires bi-ovulaires, si les fœtus sont de même sexe, ce sont de vrais jumeaux.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"Les jumeaux issus d'une grossesse bi-ovulaire (dizygote) sont TOUJOURS de faux jumeaux (génétiquement différents comme deux frères ou deux sœurs), même lorsqu'ils sont de même sexe.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"aboisso-2__gynecologie-obstetrique__9\",\"num\":\"10\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"I. Questions à Choix Direct (QCD : Q1 à Q20)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Le score de BISHOP est coté de 0 à 10.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"Le score de Bishop comprend 5 paramètres (dilatation, effacement, consistance, position du col et hauteur de la présentation) : les 3 premiers sont cotés de 0 à 3 et les 2 autres de 0 à 2, soit un score total coté de 0 à 13 (et non de 0 à 10, qui est la cotation du score d'Apgar).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"aboisso-2__gynecologie-obstetrique__10\",\"num\":\"11\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"I. Questions à Choix Direct (QCD : Q1 à Q20)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"L'accouchement de siège est un accouchement potentiellement dystocique.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Vrai\",\"answerLetters\":[\"A\"],\"explanation\":\"L'accouchement en présentation du siège est classé à la frontière de l'eutocie et de la dystocie (accouchement potentiellement dystocique) en raison du risque de relèvement des bras et de rétention de la tête dernière.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"aboisso-2__gynecologie-obstetrique__11\",\"num\":\"12\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"I. Questions à Choix Direct (QCD : Q1 à Q20)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"La manœuvre de BRACHT est une attitude dite abstentionniste au cours de l'accouchement de siège.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"L'attitude purement abstentionniste est la méthode de VERMELIN. La manœuvre de BRACHT consiste à saisir le siège et les membres inférieurs à deux mains dès l'apparition des omoplates et à basculer le dos du fœtus vers le ventre de la mère.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"aboisso-2__gynecologie-obstetrique__12\",\"num\":\"13\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"I. Questions à Choix Direct (QCD : Q1 à Q20)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"La complication majeure de la grossesse prolongée est la souffrance fœtale chronique (et aiguë par sénescence placentaire et oligoamnios).\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Vrai\",\"answerLetters\":[\"A\"],\"explanation\":\"Au-delà de 41-42 SA, la sénescence placentaire (calcifications, diminution des échanges fœto-maternels) et l'oligoamnios entraînent une hypoxie fœtale progressive (souffrance fœtale chronique puis aiguë per-partum avec liquide méconial et risque de MFIU).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"aboisso-2__gynecologie-obstetrique__13\",\"num\":\"14\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"I. Questions à Choix Direct (QCD : Q1 à Q20)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Dans la grossesse gémellaire, l'accouchement se fait classiquement en quatre temps.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Vrai\",\"answerLetters\":[\"A\"],\"explanation\":\"Les 4 temps classiques de l'accouchement gémellaire sont : 1er temps = accouchement du 1er jumeau (J1) ; 2e temps = intervalle libre ou phase de rémission clinique (10 à 15 min) ; 3e temps = accouchement du 2e jumeau (J2) ; 4e temps = délivrance (dirigée/GATPA).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"aboisso-2__gynecologie-obstetrique__14\",\"num\":\"15\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"I. Questions à Choix Direct (QCD : Q1 à Q20)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"En cas d'échec de l'épreuve du travail, une césarienne s'impose en urgence.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Vrai\",\"answerLetters\":[\"A\"],\"explanation\":\"L'échec de l'épreuve du travail (défaut d'engagement, stagnation de la dilatation malgré une bonne dynamique utérine ou apparition d'une souffrance fœtale aiguë) impose l'arrêt immédiat de l'épreuve et l'extraction fœtale par césarienne en urgence.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"aboisso-2__gynecologie-obstetrique__15\",\"num\":\"16\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"I. Questions à Choix Direct (QCD : Q1 à Q20)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Les grossesses gémellaires uniovulaires sont issues toujours de la fécondation d'un ovule par un spermatozoïde.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Vrai\",\"answerLetters\":[\"A\"],\"explanation\":\"Les grossesses gémellaires monozygotes (uniovulaires : vrais jumeaux) proviennent de la fécondation d'un seul ovocyte par un seul spermatozoïde, suivie d'une division précoce de l'œuf unique en deux embryons.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"aboisso-2__gynecologie-obstetrique__16\",\"num\":\"17\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"I. Questions à Choix Direct (QCD : Q1 à Q20)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Un diabète équilibré (à terme, vers 38-39 SA) est une indication du déclenchement artificiel du travail.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Vrai\",\"answerLetters\":[\"A\"],\"explanation\":\"Dans les cours d'obstétrique INFAS, le diabète associé à la grossesse (sous insuline ou à terme à 38-39 SA pour prévenir la MFIU tardive et la dystocie des épaules) figure parmi les indications médicales classiques du déclenchement artificiel du travail lorsque les conditions locales (Bishop) et mécaniques sont favorables.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"aboisso-2__gynecologie-obstetrique__17\",\"num\":\"18\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"I. Questions à Choix Direct (QCD : Q1 à Q20)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Dans la grossesse gémellaire uniovulaire, les fœtus peuvent être de sexe différent.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"Issus de la division d'un seul zygote, les jumeaux monozygotes (uniovulaires) possèdent exactement le même patrimoine génétique et sont donc TOUJOURS de même sexe.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"aboisso-2__gynecologie-obstetrique__18\",\"num\":\"19\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"I. Questions à Choix Direct (QCD : Q1 à Q20)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Le score de BISHOP permet d'apprécier les conditions locales en vue d'un déclenchement artificiel.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Vrai\",\"answerLetters\":[\"A\"],\"explanation\":\"Le score de Bishop évalue la maturité cervicale (conditions locales du col et de la présentation) pour décider de la modalité d'un déclenchement artificiel du travail.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"aboisso-2__gynecologie-obstetrique__19\",\"num\":\"20\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"I. Questions à Choix Direct (QCD : Q1 à Q20)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Dans la grossesse gémellaire monochoriale et biamniotique, il existe deux placentas et une cavité amniotique.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"C'est exactement l'inverse : 'monochoriale' signifie UN SEUL placenta (chorion), et 'biamniotique' signifie DEUX cavités amniotiques séparées par une fine cloison interamniotique.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"aboisso-2__gynecologie-obstetrique__20\",\"num\":\"1\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"II. Questions à Choix Multiples (QCM : 1 à 14bis)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Parmi les propositions suivantes, deux caractérisent les grossesses gémellaires uniovulaires bichoriales et biamniotiques : lesquelles ?\",\"options\":[{\"letter\":\"A\",\"text\":\"Les fœtus sont de même sexe ou de sexe différent\"},{\"letter\":\"B\",\"text\":\"Les fœtus sont toujours de même sexe\"},{\"letter\":\"C\",\"text\":\"Il existe 2 placentas distincts et 2 cavités amniotiques\"},{\"letter\":\"D\",\"text\":\"Ce sont les faux jumeaux\"},{\"letter\":\"E\",\"text\":\"Ils peuvent donner des siamois\"}],\"mode\":\"mcq\",\"multi\":true,\"answer\":\"B et C\",\"answerLetters\":[\"B\",\"C\"],\"explanation\":\"Lorsque la division d'un œuf unique (grossesse uniovulaire/monozygote) survient très tôt (avant le 3e-4e jour post-fécondation, au stade morula), elle donne une grossesse bichoriale biamniotique (2 placentas et 2 poches amniotiques : c), mais comme elle est uniovulaire, ce sont de vrais jumeaux TOUJOURS de même sexe (b).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"aboisso-2__gynecologie-obstetrique__21\",\"num\":\"2\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"II. Questions à Choix Multiples (QCM : 1 à 14bis)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Parmi les conditions suivantes, deux doivent être respectées pour la réalisation de l'épreuve utérine (ou épreuve du travail) :\",\"options\":[{\"letter\":\"A\",\"text\":\"Poids fœtal estimé à 4 000 g\"},{\"letter\":\"B\",\"text\":\"Présentation du sommet\"},{\"letter\":\"C\",\"text\":\"Hauteur utérine à 32 cm\"},{\"letter\":\"D\",\"text\":\"Diamètre bipariétal à 100 mm\"},{\"letter\":\"E\",\"text\":\"Bassin limite (pour l'épreuve du travail ; bassin normal et HU ≤ 32 cm pour l'épreuve utérine)\"}],\"mode\":\"mcq\",\"multi\":true,\"answer\":\"B et C\",\"answerLetters\":[\"B\",\"C\"],\"explanation\":\"Que ce soit pour l'épreuve utérine ou l'épreuve du travail, le fœtus doit impérativement être en présentation céphalique bien fléchie du SOMMET (b) et de poids normal sans macrosomie (HU ≤ 32 cm : c ; un poids de 4 000 g ou un BIP de 100 mm contre-indiquent l'épreuve).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"aboisso-2__gynecologie-obstetrique__22\",\"num\":\"3\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"II. Questions à Choix Multiples (QCM : 1 à 14bis)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Dans l'accouchement gémellaire, deux gestes sont à réaliser au cours de la phase de rémission (2e temps après la naissance de J1) : lesquels ?\",\"options\":[{\"letter\":\"A\",\"text\":\"Référer la patiente\"},{\"letter\":\"B\",\"text\":\"Mettre une perfusion d'ocytocine\"},{\"letter\":\"C\",\"text\":\"Vérifier la présentation de J2\"},{\"letter\":\"D\",\"text\":\"Écouter les bruits du cœur de J2\"},{\"letter\":\"E\",\"text\":\"Faire une extraction de siège de J2\"}],\"mode\":\"mcq\",\"multi\":true,\"answer\":\"C et D\",\"answerLetters\":[\"C\",\"D\"],\"explanation\":\"Immédiatement après l'accouchement de J1 et le clampage de son cordon, pendant la phase de rémission (repos utérin), l'accoucheur doit : 1) ausculter les BDCF de J2 (d), et 2) vérifier par le palper abdominal et le toucher vaginal la présentation de J2 et l'intégrité de la 2e poche des eaux (c).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"aboisso-2__gynecologie-obstetrique__23\",\"num\":\"4\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"II. Questions à Choix Multiples (QCM : 1 à 14bis)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Parmi les propositions suivantes, deux conditions ne respectent pas la conduite de l'épreuve utérine : lesquelles ?\",\"options\":[{\"letter\":\"A\",\"text\":\"Doit être réalisée en milieu médico-chirurgical\"},{\"letter\":\"B\",\"text\":\"Bilan préopératoire et consultation pré-anesthésique non obligatoires\"},{\"letter\":\"C\",\"text\":\"Peut être réalisée dans un établissement de SONU B\"},{\"letter\":\"D\",\"text\":\"Matériel de surveillance fœtale disponible\"},{\"letter\":\"E\",\"text\":\"Information de la patiente sur l'issue et la possibilité de la césarienne\"}],\"mode\":\"mcq\",\"multi\":true,\"answer\":\"B et C\",\"answerLetters\":[\"B\",\"C\"],\"explanation\":\"L'épreuve utérine (accouchement sur utérus cicatriciel) comporte un risque de rupture utérine : elle ne peut JAMAIS être conduite en SONU de base (SONU B sans bloc opératoire, c est faux) et exige obligatoirement un bilan préopératoire et une consultation d'anesthésie prêts en SONU Complet (b est faux).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"aboisso-2__gynecologie-obstetrique__24\",\"num\":\"5\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"II. Questions à Choix Multiples (QCM : 1 à 14bis)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Parmi les assertions suivantes, deux signes sont retrouvés dans la grossesse gémellaire à l'examen physique : lesquels ?\",\"options\":[{\"letter\":\"A\",\"text\":\"La hauteur utérine est égale à l'âge gestationnel\"},{\"letter\":\"B\",\"text\":\"On perçoit 2 foyers d'auscultation différents (des BDCF)\"},{\"letter\":\"C\",\"text\":\"Le segment inférieur se forme tardivement\"},{\"letter\":\"D\",\"text\":\"L'utérus est trop globuleux (hauteur utérine excessive pour le terme)\"},{\"letter\":\"E\",\"text\":\"Les signes sympathiques sont moins marqués\"}],\"mode\":\"mcq\",\"multi\":true,\"answer\":\"B et D\",\"answerLetters\":[\"B\",\"D\"],\"explanation\":\"À l'examen physique d'une grossesse gémellaire, l'inspection et la mensuration montrent un utérus surdistendu, trop gros/globuleux avec une hauteur utérine supérieure de +4 cm à la normale pour le terme (d), la palpation perçoit au moins 3 pôles fœtaux, et l'auscultation perçoit deux foyers distincts de BDCF non synchrones (b).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"aboisso-2__gynecologie-obstetrique__25\",\"num\":\"6\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"II. Questions à Choix Multiples (QCM : 1 à 14bis)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Parmi les propositions suivantes, deux sont des contre-indications absolues du déclenchement artificiel du travail : lesquelles ?\",\"options\":[{\"letter\":\"A\",\"text\":\"Grossesse prolongée\"},{\"letter\":\"B\",\"text\":\"Prématurité\"},{\"letter\":\"C\",\"text\":\"Souffrance fœtale aiguë\"},{\"letter\":\"D\",\"text\":\"Grande multiparité (et utérus cicatriciel/fragilisé)\"},{\"letter\":\"E\",\"text\":\"Pré-éclampsie\"}],\"mode\":\"mcq\",\"multi\":true,\"answer\":\"C et D\",\"answerLetters\":[\"C\",\"D\"],\"explanation\":\"La souffrance fœtale aiguë (c, qui impose une extraction immédiate par césarienne car le fœtus ne supporterait pas le stress des contractions induites) et la grande multiparité / utérus fragilisé (d, risque majeur de rupture utérine sous ocytociques) — ainsi que la prématurité hors indication médicale d'arrêt de grossesse (b) — contre-indiquent le déclenchement artificiel.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"aboisso-2__gynecologie-obstetrique__26\",\"num\":\"7\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"II. Questions à Choix Multiples (QCM : 1 à 14bis)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Parmi les propositions suivantes, deux sont des complications maternelles (ou obstétricales) rencontrées au cours de la grossesse gémellaire : lesquelles ?\",\"options\":[{\"letter\":\"A\",\"text\":\"La pré-éclampsie (toxémie gravidique)\"},{\"letter\":\"B\",\"text\":\"L'hématome rétroplacentaire\"},{\"letter\":\"C\",\"text\":\"La prématurité\"},{\"letter\":\"D\",\"text\":\"Le placenta praevia\"},{\"letter\":\"E\",\"text\":\"L'hydramnios\"}],\"mode\":\"mcq\",\"multi\":true,\"answer\":\"A et D\",\"answerLetters\":[\"A\",\"D\"],\"explanation\":\"Chez la mère porteuse d'une grossesse gémellaire, la pré-éclampsie (a, 3 à 4 fois plus fréquente) et le placenta praevia (d, lié à l'étalement de la grande masse placentaire sur le segment inférieur) [ainsi que l'anémie maternelle] sont les complications maternelles classiques, tandis que la prématurité (c) est la complication fœtale n°1.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"aboisso-2__gynecologie-obstetrique__27\",\"num\":\"8\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"II. Questions à Choix Multiples (QCM : 1 à 14bis)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Parmi les complications suivantes, deux sont fréquentes au cours de l'accouchement gémellaire : lesquelles ?\",\"options\":[{\"letter\":\"A\",\"text\":\"L'hémorragie du post-partum (par atonie utérine de surdistension)\"},{\"letter\":\"B\",\"text\":\"Les grossesses prolongées\"},{\"letter\":\"C\",\"text\":\"La procidence du cordon (notamment à la rupture de la poche de J2)\"},{\"letter\":\"D\",\"text\":\"Le placenta praevia\"},{\"letter\":\"E\",\"text\":\"La rupture utérine\"}],\"mode\":\"mcq\",\"multi\":true,\"answer\":\"A et C\",\"answerLetters\":[\"A\",\"C\"],\"explanation\":\"Au cours de l'accouchement gémellaire, les deux complications per- et post-partum majeures sont la procidence du cordon (c, favorisée par l'hydramnios et les présentations dystociques de J2 lors de la rupture des membranes) et l'hémorragie de la délivrance par inertie/atonie utérine liée à la surdistension myométriale (a).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"aboisso-2__gynecologie-obstetrique__28\",\"num\":\"9\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"II. Questions à Choix Multiples (QCM : 1 à 14bis)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Parmi les diagnostics différentiels de la grossesse gémellaire (devant un gros utérus), deux se rencontrent au 1er trimestre : lesquels ?\",\"options\":[{\"letter\":\"A\",\"text\":\"Un hydramnios\"},{\"letter\":\"B\",\"text\":\"Une erreur sur la date des dernières règles (erreur de terme)\"},{\"letter\":\"C\",\"text\":\"Une grossesse molaire (môle hydatiforme)\"},{\"letter\":\"D\",\"text\":\"Un gros fœtus (macrosomie)\"},{\"letter\":\"E\",\"text\":\"Une grossesse extra-utérine\"}],\"mode\":\"mcq\",\"multi\":true,\"answer\":\"B et C\",\"answerLetters\":[\"B\",\"C\"],\"explanation\":\"Au 1er trimestre, un utérus plus gros que l'âge gestationnel présumé fait discuter : une erreur de terme sur la DDR (b), une grossesse molaire / môle hydatiforme (c), ou un fibrome utérin associé à la grossesse. En revanche, l'hydramnios (a) et la macrosomie fœtale (d) sont des diagnostics différentiels des 2e et 3e trimestres (et la GEU donne un utérus plus petit que le terme).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"aboisso-2__gynecologie-obstetrique__29\",\"num\":\"10\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"II. Questions à Choix Multiples (QCM : 1 à 14bis)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Parmi les manœuvres suivantes, une se réalise lors de la rétention de la tête du fœtus dans l'excavation pelvienne au cours de l'accouchement de siège : laquelle ?\",\"options\":[{\"letter\":\"A\",\"text\":\"La manœuvre de BRACHT\"},{\"letter\":\"B\",\"text\":\"La manœuvre de LOVSET\"},{\"letter\":\"C\",\"text\":\"La manœuvre de VERMELIN\"},{\"letter\":\"D\",\"text\":\"La manœuvre de MAURICEAU\"},{\"letter\":\"E\",\"text\":\"La grande extraction de siège\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"D. La manœuvre de MAURICEAU\",\"answerLetters\":[\"D\"],\"explanation\":\"En cas de rétention de la tête dernière dans l'excavation pelvienne (partie moyenne/basse), la manœuvre obstétricale spécifique permettant de fléchir, orienter et extraire la tête est la manœuvre de MAURICEAU (d) [tandis que Champetier de Ribes concerne la rétention de tête dernière haute au détroit supérieur, et Lovset le relèvement des bras].\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"aboisso-2__gynecologie-obstetrique__30\",\"num\":\"11\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"II. Questions à Choix Multiples (QCM : 1 à 14bis)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Parmi les propositions suivantes, deux sont des complications fœtales rencontrées au cours de l'anémie pendant la grossesse : lesquelles ?\",\"options\":[{\"letter\":\"A\",\"text\":\"Prématurité\"},{\"letter\":\"B\",\"text\":\"Disproportion fœto-pelvienne\"},{\"letter\":\"C\",\"text\":\"Endométrite\"},{\"letter\":\"D\",\"text\":\"Souffrance fœtale aiguë (et RCIU/MFIU)\"},{\"letter\":\"E\",\"text\":\"Hémorragie du post-partum immédiat\"}],\"mode\":\"mcq\",\"multi\":true,\"answer\":\"A et D\",\"answerLetters\":[\"A\",\"D\"],\"explanation\":\"L'anémie maternelle réduit l'oxygénation fœto-placentaire, exposant le fœtus à la prématurité (a), au retard de croissance intra-utérin (RCIU), à la souffrance fœtale chronique/aiguë (d) et à la mort fœtale in utero. L'endométrite (c) et l'HPP (e) sont des complications maternelles.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"aboisso-2__gynecologie-obstetrique__31\",\"num\":\"12\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"II. Questions à Choix Multiples (QCM : 1 à 14bis)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Parmi les propositions suivantes, deux sont des contre-indications à la voie basse devant un accouchement de siège : lesquelles ?\",\"options\":[{\"letter\":\"A\",\"text\":\"Bassin limite (ou rétréci)\"},{\"letter\":\"B\",\"text\":\"Grossesse gémellaire avec J1 en présentation céphalique\"},{\"letter\":\"C\",\"text\":\"Mort fœtale in utero\"},{\"letter\":\"D\",\"text\":\"Antécédent de césarienne (utérus cicatriciel)\"},{\"letter\":\"E\",\"text\":\"Patiente PTME\"}],\"mode\":\"mcq\",\"multi\":true,\"answer\":\"A et D\",\"answerLetters\":[\"A\",\"D\"],\"explanation\":\"L'accouchement du siège par voie basse exige un bassin strictement normal et un utérus sain : un bassin limite/rétréci (a) et un utérus cicatriciel (antécédent de césarienne, d) sont des contre-indications classiques à la voie basse en présentation du siège.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"aboisso-2__gynecologie-obstetrique__32\",\"num\":\"13\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"II. Questions à Choix Multiples (QCM : 1 à 14bis)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Parmi les propositions suivantes, deux ne font pas partie des paramètres du score de BISHOP (noté par coquille 'APGAR' dans le sujet, mais les items b, c, e sont ceux de Bishop) : lesquels ?\",\"options\":[{\"letter\":\"A\",\"text\":\"Les BDCF\"},{\"letter\":\"B\",\"text\":\"La présentation (hauteur)\"},{\"letter\":\"C\",\"text\":\"La consistance (du col)\"},{\"letter\":\"D\",\"text\":\"Le bassin\"},{\"letter\":\"E\",\"text\":\"La position (du col)\"}],\"mode\":\"mcq\",\"multi\":true,\"answer\":\"A et D\",\"answerLetters\":[\"A\",\"D\"],\"explanation\":\"Il s'agit d'une coquille typographique du sujet pour 'score de BISHOP' : la hauteur de la présentation (b), la consistance du col (c) et la position du col (e) [avec la dilatation et l'effacement] sont les 5 paramètres du score de Bishop. Les BDCF (a) et l'état du bassin (d) n'en font pas partie.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"aboisso-2__gynecologie-obstetrique__33\",\"num\":\"14\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"II. Questions à Choix Multiples (QCM : 1 à 14bis)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Parmi les assertions suivantes, deux sont des contre-indications à l'épreuve du travail : lesquelles ?\",\"options\":[{\"letter\":\"A\",\"text\":\"Les utérus cicatriciels\"},{\"letter\":\"B\",\"text\":\"Une dilatation cervicale de 4 cm\"},{\"letter\":\"C\",\"text\":\"Les présentations de siège\"},{\"letter\":\"D\",\"text\":\"Une bonne dynamique utérine\"},{\"letter\":\"E\",\"text\":\"Une surveillance fœtale\"}],\"mode\":\"mcq\",\"multi\":true,\"answer\":\"A et C\",\"answerLetters\":[\"A\",\"C\"],\"explanation\":\"L'épreuve du travail (sur bassin limite) est formellement contre-indiquée en cas d'utérus cicatriciel (a, risque de rupture utérine) et en cas de présentation autre que le sommet, notamment la présentation du siège (c, risque de rétention de tête dernière sur bassin limite).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"aboisso-2__gynecologie-obstetrique__34\",\"num\":\"14bis\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"II. Questions à Choix Multiples (QCM : 1 à 14bis)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Parmi les pathologies suivantes, une ne fait pas partie des suites de couches pathologiques : laquelle ?\",\"options\":[{\"letter\":\"A\",\"text\":\"L'endométrite\"},{\"letter\":\"B\",\"text\":\"Le baby-blues\"},{\"letter\":\"C\",\"text\":\"La phlébite\"},{\"letter\":\"D\",\"text\":\"La chorioamniotite\"},{\"letter\":\"E\",\"text\":\"La galactophorite\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"D. La chorioamniotite\",\"answerLetters\":[\"D\"],\"explanation\":\"La chorioamniotite (infection de la cavité amniotique, des membranes et du liquide amniotique) est une pathologie de la GROSSESSE et du TRAVAIL, et non des suites de couches (puisque le placenta et les membranes ont été expulsés à la délivrance). +-----------------------------------------------------------------------+\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null}]},{\"name\":\"SSR / PF\",\"slug\":\"ssr-pf\",\"pages\":\"\",\"count\":50,\"session\":\"S2\",\"annee\":2025,\"source\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"questions\":[{\"id\":\"aboisso-2__ssr-pf__0\",\"num\":\"1\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"I. Questions à Choix Double (QCD : Q1 à Q20)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"La cystite isolée aiguë est l'infection urinaire la plus rencontrée au cours de la grossesse.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"L'infection urinaire la plus fréquemment rencontrée au cours de la grossesse est la BACTÉRIURIE ASYMPTOMATIQUE (5 à 10 % des femmes enceintes, confirmée par la Q49 de cette même épreuve) et non la cystite aiguë (1 à 2 %).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"aboisso-2__ssr-pf__1\",\"num\":\"2\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"I. Questions à Choix Double (QCD : Q1 à Q20)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Le test de Coombs indirect consiste à rechercher des agglutinines irrégulières après injection d'une dose d'immunoglobulines.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"La Recherche d'Agglutinines Irrégulières (RAI / test de Coombs indirect) se réalise AVANT toute injection de gammaglobulines anti-D (sérum anti-D / Rhophylac) pour vérifier que la femme Rhésus négatif n'est pas déjà allo-immunisée (si on la fait juste après l'injection, le test détecte passivement les anticorps injectés).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"aboisso-2__ssr-pf__2\",\"num\":\"3\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"I. Questions à Choix Double (QCD : Q1 à Q20)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Dans l'accouchement de siège, en cas de rétention des épaules (relèvement des bras), l'attitude de Lovset est préconisée.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Vrai\",\"answerLetters\":[\"A\"],\"explanation\":\"La manœuvre de Lovset (double rotation axiale de 180° associée à une traction vers le bas) est la manœuvre de référence pour abaisser et dégager les épaules et les bras relevés lors d'un accouchement en présentation du siège.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"aboisso-2__ssr-pf__3\",\"num\":\"4\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"I. Questions à Choix Double (QCD : Q1 à Q20)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"La césarienne programmée n'est pas retenue comme stratégie nationale systématique de PTME en Côte d'Ivoire.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Vrai\",\"answerLetters\":[\"A\"],\"explanation\":\"En Côte d'Ivoire (et selon l'OMS en contexte de ressources limitées), la stratégie nationale d'eTME repose sur la trithérapie antirétrovirale maternelle précoce à vie (Option B+) permettant l'accouchement par voie basse sécurisée ; la césarienne n'est pratiquée que sur indication obstétricale.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"aboisso-2__ssr-pf__4\",\"num\":\"5\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"I. Questions à Choix Double (QCD : Q1 à Q20)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"La galactophorite se manifeste par la présence de lait mêlé à du pus lors de l'expression du mamelon.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Vrai\",\"answerLetters\":[\"A\"],\"explanation\":\"C'est le signe de BUDIN positif (le lait exprimé du mamelon sur une compresse laisse une tache jaunâtre purulente qui ne s'étale pas), pathognomonique de la galactophorite (mastite infectieuse canaliculaire) et imposant l'arrêt temporaire de la mise au sein du côté atteint (on tire et on jette le lait).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"aboisso-2__ssr-pf__5\",\"num\":\"6\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"I. Questions à Choix Double (QCD : Q1 à Q20)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"L'infertilité est l'absence de survenue d'une grossesse après 1 an de rapports sexuels réguliers sous contraception.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"L'infertilité se définit après 1 an (12 mois) de rapports sexuels réguliers SANS contraception.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"aboisso-2__ssr-pf__6\",\"num\":\"7\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"I. Questions à Choix Double (QCD : Q1 à Q20)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Une mère de groupe sanguin A positif et le conjoint de groupe B peuvent donner naissance à un enfant de groupe O.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Vrai\",\"answerLetters\":[\"A\"],\"explanation\":\"Si la mère est de génotype hétérozygote A/O et le père de génotype B/O, ils ont 25 % de chances à chaque grossesse de concevoir un enfant homozygote O/O (groupe O).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"aboisso-2__ssr-pf__7\",\"num\":\"8\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"I. Questions à Choix Double (QCD : Q1 à Q20)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"La drépanocytose est une hémoglobinopathie quantitative.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"La drépanocytose est une hémoglobinopathie QUALITATIVE (de structure : mutation ponctuelle donnant l'HbS). Ce sont les thalassémies qui sont des hémoglobinopathies quantitatives.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"aboisso-2__ssr-pf__8\",\"num\":\"9\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"I. Questions à Choix Double (QCD : Q1 à Q20)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Le fibrome utérin est une masse pelvienne indépendante de l'utérus.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"Le fibrome utérin est une tumeur bénigne du myomètre qui fait corps avec l'utérus (solidarité utéro-tumorale sans sillon de séparation, sauf le fibrome sous-séreux longuement pédiculé).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"aboisso-2__ssr-pf__9\",\"num\":\"10\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"I. Questions à Choix Double (QCD : Q1 à Q20)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"La pré-éclampsie surajoutée est l'association d'une HTA chronique (préexistante avant 20 SA) à une protéinurie positive apparaissant après 20 SA.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Vrai\",\"answerLetters\":[\"A\"],\"explanation\":\"Par définition, la pré-éclampsie surajoutée est la greffe d'une protéinurie significative (≥ 300 mg/24h ou ≥ ++ à la bandelette) à partir de 20 SA chez une femme porteuse d'une HTA chronique connue avant la grossesse ou découverte avant 20 SA.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"aboisso-2__ssr-pf__10\",\"num\":\"11\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"I. Questions à Choix Double (QCD : Q1 à Q20)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Dans le diabète gestationnel, le dépistage par HGPO se fait à la 24ème Semaine d'Aménorrhée (entre 24 et 28 SA).\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Vrai\",\"answerLetters\":[\"A\"],\"explanation\":\"L'HGPO à 75 g de glucose pour le dépistage du diabète gestationnel se pratique entre 24 et 28 SA, donc dès 24 SA.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"aboisso-2__ssr-pf__11\",\"num\":\"12\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"I. Questions à Choix Double (QCD : Q1 à Q20)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Le cycle menstruel se déroule de la puberté à la ménopause et n'est interrompu par aucun facteur.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"Au cours de la vie génitale active, le cycle menstruel est physiologiquement interrompu par la GROSSESSE et l'ALLAITEMENT (aménorrhée gravidique et lactée), ainsi que par diverses causes pathologiques ou contraceptives.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"aboisso-2__ssr-pf__12\",\"num\":\"13\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"I. Questions à Choix Double (QCD : Q1 à Q20)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"L'accrochage des mentons au cours d'un accouchement gémellaire peut survenir si J1 est en présentation de siège et J2 en présentation céphalique.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Vrai\",\"answerLetters\":[\"A\"],\"explanation\":\"Oui ! C'est exactement la configuration anatomique (J1 en siège et J2 en céphalique) qui expose au risque d'accrochage de la tête dernière de J1 par la tête première de J2.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"aboisso-2__ssr-pf__13\",\"num\":\"14\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"I. Questions à Choix Double (QCD : Q1 à Q20)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Dans la présentation de la face, le repère est le menton.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Vrai\",\"answerLetters\":[\"A\"],\"explanation\":\"Le repère de la présentation de la face (tête totalement défléchie) est le MENTON (qui doit obligatoirement tourner en avant sous la symphyse pubienne, en mento-pubienne, pour que l'accouchement par voie basse soit possible).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"aboisso-2__ssr-pf__14\",\"num\":\"15\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"I. Questions à Choix Double (QCD : Q1 à Q20)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"L'hypophyse intervient dans le cycle menstruel au niveau central.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Vrai\",\"answerLetters\":[\"A\"],\"explanation\":\"L'axe gonadotrope qui régule le cycle menstruel comporte un étage central (complexe hypothalamo-hypophysaire sécrétant GnRH puis FSH et LH) et un étage périphérique (ovaires et endomètre).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"aboisso-2__ssr-pf__15\",\"num\":\"16\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"I. Questions à Choix Double (QCD : Q1 à Q20)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"La souffrance fœtale aiguë se traduit par une altération du rythme cardiaque fœtal sans retard de croissance intra-utérin (lorsqu'elle survient sur un fœtus initialement sain au cours du travail).\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Vrai\",\"answerLetters\":[\"A\"],\"explanation\":\"La souffrance fœtale aiguë (SFA) est un accident hypoxique brutal per-partum se traduisant par des anomalies du RCF (bradycardie < 110 bpm, tachycardie > 160 bpm, décélérations tardives) et un liquide amniotique méconial, sans retard de croissance intra-utérin (le RCIU étant le propre de la souffrance fœtale chronique).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"aboisso-2__ssr-pf__16\",\"num\":\"17\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"I. Questions à Choix Double (QCD : Q1 à Q20)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"La présentation de l'épaule est une complication d'une présentation de l'épaule négligée qui n'a pas été vite prise en charge.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"C'est l'inverse : c'est la présentation de l'épaule NÉGLIGÉE qui est la complication évolutive grave d'une présentation de l'épaule non prise en charge à temps.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"aboisso-2__ssr-pf__17\",\"num\":\"18\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"I. Questions à Choix Double (QCD : Q1 à Q20)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"La compression est une complication survenant dans la procidence du cordon 1er degré uniquement.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"La compression funiculaire entre la présentation fœtale et la paroi pelvienne survient à TOUS les degrés de procidence du cordon (1er degré intra-vaginal, 2e degré à la vulve et 3e degré extériorisé hors de la vulve, où s'ajoute le vasospasme au froid et à la dessiccation).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"aboisso-2__ssr-pf__18\",\"num\":\"19\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"I. Questions à Choix Double (QCD : Q1 à Q20)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Dans l'HRP, le toucher vaginal doit être réalisé avec prudence pour ne pas déclencher une hémorragie cataclysmique.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"Cette précaution (interdiction du toucher vaginal intracervical avant localisation échographique du placenta car risque d'hémorragie cataclysmique par décollement cotylédonaire) concerne le PLACENTA PRAEVIA, et non l'HRP (où l'on pratique au contraire la rupture artificielle des membranes au TV pour abaisser la pression intra-utérine).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"aboisso-2__ssr-pf__19\",\"num\":\"20\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"I. Questions à Choix Double (QCD : Q1 à Q20)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Au stade de pré-rupture (syndrome de Bandl-Frommel), en cas d'accouchement par voie basse, la révision utérine n'est pas nécessaire.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"Le syndrome de pré-rupture (anneau de Bandl-Frommel) impose une césarienne d'urgence ; et si un accouchement par voie basse venait à se produire sur un utérus suspect de déhiscence/pré-rupture, une révision utérine prudente est formellement obligatoire pour vérifier l'intégrité des parois utérines.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"aboisso-2__ssr-pf__20\",\"num\":\"21\",\"type\":\"CAS_CLINIQUE\",\"typeLabel\":\"Étude de cas / Cas clinique\",\"partieTitle\":\"I. Questions à Choix Double (QCD : Q1 à Q20)\",\"caseTitle\":\"Cas clinique — Mme S., 36 ans, G5P4 (Q21 à Q32)\",\"caseData\":null,\"text\":\"À combien de semaines d'aménorrhée Madame S. est-elle (lors de l'examen blanc en septembre 2025, ex. le 08/09/2025 ou le 22/09/2025) ?\",\"options\":[{\"letter\":\"A\",\"text\":\"33 SA + 4 jours\"},{\"letter\":\"B\",\"text\":\"35 SA + 4 jours\"},{\"letter\":\"C\",\"text\":\"37 SA + 4 jours\"},{\"letter\":\"D\",\"text\":\"39 SA + 4 jours\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. 33 SA + 4 jours\",\"answerLetters\":[\"A\"],\"explanation\":\"Avec une DDR au 16/01/2025 : Janvier = 15 j (31 − 16), Février = 28 j, Mars = 31 j, Avril = 30 j, Mai = 31 j, Juin = 30 j, Juillet = 31 j, Août = 31 j (Total au 31 août = 227 jours = 32 SA + 3 jours). En septembre 2025 : au 8 septembre (+8 j = 235 j = 33 SA + 4 jours : A) ; au 22 septembre (+22 j = 249 j = 35 SA + 4 jours : B).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"aboisso-2__ssr-pf__21\",\"num\":\"22\",\"type\":\"CAS_CLINIQUE\",\"typeLabel\":\"Étude de cas / Cas clinique\",\"partieTitle\":\"I. Questions à Choix Double (QCD : Q1 à Q20)\",\"caseTitle\":\"Cas clinique — Mme S., 36 ans, G5P4 (Q21 à Q32)\",\"caseData\":null,\"text\":\"Quelle est sa date probable d'accouchement (DPA) ?\",\"options\":[{\"letter\":\"A\",\"text\":\"16 Octobre\"},{\"letter\":\"B\",\"text\":\"30 Octobre\"},{\"letter\":\"C\",\"text\":\"4 Novembre\"},{\"letter\":\"D\",\"text\":\"11 Novembre\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. 30 Octobre\",\"answerLetters\":[\"B\"],\"explanation\":\"En appliquant la règle de Naegele-Pinard (variante francophone enseignée à l'INFAS : DDR + 14 jours − 3 mois + 1 an, ou + 9 mois + 14 jours) à partir du 16/01/2025 : Jour = 16 + 14 = 30 ; Mois = 01 + 9 = 10 (Octobre). La DPA est donc le 30 Octobre 2025 (Réponse B).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"aboisso-2__ssr-pf__22\",\"num\":\"23\",\"type\":\"CAS_CLINIQUE\",\"typeLabel\":\"Étude de cas / Cas clinique\",\"partieTitle\":\"I. Questions à Choix Double (QCD : Q1 à Q20)\",\"caseTitle\":\"Cas clinique — Mme S., 36 ans, G5P4 (Q21 à Q32)\",\"caseData\":null,\"text\":\"De quel type d'anémie (selon la sévérité clinique/biologique) s'agit-il ?\",\"options\":[{\"letter\":\"A\",\"text\":\"Minime\"},{\"letter\":\"B\",\"text\":\"Modérée\"},{\"letter\":\"C\",\"text\":\"Légère\"},{\"letter\":\"D\",\"text\":\"Sévère\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Modérée\",\"answerLetters\":[\"B\"],\"explanation\":\"Chez la femme enceinte, l'OMS classe la sévérité de l'anémie selon le taux d'hémoglobine : Anémie légère = 10,0 à 10,9 g/dl ; Anémie modérée = 7,0 à 9,9 g/dl ; Anémie sévère = < 7,0 g/dl. Avec Hb = 9,2 g/dl, il s'agit d'une anémie MODÉRÉE (Réponse B).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"aboisso-2__ssr-pf__23\",\"num\":\"24\",\"type\":\"CAS_CLINIQUE\",\"typeLabel\":\"Étude de cas / Cas clinique\",\"partieTitle\":\"I. Questions à Choix Double (QCD : Q1 à Q20)\",\"caseTitle\":\"Cas clinique — Mme S., 36 ans, G5P4 (Q21 à Q32)\",\"caseData\":null,\"text\":\"Madame S. (SS) aimerait savoir la probabilité d'avoir des enfants de groupe électrophorétique identique à leur père (AS) ?\",\"options\":[{\"letter\":\"A\",\"text\":\"25%\"},{\"letter\":\"B\",\"text\":\"50%\"},{\"letter\":\"C\",\"text\":\"75%\"},{\"letter\":\"D\",\"text\":\"100%\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. 50%\",\"answerLetters\":[\"B\"],\"explanation\":\"Lors du croisement d'une mère homozygote SS (qui transmet obligatoirement l'allèle S à 100 % de ses enfants) avec un père hétérozygote AS (qui transmet 50 % d'allèle A et 50 % d'allèle S), la descendance est composée à 50 % d'enfants AS (identiques au père) et à 50 % d'enfants SS (identiques à la mère). La probabilité est donc de 50 % (Réponse B).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"aboisso-2__ssr-pf__24\",\"num\":\"25\",\"type\":\"CAS_CLINIQUE\",\"typeLabel\":\"Étude de cas / Cas clinique\",\"partieTitle\":\"I. Questions à Choix Double (QCD : Q1 à Q20)\",\"caseTitle\":\"Cas clinique — Mme S., 36 ans, G5P4 (Q21 à Q32)\",\"caseData\":null,\"text\":\"Parmi les propositions suivantes, deux (02) sont des facteurs de risque liés à la grossesse (obstétricaux/gynécologiques) dans le texte : Lesquelles ?\",\"options\":[{\"letter\":\"A\",\"text\":\"Âge maternel supérieur à 35 ans\"},{\"letter\":\"B\",\"text\":\"Palpitations\"},{\"letter\":\"C\",\"text\":\"Multiparité (G5P4)\"},{\"letter\":\"D\",\"text\":\"Notion de paludisme antérieur à la grossesse\"},{\"letter\":\"E\",\"text\":\"Drépanocytaire\"},{\"letter\":\"F\",\"text\":\"Intervalle inter-génésique court\"}],\"mode\":\"mcq\",\"multi\":true,\"answer\":\"C et F\",\"answerLetters\":[\"C\",\"F\"],\"explanation\":\"Les facteurs de risque spécifiquement liés à l'histoire obstétricale / aux grossesses mentionnés dans le texte sont la multiparité (G5P4 : C) et les espaces intergénésiques courts (F), auxquels s'ajoutent le terrain maternel d'âge > 35 ans (36 ans : A) et la drépanocytose SS (E).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"aboisso-2__ssr-pf__25\",\"num\":\"26\",\"type\":\"CAS_CLINIQUE\",\"typeLabel\":\"Étude de cas / Cas clinique\",\"partieTitle\":\"I. Questions à Choix Double (QCD : Q1 à Q20)\",\"caseTitle\":\"Cas clinique — Mme S., 36 ans, G5P4 (Q21 à Q32)\",\"caseData\":null,\"text\":\"Quel est le type d'hémoglobinopathie de Madame S. (SS) ?\",\"options\":[{\"letter\":\"A\",\"text\":\"Drépanocytose mineure\"},{\"letter\":\"B\",\"text\":\"Thalasso-drépanocytaire\"},{\"letter\":\"C\",\"text\":\"Drépanocytose majeure\"},{\"letter\":\"D\",\"text\":\"Hémoglobinoses combinées\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"C. Drépanocytose majeure\",\"answerLetters\":[\"C\"],\"explanation\":\"La forme homozygote SS constitue la forme typique du syndrome drépanocytaire MAJEUR (drépanocytose majeure : C), par opposition à la forme hétérozygote AS qui est la forme mineure (trait drépanocytaire).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"aboisso-2__ssr-pf__26\",\"num\":\"27\",\"type\":\"CAS_CLINIQUE\",\"typeLabel\":\"Étude de cas / Cas clinique\",\"partieTitle\":\"I. Questions à Choix Double (QCD : Q1 à Q20)\",\"caseTitle\":\"Cas clinique — Mme S., 36 ans, G5P4 (Q21 à Q32)\",\"caseData\":null,\"text\":\"De quel type morphologique d'anémie s'agit-il au vu de la NFS ?\",\"options\":[{\"letter\":\"A\",\"text\":\"Anémie hypochrome microcytaire\"},{\"letter\":\"B\",\"text\":\"Anémie normochrome macrocytaire\"},{\"letter\":\"C\",\"text\":\"Anémie macrocytaire\"},{\"letter\":\"D\",\"text\":\"Anémie normochrome normocytaire\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Anémie hypochrome microcytaire\",\"answerLetters\":[\"A\"],\"explanation\":\"Sur l'hémogramme : VGM = 70 fl (< 80 fl = microcytaire) et CCMH = 30 g/dl (< 32 g/dl = hypochrome). Il s'agit donc d'une anémie hypochrome microcytaire (Réponse A).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"aboisso-2__ssr-pf__27\",\"num\":\"28\",\"type\":\"CAS_CLINIQUE\",\"typeLabel\":\"Étude de cas / Cas clinique\",\"partieTitle\":\"I. Questions à Choix Double (QCD : Q1 à Q20)\",\"caseTitle\":\"Cas clinique — Mme S., 36 ans, G5P4 (Q21 à Q32)\",\"caseData\":null,\"text\":\"Quelle serait la cause probable de cette anémie (hypochrome microcytaire chez une multipare aux grossesses rapprochées sans prophylaxie martiale) ?\",\"options\":[{\"letter\":\"A\",\"text\":\"La drépanocytose\"},{\"letter\":\"B\",\"text\":\"Une carence en acide folique\"},{\"letter\":\"C\",\"text\":\"Une carence en fer\"},{\"letter\":\"D\",\"text\":\"Paludisme antérieur à la grossesse\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"C. Une carence en fer\",\"answerLetters\":[\"C\"],\"explanation\":\"Une anémie MICROCYTAIRE HYPOCHROME (VGM = 70 fl, CCMH = 30 g/dl) chez une multipare (G5P4) ayant des espaces intergénésiques courts et n'ayant pas suivi sa prophylaxie anti-anémique est caractéristique d'une anémie ferriprive par CARENCE EN FER (C). (L'anémie hémolytique pure de la drépanocytose ou du paludisme est normocytaire ou macrocytaire régénérative, et la carence en acide folique donne une anémie macrocytaire).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"aboisso-2__ssr-pf__28\",\"num\":\"29\",\"type\":\"CAS_CLINIQUE\",\"typeLabel\":\"Étude de cas / Cas clinique\",\"partieTitle\":\"I. Questions à Choix Double (QCD : Q1 à Q20)\",\"caseTitle\":\"Cas clinique — Mme S., 36 ans, G5P4 (Q21 à Q32)\",\"caseData\":null,\"text\":\"À quel moment aurait-on pu dépister cette anémie au cours de la grossesse ?\",\"options\":[{\"letter\":\"A\",\"text\":\"Uniquement au début de la grossesse\"},{\"letter\":\"B\",\"text\":\"Au 3ème mois de la grossesse (lors du bilan prénatal de la CPN1 au 1er trimestre)\"},{\"letter\":\"C\",\"text\":\"Au 6ème mois de la grossesse\"},{\"letter\":\"D\",\"text\":\"À terme\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Au 3ème mois de la grossesse (lors du bilan prénatal de la CPN1 au 1er trimestre)\",\"answerLetters\":[\"B\"],\"explanation\":\"La NFS fait partie du bilan prénatal systématique obligatoire dès la 1re consultation prénatale (CPN1 au 1er trimestre / avant la fin du 3e mois de grossesse : B), puis contrôlée au 6e mois.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"aboisso-2__ssr-pf__29\",\"num\":\"30\",\"type\":\"CAS_CLINIQUE\",\"typeLabel\":\"Étude de cas / Cas clinique\",\"partieTitle\":\"I. Questions à Choix Double (QCD : Q1 à Q20)\",\"caseTitle\":\"Cas clinique — Mme S., 36 ans, G5P4 (Q21 à Q32)\",\"caseData\":null,\"text\":\"Quelles sont les deux complications auxquelles s'expose Madame S. dans le post-partum ?\",\"options\":[{\"letter\":\"A\",\"text\":\"Menace d'accouchement prématuré\"},{\"letter\":\"B\",\"text\":\"Pyélonéphrite aiguë\"},{\"letter\":\"C\",\"text\":\"Endométrite\"},{\"letter\":\"D\",\"text\":\"Mauvais efforts expulsifs\"},{\"letter\":\"E\",\"text\":\"Hémorragie du post-partum\"}],\"mode\":\"mcq\",\"multi\":true,\"answer\":\"C et E\",\"answerLetters\":[\"C\",\"E\"],\"explanation\":\"Dans le post-partum (suites de couches), cette grande multipare (G5P4) anémiée et drépanocytaire SS est particulièrement exposée à l'hémorragie du post-partum par atonie utérine mal tolérée sur terrain anémique (E) et aux infections puerpérales telles que l'endométrite aiguë (C, favorisée par l'anémie et l'immunodépression de la drépanocytose). La MAP (A) est une complication de la grossesse et les mauvais efforts expulsifs (D) du travail.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"aboisso-2__ssr-pf__30\",\"num\":\"31\",\"type\":\"CAS_CLINIQUE\",\"typeLabel\":\"Étude de cas / Cas clinique\",\"partieTitle\":\"I. Questions à Choix Double (QCD : Q1 à Q20)\",\"caseTitle\":\"Cas clinique — Mme S., 36 ans, G5P4 (Q21 à Q32)\",\"caseData\":null,\"text\":\"Quel sera le traitement recommandé pour corriger cette anémie (modérée à 9,2 g/dl par carence martiale) ?\",\"options\":[{\"letter\":\"A\",\"text\":\"Transfusion sanguine\"},{\"letter\":\"B\",\"text\":\"200 mg de fer élément par jour pendant 1 mois\"},{\"letter\":\"C\",\"text\":\"60 mg de fer élément par jour pendant 3 mois\"},{\"letter\":\"D\",\"text\":\"100 mg d'acide folique par jour pendant 2 mois\"},{\"letter\":\"E\",\"text\":\"200 mg de fer élément par jour pendant 3 mois (ou 2 mois)\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"E. 200 mg de fer élément par jour pendant 3 mois (ou 2 mois)\",\"answerLetters\":[\"E\"],\"explanation\":\"Le traitement CURATIF d'une anémie ferriprive modérée (Hb entre 7 et 9,9 g/dl bien tolérée) repose sur une supplémentation martiale orale à dose curative de 120 à 200 mg de fer élément par jour pendant 2 à 3 mois pour corriger l'hémoglobine et reconstituer les réserves de ferritine (E). (60 mg/j en C est la dose préventive, et la transfusion en A est réservée aux anémies sévères < 7 g/dl ou décompensées).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"aboisso-2__ssr-pf__31\",\"num\":\"32\",\"type\":\"CAS_CLINIQUE\",\"typeLabel\":\"Étude de cas / Cas clinique\",\"partieTitle\":\"I. Questions à Choix Double (QCD : Q1 à Q20)\",\"caseTitle\":\"Cas clinique — Mme S., 36 ans, G5P4 (Q21 à Q32)\",\"caseData\":null,\"text\":\"Quel sera le rythme de surveillance de Madame S. dans le post-partum immédiat en salle de naissance ?\",\"options\":[{\"letter\":\"A\",\"text\":\"Toutes les 15 min pendant 30 min puis toutes les heures pendant 2 heures\"},{\"letter\":\"B\",\"text\":\"Toutes les 30 min pendant deux heures et toutes les heures pendant 6h\"},{\"letter\":\"C\",\"text\":\"Toutes les 15 min pendant 2 heures et toutes les 30 min la 3ème heure\"},{\"letter\":\"D\",\"text\":\"Elle doit se faire pendant 6 heures ensuite la patiente pourra sortir\"},{\"letter\":\"E\",\"text\":\"Elle portera principalement sur l'état de conscience de la mère\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"C. Toutes les 15 min pendant 2 heures et toutes les 30 min la 3ème heure\",\"answerLetters\":[\"C\"],\"explanation\":\"En salle d'accouchement (surveillance du post-partum immédiat pendant les 2 premières heures critiques pour dépister l'HPP), la surveillance des constantes (pouls, TA), du globe de sécurité utérin et du saignement vulvaire s'effectue toutes les 15 minutes pendant 2 heures, puis toutes les 30 minutes la 3e heure / toutes les heures jusqu'à la 6e heure (C).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"aboisso-2__ssr-pf__32\",\"num\":\"33\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"II. Questions à Choix Multiples (QCM : Q33 à Q50)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"À quelle période de la grossesse la pyélonéphrite aiguë est-elle le plus fréquente ?\",\"options\":[{\"letter\":\"A\",\"text\":\"Premier trimestre\"},{\"letter\":\"B\",\"text\":\"Deuxième trimestre (et 3e trimestre : à partir du 5e mois)\"},{\"letter\":\"C\",\"text\":\"Troisième trimestre\"},{\"letter\":\"D\",\"text\":\"Post-partum\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Deuxième trimestre (et 3e trimestre : à partir du 5e mois)\",\"answerLetters\":[\"B\"],\"explanation\":\"La pyélonéphrite aiguë gravidique survient essentiellement aux 2e et 3e trimestres (à partir du 5e mois de grossesse), lorsque l'utérus gravide comprime l'uretère droit contre le détroit supérieur, associé à l'hypotonie urétérale progestative.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"aboisso-2__ssr-pf__33\",\"num\":\"34\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"II. Questions à Choix Multiples (QCM : Q33 à Q50)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Quelle manœuvre est réalisée en cas de rétention de la tête dernière (dans l'excavation) lors d'un accouchement de siège ?\",\"options\":[{\"letter\":\"A\",\"text\":\"Manœuvre de Bracht\"},{\"letter\":\"B\",\"text\":\"Manœuvre de Lovset\"},{\"letter\":\"C\",\"text\":\"Manœuvre de Mauriceau\"},{\"letter\":\"D\",\"text\":\"Attitude de Vermelin\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"C. Manœuvre de Mauriceau\",\"answerLetters\":[\"C\"],\"explanation\":\"La manœuvre de Mauriceau (flexion de la tête par deux doigts introduits dans la bouche du fœtus appuyant sur la base de la langue, à cheval sur l'avant-bras de l'opérateur) est la manœuvre spécifique de la rétention de tête dernière dans l'excavation (C).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"aboisso-2__ssr-pf__34\",\"num\":\"35\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"II. Questions à Choix Multiples (QCM : Q33 à Q50)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Quel matériel est essentiel en ESPC pour désobstruer les voies aériennes d'un nouveau-né (selon l'algorithme HBB / Aider les Bébés à Respirer) ?\",\"options\":[{\"letter\":\"A\",\"text\":\"La poire à lavement\"},{\"letter\":\"B\",\"text\":\"Le masque de ventilation\"},{\"letter\":\"C\",\"text\":\"Le Pingouin (poire d'aspiration réutilisable stérilisable)\"},{\"letter\":\"D\",\"text\":\"La sonde naso-gastrique\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"C. Le Pingouin (poire d'aspiration réutilisable stérilisable)\",\"answerLetters\":[\"C\"],\"explanation\":\"Dans le kit HBB ('Aider les Bébés à Respirer') des maternités périphériques (ESPC), l'aspirateur manuel en silicone transparent facilement démontable et stérilisable appelé 'Pingouin' (C) est le matériel de référence pour désobstruer la bouche puis le nez du nouveau-né.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"aboisso-2__ssr-pf__35\",\"num\":\"36\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"II. Questions à Choix Multiples (QCM : Q33 à Q50)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Quel type de complication est le plus susceptible de survenir à J5 du post-partum ?\",\"options\":[{\"letter\":\"A\",\"text\":\"Complications mammaires\"},{\"letter\":\"B\",\"text\":\"Complications infectieuses (endométrite puerpérale)\"},{\"letter\":\"C\",\"text\":\"Complications hémorragiques\"},{\"letter\":\"D\",\"text\":\"Complications psychologiques\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Complications infectieuses (endométrite puerpérale)\",\"answerLetters\":[\"B\"],\"explanation\":\"Le 5e jour du post-partum (J3–J5) est le moment électif d'apparition de l'endométrite aiguë puerpérale (complication infectieuse parenchymateuse utérine de référence : B), tandis que les complications hémorragiques graves surviennent surtout dans le post-partum immédiat (H1–H24).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"aboisso-2__ssr-pf__36\",\"num\":\"37\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"II. Questions à Choix Multiples (QCM : Q33 à Q50)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Parmi les affections suivantes, une peut être responsable d'embryopathies : laquelle ?\",\"options\":[{\"letter\":\"A\",\"text\":\"La toxoplasmose\"},{\"letter\":\"B\",\"text\":\"La rubéole\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. La rubéole\",\"answerLetters\":[\"B\"],\"explanation\":\"La rubéole congénitale contractée au 1er trimestre est le modèle type de l'embryopathie malformative tératogène (syndrome de Gregg, B), tandis que la toxoplasmose entraîne une fœtopathie.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"aboisso-2__ssr-pf__37\",\"num\":\"38\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"II. Questions à Choix Multiples (QCM : Q33 à Q50)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Dans l'épisiotomie médio-latérale, la section est effectuée à partir de la fourchette vulvaire selon un angle de (par rapport à l'horizontale ou à la verticale) :\",\"options\":[{\"letter\":\"A\",\"text\":\"60° (ou 45°)\"},{\"letter\":\"B\",\"text\":\"135°\"},{\"letter\":\"C\",\"text\":\"90°\"},{\"letter\":\"D\",\"text\":\"180°\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. 60° (ou 45°)\",\"answerLetters\":[\"A\"],\"explanation\":\"L'épisiotomie médio-latérale part de la commissure postérieure de la vulve (fourchette) et se dirige obliquement en bas et en dehors vers l'ischion selon un angle de 45° à 60° (Réponse A) afin d'épargner le sphincter anal en bas et le canal de la glande de Bartholin en haut.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"aboisso-2__ssr-pf__38\",\"num\":\"39\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"II. Questions à Choix Multiples (QCM : Q33 à Q50)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Parmi les organes suivants, deux sont des organes érectiles chez la femme : lesquels ?\",\"options\":[{\"letter\":\"A\",\"text\":\"La vulve\"},{\"letter\":\"B\",\"text\":\"Le clitoris\"},{\"letter\":\"C\",\"text\":\"Les petites lèvres\"},{\"letter\":\"D\",\"text\":\"Le bulbe vestibulaire (bulbes spongieux du vagin)\"},{\"letter\":\"E\",\"text\":\"L'hymen\"},{\"letter\":\"F\",\"text\":\"Le col de l'utérus\"}],\"mode\":\"mcq\",\"multi\":true,\"answer\":\"B et D\",\"answerLetters\":[\"B\",\"D\"],\"explanation\":\"Les organes érectiles de l'appareil génital externe féminin sont constitués par les corps caverneux du CLITORIS (B) et les deux BULBES VESTIBULAIRES (ou bulbes vaginaux, homologues du corps spongieux masculin, situés de part et d'autre de l'orifice vaginal et de l'urètre : D).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"aboisso-2__ssr-pf__39\",\"num\":\"40\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"II. Questions à Choix Multiples (QCM : Q33 à Q50)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Au cours de l'accouchement chez une patiente PTME (VIH+) : trouvez les deux réponses exactes :\",\"options\":[{\"letter\":\"A\",\"text\":\"Faire une épisiotomie systématique lors de l'accouchement\"},{\"letter\":\"B\",\"text\":\"Rompre la poche des eaux en début de travail d'accouchement\"},{\"letter\":\"C\",\"text\":\"Éviter de traire le cordon\"},{\"letter\":\"D\",\"text\":\"La césarienne est systématique\"},{\"letter\":\"E\",\"text\":\"Faire la section du cordon sous une compresse\"},{\"letter\":\"F\",\"text\":\"Aspirer le nouveau-né systématiquement\"}],\"mode\":\"mcq\",\"multi\":true,\"answer\":\"C et E\",\"answerLetters\":[\"C\",\"E\"],\"explanation\":\"Parmi les gestes obstétricaux sécurisés de PTME per-partum, il faut éviter de traire le cordon ombilical vers le fœtus (C, pour ne pas transfuser de sang maternel contaminé) et sectionner le cordon sous protection d'une compresse stérile (E, pour éviter toute projection de sang sur le nouveau-né et l'accoucheur). L'épisiotomie systématique (A), la RAM précoce (B) et l'aspiration systématique (F) sont proscrites.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"aboisso-2__ssr-pf__40\",\"num\":\"41\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"II. Questions à Choix Multiples (QCM : Q33 à Q50)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Deux éléments font partie de la cystite isolée. Lesquels ?\",\"options\":[{\"letter\":\"A\",\"text\":\"Hospitalisation\"},{\"letter\":\"B\",\"text\":\"Traitement par voie orale\"},{\"letter\":\"C\",\"text\":\"Contrôle par l'ECBU\"},{\"letter\":\"D\",\"text\":\"Elle est le plus souvent asymptomatique\"},{\"letter\":\"E\",\"text\":\"C'est l'infection urinaire la plus caractéristique\"},{\"letter\":\"F\",\"text\":\"C'est une infection urinaire haute\"}],\"mode\":\"mcq\",\"multi\":true,\"answer\":\"B et C\",\"answerLetters\":[\"B\",\"C\"],\"explanation\":\"La cystite aiguë isolée de la femme enceinte est une infection urinaire basse symptomatique (sans fièvre) qui se traite en ambulatoire par antibiothérapie orale (B) avec vérification de la guérison par un ECBU de contrôle (C).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"aboisso-2__ssr-pf__41\",\"num\":\"42\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"II. Questions à Choix Multiples (QCM : Q33 à Q50)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Parmi les propositions suivantes, deux sont des causes classiques de coagulopathie (CIVD) en obstétrique : lesquelles ?\",\"options\":[{\"letter\":\"A\",\"text\":\"La mort fœtale in utero (rétention prolongée de fœtus mort > 3-4 semaines)\"},{\"letter\":\"B\",\"text\":\"Le placenta praevia\"},{\"letter\":\"C\",\"text\":\"L'hématome rétroplacentaire (HRP)\"},{\"letter\":\"D\",\"text\":\"La macrosomie fœtale\"},{\"letter\":\"E\",\"text\":\"Le fibrome utérin\"},{\"letter\":\"F\",\"text\":\"La dystocie dynamique\"}],\"mode\":\"mcq\",\"multi\":true,\"answer\":\"A et C\",\"answerLetters\":[\"A\",\"C\"],\"explanation\":\"La Coagulation Intravasculaire Disséminée (CIVD / défibrination avec sang incoagulable) par libération massive de thromboplastines tissulaires dans la circulation maternelle complique classiquement l'hématome rétroplacentaire (HRP : C) et la rétention prolongée d'une mort fœtale in utero (MFIU : A).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"aboisso-2__ssr-pf__42\",\"num\":\"43\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"II. Questions à Choix Multiples (QCM : Q33 à Q50)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Parmi les signes cliniques observés chez une femme enceinte qui saigne au 3ème trimestre, quels sont les deux qui sont en faveur d'un placenta praevia ?\",\"options\":[{\"letter\":\"A\",\"text\":\"Saignement rouge vif indolore\"},{\"letter\":\"B\",\"text\":\"Saignement noirâtre plus ou moins abondant\"},{\"letter\":\"C\",\"text\":\"Utérus déformé en sablier\"},{\"letter\":\"D\",\"text\":\"BDCF perçus (et utérus souple)\"},{\"letter\":\"E\",\"text\":\"Le petit côté des membranes est supérieur à 10 cm\"},{\"letter\":\"F\",\"text\":\"L'hypertension artérielle étant une cause\"}],\"mode\":\"mcq\",\"multi\":true,\"answer\":\"A et D\",\"answerLetters\":[\"A\",\"D\"],\"explanation\":\"Le placenta praevia se caractérise au 3e trimestre par une hémorragie de sang ROUGE VIF, spontanée, INDOLORE et récidivante (A), avec un utérus souple et des BDCF généralement présents et normaux (D) [et à l'examen du délivre après l'accouchement, le petit côté des membranes est < 10 cm, donc E est faux ; B et F caractérisent l'HRP].\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"aboisso-2__ssr-pf__43\",\"num\":\"44\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"II. Questions à Choix Multiples (QCM : Q33 à Q50)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Dans les grossesses gémellaires uniovulaires (monozygotes) : Cochez les 2 bonnes réponses :\",\"options\":[{\"letter\":\"A\",\"text\":\"Les fœtus peuvent être de sexe différent\"},{\"letter\":\"B\",\"text\":\"Elles sont toujours monochoriales et biovulaires\"},{\"letter\":\"C\",\"text\":\"Ce sont de vrais jumeaux\"},{\"letter\":\"D\",\"text\":\"Elles peuvent être bichoriales biamniotiques (si division précoce avant J4)\"},{\"letter\":\"E\",\"text\":\"La scission de l'œuf précocement aboutit à une grossesse monochoriale monoamniotique\"},{\"letter\":\"F\",\"text\":\"Seules les grossesses monochoriales biamniotiques peuvent aboutir à des siamois\"}],\"mode\":\"mcq\",\"multi\":true,\"answer\":\"C et D\",\"answerLetters\":[\"C\",\"D\"],\"explanation\":\"Les grossesses gémellaires uniovulaires (monozygotes) donnent toujours de vrais jumeaux génétiquement identiques et de même sexe (C), et selon le jour de scission de l'œuf, elles peuvent être bichoriales biamniotiques (division entre J1 et J3 : D, 30 % des cas), monochoriales biamniotiques (J4 à J8 : 68 %) ou monochoriales monoamniotiques (J8 à J13 : 2 %, et siamois si > J13).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"aboisso-2__ssr-pf__44\",\"num\":\"45\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"II. Questions à Choix Multiples (QCM : Q33 à Q50)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Concernant le fibrome utérin : deux assertions sont exactes : lesquelles ?\",\"options\":[{\"letter\":\"A\",\"text\":\"Il existe un sillon le plus souvent entre la masse et l'utérus au toucher vaginal\"},{\"letter\":\"B\",\"text\":\"Il se développe aux dépens de la muqueuse utérine\"},{\"letter\":\"C\",\"text\":\"Ils ont tendance à augmenter de volume au cours de la grossesse\"},{\"letter\":\"D\",\"text\":\"Ils peuvent devenir des cancers dans près de 30 %\"},{\"letter\":\"E\",\"text\":\"Il est une cause d'hémorragie du post-partum immédiat (par atonie/mauvaise rétraction utérine)\"},{\"letter\":\"F\",\"text\":\"Son traitement consiste systématiquement en l'ablation de l'utérus (hystérectomie)\"}],\"mode\":\"mcq\",\"multi\":true,\"answer\":\"C et E\",\"answerLetters\":[\"C\",\"E\"],\"explanation\":\"Sous l'effet de l'imprégnation œstroprogestative gravidique, les fibromes utérins ont tendance à augmenter de volume et peuvent subir une nécrobiose aseptique pendant la grossesse (C), et ils exposent dans le post-partum immédiat à l'hémorragie de la délivrance en gênant la rétraction physiologique du myomètre (E).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"aboisso-2__ssr-pf__45\",\"num\":\"46\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"II. Questions à Choix Multiples (QCM : Q33 à Q50)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Cochez les 2 facteurs favorisant le plus la procidence du cordon :\",\"options\":[{\"letter\":\"A\",\"text\":\"Présentation du siège décomplété\"},{\"letter\":\"B\",\"text\":\"Présentation céphalique\"},{\"letter\":\"C\",\"text\":\"Présentation transversale (et présentation du siège complet)\"},{\"letter\":\"D\",\"text\":\"Présentation de l'épaule négligée\"},{\"letter\":\"E\",\"text\":\"Présentation du siège complet\"},{\"letter\":\"F\",\"text\":\"L'hydramnios\"}],\"mode\":\"mcq\",\"multi\":true,\"answer\":\"C et F\",\"answerLetters\":[\"C\",\"F\"],\"explanation\":\"La procidence du cordon est favorisée par tout défaut d'accommodation entre la présentation et le segment inférieur : les présentations transversales/épaule (C) et le siège complet (E, alors que le siège décomplété mode des fesses moule bien le segment inférieur), ainsi que les causes ovulaires telles que l'hydramnios (F, débâcle de liquide amniotique à la rupture des membranes).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"aboisso-2__ssr-pf__46\",\"num\":\"47\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"II. Questions à Choix Multiples (QCM : Q33 à Q50)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Parmi les propositions suivantes, identifiez les deux causes principales de la rupture utérine :\",\"options\":[{\"letter\":\"A\",\"text\":\"Antécédent de césarienne corporéale (cicatrice utérine fragile)\"},{\"letter\":\"B\",\"text\":\"Abus d'antispasmodiques\"},{\"letter\":\"C\",\"text\":\"Accouchement par ventouse\"},{\"letter\":\"D\",\"text\":\"Expression utérine (ou abus d'ocytociques / dystocie mécanique)\"},{\"letter\":\"E\",\"text\":\"L'hypertension artérielle\"},{\"letter\":\"F\",\"text\":\"Grossesse gémellaire\"}],\"mode\":\"mcq\",\"multi\":true,\"answer\":\"A et D\",\"answerLetters\":[\"A\",\"D\"],\"explanation\":\"Parmi les propositions, les deux causes majeures de rupture utérine sont la cicatrice de césarienne corporéale (A, cicatrice longitudinale haute particulièrement fragile) et les manœuvres traumatiques interdites telles que l'expression abdominale du fond utérin (manœuvre de Kristeller, D).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"aboisso-2__ssr-pf__47\",\"num\":\"48\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"II. Questions à Choix Multiples (QCM : Q33 à Q50)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Quelle sera la conduite à tenir en cas de procidence du cordon 3ème degré non battant avec fœtus macéré en présentation de l'épaule ?\",\"options\":[{\"letter\":\"A\",\"text\":\"Recouvrir le cordon avec des compresses sèches\"},{\"letter\":\"B\",\"text\":\"Installer la patiente en position de Trendelenburg\"},{\"letter\":\"C\",\"text\":\"Privilégier la voie basse\"},{\"letter\":\"D\",\"text\":\"Refouler la présentation\"},{\"letter\":\"E\",\"text\":\"Faire une césarienne en urgence\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"E. Faire une césarienne en urgence\",\"answerLetters\":[\"E\"],\"explanation\":\"Même si le fœtus est mort et macéré, il se trouve en PRÉSENTATION DE L'ÉPAULE (présentation transversale absolument dystocique) avec membranes rompues : l'accouchement par voie basse est mécaniquement impossible et toute tentative de version interne sur utérus rétracté provoquerait une rupture utérine mortelle pour la mère. La césarienne s'impose donc en urgence pour sauver la mère (E).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"aboisso-2__ssr-pf__48\",\"num\":\"49\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"II. Questions à Choix Multiples (QCM : Q33 à Q50)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Quelle est l'infection urinaire la plus rencontrée au cours de la grossesse ?\",\"options\":[{\"letter\":\"A\",\"text\":\"L'urétrite\"},{\"letter\":\"B\",\"text\":\"La pyélonéphrite aiguë\"},{\"letter\":\"C\",\"text\":\"La bactériurie asymptomatique\"},{\"letter\":\"D\",\"text\":\"La cystite aiguë\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"C. La bactériurie asymptomatique\",\"answerLetters\":[\"C\"],\"explanation\":\"La bactériurie asymptomatique (colonisation bactérienne urinaire ≥ 10⁵ UFC/ml sans aucun signe fonctionnel clinique) est la forme la plus fréquente d'infection urinaire gravidique (5 à 10 % des grossesses, C).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"aboisso-2__ssr-pf__49\",\"num\":\"50\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"II. Questions à Choix Multiples (QCM : Q33 à Q50)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Parmi les présentations suivantes, laquelle a pour diamètre d'engagement le diamètre occipito-frontal (12 cm) ?\",\"options\":[{\"letter\":\"A\",\"text\":\"La présentation du front\"},{\"letter\":\"B\",\"text\":\"La présentation du sommet\"},{\"letter\":\"C\",\"text\":\"La présentation du bregma\"},{\"letter\":\"D\",\"text\":\"La présentation de la face\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"C. La présentation du bregma\",\"answerLetters\":[\"C\"],\"explanation\":\"Rappel des diamètres d'engagement des présentations céphaliques : Sommet (fléchie) = sous-occipito-bregmatique (9,5 cm) ; Bregma (légèrement défléchie, attitude indifférente) = occipito-frontal (12 cm : C) ; Front (déflexion partielle, dystocique) = syncipito-mentonnier (13,5 cm) ; Face (déflexion totale) = sous-mento-bregmatique (9,5 cm). +-----------------------------------------------------------------------+ Épreuves : Santé Publique Version A (Q1-Q56) | Pédiatrie Version A (Q1-Q60) | Gynécologie-Obstétrique (Q1-Q55) | SR/PF (Q1-Q43) +=======================================================================+ +-----------------------------------------------------------------------+ +-----------------------------------------------------------------------+\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null}]}]},{\"name\":\"AGBOVILLE (S2 : 2025)\",\"slug\":\"agboville-2\",\"session\":\"S2\",\"annee\":2025,\"existe\":true,\"sujets\":[{\"name\":\"Gynéco-obstétrique\",\"slug\":\"gynecologie-obstetrique\",\"pages\":\"\",\"count\":55,\"session\":\"S2\",\"annee\":2025,\"source\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"questions\":[{\"id\":\"agboville-2__gynecologie-obstetrique__0\",\"num\":\"1\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"Premier Groupe de Sujet — QCD (Q1 à Q50)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Au cours de la G.A.T.P.A., immédiatement après l'expulsion du fœtus, il faut palper l'abdomen de la mère pour écarter l'éventualité d'un ou d'autres fœtus, avant d'administrer par voie IM 10 UI d'ocytocine.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Vrai\",\"answerLetters\":[\"A\"],\"explanation\":\"Avant d'injecter les 10 UI d'ocytocine en IM dans la minute suivant la naissance (1re étape de la GATPA), il est impératif de palper l'abdomen maternel pour vérifier l'absence d'un second jumeau méconnu (risque d'enchatonnement/hypertonie sur J2).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"agboville-2__gynecologie-obstetrique__1\",\"num\":\"2\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"Premier Groupe de Sujet — QCD (Q1 à Q50)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"L'hémorragie du post-partum (H.P.P.) est la première cause de décès maternel d'origine obstétricale directe en Côte d'Ivoire.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Vrai\",\"answerLetters\":[\"A\"],\"explanation\":\"En Côte d'Ivoire comme en Afrique subsaharienne, l'hémorragie du post-partum immédiat (HPP) demeure la première cause de mortalité maternelle directe (plus de 30 à 40 % des décès maternels).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"agboville-2__gynecologie-obstetrique__2\",\"num\":\"3\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"Premier Groupe de Sujet — QCD (Q1 à Q50)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Les précautions d'asepsie rigoureuse ne sont pas nécessaires au cours de la révision utérine.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"La révision utérine est une manœuvre endo-utérine à très haut risque infectieux (endométrite, septicémie) qui exige impérativement une asepsie chirurgicale rigoureuse (badigeonnage vulvo-périnéal, gants stériles de révision utérine longs jusqu'au coude) et une antibioprophylaxie. (Attention : la feuille brute comporte une faute de frappe 'A', mais la vérité obstétricale absolue est B = Faux).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"agboville-2__gynecologie-obstetrique__3\",\"num\":\"4\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"Premier Groupe de Sujet — QCD (Q1 à Q50)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"L'épisiotomie est indiquée au cours de toute extraction fœtale par forceps.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Vrai\",\"answerLetters\":[\"A\"],\"explanation\":\"Dans l'enseignement classique de l'INFAS, l'extraction instrumentale par forceps (dont les cuillères augmentent le volume céphalique et distendent fortement le périnée) est une indication classique d'épisiotomie préventive des déchirures périnéales complètes.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"agboville-2__gynecologie-obstetrique__4\",\"num\":\"5\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"Premier Groupe de Sujet — QCD (Q1 à Q50)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Au cours des déchirures périnéales incomplètes (du 1er ou 2e degré), le sphincter de l'anus est intéressé par la déchirure.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"Dans la classification française classique utilisée à l'INFAS : une déchirure périnéale INCOMPLÈTE (1er ou 2e degré) respecte le sphincter externe de l'anus ; dès que le sphincter anal est rompu, on parle de déchirure COMPLÈTE (3e degré, et complète compliquée / 4e degré si la muqueuse ano-rectale est atteinte).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"agboville-2__gynecologie-obstetrique__5\",\"num\":\"6\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"Premier Groupe de Sujet — QCD (Q1 à Q50)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Un taux d'hémoglobine égal à 10,60 g pour 100 ml de sang (10,6 g/dl) chez une gestante à la 24ème semaine d'aménorrhée (2e trimestre) est synonyme d'anémie.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"Au 2e trimestre de la grossesse (ici à 24 SA), en raison du pic d'hémodilution physiologique plasmatique, le seuil inférieur normal de l'hémoglobine est abaissé à 10,5 g/dl (alors qu'il est de 11,0 g/dl aux 1er et 3e trimestres). Un taux de 10,60 g/dl à 24 SA est donc supérieur à 10,5 g/dl et n'est pas synonyme d'anémie !\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"agboville-2__gynecologie-obstetrique__6\",\"num\":\"7\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"Premier Groupe de Sujet — QCD (Q1 à Q50)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"La mesure de la hauteur utérine se fait à chaque consultation à partir du 3ème mois de grossesse.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"La mesure de la hauteur utérine au ruban métrique se pratique à partir du 4ème MOIS de grossesse (16 SA, lorsque le fond utérin déborde nettement le bord supérieur de la symphyse pubienne) et non dès le 3e mois.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"agboville-2__gynecologie-obstetrique__7\",\"num\":\"8\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"Premier Groupe de Sujet — QCD (Q1 à Q50)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"L'hémoglobinopathie AS est une forme majeure (ou grave) de la drépanocytose.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"Le phénotype hétérozygote AS est la forme MINEURE asymptomatique (trait drépanocytaire, porteur sain). Les formes majeures sont SS, SC et Sβ-thalassémie.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"agboville-2__gynecologie-obstetrique__8\",\"num\":\"9\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"Premier Groupe de Sujet — QCD (Q1 à Q50)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"La nécrobiose aseptique du fibrome est une complication rare du myome durant la grossesse.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"La nécrobiose aseptique (ischémie aiguë du fibrome par insuffisance de vascularisation face à son hypertrophie rapide sous l'influence hormonale gravidique) est au contraire la complication LA PLUS FRÉQUENTE et la plus caractéristique du fibrome pendant la grossesse.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"agboville-2__gynecologie-obstetrique__9\",\"num\":\"10\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"Premier Groupe de Sujet — QCD (Q1 à Q50)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"La troisième phase du travail de l'accouchement (la délivrance) constitue la période la plus à risque pour le nouveau-né.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"La 3e phase du travail (délivrance placentaire après la naissance de l'enfant) est la période la plus à risque pour la MÈRE (risque d'hémorragie de la délivrance), tandis que la 2e phase (expulsion) est la plus à risque pour le fœtus.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"agboville-2__gynecologie-obstetrique__10\",\"num\":\"11\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"Premier Groupe de Sujet — QCD (Q1 à Q50)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"L'hémorragie du post-partum immédiat est l'hémorragie génitale qui survient dans les 2 heures qui suivent l'accouchement.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"Selon l'OMS, l'hémorragie du post-partum immédiat (HPPI ou primaire) se définit par une perte sanguine ≥ 500 ml survenant dans les 24 PREMIÈRES HEURES qui suivent l'accouchement (et non seulement dans les 2 premières heures).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"agboville-2__gynecologie-obstetrique__11\",\"num\":\"12\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"Premier Groupe de Sujet — QCD (Q1 à Q50)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"L'épisiotomie n'est pas obligatoire dans l'accouchement du prématuré.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"Selon les normes académiques classiques de l'INFAS, la prématurité (et la souffrance fœtale) figure parmi les indications fœtales d'épisiotomie afin de raccourcir la période d'expulsion et protéger le crâne malléable du prématuré.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"agboville-2__gynecologie-obstetrique__12\",\"num\":\"13\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"Premier Groupe de Sujet — QCD (Q1 à Q50)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Un taux d'hémoglobine égal à 10,60 g pour 100 ml de sang (10,6 g/dl) chez une gestante à la 34ème semaine d'aménorrhée (3e trimestre) est synonyme d'anémie.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Vrai\",\"answerLetters\":[\"A\"],\"explanation\":\"Au 3e trimestre de la grossesse (ici à 34 SA), le seuil définissant l'anémie est de 11,0 g/dl (< 11 g/dl). Un taux de 10,60 g/dl à 34 SA est donc bien inférieur à 11 g/dl et définit une anémie légère !\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"agboville-2__gynecologie-obstetrique__13\",\"num\":\"14\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"Premier Groupe de Sujet — QCD (Q1 à Q50)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"À 7 mois d'une grossesse monofœtale normale, la hauteur utérine normale est égale à 28 cm.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Vrai\",\"answerLetters\":[\"A\"],\"explanation\":\"D'après la règle de calcul de la hauteur utérine normale entre le 4e et le 7e mois : HU (cm) = Nombre de mois × 4. À 7 mois : 7 × 4 = 28 cm.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"agboville-2__gynecologie-obstetrique__14\",\"num\":\"15\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"Premier Groupe de Sujet — QCD (Q1 à Q50)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"L'endométrite puerpérale peut se compliquer de stérilité primaire.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"Piège subtil mais imparable : une endométrite PUERPÉRALE survient par définition APRÈS un accouchement (la femme a donc déjà été enceinte au moins une fois). Toute stérilité ultérieure (par synéchie utérine ou obstruction tubaire) sera donc obligatoirement une stérilité SECONDAIRE, et jamais primaire !\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"agboville-2__gynecologie-obstetrique__15\",\"num\":\"16\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"Premier Groupe de Sujet — QCD (Q1 à Q50)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"L'hémoglobinopathie SC n'est pas une forme majeure de drépanocytose.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"Le double hétérozygote composite SC fait pleinement partie des syndromes drépanocytaires MAJEURS (avec les formes SS et Sβ-thalassémie) et expose à de graves complications vaso-occlusives et thromboemboliques, notamment au 3e trimestre et en post-partum.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"agboville-2__gynecologie-obstetrique__16\",\"num\":\"17\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"Premier Groupe de Sujet — QCD (Q1 à Q50)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"La pyélonéphrite peut être une complication maternelle de l'anémie dans les suites de couches.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Vrai\",\"answerLetters\":[\"A\"],\"explanation\":\"L'anémie maternelle diminue les défenses immunitaires et favorise toutes les infections bactériennes des suites de couches (endométrite, infections urinaires / pyélonéphrite aiguë, suppurations pariétales).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"agboville-2__gynecologie-obstetrique__17\",\"num\":\"18\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"Premier Groupe de Sujet — QCD (Q1 à Q50)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Dans les suites de couches, un utérus mou, gros, douloureux à la pression et des lochies fétides mélangées aux métrorragies évoquent une endométrite puerpérale.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Vrai\",\"answerLetters\":[\"A\"],\"explanation\":\"C'est la triade clinique pathognomonique de l'endométrite aiguë du post-partum : syndrome infectieux (fièvre) + subinvolution utérine douloureuse (utérus gros, mou et sensible à la mobilisation) + lochies fétides/hémorragiques.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"agboville-2__gynecologie-obstetrique__18\",\"num\":\"19\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"Premier Groupe de Sujet — QCD (Q1 à Q50)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Au cours de la déchirure complète et compliquée du périnée, il y a uniquement une déchirure de la muqueuse vaginale (sans atteinte du sphincter anal ni de la muqueuse ano-rectale).\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"La déchirure périnéale complète et compliquée (4e degré) intéresse la peau périnéale, la muqueuse vaginale, les muscles du périnée superficiel et profond, le sphincter externe de l'anus ET la muqueuse du canal anal / rectum (transformant la vulve et l'anus en un cloaque unique).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"agboville-2__gynecologie-obstetrique__19\",\"num\":\"20\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"Premier Groupe de Sujet — QCD (Q1 à Q50)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Durant la technique de réalisation de la G.A.T.P.A., il est recommandé de renouveler le massage utérin toutes les 15 mn pendant trois heures.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"La surveillance de la tonicité utérine (globe de sécurité) toutes les 15 minutes après la GATPA se fait pendant les DEUX (02) premières heures du post-partum immédiat en salle de naissance (et non pendant trois heures).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"agboville-2__gynecologie-obstetrique__20\",\"num\":\"21\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"Premier Groupe de Sujet — QCD (Q1 à Q50)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"L'hémorragie de la délivrance peut être l'une des causes de l'hémorragie du post-partum immédiat.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Vrai\",\"answerLetters\":[\"A\"],\"explanation\":\"L'hémorragie du post-partum immédiat regroupe les saignements provenant de la zone d'insertion placentaire (hémorragie de la délivrance par atonie utérine ou rétention placentaire, qui en représente 80 % des cas), les traumatismes de la filière génitale (déchirures cervicales, vaginales, périnéales, rupture utérine) et les coagulopathies.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"agboville-2__gynecologie-obstetrique__21\",\"num\":\"22\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"Premier Groupe de Sujet — QCD (Q1 à Q50)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"En cas de présentation céphalique, le bon moment pour pratiquer l'épisiotomie correspond classiquement à une dilatation anale de 2 cm (lorsque la présentation distend le périnée et ouvre l'anus de 2 cm pendant l'effort expulsif).\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Vrai\",\"answerLetters\":[\"A\"],\"explanation\":\"Classiquement, l'épisiotomie se réalise au moment du couronnement, au sommet d'une contraction utérine et d'un effort expulsif, lorsque la tête fœtale distend et amincit le périnée postérieur avec une béance de l'orifice anal d'environ 2 cm.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"agboville-2__gynecologie-obstetrique__22\",\"num\":\"23\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"Premier Groupe de Sujet — QCD (Q1 à Q50)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"La carence en acide folique est une cause de l'anémie chez la gestante.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Vrai\",\"answerLetters\":[\"A\"],\"explanation\":\"Oui, la carence en acide folique (vitamine B9) est la principale cause d'anémie macrocytaire mégaloblastique chez la femme enceinte (souvent associée à la carence en fer).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"agboville-2__gynecologie-obstetrique__23\",\"num\":\"24\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"Premier Groupe de Sujet — QCD (Q1 à Q50)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"La chorioamniotite et la rupture prématurée des membranes supérieure à 12 heures sont des facteurs favorisant l'endométrite puerpérale.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Vrai\",\"answerLetters\":[\"A\"],\"explanation\":\"L'ouverture prolongée de l'œuf (> 12 h) et l'infection amniotique per-partum (chorioamniotite) constituent les facteurs de risque majeurs d'endométrite aiguë du post-partum.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"agboville-2__gynecologie-obstetrique__24\",\"num\":\"25\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"Premier Groupe de Sujet — QCD (Q1 à Q50)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"L'électrophorèse de l'hémoglobine et l'hémogramme sont des examens complémentaires qui dépistent (affirment tous deux spécifiquement) la drépanocytose majeure.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"L'hémogramme (NFS) montre uniquement l'anémie (et l'hyperleucocytose/thrombocytose), mais ne permet pas de diagnostiquer la drépanocytose : SEULE l'électrophorèse de l'hémoglobine (ou CLHP/isoélectrofocalisation) permet de typer l'hémoglobine et d'affirmer le diagnostic de drépanocytose majeure.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"agboville-2__gynecologie-obstetrique__25\",\"num\":\"26\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"Premier Groupe de Sujet — QCD (Q1 à Q50)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"L'œuf clair peut être une complication de l'anémie par carence en fer.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"L'œuf clair (grossesse arrêtée très précocement sans développement embryonnaire visible) est dû dans la grande majorité des cas à une anomalie chromosomique sporadique de l'œuf, et non à une carence martiale maternelle.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"agboville-2__gynecologie-obstetrique__26\",\"num\":\"27\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"Premier Groupe de Sujet — QCD (Q1 à Q50)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"L'anesthésie (locale par infiltration de lidocaïne ou locorégionale/péridurale) est obligatoire avant la réparation de toute épisiotomie.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Vrai\",\"answerLetters\":[\"A\"],\"explanation\":\"Selon les normes de soins obstétricaux humanisés et de qualité (SONU), toute épisiorraphie ou suture de déchirure périnéale doit obligatoirement être précédée d'une anesthésie locale (infiltration de lidocaïne à 1 % à défaut de péridurale).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"agboville-2__gynecologie-obstetrique__27\",\"num\":\"28\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"Premier Groupe de Sujet — QCD (Q1 à Q50)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"La grossesse multiple et l'oligoamnios sont des causes de hauteur utérine supérieure à la normale.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"La grossesse multiple donne bien un excès de hauteur utérine, mais l'OLIGOAMNIOS (diminution du volume de liquide amniotique) donne au contraire une hauteur utérine INFÉRIEURE à la normale (c'est l'hydramnios qui donne une HU excessive).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"agboville-2__gynecologie-obstetrique__28\",\"num\":\"29\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"Premier Groupe de Sujet — QCD (Q1 à Q50)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"La douleur pelvienne médiane associée aux lochies abondantes et fétides sont des signes fonctionnels de l'endométrite puerpérale.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Vrai\",\"answerLetters\":[\"A\"],\"explanation\":\"Les douleurs pelviennes hypogastriques spontanées et l'écoulement de lochies fétides/malodorantes constituent les signes fonctionnels typiques de l'endométrite du post-partum.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"agboville-2__gynecologie-obstetrique__29\",\"num\":\"30\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"Premier Groupe de Sujet — QCD (Q1 à Q50)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Durant la technique de la traction contrôlée sur le cordon ombilical, il faut tirer fortement sur le cordon ombilical en direction du bas pour extraire le placenta.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"Tirer fortement (brutalement) sur le cordon sans contre-pression sus-pubienne expose à deux accidents dramatiques : l'arrachement du cordon et l'inversion utérine aiguë. La traction doit être douce, constante et contrôlée, uniquement pendant une contraction utérine et toujours associée à une contre-pression sus-pubienne refoulant le corps utérin vers le haut.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"agboville-2__gynecologie-obstetrique__30\",\"num\":\"31\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"Premier Groupe de Sujet — QCD (Q1 à Q50)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"La délivrance artificielle et la révision utérine font toutes deux partie des éléments de prise en charge de la rétention placentaire incomplète (rétention de cotylédon ou de membranes après expulsion du placenta).\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"En cas de rétention placentaire INCOMPLÈTE (le placenta a déjà été expulsé mais est incomplet à l'examen du délivre : cotylédon manquant ou membranes déchiquetées), on réalise uniquement une RÉVISION UTÉRINE (et non une délivrance artificielle, qui ne se conçoit que lorsque le placenta tout entier est encore retenu dans l'utérus).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"agboville-2__gynecologie-obstetrique__31\",\"num\":\"32\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"Premier Groupe de Sujet — QCD (Q1 à Q50)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"La section au cours de l'épisiotomie doit être d'un seul coup de ciseaux sur une longueur de 4 cm en dehors d'une contraction utérine, sous contrôle de la vue.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"L'épisiotomie ne se pratique JAMAIS 'en dehors d'une contraction utérine' : elle doit être effectuée AU SOMMET d'une contraction utérine et d'un effort expulsif, lorsque la présentation distend et amincit au maximum le périnée.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"agboville-2__gynecologie-obstetrique__32\",\"num\":\"33\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"Premier Groupe de Sujet — QCD (Q1 à Q50)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Chez la femme enceinte séropositive au VIH sous prophylaxie au Cotrimoxazole, il est recommandé d'administrer la Sulfadoxine-Pyriméthamine (S-P) en traitement préventif intermittent.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"L'association Cotrimoxazole + Sulfadoxine-Pyriméthamine (deux sulfamides antifoliques) est formellement contre-indiquée en raison du risque accru de toxidermie grave (syndrome de Lyell / Stevens-Johnson) et de cytopénie. Le Cotrimoxazole quotidien assure déjà la prévention antipaludique.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"agboville-2__gynecologie-obstetrique__33\",\"num\":\"34\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"Premier Groupe de Sujet — QCD (Q1 à Q50)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"La pratique avec asepsie de la délivrance artificielle et de la révision utérine sont des facteurs favorisant l'endométrite puerpérale.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"Comme indiqué sur la feuille du sujet (B), c'est la réalisation SANS asepsie (ou sans antibioprophylaxie) des manœuvres endo-utérines qui est le facteur fautif d'infection puerpérale.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"agboville-2__gynecologie-obstetrique__34\",\"num\":\"35\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"Premier Groupe de Sujet — QCD (Q1 à Q50)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"L'extraction fœtale instrumentale (pour abréger les efforts expulsifs) est vivement recommandée chez une parturiente ayant un taux d'hémoglobine égal à 10 g/100 ml de sang.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"Médicalement, l'extraction instrumentale prophylactique d'épargne maternelle est indiquée dans les anémies sévères mal tolérées (Hb < 7 g/dl avec dyspnée/tachycardie). Cependant, le corrigé indicatif figurant sur l'épreuve d'Agboville indique 'A' (Vrai).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"agboville-2__gynecologie-obstetrique__35\",\"num\":\"36\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"Premier Groupe de Sujet — QCD (Q1 à Q50)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Le bec-de-lièvre (fente labio-palatine) et la souffrance fœtale chronique peuvent compliquer l'anémie par manque de fer.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"Les malformations embryonnaires de fermeture (anomalie du tube neural : spina bifida, anencéphalie, et fentes labio-palatines / bec-de-lièvre) sont liées à la carence pré-conceptionnelle et du 1er trimestre en ACIDE FOLIQUE (vitamine B9), et non à la carence en fer !\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"agboville-2__gynecologie-obstetrique__36\",\"num\":\"37\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"Premier Groupe de Sujet — QCD (Q1 à Q50)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"L'épisiotomie doit être réparée rapidement avant la délivrance pour minimiser les pertes de sang.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"On ne suture JAMAIS une épisiotomie avant la délivrance placentaire ! En effet, si une rétention placentaire ou une hémorragie de la délivrance survient, l'introduction de la main pour une délivrance artificielle ou une révision utérine ferait sauter tous les points de suture. En attendant la délivrance, on place un tampon/compresse hémostatique et on réalise la GATPA.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"agboville-2__gynecologie-obstetrique__37\",\"num\":\"38\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"Premier Groupe de Sujet — QCD (Q1 à Q50)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Au cours de la révision utérine, il faut introduire la main dans les voies génitales en suivant le trajet du cordon ombilical.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"Suivre le trajet du cordon ombilical jusqu'à son insertion placentaire est la technique de la DÉLIVRANCE ARTIFICIELLE (lorsque le placenta est encore dans l'utérus). Lors d'une RÉVISION UTÉRINE, le placenta et le cordon sont déjà sortis : il n'y a donc plus de cordon ombilical à suivre !\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"agboville-2__gynecologie-obstetrique__38\",\"num\":\"39\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"Premier Groupe de Sujet — QCD (Q1 à Q50)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"La révision utérine et le massage de l'utérus sont préconisés dans le traitement de l'atonie utérine.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Vrai\",\"answerLetters\":[\"A\"],\"explanation\":\"Devant toute hémorragie du post-partum par atonie utérine, la conduite immédiate associe la révision utérine (pour s'assurer de la vacuité totale de l'utérus et évacuer les caillots qui empêchent la rétraction), le massage utérin externe/bimanuel, le sondage vésical et la perfusion d'utérotoniques.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"agboville-2__gynecologie-obstetrique__39\",\"num\":\"40\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"Premier Groupe de Sujet — QCD (Q1 à Q50)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Avant de réaliser la G.A.T.P.A., il faut examiner soigneusement les voies génitales sous valves et procéder à la réfection des déchirures cervicales.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"La GATPA se réalise dans la minute qui suit la naissance du bébé pour diriger la délivrance placentaire. L'examen sous valves du col utérin et des parois vaginales ainsi que la suture des déchirures ne se font qu'APRÈS la délivrance.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"agboville-2__gynecologie-obstetrique__40\",\"num\":\"41\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"Premier Groupe de Sujet — QCD (Q1 à Q50)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"L'antécédent de césarienne est une contre-indication à l'accouchement par la voie basse si le fœtus est en présentation du siège complet.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Vrai\",\"answerLetters\":[\"A\"],\"explanation\":\"L'association d'un utérus cicatriciel (antécédent de césarienne) et d'une présentation du siège est une contre-indication formelle à l'épreuve utérine par voie basse et impose une césarienne prophylactique.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"agboville-2__gynecologie-obstetrique__41\",\"num\":\"42\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"Premier Groupe de Sujet — QCD (Q1 à Q50)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Le paludisme est la maladie bactérienne causée par le Plasmodium.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"Le paludisme est une maladie PARASITAIRE (protozoaire hématozoaire du genre Plasmodium) et non bactérienne.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"agboville-2__gynecologie-obstetrique__42\",\"num\":\"43\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"Premier Groupe de Sujet — QCD (Q1 à Q50)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Au cours de l'accouchement du siège décomplété par voie vaginale, la sage-femme est autorisée à placer une perfusion de 5 UI de Syntocinon dans 500 ml de sérum glucosé isotonique à 9 cm de dilatation cervicale, même si elle se trouve dans une maternité périphérique.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"Un accouchement en présentation du siège est un accouchement à haut risque qui ne doit JAMAIS être conduit ni dirigé aux ocytociques dans une maternité périphérique (SONU de base sans bloc opératoire) : toute présentation du siège diagnostiquée en périphérie doit être référée vers un centre SONU Complet.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"agboville-2__gynecologie-obstetrique__43\",\"num\":\"44\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"Premier Groupe de Sujet — QCD (Q1 à Q50)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"L'usage de la moustiquaire imprégnée d'insecticide à longue durée d'action (MILDA) peut débuter au 2ème trimestre de grossesse (si la gestante vient pour sa CPN1 au 2e trimestre).\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Vrai\",\"answerLetters\":[\"A\"],\"explanation\":\"Bien que la MILDA doive être remise dès le 1er contact prénatal (idéalement dès le 1er trimestre), elle peut et doit être débutée à n'importe quel terme de la grossesse (y compris au 2e trimestre) dès que la gestante se présente.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"agboville-2__gynecologie-obstetrique__44\",\"num\":\"45\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"Premier Groupe de Sujet — QCD (Q1 à Q50)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"La pratique d'une large épisiotomie est recommandée au cours de l'expulsion du siège (notamment chez la primipare).\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Vrai\",\"answerLetters\":[\"A\"],\"explanation\":\"Dans l'obstétrique classique enseignée à l'INFAS, l'épisiotomie est recommandée lors du dégagement du siège (notamment chez la primipare) pour supprimer la résistance des parties molles périnéales et faciliter le dégagement rapide des épaules et de la tête dernière.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"agboville-2__gynecologie-obstetrique__45\",\"num\":\"46\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"Premier Groupe de Sujet — QCD (Q1 à Q50)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"L'usage de la moustiquaire imprégnée d'insecticide à longue durée d'action (MILDA) fait partie des mesures de prévention du paludisme à la 35ème semaine d'aménorrhée.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Vrai\",\"answerLetters\":[\"A\"],\"explanation\":\"La gestante doit dormir sous MILDA toutes les nuits tout au long de sa grossesse (y compris à 35 SA) et pendant le post-partum avec son nouveau-né.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"agboville-2__gynecologie-obstetrique__46\",\"num\":\"47\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"Premier Groupe de Sujet — QCD (Q1 à Q50)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"L'accouchement par la voie basse n'est pas contre-indiqué en cas de grossesse gémellaire avec le premier jumeau (J1) en présentation du siège décomplété.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"Dans le programme INFAS, une grossesse gémellaire dont le premier jumeau (J1) n'est pas en présentation céphalique du sommet (ici J1 en présentation du siège) constitue une indication classique de césarienne prophylactique (notamment pour éviter toute dystocie de J1 et le risque d'accrochage des mentons si J2 est en céphalique).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"agboville-2__gynecologie-obstetrique__47\",\"num\":\"48\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"Premier Groupe de Sujet — QCD (Q1 à Q50)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Au cours de l'accouchement du siège décomplété par voie vaginale, la sage-femme doit effectuer la manœuvre de Bracht dès que les oreilles du fœtus apparaissent à la vulve.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"La manœuvre de Bracht se débute dès que la pointe des OMOPLATES (scapulas) apparaît à la vulve et que les épaules se dégagent, le menton et la bouche puis le nez, les yeux et le front se dégageant progressivement à la commissure postérieure — on n'attend pas l'apparition des 'oreilles' !\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"agboville-2__gynecologie-obstetrique__48\",\"num\":\"49\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"Premier Groupe de Sujet — QCD (Q1 à Q50)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Les dérivés de l'Artémisinine (CTA par voie orale) peuvent être conseillés au cours du traitement du paludisme simple durant le 1er trimestre de grossesse (selon l'ancien protocole national utilisant la Quinine au 1er trimestre).\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"Dans le protocole classique enseigné à l'INFAS, le traitement du paludisme simple au 1er trimestre de la grossesse repose sur les sels de QUININE par voie orale (les CTA n'étant utilisées en première intention qu'à partir du 2e trimestre, bien que les directives récentes de l'OMS autorisent désormais l'Artéméther-Luméfantrine au 1er trimestre).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"agboville-2__gynecologie-obstetrique__49\",\"num\":\"50\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"Premier Groupe de Sujet — QCD (Q1 à Q50)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Au cours de l'accouchement du siège complet par voie basse, la sage-femme doit rompre artificiellement la poche des eaux à 9 centimètres de dilatation cervicale.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"Règle d'or absolue dans l'accouchement du siège (surtout du siège complet) : il faut RESPECTER L'INTÉGRITÉ DE LA POCHE DES EAUX le plus longtemps possible (au moins jusqu'à dilatation complète à 10 cm et engagement profond du siège), car la poche des eaux dilate harmonieusement le col et empêche la procidence du cordon ou d'un pied !\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"agboville-2__gynecologie-obstetrique__50\",\"num\":\"51\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"Deuxième Groupe de Sujet — QCD à 2 points (Q51 à Q55)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Le poignet de la main qui réalise la délivrance artificielle est visible à l'extérieur durant la réalisation de ce geste.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"Lors de la délivrance artificielle, la main de l'opérateur est au fond de la cavité utérine et l'avant-bras est engagé dans le vagin : le poignet est donc à l'intérieur des voies génitales et n'est pas visible à l'extérieur.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"agboville-2__gynecologie-obstetrique__51\",\"num\":\"52\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"Deuxième Groupe de Sujet — QCD à 2 points (Q51 à Q55)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Dans l'épisiotomie médio-latérale, l'incision part du milieu de la fourchette vulvaire et se dirige latéralement selon un angle de 90° avec la ligne médiane, dans le but de respecter l'anus et le rectum.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"L'épisiotomie médio-latérale se dirige obliquement en bas et en dehors selon un angle de 45° (à 60°) par rapport à la verticale médiane vers l'ischion, et non à 90° (un angle de 90° serait horizontal et sectionnerait la glande de Bartholin et les corps érectiles).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"agboville-2__gynecologie-obstetrique__52\",\"num\":\"53\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"Deuxième Groupe de Sujet — QCD à 2 points (Q51 à Q55)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"En cas de prévention du paludisme avec la Sulfadoxine-Pyriméthamine (SP) au cours de la grossesse, la gestante doit arrêter durant 15 jours (1 à 2 semaines) la prise de l'acide folique quand elle prend ≥ 5 mg (ici 10 mg/jour) d'acide folique.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Vrai\",\"answerLetters\":[\"A\"],\"explanation\":\"L'acide folique à forte dose (≥ 5 mg/jour, ici 10 mg/jour) antagonise par compétition le mécanisme d'action antifolate de la Sulfadoxine-Pyriméthamine sur le Plasmodium et annule l'efficacité du TPI-SP. Il faut donc suspendre l'acide folique fortement dosé pendant 14 jours (2 semaines) après la prise de la SP (alors que la dose préventive faible de 0,4 mg = 400 µg n'interfère pas).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"agboville-2__gynecologie-obstetrique__53\",\"num\":\"54\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"Deuxième Groupe de Sujet — QCD à 2 points (Q51 à Q55)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Au cours de la mesure de la hauteur utérine, il faut palper le bord supérieur de la symphyse pubienne et placer l'extrémité (le zéro) du centimètre au contact du bord supérieur de cette symphyse pubienne et l'y maintenir avec l'index.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Vrai\",\"answerLetters\":[\"A\"],\"explanation\":\"C'est exactement la technique normalisée de mesure de la hauteur utérine (patiente en décubitus dorsal, vessie préalablement vidée, extrémité 0 du ruban métrique souple maintenue sur le bord supérieur de la symphyse pubienne et déroulée sur la ligne médiane jusqu'au fond utérin maintenu par le bord cubital de l'autre main).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"agboville-2__gynecologie-obstetrique__54\",\"num\":\"55\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"Deuxième Groupe de Sujet — QCD à 2 points (Q51 à Q55)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Dans le traitement curatif de l'anémie ferriprive chez une gestante, avec un taux d'hémoglobine égal à 10,40 g/100 ml de sang, on doit prescrire 200 mg de fer/jour par voie orale, à prendre durant les repas.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"Pour une absorption digestive maximale du fer ferreux au niveau duodénal, les comprimés de fer doivent être pris EN DEHORS DES REPAS (à jeun ou 30 à 60 minutes avant les repas, avec de l'eau ou un jus d'agrume riche en vitamine C), car les phytates, tanins (thé, café) et calcium des repas chélatent le fer et réduisent fortement son absorption. +-----------------------------------------------------------------------+\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null}]},{\"name\":\"SSR / PF\",\"slug\":\"ssr-pf\",\"pages\":\"\",\"count\":42,\"session\":\"S2\",\"annee\":2025,\"source\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"questions\":[{\"id\":\"agboville-2__ssr-pf__0\",\"num\":\"1\",\"type\":\"CAS_CLINIQUE\",\"typeLabel\":\"Étude de cas / Cas clinique\",\"partieTitle\":\"Questions Q1 à Q43 (Études de cas Broukro & Mme Droh + QCM/QCD)\",\"caseTitle\":\"Étude de cas N°I Centre de santé de Broukro & Étude de cas N°II Mme\",\"caseData\":\"Droh, 48 ans, G5P4 (Q1 à Q43) +=======================================================================+ +-----------------------------------------------------------------------+ ◆ ÉTUDES DE CAS N°I (Centre de Broukro) et N°II (Mme Droh, 48 ans, G5P4) [Q1 à Q43] ----------------------------------------------------------------------- Énoncé du cas : Cas N°I (Broukro) : Consommation de COC des 3 derniers mois typiques : Mars = 48 cycles ; Avril = 45 cycles ; Mai = 43 cycles. Stock après inventaire physique disponible utilisable = 110 cycles (et 5 cycles ayant des comprimés écrasés). Cas N°II (Mme Droh) : Mme Droh, 48 ans, G5P4 (4 enfants vivants), consulte en PF. Elle a utilisé un DIU il y a 3 ans posé en salle d'accouchement juste après l'accouchement. La persistance des crampes menstruelles l'a motivée à changer de méthode. Ces 5 derniers mois, son cycle menstruel est irrégulier. Elle opte pour l'auto-observation. ----------------------------------------------------------------------- -----------------------------------------------------------------------\",\"text\":\"Quelle est la consommation moyenne mensuelle (CMM) de COC du centre de santé de Broukro ?\",\"options\":[{\"letter\":\"A\",\"text\":\"45,33 cycles\"},{\"letter\":\"B\",\"text\":\"45 cycles\"},{\"letter\":\"C\",\"text\":\"45,50 cycles\"},{\"letter\":\"D\",\"text\":\"46 cycles\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. 45 cycles\",\"answerLetters\":[\"B\"],\"explanation\":\"Formule de la CMM = (Consommation Mois 1 + Mois 2 + Mois 3) / 3 = (48 + 45 + 43) / 3 = 136 / 3 = 45,33 cycles (a), soit 45 cycles à l'arrondi standard (b) ou 46 cycles à l'entier supérieur (d).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"agboville-2__ssr-pf__1\",\"num\":\"2\",\"type\":\"CAS_CLINIQUE\",\"typeLabel\":\"Étude de cas / Cas clinique\",\"partieTitle\":\"Questions Q1 à Q43 (Études de cas Broukro & Mme Droh + QCM/QCD)\",\"caseTitle\":\"Étude de cas N°I Centre de santé de Broukro & Étude de cas N°II Mme\",\"caseData\":\"Droh, 48 ans, G5P4 (Q1 à Q43) +=======================================================================+ +-----------------------------------------------------------------------+ ◆ ÉTUDES DE CAS N°I (Centre de Broukro) et N°II (Mme Droh, 48 ans, G5P4) [Q1 à Q43] ----------------------------------------------------------------------- Énoncé du cas : Cas N°I (Broukro) : Consommation de COC des 3 derniers mois typiques : Mars = 48 cycles ; Avril = 45 cycles ; Mai = 43 cycles. Stock après inventaire physique disponible utilisable = 110 cycles (et 5 cycles ayant des comprimés écrasés). Cas N°II (Mme Droh) : Mme Droh, 48 ans, G5P4 (4 enfants vivants), consulte en PF. Elle a utilisé un DIU il y a 3 ans posé en salle d'accouchement juste après l'accouchement. La persistance des crampes menstruelles l'a motivée à changer de méthode. Ces 5 derniers mois, son cycle menstruel est irrégulier. Elle opte pour l'auto-observation. ----------------------------------------------------------------------- -----------------------------------------------------------------------\",\"text\":\"Cette dernière étape (de la consultation PF) permet au praticien de discuter avec la cliente des méthodes adaptées à sa situation :\",\"options\":[],\"mode\":\"open\",\"multi\":false,\"answer\":\"Non\",\"answerLetters\":[],\"explanation\":\"La discussion des méthodes adaptées à la situation de la cliente se fait lors du counseling et du choix éclairé (avant la dernière étape), tandis que la dernière étape de la consultation est l'administration de la méthode / prise de rendez-vous de suivi.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"agboville-2__ssr-pf__2\",\"num\":\"3\",\"type\":\"CAS_CLINIQUE\",\"typeLabel\":\"Étude de cas / Cas clinique\",\"partieTitle\":\"Questions Q1 à Q43 (Études de cas Broukro & Mme Droh + QCM/QCD)\",\"caseTitle\":\"Étude de cas N°I Centre de santé de Broukro & Étude de cas N°II Mme\",\"caseData\":\"Droh, 48 ans, G5P4 (Q1 à Q43) +=======================================================================+ +-----------------------------------------------------------------------+ ◆ ÉTUDES DE CAS N°I (Centre de Broukro) et N°II (Mme Droh, 48 ans, G5P4) [Q1 à Q43] ----------------------------------------------------------------------- Énoncé du cas : Cas N°I (Broukro) : Consommation de COC des 3 derniers mois typiques : Mars = 48 cycles ; Avril = 45 cycles ; Mai = 43 cycles. Stock après inventaire physique disponible utilisable = 110 cycles (et 5 cycles ayant des comprimés écrasés). Cas N°II (Mme Droh) : Mme Droh, 48 ans, G5P4 (4 enfants vivants), consulte en PF. Elle a utilisé un DIU il y a 3 ans posé en salle d'accouchement juste après l'accouchement. La persistance des crampes menstruelles l'a motivée à changer de méthode. Ces 5 derniers mois, son cycle menstruel est irrégulier. Elle opte pour l'auto-observation. ----------------------------------------------------------------------- -----------------------------------------------------------------------\",\"text\":\"La planification familiale ne peut pas contrôler directement l'un des risques suivants, lequel ?\",\"options\":[{\"letter\":\"A\",\"text\":\"La taille d'une famille\"},{\"letter\":\"B\",\"text\":\"La délinquance juvénile\"},{\"letter\":\"C\",\"text\":\"L'intervalle intergénésique\"},{\"letter\":\"D\",\"text\":\"L'âge de la mère et les grossesses non désirées\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. La délinquance juvénile\",\"answerLetters\":[\"B\"],\"explanation\":\"La planification familiale agit directement sur les quatre facteurs de risque obstétricaux ('trop tôt, trop tard, trop rapproché, trop nombreux' : taille de la famille a, intervalle intergénésique c, âge maternel et grossesses non désirées d), mais ne contrôle pas directement un phénomène sociologique multifactoriel comme la délinquance juvénile (b).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"agboville-2__ssr-pf__3\",\"num\":\"4\",\"type\":\"CAS_CLINIQUE\",\"typeLabel\":\"Étude de cas / Cas clinique\",\"partieTitle\":\"Questions Q1 à Q43 (Études de cas Broukro & Mme Droh + QCM/QCD)\",\"caseTitle\":\"Étude de cas N°I Centre de santé de Broukro & Étude de cas N°II Mme\",\"caseData\":\"Droh, 48 ans, G5P4 (Q1 à Q43) +=======================================================================+ +-----------------------------------------------------------------------+ ◆ ÉTUDES DE CAS N°I (Centre de Broukro) et N°II (Mme Droh, 48 ans, G5P4) [Q1 à Q43] ----------------------------------------------------------------------- Énoncé du cas : Cas N°I (Broukro) : Consommation de COC des 3 derniers mois typiques : Mars = 48 cycles ; Avril = 45 cycles ; Mai = 43 cycles. Stock après inventaire physique disponible utilisable = 110 cycles (et 5 cycles ayant des comprimés écrasés). Cas N°II (Mme Droh) : Mme Droh, 48 ans, G5P4 (4 enfants vivants), consulte en PF. Elle a utilisé un DIU il y a 3 ans posé en salle d'accouchement juste après l'accouchement. La persistance des crampes menstruelles l'a motivée à changer de méthode. Ces 5 derniers mois, son cycle menstruel est irrégulier. Elle opte pour l'auto-observation. ----------------------------------------------------------------------- -----------------------------------------------------------------------\",\"text\":\"Dans la stérilisation féminine ou masculine (CCV), la catégorie « Prudence » (C = Caution de l'OMS) signifie :\",\"options\":[{\"letter\":\"A\",\"text\":\"Attendre que l'état pathologique soit évalué (cela correspond à la catégorie D = Delay / Différer)\"},{\"letter\":\"B\",\"text\":\"Il n'y a aucune raison médicale de refuser la méthode (cela correspond à A = Accepter)\"},{\"letter\":\"C\",\"text\":\"Offrir la méthode normalement mais avec des préparatifs et des précautions supplémentaires\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"C. Offrir la méthode normalement mais avec des préparatifs et des précautions supplémentaires\",\"answerLetters\":[\"C\"],\"explanation\":\"Pour la contraception chirurgicale volontaire (CCV), l'OMS utilise 4 catégories : A (Accepter), C (Caution / Prudence : l'intervention est pratiquée dans un cadre normal mais avec une préparation et des précautions supplémentaires : c), D (Delay / Différer : attendre que l'état pathologique soit traité/évalué : a), et S (Special : exiger un bloc spécialisé avec chirurgien expérimenté et anesthésie générale).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"agboville-2__ssr-pf__4\",\"num\":\"5\",\"type\":\"CAS_CLINIQUE\",\"typeLabel\":\"Étude de cas / Cas clinique\",\"partieTitle\":\"Questions Q1 à Q43 (Études de cas Broukro & Mme Droh + QCM/QCD)\",\"caseTitle\":\"Étude de cas N°I Centre de santé de Broukro & Étude de cas N°II Mme\",\"caseData\":\"Droh, 48 ans, G5P4 (Q1 à Q43) +=======================================================================+ +-----------------------------------------------------------------------+ ◆ ÉTUDES DE CAS N°I (Centre de Broukro) et N°II (Mme Droh, 48 ans, G5P4) [Q1 à Q43] ----------------------------------------------------------------------- Énoncé du cas : Cas N°I (Broukro) : Consommation de COC des 3 derniers mois typiques : Mars = 48 cycles ; Avril = 45 cycles ; Mai = 43 cycles. Stock après inventaire physique disponible utilisable = 110 cycles (et 5 cycles ayant des comprimés écrasés). Cas N°II (Mme Droh) : Mme Droh, 48 ans, G5P4 (4 enfants vivants), consulte en PF. Elle a utilisé un DIU il y a 3 ans posé en salle d'accouchement juste après l'accouchement. La persistance des crampes menstruelles l'a motivée à changer de méthode. Ces 5 derniers mois, son cycle menstruel est irrégulier. Elle opte pour l'auto-observation. ----------------------------------------------------------------------- -----------------------------------------------------------------------\",\"text\":\"Les avantages des méthodes de barrière mécanique :\",\"options\":[{\"letter\":\"A\",\"text\":\"Le réapprovisionnement doit être disponible\"},{\"letter\":\"B\",\"text\":\"Pas de risque de santé (systémique/hormonal) lié à la méthode\"},{\"letter\":\"C\",\"text\":\"Aide à la prévention du cancer du col de l'utérus (en protégeant contre l'HPV)\"},{\"letter\":\"D\",\"text\":\"Augmente l'humidité pendant le rapport sexuel\"}],\"mode\":\"mcq\",\"multi\":true,\"answer\":\"B et C\",\"answerLetters\":[\"B\",\"C\"],\"explanation\":\"Les méthodes de barrière mécanique (préservatifs) ont pour avantages majeurs l'absence d'effets secondaires systémiques/hormonaux sur la santé (b) et la protection contre les IST dont le virus HPV, contribuant ainsi à prévenir le cancer du col de l'utérus (c).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"agboville-2__ssr-pf__5\",\"num\":\"6\",\"type\":\"CAS_CLINIQUE\",\"typeLabel\":\"Étude de cas / Cas clinique\",\"partieTitle\":\"Questions Q1 à Q43 (Études de cas Broukro & Mme Droh + QCM/QCD)\",\"caseTitle\":\"Étude de cas N°I Centre de santé de Broukro & Étude de cas N°II Mme\",\"caseData\":\"Droh, 48 ans, G5P4 (Q1 à Q43) +=======================================================================+ +-----------------------------------------------------------------------+ ◆ ÉTUDES DE CAS N°I (Centre de Broukro) et N°II (Mme Droh, 48 ans, G5P4) [Q1 à Q43] ----------------------------------------------------------------------- Énoncé du cas : Cas N°I (Broukro) : Consommation de COC des 3 derniers mois typiques : Mars = 48 cycles ; Avril = 45 cycles ; Mai = 43 cycles. Stock après inventaire physique disponible utilisable = 110 cycles (et 5 cycles ayant des comprimés écrasés). Cas N°II (Mme Droh) : Mme Droh, 48 ans, G5P4 (4 enfants vivants), consulte en PF. Elle a utilisé un DIU il y a 3 ans posé en salle d'accouchement juste après l'accouchement. La persistance des crampes menstruelles l'a motivée à changer de méthode. Ces 5 derniers mois, son cycle menstruel est irrégulier. Elle opte pour l'auto-observation. ----------------------------------------------------------------------- -----------------------------------------------------------------------\",\"text\":\"Fournir des services de planification familiale de qualité, y compris la lutte contre la stérilité, est un volet de la SAJ (Santé des Adolescents et des Jeunes) / SR :\",\"options\":[],\"mode\":\"open\",\"multi\":false,\"answer\":\"VRAI (dans la Santé de la Reproduction globale ; ou Faux si restreint strictement aux volets spécifiques SAJ où l'infertilité du couple appartient au volet 'Santé des femmes et des mères / SR')\",\"answerLetters\":[],\"explanation\":\"L'offre de services de PF de qualité fait partie intégrante des services adaptés aux adolescents et aux jeunes (SAJ) et de la santé de la reproduction.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"agboville-2__ssr-pf__6\",\"num\":\"7\",\"type\":\"CAS_CLINIQUE\",\"typeLabel\":\"Étude de cas / Cas clinique\",\"partieTitle\":\"Questions Q1 à Q43 (Études de cas Broukro & Mme Droh + QCM/QCD)\",\"caseTitle\":\"Étude de cas N°I Centre de santé de Broukro & Étude de cas N°II Mme\",\"caseData\":\"Droh, 48 ans, G5P4 (Q1 à Q43) +=======================================================================+ +-----------------------------------------------------------------------+ ◆ ÉTUDES DE CAS N°I (Centre de Broukro) et N°II (Mme Droh, 48 ans, G5P4) [Q1 à Q43] ----------------------------------------------------------------------- Énoncé du cas : Cas N°I (Broukro) : Consommation de COC des 3 derniers mois typiques : Mars = 48 cycles ; Avril = 45 cycles ; Mai = 43 cycles. Stock après inventaire physique disponible utilisable = 110 cycles (et 5 cycles ayant des comprimés écrasés). Cas N°II (Mme Droh) : Mme Droh, 48 ans, G5P4 (4 enfants vivants), consulte en PF. Elle a utilisé un DIU il y a 3 ans posé en salle d'accouchement juste après l'accouchement. La persistance des crampes menstruelles l'a motivée à changer de méthode. Ces 5 derniers mois, son cycle menstruel est irrégulier. Elle opte pour l'auto-observation. ----------------------------------------------------------------------- -----------------------------------------------------------------------\",\"text\":\"La différence de traitement ou de conditions de vie entre les hommes et les femmes dans la société ou dans un domaine particulier est une disparité de genre :\",\"options\":[],\"mode\":\"open\",\"multi\":false,\"answer\":\"VRAI\",\"answerLetters\":[],\"explanation\":\"Une disparité (ou inégalité) de genre désigne précisément tout écart ou différence injuste de traitement, de statut, de droits ou de conditions de vie entre les hommes et les femmes dans un domaine donné.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"agboville-2__ssr-pf__7\",\"num\":\"8\",\"type\":\"CAS_CLINIQUE\",\"typeLabel\":\"Étude de cas / Cas clinique\",\"partieTitle\":\"Questions Q1 à Q43 (Études de cas Broukro & Mme Droh + QCM/QCD)\",\"caseTitle\":\"Étude de cas N°I Centre de santé de Broukro & Étude de cas N°II Mme\",\"caseData\":\"Droh, 48 ans, G5P4 (Q1 à Q43) +=======================================================================+ +-----------------------------------------------------------------------+ ◆ ÉTUDES DE CAS N°I (Centre de Broukro) et N°II (Mme Droh, 48 ans, G5P4) [Q1 à Q43] ----------------------------------------------------------------------- Énoncé du cas : Cas N°I (Broukro) : Consommation de COC des 3 derniers mois typiques : Mars = 48 cycles ; Avril = 45 cycles ; Mai = 43 cycles. Stock après inventaire physique disponible utilisable = 110 cycles (et 5 cycles ayant des comprimés écrasés). Cas N°II (Mme Droh) : Mme Droh, 48 ans, G5P4 (4 enfants vivants), consulte en PF. Elle a utilisé un DIU il y a 3 ans posé en salle d'accouchement juste après l'accouchement. La persistance des crampes menstruelles l'a motivée à changer de méthode. Ces 5 derniers mois, son cycle menstruel est irrégulier. Elle opte pour l'auto-observation. ----------------------------------------------------------------------- -----------------------------------------------------------------------\",\"text\":\"Le patch contraceptif et l'anneau vaginal sont des méthodes :\",\"options\":[{\"letter\":\"A\",\"text\":\"D'auto-observation\"},{\"letter\":\"B\",\"text\":\"Définitives ou irréversibles\"},{\"letter\":\"C\",\"text\":\"De barrière\"},{\"letter\":\"D\",\"text\":\"Hormonales\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"D. Hormonales\",\"answerLetters\":[\"D\"],\"explanation\":\"Le timbre (patch) transdermique et l'anneau vaginal contraceptif délivrent une association œstroprogestative qui passe dans la circulation sanguine pour bloquer l'ovulation : ce sont des méthodes HORMONALES combinées (d).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"agboville-2__ssr-pf__8\",\"num\":\"9\",\"type\":\"CAS_CLINIQUE\",\"typeLabel\":\"Étude de cas / Cas clinique\",\"partieTitle\":\"Questions Q1 à Q43 (Études de cas Broukro & Mme Droh + QCM/QCD)\",\"caseTitle\":\"Étude de cas N°I Centre de santé de Broukro & Étude de cas N°II Mme\",\"caseData\":\"Droh, 48 ans, G5P4 (Q1 à Q43) +=======================================================================+ +-----------------------------------------------------------------------+ ◆ ÉTUDES DE CAS N°I (Centre de Broukro) et N°II (Mme Droh, 48 ans, G5P4) [Q1 à Q43] ----------------------------------------------------------------------- Énoncé du cas : Cas N°I (Broukro) : Consommation de COC des 3 derniers mois typiques : Mars = 48 cycles ; Avril = 45 cycles ; Mai = 43 cycles. Stock après inventaire physique disponible utilisable = 110 cycles (et 5 cycles ayant des comprimés écrasés). Cas N°II (Mme Droh) : Mme Droh, 48 ans, G5P4 (4 enfants vivants), consulte en PF. Elle a utilisé un DIU il y a 3 ans posé en salle d'accouchement juste après l'accouchement. La persistance des crampes menstruelles l'a motivée à changer de méthode. Ces 5 derniers mois, son cycle menstruel est irrégulier. Elle opte pour l'auto-observation. ----------------------------------------------------------------------- -----------------------------------------------------------------------\",\"text\":\"Au cours d'un coït, il peut se produire une rupture du préservatif. Si cette rupture a lieu pendant l'éjaculation sans usage de spermicide, la conduite à tenir sera en l'absence de notion de VIH :\",\"options\":[{\"letter\":\"A\",\"text\":\"Dans les 7 jours suivant les rapports sexuels poser un DIU\"},{\"letter\":\"B\",\"text\":\"Arrêter le coït et changer de préservatif\"},{\"letter\":\"C\",\"text\":\"Pas de toilette intime chez la femme avant 6 h\"},{\"letter\":\"D\",\"text\":\"Dans les 72 h : prescrire une contraception orale d'urgence\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"D. Dans les 72 h : prescrire une contraception orale d'urgence\",\"answerLetters\":[\"D\"],\"explanation\":\"Si la rupture survient après l'éjaculation sans protection spermicide, la conduite immédiate de première intention est la prise d'une pilule contraceptive d'urgence dans les 72 heures (d).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"agboville-2__ssr-pf__9\",\"num\":\"10\",\"type\":\"CAS_CLINIQUE\",\"typeLabel\":\"Étude de cas / Cas clinique\",\"partieTitle\":\"Questions Q1 à Q43 (Études de cas Broukro & Mme Droh + QCM/QCD)\",\"caseTitle\":\"Étude de cas N°I Centre de santé de Broukro & Étude de cas N°II Mme\",\"caseData\":\"Droh, 48 ans, G5P4 (Q1 à Q43) +=======================================================================+ +-----------------------------------------------------------------------+ ◆ ÉTUDES DE CAS N°I (Centre de Broukro) et N°II (Mme Droh, 48 ans, G5P4) [Q1 à Q43] ----------------------------------------------------------------------- Énoncé du cas : Cas N°I (Broukro) : Consommation de COC des 3 derniers mois typiques : Mars = 48 cycles ; Avril = 45 cycles ; Mai = 43 cycles. Stock après inventaire physique disponible utilisable = 110 cycles (et 5 cycles ayant des comprimés écrasés). Cas N°II (Mme Droh) : Mme Droh, 48 ans, G5P4 (4 enfants vivants), consulte en PF. Elle a utilisé un DIU il y a 3 ans posé en salle d'accouchement juste après l'accouchement. La persistance des crampes menstruelles l'a motivée à changer de méthode. Ces 5 derniers mois, son cycle menstruel est irrégulier. Elle opte pour l'auto-observation. ----------------------------------------------------------------------- -----------------------------------------------------------------------\",\"text\":\"La lutte contre les infections sexuellement transmissibles (IST), dont le VIH, les infections de l'appareil reproducteur, le cancer du col de l'utérus et autres causes de morbidité ne fait pas partie des soins de santé des adolescents-jeunes :\",\"options\":[],\"mode\":\"open\",\"multi\":false,\"answer\":\"Faux\",\"answerLetters\":[],\"explanation\":\"C'est faux : la prévention et la prise en charge des IST/VIH constituent au contraire un pilier central de la Santé des Adolescents et des Jeunes (SAJ).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"agboville-2__ssr-pf__10\",\"num\":\"11\",\"type\":\"CAS_CLINIQUE\",\"typeLabel\":\"Étude de cas / Cas clinique\",\"partieTitle\":\"Questions Q1 à Q43 (Études de cas Broukro & Mme Droh + QCM/QCD)\",\"caseTitle\":\"Étude de cas N°I Centre de santé de Broukro & Étude de cas N°II Mme\",\"caseData\":\"Droh, 48 ans, G5P4 (Q1 à Q43) +=======================================================================+ +-----------------------------------------------------------------------+ ◆ ÉTUDES DE CAS N°I (Centre de Broukro) et N°II (Mme Droh, 48 ans, G5P4) [Q1 à Q43] ----------------------------------------------------------------------- Énoncé du cas : Cas N°I (Broukro) : Consommation de COC des 3 derniers mois typiques : Mars = 48 cycles ; Avril = 45 cycles ; Mai = 43 cycles. Stock après inventaire physique disponible utilisable = 110 cycles (et 5 cycles ayant des comprimés écrasés). Cas N°II (Mme Droh) : Mme Droh, 48 ans, G5P4 (4 enfants vivants), consulte en PF. Elle a utilisé un DIU il y a 3 ans posé en salle d'accouchement juste après l'accouchement. La persistance des crampes menstruelles l'a motivée à changer de méthode. Ces 5 derniers mois, son cycle menstruel est irrégulier. Elle opte pour l'auto-observation. ----------------------------------------------------------------------- -----------------------------------------------------------------------\",\"text\":\"La consultation en PF est un processus qui a pour but de :\",\"options\":[{\"letter\":\"A\",\"text\":\"Identifier les contre-indications médico-chirurgicales\"},{\"letter\":\"B\",\"text\":\"Dépister les peurs et la frayeur et dissiper les doutes\"},{\"letter\":\"C\",\"text\":\"Dépister les IST, les cas d'infertilité/infécondité pour une prise en charge adéquate\"},{\"letter\":\"D\",\"text\":\"Identifier les contre-indications demandant une prise de précaution à l'emploi d'une méthode particulière\"},{\"letter\":\"E\",\"text\":\"Arriver à un choix éclairé concernant leurs options en matière de reproduction (ainsi que a, c, d pour le bilan clinique)\"}],\"mode\":\"mcq\",\"multi\":true,\"answer\":\"A et C et D et E\",\"answerLetters\":[\"A\",\"C\",\"D\",\"E\"],\"explanation\":\"La consultation clinique de PF permet d'amener la cliente à un choix éclairé (e), tout en vérifiant son éligibilité médicale (dépistage des contre-indications absolues ou relatives a, d) et en dépistant les IST ou problèmes gynécologiques associés (c).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"agboville-2__ssr-pf__11\",\"num\":\"12\",\"type\":\"CAS_CLINIQUE\",\"typeLabel\":\"Étude de cas / Cas clinique\",\"partieTitle\":\"Questions Q1 à Q43 (Études de cas Broukro & Mme Droh + QCM/QCD)\",\"caseTitle\":\"Étude de cas N°I Centre de santé de Broukro & Étude de cas N°II Mme\",\"caseData\":\"Droh, 48 ans, G5P4 (Q1 à Q43) +=======================================================================+ +-----------------------------------------------------------------------+ ◆ ÉTUDES DE CAS N°I (Centre de Broukro) et N°II (Mme Droh, 48 ans, G5P4) [Q1 à Q43] ----------------------------------------------------------------------- Énoncé du cas : Cas N°I (Broukro) : Consommation de COC des 3 derniers mois typiques : Mars = 48 cycles ; Avril = 45 cycles ; Mai = 43 cycles. Stock après inventaire physique disponible utilisable = 110 cycles (et 5 cycles ayant des comprimés écrasés). Cas N°II (Mme Droh) : Mme Droh, 48 ans, G5P4 (4 enfants vivants), consulte en PF. Elle a utilisé un DIU il y a 3 ans posé en salle d'accouchement juste après l'accouchement. La persistance des crampes menstruelles l'a motivée à changer de méthode. Ces 5 derniers mois, son cycle menstruel est irrégulier. Elle opte pour l'auto-observation. ----------------------------------------------------------------------- -----------------------------------------------------------------------\",\"text\":\"Fournir des informations, un avis, des conseils et des services cliniques qui les aideront à continuer à avoir des comportements sains ou à modifier des comportements à risque est l'un des rôles de la SAJ :\",\"options\":[],\"mode\":\"open\",\"multi\":false,\"answer\":\"VRAI\",\"answerLetters\":[],\"explanation\":\"Oui, c'est exactement la mission des Services Adaptés aux Adolescents et aux Jeunes (SAAJ).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"agboville-2__ssr-pf__12\",\"num\":\"13\",\"type\":\"CAS_CLINIQUE\",\"typeLabel\":\"Étude de cas / Cas clinique\",\"partieTitle\":\"Questions Q1 à Q43 (Études de cas Broukro & Mme Droh + QCM/QCD)\",\"caseTitle\":\"Étude de cas N°I Centre de santé de Broukro & Étude de cas N°II Mme\",\"caseData\":\"Droh, 48 ans, G5P4 (Q1 à Q43) +=======================================================================+ +-----------------------------------------------------------------------+ ◆ ÉTUDES DE CAS N°I (Centre de Broukro) et N°II (Mme Droh, 48 ans, G5P4) [Q1 à Q43] ----------------------------------------------------------------------- Énoncé du cas : Cas N°I (Broukro) : Consommation de COC des 3 derniers mois typiques : Mars = 48 cycles ; Avril = 45 cycles ; Mai = 43 cycles. Stock après inventaire physique disponible utilisable = 110 cycles (et 5 cycles ayant des comprimés écrasés). Cas N°II (Mme Droh) : Mme Droh, 48 ans, G5P4 (4 enfants vivants), consulte en PF. Elle a utilisé un DIU il y a 3 ans posé en salle d'accouchement juste après l'accouchement. La persistance des crampes menstruelles l'a motivée à changer de méthode. Ces 5 derniers mois, son cycle menstruel est irrégulier. Elle opte pour l'auto-observation. ----------------------------------------------------------------------- -----------------------------------------------------------------------\",\"text\":\"Selon vous, quel est le type d'insertion de DIU que Mme DROH portait il y a trois ans (posé en salle d'accouchement juste après son accouchement) ?\",\"options\":[{\"letter\":\"A\",\"text\":\"Le DIU classique\"},{\"letter\":\"B\",\"text\":\"Le DIU d'intervalle\"},{\"letter\":\"C\",\"text\":\"DIU du post-partum (DIUPP)\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"C. DIU du post-partum (DIUPP)\",\"answerLetters\":[\"C\"],\"explanation\":\"Un DIU inséré en salle d'accouchement immédiatement après la délivrance du placenta (dans les 10 minutes, ou dans les 48 heures suivant l'accouchement) est un DIU du post-partum (DIUPP, c).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"agboville-2__ssr-pf__13\",\"num\":\"14\",\"type\":\"CAS_CLINIQUE\",\"typeLabel\":\"Étude de cas / Cas clinique\",\"partieTitle\":\"Questions Q1 à Q43 (Études de cas Broukro & Mme Droh + QCM/QCD)\",\"caseTitle\":\"Étude de cas N°I Centre de santé de Broukro & Étude de cas N°II Mme\",\"caseData\":\"Droh, 48 ans, G5P4 (Q1 à Q43) +=======================================================================+ +-----------------------------------------------------------------------+ ◆ ÉTUDES DE CAS N°I (Centre de Broukro) et N°II (Mme Droh, 48 ans, G5P4) [Q1 à Q43] ----------------------------------------------------------------------- Énoncé du cas : Cas N°I (Broukro) : Consommation de COC des 3 derniers mois typiques : Mars = 48 cycles ; Avril = 45 cycles ; Mai = 43 cycles. Stock après inventaire physique disponible utilisable = 110 cycles (et 5 cycles ayant des comprimés écrasés). Cas N°II (Mme Droh) : Mme Droh, 48 ans, G5P4 (4 enfants vivants), consulte en PF. Elle a utilisé un DIU il y a 3 ans posé en salle d'accouchement juste après l'accouchement. La persistance des crampes menstruelles l'a motivée à changer de méthode. Ces 5 derniers mois, son cycle menstruel est irrégulier. Elle opte pour l'auto-observation. ----------------------------------------------------------------------- -----------------------------------------------------------------------\",\"text\":\"L'estimation des besoins permet uniquement d'éviter les ruptures de stock.\",\"options\":[],\"mode\":\"open\",\"multi\":false,\"answer\":\"Faux\",\"answerLetters\":[],\"explanation\":\"L'estimation rationnelle des besoins permet d'éviter à la fois les RUPTURES DE STOCK (sous-stockage) ET les SURSTOCKS (qui entraînent la péremption et le gaspillage des produits).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"agboville-2__ssr-pf__14\",\"num\":\"15\",\"type\":\"CAS_CLINIQUE\",\"typeLabel\":\"Étude de cas / Cas clinique\",\"partieTitle\":\"Questions Q1 à Q43 (Études de cas Broukro & Mme Droh + QCM/QCD)\",\"caseTitle\":\"Étude de cas N°I Centre de santé de Broukro & Étude de cas N°II Mme\",\"caseData\":\"Droh, 48 ans, G5P4 (Q1 à Q43) +=======================================================================+ +-----------------------------------------------------------------------+ ◆ ÉTUDES DE CAS N°I (Centre de Broukro) et N°II (Mme Droh, 48 ans, G5P4) [Q1 à Q43] ----------------------------------------------------------------------- Énoncé du cas : Cas N°I (Broukro) : Consommation de COC des 3 derniers mois typiques : Mars = 48 cycles ; Avril = 45 cycles ; Mai = 43 cycles. Stock après inventaire physique disponible utilisable = 110 cycles (et 5 cycles ayant des comprimés écrasés). Cas N°II (Mme Droh) : Mme Droh, 48 ans, G5P4 (4 enfants vivants), consulte en PF. Elle a utilisé un DIU il y a 3 ans posé en salle d'accouchement juste après l'accouchement. La persistance des crampes menstruelles l'a motivée à changer de méthode. Ces 5 derniers mois, son cycle menstruel est irrégulier. Elle opte pour l'auto-observation. ----------------------------------------------------------------------- -----------------------------------------------------------------------\",\"text\":\"Les méthodes hormonales interfèrent en général avec les conditions de survenue de grossesse suivantes :\",\"options\":[{\"letter\":\"A\",\"text\":\"Glaire cervicale, spermatozoïdes, ovulation et nidation\"},{\"letter\":\"B\",\"text\":\"Glaire cervicale, spermatozoïdes, ovulation et vagin fonctionnel\"},{\"letter\":\"C\",\"text\":\"Glaire cervicale, spermatozoïdes, trompes et vagin fonctionnel\"},{\"letter\":\"D\",\"text\":\"Glaire cervicale, ovulation, endomètre, le transport des spermatozoïdes dans les trompes\"},{\"letter\":\"E\",\"text\":\"Glaire cervicale, spermatozoïdes, trompes et nidation\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"D. Glaire cervicale, ovulation, endomètre, le transport des spermatozoïdes dans les trompes\",\"answerLetters\":[\"D\"],\"explanation\":\"Les contraceptifs hormonaux agissent sur 4 cibles physiologiques : 1) inhibition de l'OVULATION, 2) épaississement de la GLAIRE CERVICALE, 3) atrophie de l'ENDOMÈTRE (impropre à la nidation), et 4) ralentissement de la motilité tubaire (transport des gamètes dans les TROMPES : d).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"agboville-2__ssr-pf__15\",\"num\":\"16\",\"type\":\"CAS_CLINIQUE\",\"typeLabel\":\"Étude de cas / Cas clinique\",\"partieTitle\":\"Questions Q1 à Q43 (Études de cas Broukro & Mme Droh + QCM/QCD)\",\"caseTitle\":\"Étude de cas N°I Centre de santé de Broukro & Étude de cas N°II Mme\",\"caseData\":\"Droh, 48 ans, G5P4 (Q1 à Q43) +=======================================================================+ +-----------------------------------------------------------------------+ ◆ ÉTUDES DE CAS N°I (Centre de Broukro) et N°II (Mme Droh, 48 ans, G5P4) [Q1 à Q43] ----------------------------------------------------------------------- Énoncé du cas : Cas N°I (Broukro) : Consommation de COC des 3 derniers mois typiques : Mars = 48 cycles ; Avril = 45 cycles ; Mai = 43 cycles. Stock après inventaire physique disponible utilisable = 110 cycles (et 5 cycles ayant des comprimés écrasés). Cas N°II (Mme Droh) : Mme Droh, 48 ans, G5P4 (4 enfants vivants), consulte en PF. Elle a utilisé un DIU il y a 3 ans posé en salle d'accouchement juste après l'accouchement. La persistance des crampes menstruelles l'a motivée à changer de méthode. Ces 5 derniers mois, son cycle menstruel est irrégulier. Elle opte pour l'auto-observation. ----------------------------------------------------------------------- -----------------------------------------------------------------------\",\"text\":\"Les adolescents sexuellement actifs ont besoin d'une contraception sûre et efficace parce que :\",\"options\":[{\"letter\":\"A\",\"text\":\"Ils doivent avoir une sexualité responsable\"},{\"letter\":\"B\",\"text\":\"Ils ont du mal à négocier le port de préservatif\"},{\"letter\":\"C\",\"text\":\"Ils tendent à avoir des styles de vie imprévisibles (et toutes les raisons a, b, c)\"}],\"mode\":\"mcq\",\"multi\":true,\"answer\":\"A et B et C\",\"answerLetters\":[\"A\",\"B\",\"C\"],\"explanation\":\"Les adolescents ont des rapports souvent sporadiques/non planifiés (styles de vie imprévisibles : c), rencontrent des difficultés à négocier le préservatif (b) et doivent être accompagnés vers une sexualité responsable (a).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"agboville-2__ssr-pf__16\",\"num\":\"17\",\"type\":\"CAS_CLINIQUE\",\"typeLabel\":\"Étude de cas / Cas clinique\",\"partieTitle\":\"Questions Q1 à Q43 (Études de cas Broukro & Mme Droh + QCM/QCD)\",\"caseTitle\":\"Étude de cas N°I Centre de santé de Broukro & Étude de cas N°II Mme\",\"caseData\":\"Droh, 48 ans, G5P4 (Q1 à Q43) +=======================================================================+ +-----------------------------------------------------------------------+ ◆ ÉTUDES DE CAS N°I (Centre de Broukro) et N°II (Mme Droh, 48 ans, G5P4) [Q1 à Q43] ----------------------------------------------------------------------- Énoncé du cas : Cas N°I (Broukro) : Consommation de COC des 3 derniers mois typiques : Mars = 48 cycles ; Avril = 45 cycles ; Mai = 43 cycles. Stock après inventaire physique disponible utilisable = 110 cycles (et 5 cycles ayant des comprimés écrasés). Cas N°II (Mme Droh) : Mme Droh, 48 ans, G5P4 (4 enfants vivants), consulte en PF. Elle a utilisé un DIU il y a 3 ans posé en salle d'accouchement juste après l'accouchement. La persistance des crampes menstruelles l'a motivée à changer de méthode. Ces 5 derniers mois, son cycle menstruel est irrégulier. Elle opte pour l'auto-observation. ----------------------------------------------------------------------- -----------------------------------------------------------------------\",\"text\":\"Les implants sont des capsules fines souples contenant du Lévonorgestrel (ou Étonogestrel) que l'on place à :\",\"options\":[{\"letter\":\"A\",\"text\":\"La face interne du bras à 5 à 7 cm du pli du coude\"},{\"letter\":\"B\",\"text\":\"La face externe du bras à 3 à 7 cm du pli du coude\"},{\"letter\":\"C\",\"text\":\"La face externe du bras à 6 à 8 cm du pli du coude\"},{\"letter\":\"D\",\"text\":\"La face interne du bras à 6 à 8 cm du pli du coude\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"D. La face interne du bras à 6 à 8 cm du pli du coude\",\"answerLetters\":[\"D\"],\"explanation\":\"L'implant contraceptif sous-cutané (Jadelle, Implanon NXT) s'insère sous anesthésie locale en sous-dermique strict à la face INTERNE du bras non dominant, à 6 à 8 cm (environ 4 travers de doigts) au-dessus du pli du coude (d).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"agboville-2__ssr-pf__17\",\"num\":\"18\",\"type\":\"CAS_CLINIQUE\",\"typeLabel\":\"Étude de cas / Cas clinique\",\"partieTitle\":\"Questions Q1 à Q43 (Études de cas Broukro & Mme Droh + QCM/QCD)\",\"caseTitle\":\"Étude de cas N°I Centre de santé de Broukro & Étude de cas N°II Mme\",\"caseData\":\"Droh, 48 ans, G5P4 (Q1 à Q43) +=======================================================================+ +-----------------------------------------------------------------------+ ◆ ÉTUDES DE CAS N°I (Centre de Broukro) et N°II (Mme Droh, 48 ans, G5P4) [Q1 à Q43] ----------------------------------------------------------------------- Énoncé du cas : Cas N°I (Broukro) : Consommation de COC des 3 derniers mois typiques : Mars = 48 cycles ; Avril = 45 cycles ; Mai = 43 cycles. Stock après inventaire physique disponible utilisable = 110 cycles (et 5 cycles ayant des comprimés écrasés). Cas N°II (Mme Droh) : Mme Droh, 48 ans, G5P4 (4 enfants vivants), consulte en PF. Elle a utilisé un DIU il y a 3 ans posé en salle d'accouchement juste après l'accouchement. La persistance des crampes menstruelles l'a motivée à changer de méthode. Ces 5 derniers mois, son cycle menstruel est irrégulier. Elle opte pour l'auto-observation. ----------------------------------------------------------------------- -----------------------------------------------------------------------\",\"text\":\"Dans les principes et caractéristiques de la contraception en post-partum, il est important de savoir que chez la femme non allaitante, il faut tenir compte de :\",\"options\":[{\"letter\":\"A\",\"text\":\"Risque de survenue d'une grossesse : la première ovulation peut survenir au plus tôt dès vingt-et-un (21) jours (ou 25-28 jours)\"},{\"letter\":\"B\",\"text\":\"Première ovulation dans une moyenne de 42 à 45 jours après l'accouchement\"},{\"letter\":\"C\",\"text\":\"5 femmes sur 5 vont ovuler avant de revoir les règles\"}],\"mode\":\"mcq\",\"multi\":true,\"answer\":\"A et B\",\"answerLetters\":[\"A\",\"B\"],\"explanation\":\"Chez l'accouchée non allaitante, la fécondité peut revenir dès la fin de la 3e semaine (21 jours au plus tôt : a) et l'ovulation reprend en moyenne vers 6 semaines (42–45 jours : b).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"agboville-2__ssr-pf__18\",\"num\":\"19\",\"type\":\"CAS_CLINIQUE\",\"typeLabel\":\"Étude de cas / Cas clinique\",\"partieTitle\":\"Questions Q1 à Q43 (Études de cas Broukro & Mme Droh + QCM/QCD)\",\"caseTitle\":\"Étude de cas N°I Centre de santé de Broukro & Étude de cas N°II Mme\",\"caseData\":\"Droh, 48 ans, G5P4 (Q1 à Q43) +=======================================================================+ +-----------------------------------------------------------------------+ ◆ ÉTUDES DE CAS N°I (Centre de Broukro) et N°II (Mme Droh, 48 ans, G5P4) [Q1 à Q43] ----------------------------------------------------------------------- Énoncé du cas : Cas N°I (Broukro) : Consommation de COC des 3 derniers mois typiques : Mars = 48 cycles ; Avril = 45 cycles ; Mai = 43 cycles. Stock après inventaire physique disponible utilisable = 110 cycles (et 5 cycles ayant des comprimés écrasés). Cas N°II (Mme Droh) : Mme Droh, 48 ans, G5P4 (4 enfants vivants), consulte en PF. Elle a utilisé un DIU il y a 3 ans posé en salle d'accouchement juste après l'accouchement. La persistance des crampes menstruelles l'a motivée à changer de méthode. Ces 5 derniers mois, son cycle menstruel est irrégulier. Elle opte pour l'auto-observation. ----------------------------------------------------------------------- -----------------------------------------------------------------------\",\"text\":\"Les méthodes hormonales interfèrent en général sur les conditions de survenue de grossesse suivantes :\",\"options\":[{\"letter\":\"A\",\"text\":\"Glaire cervicale, spermatozoïdes, ovulation et vagin fonctionnel\"},{\"letter\":\"B\",\"text\":\"Glaire cervicale, spermatozoïdes, trompes et vagin fonctionnel\"},{\"letter\":\"C\",\"text\":\"Glaire cervicale, spermatozoïdes, trompes et nidation\"},{\"letter\":\"D\",\"text\":\"Glaire cervicale, transport des spermatozoïdes, ovulation et nidation\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"D. Glaire cervicale, transport des spermatozoïdes, ovulation et nidation\",\"answerLetters\":[\"D\"],\"explanation\":\"Comme à la Q15, les 4 mécanismes d'action des méthodes hormonales portent sur la glaire cervicale, le transport des spermatozoïdes, l'ovulation et la nidation endométriale (d).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"agboville-2__ssr-pf__19\",\"num\":\"20\",\"type\":\"CAS_CLINIQUE\",\"typeLabel\":\"Étude de cas / Cas clinique\",\"partieTitle\":\"Questions Q1 à Q43 (Études de cas Broukro & Mme Droh + QCM/QCD)\",\"caseTitle\":\"Étude de cas N°I Centre de santé de Broukro & Étude de cas N°II Mme\",\"caseData\":\"Droh, 48 ans, G5P4 (Q1 à Q43) +=======================================================================+ +-----------------------------------------------------------------------+ ◆ ÉTUDES DE CAS N°I (Centre de Broukro) et N°II (Mme Droh, 48 ans, G5P4) [Q1 à Q43] ----------------------------------------------------------------------- Énoncé du cas : Cas N°I (Broukro) : Consommation de COC des 3 derniers mois typiques : Mars = 48 cycles ; Avril = 45 cycles ; Mai = 43 cycles. Stock après inventaire physique disponible utilisable = 110 cycles (et 5 cycles ayant des comprimés écrasés). Cas N°II (Mme Droh) : Mme Droh, 48 ans, G5P4 (4 enfants vivants), consulte en PF. Elle a utilisé un DIU il y a 3 ans posé en salle d'accouchement juste après l'accouchement. La persistance des crampes menstruelles l'a motivée à changer de méthode. Ces 5 derniers mois, son cycle menstruel est irrégulier. Elle opte pour l'auto-observation. ----------------------------------------------------------------------- -----------------------------------------------------------------------\",\"text\":\"Les travaux des champs où les hommes ont la responsabilité des cultures de rente alors que les femmes ont celle des cultures vivrières créent une disparité de genre dans la communauté :\",\"options\":[],\"mode\":\"open\",\"multi\":false,\"answer\":\"VRAI\",\"answerLetters\":[],\"explanation\":\"Cette division inégale du travail agricole (qui réserve les revenus monétaires des cultures d'exportation/rente aux hommes et cantonne les femmes aux cultures vivrières d'autoconsommation non rémunérées) illustre une disparité économique de genre dans l'accès et le contrôle des ressources.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"agboville-2__ssr-pf__20\",\"num\":\"21\",\"type\":\"CAS_CLINIQUE\",\"typeLabel\":\"Étude de cas / Cas clinique\",\"partieTitle\":\"Questions Q1 à Q43 (Études de cas Broukro & Mme Droh + QCM/QCD)\",\"caseTitle\":\"Étude de cas N°I Centre de santé de Broukro & Étude de cas N°II Mme\",\"caseData\":\"Droh, 48 ans, G5P4 (Q1 à Q43) +=======================================================================+ +-----------------------------------------------------------------------+ ◆ ÉTUDES DE CAS N°I (Centre de Broukro) et N°II (Mme Droh, 48 ans, G5P4) [Q1 à Q43] ----------------------------------------------------------------------- Énoncé du cas : Cas N°I (Broukro) : Consommation de COC des 3 derniers mois typiques : Mars = 48 cycles ; Avril = 45 cycles ; Mai = 43 cycles. Stock après inventaire physique disponible utilisable = 110 cycles (et 5 cycles ayant des comprimés écrasés). Cas N°II (Mme Droh) : Mme Droh, 48 ans, G5P4 (4 enfants vivants), consulte en PF. Elle a utilisé un DIU il y a 3 ans posé en salle d'accouchement juste après l'accouchement. La persistance des crampes menstruelles l'a motivée à changer de méthode. Ces 5 derniers mois, son cycle menstruel est irrégulier. Elle opte pour l'auto-observation. ----------------------------------------------------------------------- -----------------------------------------------------------------------\",\"text\":\"Dans le calendrier classique de suivi d'une cliente sous implant, la 2ème visite de contrôle doit s'effectuer :\",\"options\":[{\"letter\":\"A\",\"text\":\"3 semaines après l'insertion\"},{\"letter\":\"B\",\"text\":\"6 mois après l'insertion\"},{\"letter\":\"C\",\"text\":\"3 mois après l'insertion\"},{\"letter\":\"D\",\"text\":\"2 mois après l'insertion\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"C. 3 mois après l'insertion\",\"answerLetters\":[\"C\"],\"explanation\":\"Après la pose d'un implant sous-cutané, le 1er contrôle précoce de la cicatrisation du site d'insertion a lieu à 7 jours (1 semaine), puis le 2e rendez-vous de suivi de la tolérance a lieu à 3 mois (c) [ou 6 mois : b].\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"agboville-2__ssr-pf__21\",\"num\":\"22\",\"type\":\"CAS_CLINIQUE\",\"typeLabel\":\"Étude de cas / Cas clinique\",\"partieTitle\":\"Questions Q1 à Q43 (Études de cas Broukro & Mme Droh + QCM/QCD)\",\"caseTitle\":\"Étude de cas N°I Centre de santé de Broukro & Étude de cas N°II Mme\",\"caseData\":\"Droh, 48 ans, G5P4 (Q1 à Q43) +=======================================================================+ +-----------------------------------------------------------------------+ ◆ ÉTUDES DE CAS N°I (Centre de Broukro) et N°II (Mme Droh, 48 ans, G5P4) [Q1 à Q43] ----------------------------------------------------------------------- Énoncé du cas : Cas N°I (Broukro) : Consommation de COC des 3 derniers mois typiques : Mars = 48 cycles ; Avril = 45 cycles ; Mai = 43 cycles. Stock après inventaire physique disponible utilisable = 110 cycles (et 5 cycles ayant des comprimés écrasés). Cas N°II (Mme Droh) : Mme Droh, 48 ans, G5P4 (4 enfants vivants), consulte en PF. Elle a utilisé un DIU il y a 3 ans posé en salle d'accouchement juste après l'accouchement. La persistance des crampes menstruelles l'a motivée à changer de méthode. Ces 5 derniers mois, son cycle menstruel est irrégulier. Elle opte pour l'auto-observation. ----------------------------------------------------------------------- -----------------------------------------------------------------------\",\"text\":\"Après la prise des 21 pilules actives de la plaquette de COC, les jours de prise des 7 comprimés marron (fer) correspondent à une période infertile (protégée) :\",\"options\":[],\"mode\":\"open\",\"multi\":false,\"answer\":\"VRAI\",\"answerLetters\":[],\"explanation\":\"Oui, si les 21 comprimés hormonaux actifs ont été pris régulièrement sans oubli, l'inhibition de l'axe gonadotrope persiste durant les 7 jours de comprimés marron (fer), assurant une protection contraceptive continue.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"agboville-2__ssr-pf__22\",\"num\":\"23\",\"type\":\"CAS_CLINIQUE\",\"typeLabel\":\"Étude de cas / Cas clinique\",\"partieTitle\":\"Questions Q1 à Q43 (Études de cas Broukro & Mme Droh + QCM/QCD)\",\"caseTitle\":\"Étude de cas N°I Centre de santé de Broukro & Étude de cas N°II Mme\",\"caseData\":\"Droh, 48 ans, G5P4 (Q1 à Q43) +=======================================================================+ +-----------------------------------------------------------------------+ ◆ ÉTUDES DE CAS N°I (Centre de Broukro) et N°II (Mme Droh, 48 ans, G5P4) [Q1 à Q43] ----------------------------------------------------------------------- Énoncé du cas : Cas N°I (Broukro) : Consommation de COC des 3 derniers mois typiques : Mars = 48 cycles ; Avril = 45 cycles ; Mai = 43 cycles. Stock après inventaire physique disponible utilisable = 110 cycles (et 5 cycles ayant des comprimés écrasés). Cas N°II (Mme Droh) : Mme Droh, 48 ans, G5P4 (4 enfants vivants), consulte en PF. Elle a utilisé un DIU il y a 3 ans posé en salle d'accouchement juste après l'accouchement. La persistance des crampes menstruelles l'a motivée à changer de méthode. Ces 5 derniers mois, son cycle menstruel est irrégulier. Elle opte pour l'auto-observation. ----------------------------------------------------------------------- -----------------------------------------------------------------------\",\"text\":\"Le genre est dynamique et variable dans le temps et dans l'espace :\",\"options\":[],\"mode\":\"open\",\"multi\":false,\"answer\":\"VRAI\",\"answerLetters\":[],\"explanation\":\"Parce qu'il est une construction socioculturelle, le genre évolue d'une époque à une autre (dans le temps) et diffère d'une société ou culture à une autre (dans l'espace).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"agboville-2__ssr-pf__23\",\"num\":\"24\",\"type\":\"CAS_CLINIQUE\",\"typeLabel\":\"Étude de cas / Cas clinique\",\"partieTitle\":\"Questions Q1 à Q43 (Études de cas Broukro & Mme Droh + QCM/QCD)\",\"caseTitle\":\"Étude de cas N°I Centre de santé de Broukro & Étude de cas N°II Mme\",\"caseData\":\"Droh, 48 ans, G5P4 (Q1 à Q43) +=======================================================================+ +-----------------------------------------------------------------------+ ◆ ÉTUDES DE CAS N°I (Centre de Broukro) et N°II (Mme Droh, 48 ans, G5P4) [Q1 à Q43] ----------------------------------------------------------------------- Énoncé du cas : Cas N°I (Broukro) : Consommation de COC des 3 derniers mois typiques : Mars = 48 cycles ; Avril = 45 cycles ; Mai = 43 cycles. Stock après inventaire physique disponible utilisable = 110 cycles (et 5 cycles ayant des comprimés écrasés). Cas N°II (Mme Droh) : Mme Droh, 48 ans, G5P4 (4 enfants vivants), consulte en PF. Elle a utilisé un DIU il y a 3 ans posé en salle d'accouchement juste après l'accouchement. La persistance des crampes menstruelles l'a motivée à changer de méthode. Ces 5 derniers mois, son cycle menstruel est irrégulier. Elle opte pour l'auto-observation. ----------------------------------------------------------------------- -----------------------------------------------------------------------\",\"text\":\"Selon vous, sur quelle condition agirait la méthode choisie par votre cliente Mme Droh (méthode d'auto-observation / abstinence périodique) pour empêcher la survenue d'une grossesse si elle était éligible ?\",\"options\":[{\"letter\":\"A\",\"text\":\"L'ovulation\"},{\"letter\":\"B\",\"text\":\"Les trompes\"},{\"letter\":\"C\",\"text\":\"Les spermatozoïdes (empêcher le dépôt des spermatozoïdes dans le vagin pendant la période ovulatoire fertile)\"},{\"letter\":\"D\",\"text\":\"La glaire\"},{\"letter\":\"E\",\"text\":\"L'endomètre\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"C. Les spermatozoïdes (empêcher le dépôt des spermatozoïdes dans le vagin pendant la période ovulatoire fertile)\",\"answerLetters\":[\"C\"],\"explanation\":\"Les méthodes naturelles d'auto-observation ne modifient ni l'ovulation, ni la glaire, ni les trompes, ni l'endomètre : par l'abstinence périodique en phase fertile, elles agissent en empêchant que des SPERMATOZOÏDES fécondants ne soient déposés dans les voies génitales au moment de l'ovulation (c).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"agboville-2__ssr-pf__24\",\"num\":\"25\",\"type\":\"CAS_CLINIQUE\",\"typeLabel\":\"Étude de cas / Cas clinique\",\"partieTitle\":\"Questions Q1 à Q43 (Études de cas Broukro & Mme Droh + QCM/QCD)\",\"caseTitle\":\"Étude de cas N°I Centre de santé de Broukro & Étude de cas N°II Mme\",\"caseData\":\"Droh, 48 ans, G5P4 (Q1 à Q43) +=======================================================================+ +-----------------------------------------------------------------------+ ◆ ÉTUDES DE CAS N°I (Centre de Broukro) et N°II (Mme Droh, 48 ans, G5P4) [Q1 à Q43] ----------------------------------------------------------------------- Énoncé du cas : Cas N°I (Broukro) : Consommation de COC des 3 derniers mois typiques : Mars = 48 cycles ; Avril = 45 cycles ; Mai = 43 cycles. Stock après inventaire physique disponible utilisable = 110 cycles (et 5 cycles ayant des comprimés écrasés). Cas N°II (Mme Droh) : Mme Droh, 48 ans, G5P4 (4 enfants vivants), consulte en PF. Elle a utilisé un DIU il y a 3 ans posé en salle d'accouchement juste après l'accouchement. La persistance des crampes menstruelles l'a motivée à changer de méthode. Ces 5 derniers mois, son cycle menstruel est irrégulier. Elle opte pour l'auto-observation. ----------------------------------------------------------------------- -----------------------------------------------------------------------\",\"text\":\"Les méthodes de barrière chimiques (spermicides) se présentent généralement sous forme de :\",\"options\":[{\"letter\":\"A\",\"text\":\"Latex\"},{\"letter\":\"B\",\"text\":\"Patch\"},{\"letter\":\"C\",\"text\":\"Mousse\"},{\"letter\":\"D\",\"text\":\"Comprimé (ovule/comprimé gynécologique moussant)\"}],\"mode\":\"mcq\",\"multi\":true,\"answer\":\"C et D\",\"answerLetters\":[\"C\",\"D\"],\"explanation\":\"Les spermicides (barrières chimiques) sont commercialisés sous forme de mousses en aérosol (c), de comprimés vaginaux moussants / ovules (d), de crèmes, de gelées ou de films solubles.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"agboville-2__ssr-pf__25\",\"num\":\"26\",\"type\":\"CAS_CLINIQUE\",\"typeLabel\":\"Étude de cas / Cas clinique\",\"partieTitle\":\"Questions Q1 à Q43 (Études de cas Broukro & Mme Droh + QCM/QCD)\",\"caseTitle\":\"Étude de cas N°I Centre de santé de Broukro & Étude de cas N°II Mme\",\"caseData\":\"Droh, 48 ans, G5P4 (Q1 à Q43) +=======================================================================+ +-----------------------------------------------------------------------+ ◆ ÉTUDES DE CAS N°I (Centre de Broukro) et N°II (Mme Droh, 48 ans, G5P4) [Q1 à Q43] ----------------------------------------------------------------------- Énoncé du cas : Cas N°I (Broukro) : Consommation de COC des 3 derniers mois typiques : Mars = 48 cycles ; Avril = 45 cycles ; Mai = 43 cycles. Stock après inventaire physique disponible utilisable = 110 cycles (et 5 cycles ayant des comprimés écrasés). Cas N°II (Mme Droh) : Mme Droh, 48 ans, G5P4 (4 enfants vivants), consulte en PF. Elle a utilisé un DIU il y a 3 ans posé en salle d'accouchement juste après l'accouchement. La persistance des crampes menstruelles l'a motivée à changer de méthode. Ces 5 derniers mois, son cycle menstruel est irrégulier. Elle opte pour l'auto-observation. ----------------------------------------------------------------------- -----------------------------------------------------------------------\",\"text\":\"Le sexe fait référence aux attributs biologiques et physiologiques :\",\"options\":[],\"mode\":\"open\",\"multi\":false,\"answer\":\"VRAI\",\"answerLetters\":[],\"explanation\":\"Le sexe désigne l'ensemble des caractéristiques biologiques, anatomiques, génétiques et physiologiques qui distinguent les hommes et les femmes.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"agboville-2__ssr-pf__26\",\"num\":\"27\",\"type\":\"CAS_CLINIQUE\",\"typeLabel\":\"Étude de cas / Cas clinique\",\"partieTitle\":\"Questions Q1 à Q43 (Études de cas Broukro & Mme Droh + QCM/QCD)\",\"caseTitle\":\"Étude de cas N°I Centre de santé de Broukro & Étude de cas N°II Mme\",\"caseData\":\"Droh, 48 ans, G5P4 (Q1 à Q43) +=======================================================================+ +-----------------------------------------------------------------------+ ◆ ÉTUDES DE CAS N°I (Centre de Broukro) et N°II (Mme Droh, 48 ans, G5P4) [Q1 à Q43] ----------------------------------------------------------------------- Énoncé du cas : Cas N°I (Broukro) : Consommation de COC des 3 derniers mois typiques : Mars = 48 cycles ; Avril = 45 cycles ; Mai = 43 cycles. Stock après inventaire physique disponible utilisable = 110 cycles (et 5 cycles ayant des comprimés écrasés). Cas N°II (Mme Droh) : Mme Droh, 48 ans, G5P4 (4 enfants vivants), consulte en PF. Elle a utilisé un DIU il y a 3 ans posé en salle d'accouchement juste après l'accouchement. La persistance des crampes menstruelles l'a motivée à changer de méthode. Ces 5 derniers mois, son cycle menstruel est irrégulier. Elle opte pour l'auto-observation. ----------------------------------------------------------------------- -----------------------------------------------------------------------\",\"text\":\"Vous recevez une cliente de 40 ans G2P0 à la consultation de PF ; elle désire bénéficier d'une méthode contraceptive injectable à seul progestatif (DMPA / NET-EN). Ses antécédents sont : diabète actuel sans complication vasculaire et tabagisme. Pour l'utilisation de cette méthode, à quelle classe OMS appartient-elle ?\",\"options\":[{\"letter\":\"A\",\"text\":\"Classe 1 ou OMS 1\"},{\"letter\":\"B\",\"text\":\"Classe 2 ou OMS 2\"},{\"letter\":\"C\",\"text\":\"Classe 4 ou OMS 4\"},{\"letter\":\"D\",\"text\":\"Classe 3 ou OMS 3\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Classe 2 ou OMS 2\",\"answerLetters\":[\"B\"],\"explanation\":\"Selon les Critères de recevabilité médicale de l'OMS : pour les progestatifs injectables (DMPA/NET-EN), le tabagisme quel que soit l'âge est de Classe 1, et le diabète non insulino- ou insulinodépendant SANS complication vasculaire est de CLASSE 2 (les avantages surpassent les risques théoriques, la méthode peut être utilisée : b). [NB : C'est pour les œstroprogestatifs combinés que l'âge ≥ 35 ans + tabac est de Classe 3/4, et c'est le diabète AVEC néphropathie/rétinopathie/neuropathie ou > 20 ans qui est de Classe 3 pour le DMPA].\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"agboville-2__ssr-pf__27\",\"num\":\"28\",\"type\":\"CAS_CLINIQUE\",\"typeLabel\":\"Étude de cas / Cas clinique\",\"partieTitle\":\"Questions Q1 à Q43 (Études de cas Broukro & Mme Droh + QCM/QCD)\",\"caseTitle\":\"Étude de cas N°I Centre de santé de Broukro & Étude de cas N°II Mme\",\"caseData\":\"Droh, 48 ans, G5P4 (Q1 à Q43) +=======================================================================+ +-----------------------------------------------------------------------+ ◆ ÉTUDES DE CAS N°I (Centre de Broukro) et N°II (Mme Droh, 48 ans, G5P4) [Q1 à Q43] ----------------------------------------------------------------------- Énoncé du cas : Cas N°I (Broukro) : Consommation de COC des 3 derniers mois typiques : Mars = 48 cycles ; Avril = 45 cycles ; Mai = 43 cycles. Stock après inventaire physique disponible utilisable = 110 cycles (et 5 cycles ayant des comprimés écrasés). Cas N°II (Mme Droh) : Mme Droh, 48 ans, G5P4 (4 enfants vivants), consulte en PF. Elle a utilisé un DIU il y a 3 ans posé en salle d'accouchement juste après l'accouchement. La persistance des crampes menstruelles l'a motivée à changer de méthode. Ces 5 derniers mois, son cycle menstruel est irrégulier. Elle opte pour l'auto-observation. ----------------------------------------------------------------------- -----------------------------------------------------------------------\",\"text\":\"À quel moment de la consultation intervient cette phase (le counseling spécifique) ?\",\"options\":[{\"letter\":\"A\",\"text\":\"Immédiatement après la prestation de service\"},{\"letter\":\"B\",\"text\":\"Avant et immédiatement après la prestation de service\"},{\"letter\":\"C\",\"text\":\"Lors de la réception de la cliente\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Avant et immédiatement après la prestation de service\",\"answerLetters\":[\"B\"],\"explanation\":\"Le counseling spécifique à la méthode choisie intervient juste avant et immédiatement après l'administration de la méthode (b).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"agboville-2__ssr-pf__28\",\"num\":\"29\",\"type\":\"CAS_CLINIQUE\",\"typeLabel\":\"Étude de cas / Cas clinique\",\"partieTitle\":\"Questions Q1 à Q43 (Études de cas Broukro & Mme Droh + QCM/QCD)\",\"caseTitle\":\"Étude de cas N°I Centre de santé de Broukro & Étude de cas N°II Mme\",\"caseData\":\"Droh, 48 ans, G5P4 (Q1 à Q43) +=======================================================================+ +-----------------------------------------------------------------------+ ◆ ÉTUDES DE CAS N°I (Centre de Broukro) et N°II (Mme Droh, 48 ans, G5P4) [Q1 à Q43] ----------------------------------------------------------------------- Énoncé du cas : Cas N°I (Broukro) : Consommation de COC des 3 derniers mois typiques : Mars = 48 cycles ; Avril = 45 cycles ; Mai = 43 cycles. Stock après inventaire physique disponible utilisable = 110 cycles (et 5 cycles ayant des comprimés écrasés). Cas N°II (Mme Droh) : Mme Droh, 48 ans, G5P4 (4 enfants vivants), consulte en PF. Elle a utilisé un DIU il y a 3 ans posé en salle d'accouchement juste après l'accouchement. La persistance des crampes menstruelles l'a motivée à changer de méthode. Ces 5 derniers mois, son cycle menstruel est irrégulier. Elle opte pour l'auto-observation. ----------------------------------------------------------------------- -----------------------------------------------------------------------\",\"text\":\"Quelle information du texte constitue une contre-indication (ou obstacle de recevabilité) à la méthode choisie par Mme DROH (méthode d'auto-observation) ?\",\"options\":[{\"letter\":\"A\",\"text\":\"La persistance des crampes menstruelles\"},{\"letter\":\"B\",\"text\":\"Elle a 48 ans (périménopause)\"},{\"letter\":\"C\",\"text\":\"Le cycle menstruel irrégulier\"},{\"letter\":\"D\",\"text\":\"Elle est 5ème geste\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"C. Le cycle menstruel irrégulier\",\"answerLetters\":[\"C\"],\"explanation\":\"Mme Droh présente depuis 5 mois un CYCLE MENSTRUEL IRRÉGULIER (c, lié à la périménopause à 48 ans), ce qui rend l'auto-observation (calcul de la période fertile) peu fiable et contre-indiquée en pratique (catégorie D = Différer/Attention de l'OMS pour les MAO basées sur le calendrier ou les symptômes).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"agboville-2__ssr-pf__29\",\"num\":\"30\",\"type\":\"CAS_CLINIQUE\",\"typeLabel\":\"Étude de cas / Cas clinique\",\"partieTitle\":\"Questions Q1 à Q43 (Études de cas Broukro & Mme Droh + QCM/QCD)\",\"caseTitle\":\"Étude de cas N°I Centre de santé de Broukro & Étude de cas N°II Mme\",\"caseData\":\"Droh, 48 ans, G5P4 (Q1 à Q43) +=======================================================================+ +-----------------------------------------------------------------------+ ◆ ÉTUDES DE CAS N°I (Centre de Broukro) et N°II (Mme Droh, 48 ans, G5P4) [Q1 à Q43] ----------------------------------------------------------------------- Énoncé du cas : Cas N°I (Broukro) : Consommation de COC des 3 derniers mois typiques : Mars = 48 cycles ; Avril = 45 cycles ; Mai = 43 cycles. Stock après inventaire physique disponible utilisable = 110 cycles (et 5 cycles ayant des comprimés écrasés). Cas N°II (Mme Droh) : Mme Droh, 48 ans, G5P4 (4 enfants vivants), consulte en PF. Elle a utilisé un DIU il y a 3 ans posé en salle d'accouchement juste après l'accouchement. La persistance des crampes menstruelles l'a motivée à changer de méthode. Ces 5 derniers mois, son cycle menstruel est irrégulier. Elle opte pour l'auto-observation. ----------------------------------------------------------------------- -----------------------------------------------------------------------\",\"text\":\"Devant tout problème génital qui survient chez une utilisatrice du DIU, la conduite ne nécessite pas un examen gynécologique :\",\"options\":[],\"mode\":\"open\",\"multi\":false,\"answer\":\"FAUX\",\"answerLetters\":[],\"explanation\":\"C'est faux : toute plainte gynécologique chez une porteuse de DIU (douleurs pelviennes, saignements anormaux, leucorrhées, non-perception des fils) impose obligatoirement un examen gynécologique complet (examen au spéculum et toucher vaginal) pour rechercher une infection génitale haute, un déplacement/expulsion ou une grossesse.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"agboville-2__ssr-pf__30\",\"num\":\"31\",\"type\":\"CAS_CLINIQUE\",\"typeLabel\":\"Étude de cas / Cas clinique\",\"partieTitle\":\"Questions Q1 à Q43 (Études de cas Broukro & Mme Droh + QCM/QCD)\",\"caseTitle\":\"Étude de cas N°I Centre de santé de Broukro & Étude de cas N°II Mme\",\"caseData\":\"Droh, 48 ans, G5P4 (Q1 à Q43) +=======================================================================+ +-----------------------------------------------------------------------+ ◆ ÉTUDES DE CAS N°I (Centre de Broukro) et N°II (Mme Droh, 48 ans, G5P4) [Q1 à Q43] ----------------------------------------------------------------------- Énoncé du cas : Cas N°I (Broukro) : Consommation de COC des 3 derniers mois typiques : Mars = 48 cycles ; Avril = 45 cycles ; Mai = 43 cycles. Stock après inventaire physique disponible utilisable = 110 cycles (et 5 cycles ayant des comprimés écrasés). Cas N°II (Mme Droh) : Mme Droh, 48 ans, G5P4 (4 enfants vivants), consulte en PF. Elle a utilisé un DIU il y a 3 ans posé en salle d'accouchement juste après l'accouchement. La persistance des crampes menstruelles l'a motivée à changer de méthode. Ces 5 derniers mois, son cycle menstruel est irrégulier. Elle opte pour l'auto-observation. ----------------------------------------------------------------------- -----------------------------------------------------------------------\",\"text\":\"Le Néogynon est une pilule normodosée qui contient 50 mcg (0,05 mg) d'œstrogène (éthinylestradiol) :\",\"options\":[],\"mode\":\"open\",\"multi\":false,\"answer\":\"VRAI\",\"answerLetters\":[],\"explanation\":\"Oui, le Néogynon est le contraceptif oral combiné normodosé de référence contenant 50 µg (0,05 mg) d'éthinylestradiol et 250 µg de lévonorgestrel par comprimé (par opposition aux pilules minidosées comme Microgynon/Lo-Femenal qui contiennent 30 µg d'éthinylestradiol).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"agboville-2__ssr-pf__31\",\"num\":\"32\",\"type\":\"CAS_CLINIQUE\",\"typeLabel\":\"Étude de cas / Cas clinique\",\"partieTitle\":\"Questions Q1 à Q43 (Études de cas Broukro & Mme Droh + QCM/QCD)\",\"caseTitle\":\"Étude de cas N°I Centre de santé de Broukro & Étude de cas N°II Mme\",\"caseData\":\"Droh, 48 ans, G5P4 (Q1 à Q43) +=======================================================================+ +-----------------------------------------------------------------------+ ◆ ÉTUDES DE CAS N°I (Centre de Broukro) et N°II (Mme Droh, 48 ans, G5P4) [Q1 à Q43] ----------------------------------------------------------------------- Énoncé du cas : Cas N°I (Broukro) : Consommation de COC des 3 derniers mois typiques : Mars = 48 cycles ; Avril = 45 cycles ; Mai = 43 cycles. Stock après inventaire physique disponible utilisable = 110 cycles (et 5 cycles ayant des comprimés écrasés). Cas N°II (Mme Droh) : Mme Droh, 48 ans, G5P4 (4 enfants vivants), consulte en PF. Elle a utilisé un DIU il y a 3 ans posé en salle d'accouchement juste après l'accouchement. La persistance des crampes menstruelles l'a motivée à changer de méthode. Ces 5 derniers mois, son cycle menstruel est irrégulier. Elle opte pour l'auto-observation. ----------------------------------------------------------------------- -----------------------------------------------------------------------\",\"text\":\"Les méthodes de barrière se présentent sous forme de :\",\"options\":[{\"letter\":\"A\",\"text\":\"Fibres\"},{\"letter\":\"B\",\"text\":\"Dispositifs en plastique, silicone ou en latex (diaphragme, cape, condoms)\"},{\"letter\":\"C\",\"text\":\"Produits chimiques (spermicides)\"},{\"letter\":\"D\",\"text\":\"Fines gaines en caoutchouc/latex ou en vinyle/polyuréthane (préservatifs masculin et féminin)\"}],\"mode\":\"mcq\",\"multi\":true,\"answer\":\"B et C et D\",\"answerLetters\":[\"B\",\"C\",\"D\"],\"explanation\":\"Les méthodes de barrière regroupent les barrières mécaniques (fines gaines de latex/polyuréthane pour les condoms d, coupoles/dispositifs en latex ou silicone pour le diaphragme et la cape cervicale b) et les barrières chimiques (spermicides c).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"agboville-2__ssr-pf__32\",\"num\":\"33\",\"type\":\"CAS_CLINIQUE\",\"typeLabel\":\"Étude de cas / Cas clinique\",\"partieTitle\":\"Questions Q1 à Q43 (Études de cas Broukro & Mme Droh + QCM/QCD)\",\"caseTitle\":\"Étude de cas N°I Centre de santé de Broukro & Étude de cas N°II Mme\",\"caseData\":\"Droh, 48 ans, G5P4 (Q1 à Q43) +=======================================================================+ +-----------------------------------------------------------------------+ ◆ ÉTUDES DE CAS N°I (Centre de Broukro) et N°II (Mme Droh, 48 ans, G5P4) [Q1 à Q43] ----------------------------------------------------------------------- Énoncé du cas : Cas N°I (Broukro) : Consommation de COC des 3 derniers mois typiques : Mars = 48 cycles ; Avril = 45 cycles ; Mai = 43 cycles. Stock après inventaire physique disponible utilisable = 110 cycles (et 5 cycles ayant des comprimés écrasés). Cas N°II (Mme Droh) : Mme Droh, 48 ans, G5P4 (4 enfants vivants), consulte en PF. Elle a utilisé un DIU il y a 3 ans posé en salle d'accouchement juste après l'accouchement. La persistance des crampes menstruelles l'a motivée à changer de méthode. Ces 5 derniers mois, son cycle menstruel est irrégulier. Elle opte pour l'auto-observation. ----------------------------------------------------------------------- -----------------------------------------------------------------------\",\"text\":\"Dans l'étude de cas de Broukro, si le niveau maximum est n = 2 mois, quelle est la quantité à commander ?\",\"options\":[{\"letter\":\"A\",\"text\":\"30 cycles\"},{\"letter\":\"B\",\"text\":\"28 cycles\"},{\"letter\":\"C\",\"text\":\"26 cycles\"},{\"letter\":\"D\",\"text\":\"Pas de commande à faire\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"D. Pas de commande à faire\",\"answerLetters\":[\"D\"],\"explanation\":\"Calculons le Stock Maximum : Smax = CMM × n = 45,33 × 2 = 90,66 ≈ 91 cycles (ou 45 × 2 = 90 cycles). Or le Stock Disponible Utilisable (SDU) en magasin est déjà de 110 cycles (> 91 cycles) ! La quantité à commander (Qc = Smax − SDU = 91 − 110 = −19 cycles) étant négative, le centre est en surstock : il n'y a donc PAS DE COMMANDE À FAIRE (Réponse d).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"agboville-2__ssr-pf__33\",\"num\":\"34\",\"type\":\"CAS_CLINIQUE\",\"typeLabel\":\"Étude de cas / Cas clinique\",\"partieTitle\":\"Questions Q1 à Q43 (Études de cas Broukro & Mme Droh + QCM/QCD)\",\"caseTitle\":\"Étude de cas N°I Centre de santé de Broukro & Étude de cas N°II Mme\",\"caseData\":\"Droh, 48 ans, G5P4 (Q1 à Q43) +=======================================================================+ +-----------------------------------------------------------------------+ ◆ ÉTUDES DE CAS N°I (Centre de Broukro) et N°II (Mme Droh, 48 ans, G5P4) [Q1 à Q43] ----------------------------------------------------------------------- Énoncé du cas : Cas N°I (Broukro) : Consommation de COC des 3 derniers mois typiques : Mars = 48 cycles ; Avril = 45 cycles ; Mai = 43 cycles. Stock après inventaire physique disponible utilisable = 110 cycles (et 5 cycles ayant des comprimés écrasés). Cas N°II (Mme Droh) : Mme Droh, 48 ans, G5P4 (4 enfants vivants), consulte en PF. Elle a utilisé un DIU il y a 3 ans posé en salle d'accouchement juste après l'accouchement. La persistance des crampes menstruelles l'a motivée à changer de méthode. Ces 5 derniers mois, son cycle menstruel est irrégulier. Elle opte pour l'auto-observation. ----------------------------------------------------------------------- -----------------------------------------------------------------------\",\"text\":\"La posologie exacte de COC normodosés (50 µg d'EE, ex. Néogynon) utilisés comme contraception d'urgence (méthode de Yuzpe) est :\",\"options\":[{\"letter\":\"A\",\"text\":\"4 CP la 1ère heure et 4 CP 12 heures après\"},{\"letter\":\"B\",\"text\":\"2 CP la 1ère heure et 2 CP 12 heures après\"},{\"letter\":\"C\",\"text\":\"3 CP la 1ère heure et 3 CP 12 heures après\"},{\"letter\":\"D\",\"text\":\"20 CP la 1ère heure et 20 CP 12 heures après\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. 2 CP la 1ère heure et 2 CP 12 heures après\",\"answerLetters\":[\"B\"],\"explanation\":\"Selon le protocole de Yuzpe (100 µg d'éthinylestradiol + 500 µg de lévonorgestrel par prise, renouvelé 12 heures plus tard) : avec une pilule NORMODOSÉE à 50 µg d'EE (Néogynon), la posologie est de 2 comprimés dès que possible (dans les 72 h) suivis de 2 comprimés 12 heures après (b). [Avec une pilule MINIDOSÉE à 30 µg d'EE comme Lo-Femenal/Microgynon, la posologie est de 4 comprimés puis 4 comprimés 12 h après].\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"agboville-2__ssr-pf__34\",\"num\":\"35\",\"type\":\"CAS_CLINIQUE\",\"typeLabel\":\"Étude de cas / Cas clinique\",\"partieTitle\":\"Questions Q1 à Q43 (Études de cas Broukro & Mme Droh + QCM/QCD)\",\"caseTitle\":\"Étude de cas N°I Centre de santé de Broukro & Étude de cas N°II Mme\",\"caseData\":\"Droh, 48 ans, G5P4 (Q1 à Q43) +=======================================================================+ +-----------------------------------------------------------------------+ ◆ ÉTUDES DE CAS N°I (Centre de Broukro) et N°II (Mme Droh, 48 ans, G5P4) [Q1 à Q43] ----------------------------------------------------------------------- Énoncé du cas : Cas N°I (Broukro) : Consommation de COC des 3 derniers mois typiques : Mars = 48 cycles ; Avril = 45 cycles ; Mai = 43 cycles. Stock après inventaire physique disponible utilisable = 110 cycles (et 5 cycles ayant des comprimés écrasés). Cas N°II (Mme Droh) : Mme Droh, 48 ans, G5P4 (4 enfants vivants), consulte en PF. Elle a utilisé un DIU il y a 3 ans posé en salle d'accouchement juste après l'accouchement. La persistance des crampes menstruelles l'a motivée à changer de méthode. Ces 5 derniers mois, son cycle menstruel est irrégulier. Elle opte pour l'auto-observation. ----------------------------------------------------------------------- -----------------------------------------------------------------------\",\"text\":\"Lorsqu'un homme subit une vasectomie, il ne doit s'adonner aux tâches physiques pénibles qu'après 72 heures (repos de 2 à 3 jours) :\",\"options\":[],\"mode\":\"open\",\"multi\":false,\"answer\":\"VRAI\",\"answerLetters\":[],\"explanation\":\"Après une vasectomie, il est recommandé au client de garder le pansement propre, de porter un slip suspensoir et d'éviter tout effort physique intense ou travail pénible pendant les 48 à 72 premières heures (2 à 3 jours) pour prévenir l'hématome scrotal et la douleur.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"agboville-2__ssr-pf__35\",\"num\":\"36\",\"type\":\"CAS_CLINIQUE\",\"typeLabel\":\"Étude de cas / Cas clinique\",\"partieTitle\":\"Questions Q1 à Q43 (Études de cas Broukro & Mme Droh + QCM/QCD)\",\"caseTitle\":\"Étude de cas N°I Centre de santé de Broukro & Étude de cas N°II Mme\",\"caseData\":\"Droh, 48 ans, G5P4 (Q1 à Q43) +=======================================================================+ +-----------------------------------------------------------------------+ ◆ ÉTUDES DE CAS N°I (Centre de Broukro) et N°II (Mme Droh, 48 ans, G5P4) [Q1 à Q43] ----------------------------------------------------------------------- Énoncé du cas : Cas N°I (Broukro) : Consommation de COC des 3 derniers mois typiques : Mars = 48 cycles ; Avril = 45 cycles ; Mai = 43 cycles. Stock après inventaire physique disponible utilisable = 110 cycles (et 5 cycles ayant des comprimés écrasés). Cas N°II (Mme Droh) : Mme Droh, 48 ans, G5P4 (4 enfants vivants), consulte en PF. Elle a utilisé un DIU il y a 3 ans posé en salle d'accouchement juste après l'accouchement. La persistance des crampes menstruelles l'a motivée à changer de méthode. Ces 5 derniers mois, son cycle menstruel est irrégulier. Elle opte pour l'auto-observation. ----------------------------------------------------------------------- -----------------------------------------------------------------------\",\"text\":\"Les volets de la Santé des Adolescents et des Jeunes (SAJ) sont au nombre de 6 :\",\"options\":[],\"mode\":\"open\",\"multi\":false,\"answer\":\"VRAI (ou Faux selon la nomenclature nationale à 5 ou 6 volets du PNSSU-SAJ)\",\"answerLetters\":[],\"explanation\":\"Dans le programme national de santé de la reproduction / SAJ enseigné à l'INFAS, les interventions de santé des adolescents et des jeunes s'articulent autour de 6 volets prioritaires (information/CCC, PF/prévention des grossesses précoces, prévention/PEC des IST-VIH, soins prénatals/postnatals adaptés, lutte contre les pratiques néfastes/VBG, promotion de l'hygiène et nutrition).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"agboville-2__ssr-pf__36\",\"num\":\"37\",\"type\":\"CAS_CLINIQUE\",\"typeLabel\":\"Étude de cas / Cas clinique\",\"partieTitle\":\"Questions Q1 à Q43 (Études de cas Broukro & Mme Droh + QCM/QCD)\",\"caseTitle\":\"Étude de cas N°I Centre de santé de Broukro & Étude de cas N°II Mme\",\"caseData\":\"Droh, 48 ans, G5P4 (Q1 à Q43) +=======================================================================+ +-----------------------------------------------------------------------+ ◆ ÉTUDES DE CAS N°I (Centre de Broukro) et N°II (Mme Droh, 48 ans, G5P4) [Q1 à Q43] ----------------------------------------------------------------------- Énoncé du cas : Cas N°I (Broukro) : Consommation de COC des 3 derniers mois typiques : Mars = 48 cycles ; Avril = 45 cycles ; Mai = 43 cycles. Stock après inventaire physique disponible utilisable = 110 cycles (et 5 cycles ayant des comprimés écrasés). Cas N°II (Mme Droh) : Mme Droh, 48 ans, G5P4 (4 enfants vivants), consulte en PF. Elle a utilisé un DIU il y a 3 ans posé en salle d'accouchement juste après l'accouchement. La persistance des crampes menstruelles l'a motivée à changer de méthode. Ces 5 derniers mois, son cycle menstruel est irrégulier. Elle opte pour l'auto-observation. ----------------------------------------------------------------------- -----------------------------------------------------------------------\",\"text\":\"La contraception se définit comme :\",\"options\":[{\"letter\":\"A\",\"text\":\"L'ensemble des méthodes naturelles mises à la disposition d'un couple ou d'un individu pour empêcher temporairement ou définitivement la conception\"},{\"letter\":\"B\",\"text\":\"L'ensemble des méthodes naturelles ou artificielles mises à la disposition d'un couple ou d'un individu pour empêcher temporairement ou définitivement la conception\"},{\"letter\":\"C\",\"text\":\"L'ensemble des méthodes artificielles mises à la disposition d'un couple ou d'un individu pour empêcher temporairement la conception\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. L'ensemble des méthodes naturelles ou artificielles mises à la disposition d'un couple ou d'un individu pour empêcher temporairement ou définitivement la conception\",\"answerLetters\":[\"B\"],\"explanation\":\"La définition complète de la contraception englobe l'ensemble des méthodes NATURELLES OU ARTIFICIELLES permettant d'empêcher de façon TEMPORAIRE (réversible) OU DÉFINITIVE (irréversible : stérilisation chirurgicale) la fécondation/conception (b).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"agboville-2__ssr-pf__37\",\"num\":\"38\",\"type\":\"CAS_CLINIQUE\",\"typeLabel\":\"Étude de cas / Cas clinique\",\"partieTitle\":\"Questions Q1 à Q43 (Études de cas Broukro & Mme Droh + QCM/QCD)\",\"caseTitle\":\"Étude de cas N°I Centre de santé de Broukro & Étude de cas N°II Mme\",\"caseData\":\"Droh, 48 ans, G5P4 (Q1 à Q43) +=======================================================================+ +-----------------------------------------------------------------------+ ◆ ÉTUDES DE CAS N°I (Centre de Broukro) et N°II (Mme Droh, 48 ans, G5P4) [Q1 à Q43] ----------------------------------------------------------------------- Énoncé du cas : Cas N°I (Broukro) : Consommation de COC des 3 derniers mois typiques : Mars = 48 cycles ; Avril = 45 cycles ; Mai = 43 cycles. Stock après inventaire physique disponible utilisable = 110 cycles (et 5 cycles ayant des comprimés écrasés). Cas N°II (Mme Droh) : Mme Droh, 48 ans, G5P4 (4 enfants vivants), consulte en PF. Elle a utilisé un DIU il y a 3 ans posé en salle d'accouchement juste après l'accouchement. La persistance des crampes menstruelles l'a motivée à changer de méthode. Ces 5 derniers mois, son cycle menstruel est irrégulier. Elle opte pour l'auto-observation. ----------------------------------------------------------------------- -----------------------------------------------------------------------\",\"text\":\"Quel est le Mois de Stock Disponible (MSD) du centre de santé de Broukro ?\",\"options\":[{\"letter\":\"A\",\"text\":\"2,39\"},{\"letter\":\"B\",\"text\":\"7\"},{\"letter\":\"C\",\"text\":\"Aucune proposition juste\"},{\"letter\":\"D\",\"text\":\"3\"},{\"letter\":\"E\",\"text\":\"3,5 a. Le coït interrompu\"},{\"letter\":\"B\",\"text\":\"N'est pas éligible à la méthode d'auto-observation (ou uniquement les méthodes basées sur les symptômes : méthode de Billings de la glaire cervicale avec prudence, mais pas Ogino-Knaus)\"},{\"letter\":\"C\",\"text\":\"Les spermicides\"},{\"letter\":\"D\",\"text\":\"La méthode de Billings ou de la glaire cervicale\"},{\"letter\":\"E\",\"text\":\"La méthode d'Ogino-Knaus a. La prise de décision\"},{\"letter\":\"B\",\"text\":\"Le diagnostic\"},{\"letter\":\"C\",\"text\":\"La vérification des données\"},{\"letter\":\"D\",\"text\":\"La décision finale\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"C. La vérification des données\",\"answerLetters\":[\"C\"],\"explanation\":\"Vérifions les deux calculs : 1) Si l'on a retenu à la Q1 la CMM arrondie à l'entier supérieur = 46 cycles : MSD = SDU / CMM = 110 / 46 = 2,391, soit exactement 2,39 mois (Proposition a) ! 2) Si l'on utilise la CMM non arrondie 45,33 ou arrondie à 45 : MSD = 110 / 45,33 = 2,43 mois (c). La présence du chiffre exact 2,39 en (a) prouve que l'auteur du sujet a utilisé CMM = 46 cycles (110 / 46 = 2,39). Q39 (1) — Quelles sont les différentes méthodes d'auto-observation que peut utiliser votre cliente Mme Droh (48 ans, cycles irréguliers depuis 5 mois) ? Comme Mme Droh (48 ans) a des cycles menstruels irréguliers depuis 5 mois (périménopause), elle n'est pas éligible aux méthodes d'auto-observation (b), car l'irrégularité hormonale fausse le calcul du calendrier (Ogino-Knaus) et l'interprétation de la glaire ou de la température. (Si la question vise à identifier quelles méthodes de la liste sont des MAO en général, il s'agit de Billings [d] et d'Ogino-Knaus [e], le coït interrompu et les spermicides n'étant pas des MAO). Q39 (2) — Quelle est la dernière étape de la consultation en PF ? (Seconde question numérotée 39 au bas de la page 107) Parmi les étapes de la démarche décisionnelle clinique listées ici (vérification des données → diagnostic → décision finale / prise de décision), l'étape qui clôt l'évaluation est la décision finale (d).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"agboville-2__ssr-pf__38\",\"num\":\"40\",\"type\":\"CAS_CLINIQUE\",\"typeLabel\":\"Étude de cas / Cas clinique\",\"partieTitle\":\"Questions Q1 à Q43 (Études de cas Broukro & Mme Droh + QCM/QCD)\",\"caseTitle\":\"Étude de cas N°I Centre de santé de Broukro & Étude de cas N°II Mme\",\"caseData\":\"Droh, 48 ans, G5P4 (Q1 à Q43) +=======================================================================+ +-----------------------------------------------------------------------+ ◆ ÉTUDES DE CAS N°I (Centre de Broukro) et N°II (Mme Droh, 48 ans, G5P4) [Q1 à Q43] ----------------------------------------------------------------------- Énoncé du cas : Cas N°I (Broukro) : Consommation de COC des 3 derniers mois typiques : Mars = 48 cycles ; Avril = 45 cycles ; Mai = 43 cycles. Stock après inventaire physique disponible utilisable = 110 cycles (et 5 cycles ayant des comprimés écrasés). Cas N°II (Mme Droh) : Mme Droh, 48 ans, G5P4 (4 enfants vivants), consulte en PF. Elle a utilisé un DIU il y a 3 ans posé en salle d'accouchement juste après l'accouchement. La persistance des crampes menstruelles l'a motivée à changer de méthode. Ces 5 derniers mois, son cycle menstruel est irrégulier. Elle opte pour l'auto-observation. ----------------------------------------------------------------------- -----------------------------------------------------------------------\",\"text\":\"À quelle phase du counseling allez-vous donner des instructions à Mme DROH pour qu'elle sache utiliser la méthode et discuter avec elle des effets secondaires de la méthode si elle est éligible ?\",\"options\":[{\"letter\":\"A\",\"text\":\"Counseling d'initiation (général)\"},{\"letter\":\"B\",\"text\":\"Counseling spécifique\"},{\"letter\":\"C\",\"text\":\"Counseling spécial\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Counseling spécifique\",\"answerLetters\":[\"B\"],\"explanation\":\"L'explication détaillée du mode d'emploi, des effets secondaires éventuels, de la conduite à tenir en cas d'oubli et des signes d'alarme d'une méthode choisie constitue par définition le COUNSELING SPÉCIFIQUE (b).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"agboville-2__ssr-pf__39\",\"num\":\"41\",\"type\":\"CAS_CLINIQUE\",\"typeLabel\":\"Étude de cas / Cas clinique\",\"partieTitle\":\"Questions Q1 à Q43 (Études de cas Broukro & Mme Droh + QCM/QCD)\",\"caseTitle\":\"Étude de cas N°I Centre de santé de Broukro & Étude de cas N°II Mme\",\"caseData\":\"Droh, 48 ans, G5P4 (Q1 à Q43) +=======================================================================+ +-----------------------------------------------------------------------+ ◆ ÉTUDES DE CAS N°I (Centre de Broukro) et N°II (Mme Droh, 48 ans, G5P4) [Q1 à Q43] ----------------------------------------------------------------------- Énoncé du cas : Cas N°I (Broukro) : Consommation de COC des 3 derniers mois typiques : Mars = 48 cycles ; Avril = 45 cycles ; Mai = 43 cycles. Stock après inventaire physique disponible utilisable = 110 cycles (et 5 cycles ayant des comprimés écrasés). Cas N°II (Mme Droh) : Mme Droh, 48 ans, G5P4 (4 enfants vivants), consulte en PF. Elle a utilisé un DIU il y a 3 ans posé en salle d'accouchement juste après l'accouchement. La persistance des crampes menstruelles l'a motivée à changer de méthode. Ces 5 derniers mois, son cycle menstruel est irrégulier. Elle opte pour l'auto-observation. ----------------------------------------------------------------------- -----------------------------------------------------------------------\",\"text\":\"Quels sont les deux principaux critères de qualité d'une méthode contraceptive mis en cause dans le texte à travers l'abandon du DIU par Mme DROH (pour persistance de crampes menstruelles) ?\",\"options\":[{\"letter\":\"A\",\"text\":\"La sécurité\"},{\"letter\":\"B\",\"text\":\"La réversibilité\"},{\"letter\":\"C\",\"text\":\"La tolérance (acceptabilité/innocuité clinique)\"},{\"letter\":\"D\",\"text\":\"Le coût\"},{\"letter\":\"E\",\"text\":\"La continuité (taux de continuation)\"}],\"mode\":\"mcq\",\"multi\":true,\"answer\":\"C et E\",\"answerLetters\":[\"C\",\"E\"],\"explanation\":\"La persistance d'effets secondaires douloureux (crampes menstruelles sous DIU) met directement en cause la TOLÉRANCE / acceptabilité de la méthode (c), ce qui a entraîné l'arrêt de la méthode et donc une rupture de la CONTINUITÉ d'utilisation (e).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"agboville-2__ssr-pf__40\",\"num\":\"42\",\"type\":\"CAS_CLINIQUE\",\"typeLabel\":\"Étude de cas / Cas clinique\",\"partieTitle\":\"Questions Q1 à Q43 (Études de cas Broukro & Mme Droh + QCM/QCD)\",\"caseTitle\":\"Étude de cas N°I Centre de santé de Broukro & Étude de cas N°II Mme\",\"caseData\":\"Droh, 48 ans, G5P4 (Q1 à Q43) +=======================================================================+ +-----------------------------------------------------------------------+ ◆ ÉTUDES DE CAS N°I (Centre de Broukro) et N°II (Mme Droh, 48 ans, G5P4) [Q1 à Q43] ----------------------------------------------------------------------- Énoncé du cas : Cas N°I (Broukro) : Consommation de COC des 3 derniers mois typiques : Mars = 48 cycles ; Avril = 45 cycles ; Mai = 43 cycles. Stock après inventaire physique disponible utilisable = 110 cycles (et 5 cycles ayant des comprimés écrasés). Cas N°II (Mme Droh) : Mme Droh, 48 ans, G5P4 (4 enfants vivants), consulte en PF. Elle a utilisé un DIU il y a 3 ans posé en salle d'accouchement juste après l'accouchement. La persistance des crampes menstruelles l'a motivée à changer de méthode. Ces 5 derniers mois, son cycle menstruel est irrégulier. Elle opte pour l'auto-observation. ----------------------------------------------------------------------- -----------------------------------------------------------------------\",\"text\":\"La posologie exacte de COC (minidosés ou normodosés selon les propositions ci-dessous) utilisés comme contraception d'urgence est :\",\"options\":[{\"letter\":\"A\",\"text\":\"1 CP la 1ère heure et 20 CP 12 heures après le rapport sexuel non protégé\"},{\"letter\":\"B\",\"text\":\"4 CP la 1ère heure et 4 CP 12 heures après, mais avant les 72 heures suivant le rapport sexuel non protégé\"},{\"letter\":\"C\",\"text\":\"2 CP la 1ère heure et 2 CP 72 heures après le rapport sexuel non protégé\"},{\"letter\":\"D\",\"text\":\"1 CP la 1ère heure et 4 CP 12 heures après\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. 4 CP la 1ère heure et 4 CP 12 heures après, mais avant les 72 heures suivant le rapport sexuel non protégé\",\"answerLetters\":[\"B\"],\"explanation\":\"Parmi les propositions A, B, C, D, seule la proposition B est médicalement exacte (C est faux car la 2e prise de 2 CP se fait 12 heures après la 1re prise et non '72 heures après' !). La posologie de 4 CP puis 4 CP 12 heures plus tard dans les 72 h correspond au protocole de Yuzpe avec des pilules œstroprogestatives minidosées à 30 µg d'EE (Lo-Femenal / Microgynon : B).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"agboville-2__ssr-pf__41\",\"num\":\"43\",\"type\":\"CAS_CLINIQUE\",\"typeLabel\":\"Étude de cas / Cas clinique\",\"partieTitle\":\"Questions Q1 à Q43 (Études de cas Broukro & Mme Droh + QCM/QCD)\",\"caseTitle\":\"Étude de cas N°I Centre de santé de Broukro & Étude de cas N°II Mme\",\"caseData\":\"Droh, 48 ans, G5P4 (Q1 à Q43) +=======================================================================+ +-----------------------------------------------------------------------+ ◆ ÉTUDES DE CAS N°I (Centre de Broukro) et N°II (Mme Droh, 48 ans, G5P4) [Q1 à Q43] ----------------------------------------------------------------------- Énoncé du cas : Cas N°I (Broukro) : Consommation de COC des 3 derniers mois typiques : Mars = 48 cycles ; Avril = 45 cycles ; Mai = 43 cycles. Stock après inventaire physique disponible utilisable = 110 cycles (et 5 cycles ayant des comprimés écrasés). Cas N°II (Mme Droh) : Mme Droh, 48 ans, G5P4 (4 enfants vivants), consulte en PF. Elle a utilisé un DIU il y a 3 ans posé en salle d'accouchement juste après l'accouchement. La persistance des crampes menstruelles l'a motivée à changer de méthode. Ces 5 derniers mois, son cycle menstruel est irrégulier. Elle opte pour l'auto-observation. ----------------------------------------------------------------------- -----------------------------------------------------------------------\",\"text\":\"La qualité d'une méthode contraceptive repose sur :\",\"options\":[{\"letter\":\"A\",\"text\":\"4 Critères\"},{\"letter\":\"B\",\"text\":\"5 Critères\"},{\"letter\":\"C\",\"text\":\"6 Critères\"},{\"letter\":\"D\",\"text\":\"7 Critères\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. 5 Critères\",\"answerLetters\":[\"B\"],\"explanation\":\"En planification familiale (cours INFAS), les critères classiques d'évaluation de la qualité d'une méthode contraceptive sont au nombre de 5 (Efficacité, Innocuité/Sécurité, Tolérance/Acceptabilité, Réversibilité, Accessibilité/Coût : b) ou 6 en incluant la Continuité (c). +-----------------------------------------------------------------------+ Épreuves : Santé Publique (Q1-Q53) | Pédiatrie Bloc A (Q1-Q50) | Gynécologie-Obstétrique (Q1-Q30) | PF/SSR (Q1-Q50) +=======================================================================+ +-----------------------------------------------------------------------+ +-----------------------------------------------------------------------+\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null}]}]},{\"name\":\"BOUAKÉ (S2 : 2025)\",\"slug\":\"bouake-2\",\"session\":\"S2\",\"annee\":2025,\"existe\":true,\"sujets\":[{\"name\":\"Gynéco-obstétrique\",\"slug\":\"gynecologie-obstetrique\",\"pages\":\"\",\"count\":30,\"session\":\"S2\",\"annee\":2025,\"source\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"questions\":[{\"id\":\"bouake-2__gynecologie-obstetrique__0\",\"num\":\"1\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"I. Questions à Choix Direct (QCD : Q1 à Q12)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Pour arrêter la crise d'éclampsie, il faut injecter 10 mg (sans préciser le médicament, ou alors que le traitement de référence est le sulfate de magnésium 4 g en IVL) en IVD lente en surveillant la respiration maternelle.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"D'une part, la proposition omet le nom de la molécule ('10 mg' de quoi ?) ; d'autre part, le médicament anticonvulsivant de référence absolue de l'éclampsie (protocole SONU/OMS) est le SULFATE DE MAGNÉSIUM (dose de charge de 4 g en IV lente sur 15–20 min + 10 g en IM), et non 10 mg de diazépam en IVD.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"bouake-2__gynecologie-obstetrique__1\",\"num\":\"2\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"I. Questions à Choix Direct (QCD : Q1 à Q12)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"La T.A. = 14/6 cmHg (140/60 mmHg) est considérée comme HTA durant la grossesse.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Vrai\",\"answerLetters\":[\"A\"],\"explanation\":\"L'HTA gravidique se définit par une PAS ≥ 140 mmHg (14 cmHg) ET/OU une PAD ≥ 90 mmHg (9 cmHg) : il suffit que l'un des deux chiffres atteigne le seuil (ici PAS = 14 cmHg ≥ 14) pour parler d'HTA au cours de la grossesse.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"bouake-2__gynecologie-obstetrique__2\",\"num\":\"3\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"I. Questions à Choix Direct (QCD : Q1 à Q12)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"La révision utérine est systématiquement indiquée chez une accouchée qui saigne abondamment par voie vaginale une heure de temps après son accouchement.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Vrai\",\"answerLetters\":[\"A\"],\"explanation\":\"Devant toute hémorragie du post-partum immédiat après expulsion du placenta, le premier geste obstétrical systématique est la révision utérine (sous asepsie et analgésie) pour vider la cavité utérine des caillots et d'éventuels débris placentaires afin de permettre la rétraction utérine.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"bouake-2__gynecologie-obstetrique__3\",\"num\":\"4\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"I. Questions à Choix Direct (QCD : Q1 à Q12)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Au cours de la délivrance, il est recommandé à l'infirmier, ou à la sage-femme, ou à l'obstétricien, de réaliser systématiquement la gestion active de la troisième phase de l'accouchement (GATPA).\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Vrai\",\"answerLetters\":[\"A\"],\"explanation\":\"La GATPA est recommandée systématiquement pour tout accouchement par voie basse par un prestataire qualifié afin de prévenir l'hémorragie du post-partum par atonie utérine.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"bouake-2__gynecologie-obstetrique__4\",\"num\":\"5\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"I. Questions à Choix Direct (QCD : Q1 à Q12)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"La surveillance de l'accouchée doit être poursuivie en salle d'accouchement pendant 2 heures (uniquement, ou 6 heures selon le protocole de ce sujet).\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Vrai\",\"answerLetters\":[\"A\"],\"explanation\":\"Classiquement, la surveillance immédiate en salle de naissance dure 2 heures après l'accouchement (A), puis se poursuit en suites de couches pendant au moins 24 à 48 heures (d'où la note B sur le sujet si le rédacteur jugeait la durée de 2 heures insuffisante).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"bouake-2__gynecologie-obstetrique__5\",\"num\":\"6\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"I. Questions à Choix Direct (QCD : Q1 à Q12)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"La chirurgie (laparotomie : hystérorraphie ou hystérectomie d'hémostase) est le vrai traitement curatif de la rupture utérine.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Vrai\",\"answerLetters\":[\"A\"],\"explanation\":\"La rupture utérine est une urgence chirurgicale absolue dont le traitement curatif repose sur la laparotomie d'urgence (extraction fœto-placentaire et suture conservatrice de la brèche utérine par hystérorraphie ou hystérectomie d'hémostase associée à la réanimation).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"bouake-2__gynecologie-obstetrique__6\",\"num\":\"7\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"I. Questions à Choix Direct (QCD : Q1 à Q12)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Une cupule qui déprime la face fœtale du placenta confirme le diagnostic positif de l'hématome rétroplacentaire après l'accouchement.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"Piège anatomique classique : dans l'Hématome Rétroplacentaire (HRP), le caillot noirâtre ancien déprime la FACE MATERNELLE (cotylédonaire, utérine) du placenta en formant une cupule, et NON la face fœtale !\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"bouake-2__gynecologie-obstetrique__7\",\"num\":\"8\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"I. Questions à Choix Direct (QCD : Q1 à Q12)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Les céphalées violentes, persistantes, pulsatiles et non calmées par les antalgiques évoquent une crise d'éclampsie chez une primigeste de 35ème SA.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"Les céphalées en casque intenses et rebelles (avec troubles visuels, acouphènes et barre épigastrique de Chaussier) définissent la PRÉ-ÉCLAMPSIE SÉVÈRE (ou éclampsisme = menace imminente d'éclampsie). La CRISE D'ÉCLAMPSIE se définit quant à elle par la survenue effective de CONVULSIONS tonico-cloniques généralisées et/ou d'un coma !\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"bouake-2__gynecologie-obstetrique__8\",\"num\":\"9\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"I. Questions à Choix Direct (QCD : Q1 à Q12)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Le régime sans sel associé à la prise d'un antihypertenseur doit être préconisé au cours de la gestose (pré-éclampsie).\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"Le régime sans sel (désodé) est FORMELLEMENT CONTRE-INDIQUÉ au cours de l'HTA gravidique et de la pré-éclampsie, car il aggrave l'hypovolémie plasmatique efficace déjà présente chez la pré-éclamptique et majore l'ischémie utéro-placentaire (régime normosodé obligatoire).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"bouake-2__gynecologie-obstetrique__9\",\"num\":\"10\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"I. Questions à Choix Direct (QCD : Q1 à Q12)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Le cancer du col utérin est causé par le Papillomavirus Humain (H.P.V.) et par le V.I.H.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"L'agent causal (étiologique) nécessaire du cancer du col utérin est le Papillomavirus Humain oncogène (HPV 16, 18...). Le VIH n'est pas l'agent causal direct mais un cofacteur d'immunodépression qui favorise la persistance de l'HPV et accélère l'évolution des dysplasies.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"bouake-2__gynecologie-obstetrique__10\",\"num\":\"11\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"I. Questions à Choix Direct (QCD : Q1 à Q12)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Le petit côté des membranes mesurant 7 cm (< 10 cm) est un signe qui confirme rétrospectivement un placenta praevia non recouvrant après la délivrance.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Vrai\",\"answerLetters\":[\"A\"],\"explanation\":\"À l'examen du délivre après un accouchement par voie basse, une distance entre l'orifice de rupture des membranes et le bord placentaire (petit côté des membranes) inférieure à 10 cm (ici 7 cm) confirme rétrospectivement que le placenta était bas inséré (placenta praevia latéral ou marginal).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"bouake-2__gynecologie-obstetrique__11\",\"num\":\"12\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"I. Questions à Choix Direct (QCD : Q1 à Q12)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Devant tout cas de G.E.U. non rompue ou rompue, l'infirmier ne doit pas organiser le transfert de la patiente pour une intervention chirurgicale.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"Toute suspicion de Grossesse Extra-Utérine (qu'elle soit déjà rompue ou non encore rompue) est une urgence vitale qui impose une évacuation sanitaire immédiate (avec voie veineuse de gros calibre) vers un centre chirurgical (SONU Complet).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"bouake-2__gynecologie-obstetrique__12\",\"num\":\"13\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"II. Deuxième Groupe de Sujet — QCM à items (Q13 à Q30)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"L'affection suivante est une complication du myome utérin hémorragique :\",\"options\":[{\"letter\":\"A\",\"text\":\"Anémie\"},{\"letter\":\"B\",\"text\":\"Cancer du col utérin\"},{\"letter\":\"C\",\"text\":\"Aménorrhée secondaire\"},{\"letter\":\"D\",\"text\":\"Aménorrhée primaire\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Anémie\",\"answerLetters\":[\"A\"],\"explanation\":\"Les ménorragies et métrorragies répétées provoquées par un fibrome utérin hémorragique (sous-muqueux ou interstitiel) entraînent une spoliation sanguine chronique responsable d'une anémie ferriprive (A).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"bouake-2__gynecologie-obstetrique__13\",\"num\":\"14\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"II. Deuxième Groupe de Sujet — QCM à items (Q13 à Q30)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"La localisation la plus fréquente de la grossesse extra-utérine est :\",\"options\":[{\"letter\":\"A\",\"text\":\"La trompe de Fallope\"},{\"letter\":\"B\",\"text\":\"L'utérus\"},{\"letter\":\"C\",\"text\":\"La trompe d'Eustache\"},{\"letter\":\"D\",\"text\":\"L'endomètre\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. La trompe de Fallope\",\"answerLetters\":[\"A\"],\"explanation\":\"Dans 96 à 98 % des cas, la GEU est de localisation TUBAIRE dans la trompe de Fallope (et plus particulièrement dans l'ampoule tubaire dans 70–75 % des cas : A). [La trompe d'Eustache en C est dans l'oreille moyenne !].\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"bouake-2__gynecologie-obstetrique__14\",\"num\":\"15\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"II. Deuxième Groupe de Sujet — QCM à items (Q13 à Q30)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Parmi les signes suivants, relever les 2 qui évoquent un cancer du col utérin chez une patiente âgée de 47 ans :\",\"options\":[{\"letter\":\"A\",\"text\":\"Ménorragies provoquées\"},{\"letter\":\"B\",\"text\":\"Ulcération cervicale saignant au moindre contact\"},{\"letter\":\"C\",\"text\":\"Métrorragies provoquées, répétées, sang rouge vif\"},{\"letter\":\"D\",\"text\":\"Ménorragies provoquées, répétées, sang rouge vif\"},{\"letter\":\"E\",\"text\":\"Ménorragies spontanées\"},{\"letter\":\"F\",\"text\":\"Métrorragies spontanées, répétées, sang rouge vif\"}],\"mode\":\"mcq\",\"multi\":true,\"answer\":\"B et C\",\"answerLetters\":[\"B\",\"C\"],\"explanation\":\"Le cancer invasif du col utérin se révèle fonctionnellement par des MÉTRORRAGIES PROVOQUÉES (post-coïtales ou lors de la toilette), indolores, capricieuses et répétées faites de sang rouge vif (C), et à l'examen au spéculum par une tumeur bourgeonnante ou une ULCÉRATION CERVICALE indurée saignant au moindre contact (B).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"bouake-2__gynecologie-obstetrique__15\",\"num\":\"16\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"II. Deuxième Groupe de Sujet — QCM à items (Q13 à Q30)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Les ménorragies spontanées évoquent : (relever la réponse juste)\",\"options\":[{\"letter\":\"A\",\"text\":\"Un avortement spontané\"},{\"letter\":\"B\",\"text\":\"Une grossesse extra-utérine non rompue\"},{\"letter\":\"C\",\"text\":\"Une grossesse extra-utérine rompue\"},{\"letter\":\"D\",\"text\":\"Un léiomyome utérin (fibrome utérin)\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"D. Un léiomyome utérin (fibrome utérin)\",\"answerLetters\":[\"D\"],\"explanation\":\"Les MÉNORRAGIES (règles abondantes et prolongées > 7 jours revenant de façon cyclique) constituent le maître symptôme du léiomyome (fibrome) utérin sous-muqueux ou interstitiel (D), tandis que l'avortement et la GEU donnent des métrorragies sur aménorrhée.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"bouake-2__gynecologie-obstetrique__16\",\"num\":\"17\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"II. Deuxième Groupe de Sujet — QCM à items (Q13 à Q30)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Relever les 2 affirmations suivantes qui sont exactes (ou 3 parmi A, D, F) :\",\"options\":[{\"letter\":\"A\",\"text\":\"Tout fibrome utérin qui se complique doit être traité\"},{\"letter\":\"B\",\"text\":\"Le fibrome utérin entraîne toujours une stérilité féminine\"},{\"letter\":\"C\",\"text\":\"Le fibrome utérin est une tumeur bénigne très rare chez la femme de race noire\"},{\"letter\":\"D\",\"text\":\"La douleur pelvienne, basse, bilatérale accompagnée de fièvre et de pertes vaginales purulentes évoque une salpingite aiguë bilatérale\"},{\"letter\":\"E\",\"text\":\"Les leucorrhées abondantes laiteuses évoquent une salpingite aiguë bilatérale\"},{\"letter\":\"F\",\"text\":\"Les métrorragies ou règles abondantes et prolongées peuvent évoquer un myome utérin\"}],\"mode\":\"mcq\",\"multi\":true,\"answer\":\"D et F\",\"answerLetters\":[\"D\",\"F\"],\"explanation\":\"L'association douleur pelvienne bilatérale + fièvre + leucorrhées purulentes est typique de la salpingite aiguë bilatérale (D), les ménométrorragies évoquent un myome utérin (F), et tout fibrome compliqué doit être pris en charge (A).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"bouake-2__gynecologie-obstetrique__17\",\"num\":\"18\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"II. Deuxième Groupe de Sujet — QCM à items (Q13 à Q30)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"La pathologie suivante est une cause d'avortement spontané (tardif à répétition) :\",\"options\":[{\"letter\":\"A\",\"text\":\"La béance du col de l'utérus\"},{\"letter\":\"B\",\"text\":\"Le kyste de l'ovaire\"},{\"letter\":\"C\",\"text\":\"La fausse couche spontanée\"},{\"letter\":\"D\",\"text\":\"La viabilité fœtale\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. La béance du col de l'utérus\",\"answerLetters\":[\"A\"],\"explanation\":\"La béance cervico-isthmique (A) est la cause anatomique maternelle classique des avortements spontanés tardifs du 2e trimestre (à répétition, rapides et peu douloureux), traitée préventivement par cerclage du col utérin entre 12 et 15 SA.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"bouake-2__gynecologie-obstetrique__18\",\"num\":\"19\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"II. Deuxième Groupe de Sujet — QCM à items (Q13 à Q30)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Parmi les affirmations suivantes, relever les 2 qui sont exactes :\",\"options\":[{\"letter\":\"A\",\"text\":\"Une protéinurie supérieure à une croix (≥ ++) fait partie des signes importants de la pré-éclampsie\"},{\"letter\":\"B\",\"text\":\"Le partographe sert à mieux surveiller la naissance\"},{\"letter\":\"C\",\"text\":\"L'infirmier n'est pas obligé d'organiser le transfert d'une patiente présentant un avortement molaire pour une surveillance en milieu spécialisé\"},{\"letter\":\"D\",\"text\":\"Le partographe sert à mieux surveiller l'expulsion du fœtus\"},{\"letter\":\"E\",\"text\":\"L'H.T.A. n'est pas un signe important de la pré-éclampsie\"},{\"letter\":\"F\",\"text\":\"Le partographe sert à mieux surveiller la première période du travail de l'accouchement\"}],\"mode\":\"mcq\",\"multi\":true,\"answer\":\"A et F\",\"answerLetters\":[\"A\",\"F\"],\"explanation\":\"La protéinurie significative (> 1 croix, soit ≥ 2 croix à la bandelette ou ≥ 300 mg/24h) associée à l'HTA après 20 SA est un signe cardinal de la pré-éclampsie (A), et le partogramme est l'outil graphique qui sert à surveiller la PREMIÈRE PÉRIODE du travail (dilatation du col de 4 à 10 cm : F).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"bouake-2__gynecologie-obstetrique__19\",\"num\":\"20\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"II. Deuxième Groupe de Sujet — QCM à items (Q13 à Q30)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"En cas de placenta praevia recouvrant avec hémorragie minime sur grossesse à terme et un col dilaté à 1 cm, l'infirmier doit : (relever la réponse juste)\",\"options\":[{\"letter\":\"A\",\"text\":\"Organiser le transfert rapide de la patiente pour une césarienne en urgence\"},{\"letter\":\"B\",\"text\":\"Réaliser une rupture artificielle large des membranes et surveiller très attentivement la patiente\"},{\"letter\":\"C\",\"text\":\"Réaliser une rupture artificielle large des membranes avant d'organiser la référence rapide de la patiente\"},{\"letter\":\"D\",\"text\":\"Réaliser une rupture artificielle large des membranes avant d'organiser le transfert rapide de la patiente\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Organiser le transfert rapide de la patiente pour une césarienne en urgence\",\"answerLetters\":[\"A\"],\"explanation\":\"Devant un placenta praevia RECOUVRANT (qui recouvre totalement l'orifice interne du col, il n'y a d'ailleurs pas de membranes accessibles et tout geste intracervical déclencherait une hémorragie cataclysmique !), l'accouchement par voie basse est strictement impossible : il faut organiser le transfert médicalisé immédiat pour une césarienne en urgence sans toucher au col (A).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"bouake-2__gynecologie-obstetrique__20\",\"num\":\"21\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"II. Deuxième Groupe de Sujet — QCM à items (Q13 à Q30)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Relever les 2 affirmations suivantes qui sont justes :\",\"options\":[{\"letter\":\"A\",\"text\":\"La grossesse molaire évolue toujours vers l'avortement molaire peu hémorragique\"},{\"letter\":\"B\",\"text\":\"Les métrorragies provoquées faites de sang rouge au 1er trimestre de grossesse peuvent évoquer une grossesse molaire\"},{\"letter\":\"C\",\"text\":\"La grossesse molaire évolue toujours (spontanément) vers l'avortement molaire très hémorragique\"},{\"letter\":\"D\",\"text\":\"La grossesse molaire peut évoluer vers le chorio-épithéliome (choriocarcinome)\"},{\"letter\":\"E\",\"text\":\"Les métrorragies spontanées faites de sang rouge au 3ème trimestre de grossesse peuvent évoquer une grossesse molaire\"},{\"letter\":\"F\",\"text\":\"La grossesse molaire évolue toujours vers le choriocarcinome\"}],\"mode\":\"mcq\",\"multi\":true,\"answer\":\"C et D\",\"answerLetters\":[\"C\",\"D\"],\"explanation\":\"En l'absence d'évacuation utérine par aspiration, la grossesse molaire évolue spontanément vers le 4e mois vers un avortement molaire parcellaire très hémorragique (C), et elle PEUT se compliquer secondairement dans 10 à 15 % des cas de tumeur trophoblastique gestationnelle / chorio-épithéliome (choriocarcinome : D, d'où la surveillance obligatoire des β-HCG).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"bouake-2__gynecologie-obstetrique__21\",\"num\":\"22\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"II. Deuxième Groupe de Sujet — QCM à items (Q13 à Q30)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Relever le signe suivant qui évoque une souffrance fœtale aiguë :\",\"options\":[{\"letter\":\"A\",\"text\":\"Rythme cardiaque fœtal à 170 battements par minute\"},{\"letter\":\"B\",\"text\":\"Rythme cardiaque fœtal à 120 battements par minute\"},{\"letter\":\"C\",\"text\":\"Liquide amniotique clair\"},{\"letter\":\"D\",\"text\":\"Bruits du cœur fœtal absents\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Rythme cardiaque fœtal à 170 battements par minute\",\"answerLetters\":[\"A\"],\"explanation\":\"Le RCF normal est compris entre 120 et 160 bpm (B est donc normal). Une absence de BDCF (D) signe la mort fœtale in utero. En revanche, une tachycardie fœtale à 170 bpm (> 160 bpm : A) ou une bradycardie < 110–120 bpm traduit une souffrance fœtale aiguë.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"bouake-2__gynecologie-obstetrique__22\",\"num\":\"23\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"II. Deuxième Groupe de Sujet — QCM à items (Q13 à Q30)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Parmi les propositions suivantes, relever l'élément qui ne fait pas partie des signes de l'hématome rétroplacentaire :\",\"options\":[{\"letter\":\"A\",\"text\":\"Une cupule qui déprime la face fœtale du placenta\"},{\"letter\":\"B\",\"text\":\"Métrorragies faites de sang noir au 3ème trimestre de grossesse\"},{\"letter\":\"C\",\"text\":\"Contracture utérine\"},{\"letter\":\"D\",\"text\":\"Utérus dur comme du bois\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Une cupule qui déprime la face fœtale du placenta\",\"answerLetters\":[\"A\"],\"explanation\":\"Dans l'HRP, la cupule déprime la face MATERNELLE du placenta et non la face fœtale (A est donc l'affirmation fausse, tandis que B, C et D sont les signes typiques de l'HRP).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"bouake-2__gynecologie-obstetrique__23\",\"num\":\"24\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"II. Deuxième Groupe de Sujet — QCM à items (Q13 à Q30)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Parmi les caractères suivants des leucorrhées, relever les 2 qui n'évoquent pas les leucorrhées à Trichomonas vaginalis :\",\"options\":[{\"letter\":\"A\",\"text\":\"Leucorrhées très épaisses (caséeuses/caillebottées)\"},{\"letter\":\"B\",\"text\":\"Leucorrhées très mousseuses (spumeuses, aérées)\"},{\"letter\":\"C\",\"text\":\"Leucorrhées très liquides (fluides)\"},{\"letter\":\"D\",\"text\":\"Leucorrhées ayant une odeur fade (ou inodores)\"},{\"letter\":\"E\",\"text\":\"Leucorrhées très abondantes\"},{\"letter\":\"F\",\"text\":\"Leucorrhées accompagnées de prurit vulvo-vaginal très intense et brûlures\"}],\"mode\":\"mcq\",\"multi\":true,\"answer\":\"A et D\",\"answerLetters\":[\"A\",\"D\"],\"explanation\":\"La vaginite à Trichomonas vaginalis donne des leucorrhées fluides/liquides (C), très abondantes (E), verdâtres, spumeuses/mousseuses (B), malodorantes (odeur de plâtre frais) avec prurit et brûlures intenses (F). En revanche, des leucorrhées très épaisses blanchâtres en lait caillé (A) et d'odeur fade/inodore (D) caractérisent la candidose vulvo-vaginale à Candida albicans !\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"bouake-2__gynecologie-obstetrique__24\",\"num\":\"25\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"II. Deuxième Groupe de Sujet — QCM à items (Q13 à Q30)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Relever le signe qui n'évoque pas une toxémie gravidique (pré-éclampsie) chez une primigeste de 35ème SA :\",\"options\":[{\"letter\":\"A\",\"text\":\"T.A. = 14/7\"},{\"letter\":\"B\",\"text\":\"Œdèmes des membres inférieurs\"},{\"letter\":\"C\",\"text\":\"Absence de protéinurie\"},{\"letter\":\"D\",\"text\":\"Albuminurie à une croix\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"C. Absence de protéinurie\",\"answerLetters\":[\"C\"],\"explanation\":\"La pré-éclampsie (toxémie gravidique) exige par définition l'association d'une HTA gravidique et d'une PROTÉINURIE (albuminurie) significative : l'absence de protéinurie (C) exclut donc la pré-éclampsie classique (orientant vers une HTA gravidique isolée).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"bouake-2__gynecologie-obstetrique__25\",\"num\":\"26\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"II. Deuxième Groupe de Sujet — QCM à items (Q13 à Q30)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Le signe suivant n'évoque pas en lui-même une pré-rupture utérine (syndrome de Bandl-Frommel) :\",\"options\":[{\"letter\":\"A\",\"text\":\"Dilatation stationnaire du col utérin\"},{\"letter\":\"B\",\"text\":\"Agitation maternelle (angoisse, douleur intense permanente)\"},{\"letter\":\"C\",\"text\":\"Œdème du col utérin\"},{\"letter\":\"D\",\"text\":\"Dilatation du col utérin à 7 cm\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"D. Dilatation du col utérin à 7 cm\",\"answerLetters\":[\"D\"],\"explanation\":\"Une dilatation cervicale à 7 cm est une simple mesure de la phase active du travail normale en soi (D), tandis que la stagnation de la dilatation (A), l'œdème du col comprimé par la présentation (C) et l'agitation anxieuse maternelle avec anneau de Bandl et tension des ligaments ronds (B) évoquent un travail obstructif au stade de pré-rupture.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"bouake-2__gynecologie-obstetrique__26\",\"num\":\"27\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"II. Deuxième Groupe de Sujet — QCM à items (Q13 à Q30)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Les signes suivants évoquent une grossesse extra-utérine non rompue chez une primigeste de 10ème SA : (relever la réponse fausse)\",\"options\":[{\"letter\":\"A\",\"text\":\"Métrorragies spontanées faites de sang noir\"},{\"letter\":\"B\",\"text\":\"Métrorragies provoquées faites de sang noir et abondant\"},{\"letter\":\"C\",\"text\":\"Métrorragies faites de sang noir en petite quantité et accompagnées de douleur pelvienne unilatérale\"},{\"letter\":\"D\",\"text\":\"Métrorragies faites de sang noir accompagnées de douleur pelvienne unilatérale\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Métrorragies provoquées faites de sang noir et abondant\",\"answerLetters\":[\"B\"],\"explanation\":\"Dans la GEU non rompue, les métrorragies sont SPONTANÉES, distillantes, de PETITE QUANTITÉ et de couleur brunâtre/noirâtre ('sépia'). Elles ne sont ni provoquées ni abondantes (B est donc la réponse fausse).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"bouake-2__gynecologie-obstetrique__27\",\"num\":\"28\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"II. Deuxième Groupe de Sujet — QCM à items (Q13 à Q30)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Au cours de la pré-éclampsie, l'HTA s'accompagne d'œdèmes qui ont les caractères suivants : (relever la réponse fausse)\",\"options\":[{\"letter\":\"A\",\"text\":\"Douloureux\"},{\"letter\":\"B\",\"text\":\"Prenant le godet\"},{\"letter\":\"C\",\"text\":\"Bilatéraux\"},{\"letter\":\"D\",\"text\":\"Mous (et blancs)\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Douloureux\",\"answerLetters\":[\"A\"],\"explanation\":\"Les œdèmes rénaux/vasculaires de la pré-éclampsie sont blancs, mous (D), INDOLORES, bilatéraux (C) et prennent le godet (B). Un œdème douloureux, chaud, rouge et unilatéral (A) évoque une thrombophlébite et non une pré-éclampsie.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"bouake-2__gynecologie-obstetrique__28\",\"num\":\"29\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"II. Deuxième Groupe de Sujet — QCM à items (Q13 à Q30)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Au cours du dépistage de masse du cancer du col utérin (par FCU), le rythme du dépistage est : (relever la réponse juste)\",\"options\":[{\"letter\":\"A\",\"text\":\"Tous les 24 mois si les 2 premiers examens de dépistage sont normaux\"},{\"letter\":\"B\",\"text\":\"Tous les 3 ans si les 2 premiers examens de dépistage (à 1 an d'intervalle) sont normaux\"},{\"letter\":\"C\",\"text\":\"Tous les 2 ans si les 2 premiers examens de dépistage sont normaux\"},{\"letter\":\"D\",\"text\":\"Chaque année si les 2 premiers examens de dépistage sont normaux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Tous les 3 ans si les 2 premiers examens de dépistage (à 1 an d'intervalle) sont normaux\",\"answerLetters\":[\"B\"],\"explanation\":\"Le protocole standard du dépistage cytologique par Frottis Cervico-Utérin (FCU) consiste à réaliser deux premiers frottis à 1 an d'intervalle ; s'ils sont tous deux normaux, le dépistage est ensuite répété tous les 3 ANS (B).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"bouake-2__gynecologie-obstetrique__29\",\"num\":\"30\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"II. Deuxième Groupe de Sujet — QCM à items (Q13 à Q30)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Le prestataire de santé autorisé à réaliser un avortement médicalisé conforme aux lois (interruption thérapeutique de grossesse) doit être : (relever les 2 réponses exactes)\",\"options\":[{\"letter\":\"A\",\"text\":\"Sage-femme diplômée d'État\"},{\"letter\":\"B\",\"text\":\"Infirmière diplômée d'État\"},{\"letter\":\"C\",\"text\":\"Médecin\"},{\"letter\":\"D\",\"text\":\"Médecin spécialiste en gynécologie-obstétrique\"},{\"letter\":\"E\",\"text\":\"Infirmier diplômé d'État\"},{\"letter\":\"F\",\"text\":\"Infirmière diplômée d'État ou Infirmier diplômé d'État\"}],\"mode\":\"mcq\",\"multi\":true,\"answer\":\"C et D\",\"answerLetters\":[\"C\",\"D\"],\"explanation\":\"Selon la législation ivoirienne (Code pénal et loi sur la santé de la reproduction), l'interruption thérapeutique de grossesse (pour sauver la vie de la mère ou dans les cas prévus par la loi après avis médical collégial) est un acte médical réservé exclusivement au MÉDECIN (C) et au MÉDECIN SPÉCIALISTE EN GYNÉCOLOGIE-OBSTÉTRIQUE (D) [en revanche, les soins après avortement / SAA par AMI pour avortement incomplet sont délégués aux sages-femmes]. +-----------------------------------------------------------------------+\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null}]},{\"name\":\"SSR / PF\",\"slug\":\"ssr-pf\",\"pages\":\"\",\"count\":44,\"session\":\"S2\",\"annee\":2025,\"source\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"questions\":[{\"id\":\"bouake-2__ssr-pf__0\",\"num\":\"1\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"I. Questions à Choix Double (QCD : Q1 à Q24)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Fanta qui a raté le renouvellement de son injection de Depo-Provera (DMPA) prévu le 10 septembre pourra le faire le 18 septembre (soit avec 8 jours de retard).\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Vrai\",\"answerLetters\":[\"A\"],\"explanation\":\"Selon les directives actuelles de l'OMS, la fenêtre de réinjection tardive (délai de grâce) du Depo-Provera (DMPA, trimestriel) est de 2 semaines (14 jours, et jusqu'à 4 semaines) après la date prévue sans nécessiter de méthode d'appoint. (NB : Sur le sujet brut de Bouaké figure la mention 'F' si l'auteur du corrigé limitait le retard toléré à 7 jours).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"bouake-2__ssr-pf__1\",\"num\":\"2\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"I. Questions à Choix Double (QCD : Q1 à Q24)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Katérine qui utilise un contraceptif oral combiné de 28 comprimés peut ne pas prendre les comprimés de couleur marron de la plaquette.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"Dans une plaquette de 28 comprimés (Lo-Femenal), les 7 comprimés marron contiennent du fer (fumarate ferreux) et permettent de maintenir l'habitude quotidienne d'un comprimé par jour sans interruption entre deux plaquettes afin d'éviter d'oublier la date de reprise de la nouvelle plaquette.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"bouake-2__ssr-pf__2\",\"num\":\"3\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"I. Questions à Choix Double (QCD : Q1 à Q24)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Lorsque l'implant est inséré dans les 7 premiers jours (ou 5 premiers jours) du cycle menstruel, l'utilisatrice doit utiliser une méthode d'appoint.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"Lorsque l'implant progestatif (Jadelle : dans les 7 premiers jours du cycle ; Implanon NXT : dans les 5 premiers jours) est inséré au début des règles, l'efficacité contraceptive est IMMÉDIATE et aucune méthode d'appoint n'est nécessaire.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"bouake-2__ssr-pf__3\",\"num\":\"4\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"I. Questions à Choix Double (QCD : Q1 à Q24)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Une athlète qui pratique la natation ne peut pas utiliser le patch comme méthode contraceptive.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"Le timbre (patch) transdermique contraceptif est doté d'un adhésif résistant à l'eau : l'utilisatrice peut se doucher, prendre un bain, transpirer ou pratiquer la natation sans que le patch ne perde son efficacité.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"bouake-2__ssr-pf__4\",\"num\":\"5\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"I. Questions à Choix Double (QCD : Q1 à Q24)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Le principe de base sur lequel reposent les méthodes d'auto-observation ne prend en compte que la période de l'ovulation (le seul jour de l'ovulation).\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"La fenêtre de fertilité prend en compte non seulement le jour de l'ovulation et la durée de vie de l'ovule (24 heures après l'ovulation), mais aussi la durée de survie des spermatozoïdes dans la glaire cervicale (jusqu'à 5 jours AVANT l'ovulation).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"bouake-2__ssr-pf__5\",\"num\":\"6\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"I. Questions à Choix Double (QCD : Q1 à Q24)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"À chaque contact avec l'utilisatrice de la méthode du collier (Méthode des Jours Fixes), le prestataire doit vérifier si son cycle menstruel le plus récent a une durée de 26 à 32 jours.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Vrai\",\"answerLetters\":[\"A\"],\"explanation\":\"La Méthode des Jours Fixes (collier du cycle) n'est efficace que chez les femmes dont les cycles durent entre 26 et 32 jours. Si une utilisatrice a plus d'un cycle par an en dehors de cet intervalle (court < 26 j ou long > 32 j), elle doit changer de méthode.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"bouake-2__ssr-pf__6\",\"num\":\"7\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"I. Questions à Choix Double (QCD : Q1 à Q24)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Le dispositif intra-utérin du post-abortum ne convient pas aux nullipares.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"Selon les critères OMS, après un avortement du 1er ou du 2e trimestre non compliqué (non septique), le DIU peut être inséré immédiatement y compris chez une adolescente ou une femme nullipare (Catégorie 1 ou 2 de l'OMS).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"bouake-2__ssr-pf__7\",\"num\":\"8\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"I. Questions à Choix Double (QCD : Q1 à Q24)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Le coût et la sûreté (innocuité) sont des qualités d'une bonne méthode de contraception.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Vrai\",\"answerLetters\":[\"A\"],\"explanation\":\"Les qualités d'une bonne méthode contraceptive comprennent l'efficacité, l'innocuité (sûreté), l'acceptabilité/tolérance, la réversibilité et le coût abordable (accessibilité).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"bouake-2__ssr-pf__8\",\"num\":\"9\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"I. Questions à Choix Double (QCD : Q1 à Q24)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Le moment propice pour le counseling initial (en PFPP) se situe à la phase active du travail.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"Selon les directives OMS/Jhpiego de Planification Familiale du Post-Partum (PFPP), le counseling initial doit être réalisé lors des Consultations Prénatales (CPN) ou en tout début de travail (phase de latence) / après l'accouchement, mais pas pendant la phase active du travail où la parturiente souffre de contractions intenses. (NB : La feuille du sujet porte la lettre 'V' par coquille).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"bouake-2__ssr-pf__9\",\"num\":\"10\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"I. Questions à Choix Double (QCD : Q1 à Q24)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Appliquer les critères médicaux d'éligibilité permet de classer les méthodes contraceptives selon leur mode d'action.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"Les Critères de recevabilité médicale de l'OMS (Catégories 1 à 4) permettent de vérifier l'absence de contre-indication médicale chez une cliente donnée. (Notez que le corrigé indicatif imprimé sur la feuille porte 'V').\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"bouake-2__ssr-pf__10\",\"num\":\"11\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"I. Questions à Choix Double (QCD : Q1 à Q24)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"La contraception du post-partum est l'utilisation des méthodes contraceptives durant les 12 premiers mois qui suivent l'accouchement.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Vrai\",\"answerLetters\":[\"A\"],\"explanation\":\"Par définition (OMS), la Planification Familiale du Post-Partum (PFPP) couvre les 12 premiers mois suivant l'accouchement.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"bouake-2__ssr-pf__11\",\"num\":\"12\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"I. Questions à Choix Double (QCD : Q1 à Q24)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Avant de pratiquer sur une femme une injection de Depo-Provera, le prestataire de service doit s'assurer que la femme ne souffre pas d'une affection hépatique grave (cirrhose décompensée, tumeur hépatique).\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Vrai\",\"answerLetters\":[\"A\"],\"explanation\":\"Les stéroïdes hormonaux étant métabolisés par le foie, une maladie hépatique active sévère (hépatite aiguë sévère, cirrhose décompensée, tumeur hépatique) est une contre-indication (Catégorie 3/4 OMS) aux contraceptifs hormonaux injectables.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"bouake-2__ssr-pf__12\",\"num\":\"13\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"I. Questions à Choix Double (QCD : Q1 à Q24)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Le dispositif intra-utérin au cuivre peut être utilisé comme contraceptif d'urgence.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Vrai\",\"answerLetters\":[\"A\"],\"explanation\":\"Scientifiquement et selon l'OMS, le DIU au cuivre posé dans les 5 jours (120 heures) suivant un rapport sexuel non protégé est une excellente méthode de contraception d'urgence (efficacité > 99 %). (NB : Le texte du sujet porte la mention 'F' si le rédacteur pensait uniquement aux pilules du lendemain).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"bouake-2__ssr-pf__13\",\"num\":\"14\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"I. Questions à Choix Double (QCD : Q1 à Q24)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Les hormones contenues dans l'anneau contraceptif sont absorbées par l'épithélium vaginal.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Vrai\",\"answerLetters\":[\"A\"],\"explanation\":\"L'anneau vaginal contraceptif libère en continu de faibles doses d'œstrogène et de progestatif qui traversent directement la muqueuse (épithélium) vaginale richement vascularisée pour passer dans la circulation générale.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"bouake-2__ssr-pf__14\",\"num\":\"15\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"I. Questions à Choix Double (QCD : Q1 à Q24)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Les contraceptifs hormonaux progestatifs (purs : COP, DMPA, implants) contiennent une faible quantité d'œstrogène.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"Les contraceptifs progestatifs seuls (COP, injectables DMPA/NET-EN, implants) ne contiennent AUCUN œstrogène (0 µg d'œstrogène), ce qui permet leur utilisation pendant l'allaitement et chez les femmes présentant une contre-indication aux œstrogènes.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"bouake-2__ssr-pf__15\",\"num\":\"16\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"I. Questions à Choix Double (QCD : Q1 à Q24)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"La méthode de la température basale du corps agit en empêchant les spermatozoïdes d'atteindre l'ovule (via l'abstinence périodique).\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Vrai\",\"answerLetters\":[\"A\"],\"explanation\":\"Par la pratique de l'abstinence sexuelle durant la phase fertile repérée grâce à la courbe thermique, les spermatozoïdes ne sont pas déposés dans les voies génitales au moment où l'ovule est présent (annoté V sur la copie).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"bouake-2__ssr-pf__16\",\"num\":\"17\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"I. Questions à Choix Double (QCD : Q1 à Q24)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Le stock de roulement est la quantité nécessaire pour couvrir la période entre deux approvisionnements.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Vrai\",\"answerLetters\":[\"A\"],\"explanation\":\"Le stock de roulement est la quantité de produits consommée entre deux réapprovisionnements successifs.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"bouake-2__ssr-pf__17\",\"num\":\"18\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"I. Questions à Choix Double (QCD : Q1 à Q24)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Le counseling se concentre sur les besoins collectifs des clients.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"Le counseling est un entretien interpersonnel centré sur les besoins individuels du client (cf. Abidjan SSR Q32).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"bouake-2__ssr-pf__18\",\"num\":\"19\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"I. Questions à Choix Double (QCD : Q1 à Q24)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"L'efficacité est la mesure dans laquelle une méthode de contraception n'entraîne pas d'effets secondaires défavorables ou dangereux.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"Cette définition est celle de l'INNOCUITÉ (sécurité) et non de l'efficacité.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"bouake-2__ssr-pf__19\",\"num\":\"20\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"I. Questions à Choix Double (QCD : Q1 à Q24)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"La planification familiale évite les grossesses (non désirées) et espace les naissances.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Vrai\",\"answerLetters\":[\"A\"],\"explanation\":\"Prévenir les grossesses non désirées et espacer harmonieusement les naissances sont les objectifs fondamentaux de la planification familiale.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"bouake-2__ssr-pf__20\",\"num\":\"21\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"I. Questions à Choix Double (QCD : Q1 à Q24)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"À l'approche de l'ovulation, la consistance du mucus cervical de la femme est épaisse.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"À l'approche de l'ovulation, la glaire cervicale devient fluide, filante, abondante et transparente ('blanc d'œuf cru') sous l'effet des œstrogènes, et non épaisse.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"bouake-2__ssr-pf__21\",\"num\":\"22\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"I. Questions à Choix Double (QCD : Q1 à Q24)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Pour la méthode du calendrier (Ogino-Knaus), le cycle le plus long moins 11 permet de déterminer le début de la période fertile de la cliente.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"Le début de la période fertile est donné par (Cycle le plus court − 18), tandis que (Cycle le plus long − 11) donne la FIN de la période fertile.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"bouake-2__ssr-pf__22\",\"num\":\"23\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"I. Questions à Choix Double (QCD : Q1 à Q24)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Le temps d'attente (délai de livraison) est l'un des paramètres de fonctionnement du système Max-Min.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Vrai\",\"answerLetters\":[\"A\"],\"explanation\":\"Le délai de livraison (temps d'attente entre la commande et la réception des produits), le stock de sécurité et la période de revue sont les paramètres clés permettant de fixer les seuils Minimum et Maximum.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"bouake-2__ssr-pf__23\",\"num\":\"24\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"I. Questions à Choix Double (QCD : Q1 à Q24)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Le carnet de commande sert à faire l'inventaire du stock.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"L'inventaire physique du stock et le suivi des mouvements se font sur la FICHE DE STOCK (et la fiche d'inventaire), tandis que le carnet/bon de commande sert à passer commande auprès du dépôt répartiteur.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"bouake-2__ssr-pf__24\",\"num\":\"25\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"II. Questions à Choix Multiples (QCM : Q25 à Q28 et Q35 à Q40)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Parmi les propositions suivantes, indiquez le processus normal d'adoption d'un nouveau comportement :\",\"options\":[{\"letter\":\"A\",\"text\":\"Information, approbation, décision, action, promotion\"},{\"letter\":\"B\",\"text\":\"Information, décision, approbation, action, promotion\"},{\"letter\":\"C\",\"text\":\"Approbation, décision, action, information, promotion\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Information, approbation, décision, action, promotion\",\"answerLetters\":[\"A\"],\"explanation\":\"Les 5 étapes séquentielles du changement de comportement sont : Information → Approbation → Décision → Action → Promotion (A).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"bouake-2__ssr-pf__25\",\"num\":\"26\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"II. Questions à Choix Multiples (QCM : Q25 à Q28 et Q35 à Q40)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Parmi les propositions suivantes, indiquez la période d'administration d'Ovrette (pilules progestatives au norgestrel) pendant la contraception d'urgence :\",\"options\":[{\"letter\":\"A\",\"text\":\"Dans les 120 heures après les rapports sexuels\"},{\"letter\":\"B\",\"text\":\"Dans les 72 heures après les rapports sexuels\"},{\"letter\":\"C\",\"text\":\"Dans les 48 heures après les rapports sexuels\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Dans les 72 heures après les rapports sexuels\",\"answerLetters\":[\"B\"],\"explanation\":\"Utilisée en contraception hormonale d'urgence (20 ou 25 comprimés d'Ovrette suivis de 20 ou 25 comprimés 12 heures plus tard pour atteindre la dose de lévonorgestrel), la prise doit débuter dans les 72 heures suivant le rapport sexuel non protégé (B).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"bouake-2__ssr-pf__26\",\"num\":\"27\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"II. Questions à Choix Multiples (QCM : Q25 à Q28 et Q35 à Q40)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Parmi les propositions suivantes, indiquez la question à poser à une mère en vue d'un suivi qualitatif de la méthode d'Allaitement Maternel et d'Aménorrhée (MAMA) :\",\"options\":[{\"letter\":\"A\",\"text\":\"Avez-vous un engorgement mammaire ?\"},{\"letter\":\"B\",\"text\":\"Avez-vous ajouté d'autres aliments ou liquides à l'alimentation de l'enfant ?\"},{\"letter\":\"C\",\"text\":\"Combien d'enfants avez-vous ?\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Avez-vous ajouté d'autres aliments ou liquides à l'alimentation de l'enfant ?\",\"answerLetters\":[\"B\"],\"explanation\":\"Pour vérifier que la condition d'allaitement exclusif est toujours respectée sous MAMA, on demande à la mère si elle a donné de l'eau, d'autres liquides ou des aliments de complément à son bébé (B).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"bouake-2__ssr-pf__27\",\"num\":\"28\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"II. Questions à Choix Multiples (QCM : Q25 à Q28 et Q35 à Q40)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Parmi les propositions suivantes, indiquez la période pendant laquelle les utilisateurs de la méthode des jours fixes (collier du cycle) doivent éviter les rapports sexuels non protégés :\",\"options\":[{\"letter\":\"A\",\"text\":\"Du 8ème au 19ème jour du cycle\"},{\"letter\":\"B\",\"text\":\"Du 8ème au 20ème jour du cycle\"},{\"letter\":\"C\",\"text\":\"Du 9ème au 18ème jour du cycle\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Du 8ème au 19ème jour du cycle\",\"answerLetters\":[\"A\"],\"explanation\":\"Dans la méthode des jours fixes (collier du cycle), la fenêtre fertile (perles blanches) couvre du 8e au 19e jour inclus du cycle menstruel (A). [Note : dans le sujet original page 127, la numérotation passe directement de Q28 à Q35].\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"bouake-2__ssr-pf__28\",\"num\":\"35\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"II. Questions à Choix Multiples (QCM : Q25 à Q28 et Q35 à Q40)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Parmi les propositions suivantes, indiquez l'action des spermicides :\",\"options\":[{\"letter\":\"A\",\"text\":\"Empêcher la rencontre entre le gamète mâle et femelle\"},{\"letter\":\"B\",\"text\":\"Modifier la glaire cervicale\"},{\"letter\":\"C\",\"text\":\"Inactiver (et détruire) les spermatozoïdes\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"C. Inactiver (et détruire) les spermatozoïdes\",\"answerLetters\":[\"C\"],\"explanation\":\"Les spermicides agissent chimiquement en détruisant la membrane cellulaire des spermatozoïdes pour les inactiver dans le vagin avant qu'ils ne pénètrent dans le canal cervical (C).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"bouake-2__ssr-pf__29\",\"num\":\"36\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"II. Questions à Choix Multiples (QCM : Q25 à Q28 et Q35 à Q40)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Parmi les propositions suivantes, indiquez le moment auquel l'utilisateur du préservatif masculin doit retirer le pénis du vagin :\",\"options\":[{\"letter\":\"A\",\"text\":\"Pendant l'éjaculation\"},{\"letter\":\"B\",\"text\":\"Avant que l'érection ne cesse (immédiatement après l'éjaculation, verge encore en érection)\"},{\"letter\":\"C\",\"text\":\"Après la chute totale de l'érection\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Avant que l'érection ne cesse (immédiatement après l'éjaculation, verge encore en érection)\",\"answerLetters\":[\"B\"],\"explanation\":\"Après l'éjaculation, l'homme doit retirer le pénis du vagin AVANT la disparition de l'érection (verge encore semi-rigide : B) tout en maintenant l'anneau du préservatif à la base de la verge afin d'éviter que le condom ne glisse dans le vagin et que le sperme ne s'écoule.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"bouake-2__ssr-pf__30\",\"num\":\"37\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"II. Questions à Choix Multiples (QCM : Q25 à Q28 et Q35 à Q40)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Parmi les propositions suivantes, indiquez le moment auquel doit se faire le deuxième contrôle d'un implant inséré :\",\"options\":[{\"letter\":\"A\",\"text\":\"3 mois après l'insertion\"},{\"letter\":\"B\",\"text\":\"3 semaines après l'insertion\"},{\"letter\":\"C\",\"text\":\"03 jours après l'insertion\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. 3 mois après l'insertion\",\"answerLetters\":[\"A\"],\"explanation\":\"Le 1er contrôle de la plaie d'insertion a lieu à J7 (1 semaine), et le 2e contrôle de suivi sous implant se fait à 3 mois après l'insertion (A).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"bouake-2__ssr-pf__31\",\"num\":\"38\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"II. Questions à Choix Multiples (QCM : Q25 à Q28 et Q35 à Q40)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Parmi les propositions suivantes, indiquez la cliente qui peut recevoir le dispositif intra-utérin (en ayant la certitude raisonnable qu'elle n'est pas enceinte ou en contraception d'urgence) :\",\"options\":[{\"letter\":\"A\",\"text\":\"Élodie qui est au 28ème jour du cycle menstruel\"},{\"letter\":\"B\",\"text\":\"Sandra qui est à la veille des menstrues\"},{\"letter\":\"C\",\"text\":\"Chantal qui est au 18ème jour du cycle menstruel (ou pendant les règles / dans les 12 premiers jours du cycle)\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Élodie qui est au 28ème jour du cycle menstruel\",\"answerLetters\":[\"A\"],\"explanation\":\"En insertion d'intervalle classique, le DIU au cuivre se pose préférentiellement pendant les règles (J1 à J7/J12). En dehors de cette période (à tout moment du cycle : A, B, C), il peut être posé dès lors qu'on est raisonnablement certain que la cliente n'est pas enceinte (ou dans les 5 jours suivant un rapport non protégé vers J14–J18 en C).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"bouake-2__ssr-pf__32\",\"num\":\"39\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"II. Questions à Choix Multiples (QCM : Q25 à Q28 et Q35 à Q40)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Pour une femme qui a reçu le 12 septembre, jour de son accouchement, un dispositif intra-utérin (DIUPP), indiquez à partir de quel moment celle-ci pourra se rendre au centre de santé pour faire vérifier la descente des fils (et couper l'excédent) :\",\"options\":[{\"letter\":\"A\",\"text\":\"Quatorze semaines après l'insertion\"},{\"letter\":\"B\",\"text\":\"Six semaines après l'insertion (entre 4 et 6 semaines post-partum)\"},{\"letter\":\"C\",\"text\":\"Douze semaines après l'insertion\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Six semaines après l'insertion (entre 4 et 6 semaines post-partum)\",\"answerLetters\":[\"B\"],\"explanation\":\"Après la pose d'un DIU du post-partum (DIUPP), la visite de contrôle systématique pour vérifier le bon positionnement du DIU et raccourcir les fils extériorisés par le col involué a lieu à 4 à 6 semaines du post-partum (B : Six semaines après l'insertion, lors de la CPON de la 6e semaine).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"bouake-2__ssr-pf__33\",\"num\":\"40\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"II. Questions à Choix Multiples (QCM : Q25 à Q28 et Q35 à Q40)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Parmi les contraceptifs suivants, indiquez celui que le prestataire doit formellement proscrire après un avortement septique :\",\"options\":[{\"letter\":\"A\",\"text\":\"Ovrette\"},{\"letter\":\"B\",\"text\":\"DIU\"},{\"letter\":\"C\",\"text\":\"Jadelle\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. DIU\",\"answerLetters\":[\"B\"],\"explanation\":\"Après un avortement SEPTIQUE (infecté), l'insertion immédiate d'un Dispositif Intra-Utérin (DIU : B) est une contre-indication absolue (Catégorie 4 de l'OMS) en raison du risque majeur d'aggravation de l'endométrite et de pelvipéritonite.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"bouake-2__ssr-pf__34\",\"num\":\"41\",\"type\":\"CAS_CLINIQUE\",\"typeLabel\":\"Étude de cas / Cas clinique\",\"partieTitle\":\"II. Questions à Choix Multiples (QCM : Q25 à Q28 et Q35 à Q40)\",\"caseTitle\":\"Étude de cas N°1 — Mme Yéo (Q41 à Q45)\",\"caseData\":null,\"text\":\"Madame Yéo peut-elle contracter une grossesse en cas de rapports sexuels le 24/10/2025 (pendant la semaine des comprimés marron) ?\",\"options\":[{\"letter\":\"A\",\"text\":\"Oui\"},{\"letter\":\"B\",\"text\":\"Non\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Non\",\"answerLetters\":[\"B\"],\"explanation\":\"Non ! Comme Mme Yéo avait déjà fini ses 21 comprimés hormonaux actifs et entamé les 7 comprimés marron (qui ne contiennent pas d'hormone mais uniquement du fer), l'oubli de comprimés marron n'expose à AUCUN risque de grossesse pendant cette semaine d'intervalle de 7 jours (B).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"bouake-2__ssr-pf__35\",\"num\":\"42\",\"type\":\"CAS_CLINIQUE\",\"typeLabel\":\"Étude de cas / Cas clinique\",\"partieTitle\":\"II. Questions à Choix Multiples (QCM : Q25 à Q28 et Q35 à Q40)\",\"caseTitle\":\"Étude de cas N°1 — Mme Yéo (Q41 à Q45)\",\"caseData\":null,\"text\":\"Parmi les propositions suivantes, indiquez ce que vous conseillerez à Madame Yéo pour l'oubli des comprimés marron dans l'immédiat (avant de débuter sa nouvelle plaquette à la date prévue) :\",\"options\":[{\"letter\":\"A\",\"text\":\"Prendre une pilule du lendemain\"},{\"letter\":\"B\",\"text\":\"Utiliser une méthode de barrière mécanique\"},{\"letter\":\"C\",\"text\":\"Pas de dispositions particulières (pour les comprimés marron oubliés, et lui remettre une nouvelle plaquette à débuter au 8e jour après le dernier comprimé actif)\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"C. Pas de dispositions particulières (pour les comprimés marron oubliés, et lui remettre une nouvelle plaquette à débuter au 8e jour après le dernier comprimé actif)\",\"answerLetters\":[\"C\"],\"explanation\":\"Selon les directives de l'OMS sur la conduite à tenir en cas d'oubli des comprimés non hormonaux (comprimés marron de la 4e semaine), aucune contraception d'urgence ni méthode d'appoint n'est nécessaire (C : pas de dispositions particulières) tant que la nouvelle plaquette de comprimés actifs est débutée à temps au bout des 7 jours.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"bouake-2__ssr-pf__36\",\"num\":\"43\",\"type\":\"CAS_CLINIQUE\",\"typeLabel\":\"Étude de cas / Cas clinique\",\"partieTitle\":\"II. Questions à Choix Multiples (QCM : Q25 à Q28 et Q35 à Q40)\",\"caseTitle\":\"Étude de cas N°1 — Mme Yéo (Q41 à Q45)\",\"caseData\":null,\"text\":\"Parmi les propositions suivantes, indiquez le mode d'action des pilules (COC) de Madame Yéo :\",\"options\":[{\"letter\":\"A\",\"text\":\"Bloquer l'ovulation, tuer les spermatozoïdes, rendre l'endomètre impropre à la nidation\"},{\"letter\":\"B\",\"text\":\"Bloquer l'ovulation, épaissir la glaire cervicale, rendre l'endomètre impropre à la nidation\"},{\"letter\":\"C\",\"text\":\"Bloquer partiellement l'ovulation, tuer les spermatozoïdes, rendre l'endomètre impropre à la nidation\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Bloquer l'ovulation, épaissir la glaire cervicale, rendre l'endomètre impropre à la nidation\",\"answerLetters\":[\"B\"],\"explanation\":\"Les COC n'ont pas d'effet spermicide ('tuer les spermatozoïdes' est faux) : ils agissent par blocage de l'ovulation, épaississement de la glaire cervicale et atrophie de l'endomètre le rendant impropre à la nidation (B).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"bouake-2__ssr-pf__37\",\"num\":\"44\",\"type\":\"CAS_CLINIQUE\",\"typeLabel\":\"Étude de cas / Cas clinique\",\"partieTitle\":\"II. Questions à Choix Multiples (QCM : Q25 à Q28 et Q35 à Q40)\",\"caseTitle\":\"Étude de cas N°1 — Mme Yéo (Q41 à Q45)\",\"caseData\":null,\"text\":\"À quel moment Madame Yéo doit-elle débuter une nouvelle plaquette de pilules ?\",\"options\":[{\"letter\":\"A\",\"text\":\"Le lendemain de la prise (ou de la date prévue) du dernier comprimé marron\"},{\"letter\":\"B\",\"text\":\"À la fin des menstrues\"},{\"letter\":\"C\",\"text\":\"Dès la survenue des menstrues\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Le lendemain de la prise (ou de la date prévue) du dernier comprimé marron\",\"answerLetters\":[\"A\"],\"explanation\":\"Une nouvelle plaquette de 28 comprimés se débute toujours le lendemain du 7e et dernier comprimé marron (sans aucun jour d'arrêt entre deux plaquettes et sans attendre la fin des saignements : A).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"bouake-2__ssr-pf__38\",\"num\":\"45\",\"type\":\"CAS_CLINIQUE\",\"typeLabel\":\"Étude de cas / Cas clinique\",\"partieTitle\":\"II. Questions à Choix Multiples (QCM : Q25 à Q28 et Q35 à Q40)\",\"caseTitle\":\"Étude de cas N°1 — Mme Yéo (Q41 à Q45)\",\"caseData\":null,\"text\":\"En plus du contraceptif oral combiné, quelle méthode Madame Yéo peut-elle utiliser pour éviter de contracter une infection sexuellement transmissible (double protection) ?\",\"options\":[{\"letter\":\"A\",\"text\":\"L'implant\"},{\"letter\":\"B\",\"text\":\"Le Fémidon (préservatif féminin)\"},{\"letter\":\"C\",\"text\":\"Le Dispositif intra-utérin\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Le Fémidon (préservatif féminin)\",\"answerLetters\":[\"B\"],\"explanation\":\"Le Fémidon (préservatif féminin en nitrile/polyuréthane : B) est une méthode de barrière qui protège contre les IST et le VIH en complément de la pilule (double protection).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"bouake-2__ssr-pf__39\",\"num\":\"46\",\"type\":\"CAS_CLINIQUE\",\"typeLabel\":\"Étude de cas / Cas clinique\",\"partieTitle\":\"II. Questions à Choix Multiples (QCM : Q25 à Q28 et Q35 à Q40)\",\"caseTitle\":\"Étude de cas N°2 — Mlle Cindy (Q46 à Q50)\",\"caseData\":null,\"text\":\"Précisez la catégorie OMS qui s'applique aux contraceptifs hormonaux combinés (CHC) concernant le cas de Mademoiselle Cindy (allaitante à 6 semaines du post-partum) :\",\"options\":[{\"letter\":\"A\",\"text\":\"Catégorie 1\"},{\"letter\":\"B\",\"text\":\"Catégorie 2\"},{\"letter\":\"C\",\"text\":\"Catégorie 3\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"C. Catégorie 3\",\"answerLetters\":[\"C\"],\"explanation\":\"Entre 6 semaines et 6 mois du post-partum chez une femme qui allaite, les contraceptifs hormonaux combinés (CHC) appartiennent à la Catégorie 3 de l'OMS (non recommandés car l'œstrogène diminue la sécrétion lactée : C).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"bouake-2__ssr-pf__40\",\"num\":\"47\",\"type\":\"CAS_CLINIQUE\",\"typeLabel\":\"Étude de cas / Cas clinique\",\"partieTitle\":\"II. Questions à Choix Multiples (QCM : Q25 à Q28 et Q35 à Q40)\",\"caseTitle\":\"Étude de cas N°2 — Mlle Cindy (Q46 à Q50)\",\"caseData\":null,\"text\":\"Parmi les méthodes contraceptives suivantes, indiquez celle qui est appropriée pour Mademoiselle Cindy :\",\"options\":[{\"letter\":\"A\",\"text\":\"Contraceptifs oraux combinés\"},{\"letter\":\"B\",\"text\":\"Contraceptifs oraux progestatifs\"},{\"letter\":\"C\",\"text\":\"Patch contraceptif\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Contraceptifs oraux progestatifs\",\"answerLetters\":[\"B\"],\"explanation\":\"Les contraceptifs oraux progestatifs seuls (COP : B) sont de Catégorie 1 de l'OMS à 6 semaines post-partum et n'ont aucun effet délétère sur la sécrétion lactée ni sur la croissance du nourrisson.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"bouake-2__ssr-pf__41\",\"num\":\"48\",\"type\":\"CAS_CLINIQUE\",\"typeLabel\":\"Étude de cas / Cas clinique\",\"partieTitle\":\"II. Questions à Choix Multiples (QCM : Q25 à Q28 et Q35 à Q40)\",\"caseTitle\":\"Étude de cas N°2 — Mlle Cindy (Q46 à Q50)\",\"caseData\":null,\"text\":\"Parmi les propositions suivantes, laquelle est correcte concernant le retour de la fécondité chez une femme allaitante comme Mademoiselle Cindy ?\",\"options\":[{\"letter\":\"A\",\"text\":\"La probabilité d'ovuler dans les 6 premiers mois est élevée\"},{\"letter\":\"B\",\"text\":\"La période d'infécondité est plus courte que chez les femmes non allaitantes\"},{\"letter\":\"C\",\"text\":\"La probabilité d'avoir les règles et d'ovuler les 6 premiers mois est faible\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"C. La probabilité d'avoir les règles et d'ovuler les 6 premiers mois est faible\",\"answerLetters\":[\"C\"],\"explanation\":\"Grâce à l'allaitement maternel exclusif et fréquent qui maintient un taux élevé de prolactine, la probabilité d'ovuler et d'avoir son retour de couches au cours des 6 premiers mois est très faible (< 2 % : C).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"bouake-2__ssr-pf__42\",\"num\":\"49\",\"type\":\"CAS_CLINIQUE\",\"typeLabel\":\"Étude de cas / Cas clinique\",\"partieTitle\":\"II. Questions à Choix Multiples (QCM : Q25 à Q28 et Q35 à Q40)\",\"caseTitle\":\"Étude de cas N°2 — Mlle Cindy (Q46 à Q50)\",\"caseData\":null,\"text\":\"Parmi les propositions suivantes, indiquez celle que doit remplir Mademoiselle Cindy au cas où celle-ci doit utiliser la méthode d'Allaitement Maternel et d'Aménorrhée (MAMA) :\",\"options\":[{\"letter\":\"A\",\"text\":\"Allaitement exclusif, aménorrhée et bébé de moins de 6 mois\"},{\"letter\":\"B\",\"text\":\"Allaitement partiel, retour de couches, et bébé de moins de 12 mois\"},{\"letter\":\"C\",\"text\":\"Allaitement exclusif uniquement\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Allaitement exclusif, aménorrhée et bébé de moins de 6 mois\",\"answerLetters\":[\"A\"],\"explanation\":\"Les trois conditions cumulatives obligatoires de la MAMA sont : allaitement exclusif à la demande jour et nuit, aménorrhée persistante et nourrisson âgé de moins de 6 mois (A).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"bouake-2__ssr-pf__43\",\"num\":\"50\",\"type\":\"CAS_CLINIQUE\",\"typeLabel\":\"Étude de cas / Cas clinique\",\"partieTitle\":\"II. Questions à Choix Multiples (QCM : Q25 à Q28 et Q35 à Q40)\",\"caseTitle\":\"Étude de cas N°2 — Mlle Cindy (Q46 à Q50)\",\"caseData\":null,\"text\":\"Précisez selon les normes de l'OMS, l'intervalle minimum recommandé entre une naissance vivante et le début d'une prochaine grossesse :\",\"options\":[{\"letter\":\"A\",\"text\":\"12 mois\"},{\"letter\":\"B\",\"text\":\"18 mois\"},{\"letter\":\"C\",\"text\":\"24 mois\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"C. 24 mois\",\"answerLetters\":[\"C\"],\"explanation\":\"L'OMS recommande d'espacer une naissance vivante et le début de la grossesse suivante d'au moins 24 mois (2 ans : C). +-----------------------------------------------------------------------+ Épreuves : Santé Publique (Q1-Q56) | Pédiatrie (Q1-Q52) | Gynécologie-Obstétrique (Q1-Q89) | SR/PF Version B (Q1-Q60) +=======================================================================+ +-----------------------------------------------------------------------+ +-----------------------------------------------------------------------+\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null}]}]},{\"name\":\"DALOA (S2 : 2025)\",\"slug\":\"daloa-2\",\"session\":\"S2\",\"annee\":2025,\"existe\":true,\"sujets\":[{\"name\":\"Gynéco-obstétrique\",\"slug\":\"gynecologie-obstetrique\",\"pages\":\"\",\"count\":87,\"session\":\"S2\",\"annee\":2025,\"source\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"questions\":[{\"id\":\"daloa-2__gynecologie-obstetrique__0\",\"num\":\"1\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"I. Questions à Choix Double (QCD : Q1 à Q40)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Le paludisme est une cause directe de mortalité maternelle.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"Le paludisme (tout comme l'anémie, le VIH/SIDA ou les cardiopathies préexistantes aggravées par la grossesse) est une cause obstétricale indirecte de mortalité maternelle. Les causes directes résultent de complications obstétricales de la grossesse, du travail ou du post-partum (hémorragies, pré-éclampsie/éclampsie, infections puerpérales, avortements, dystocies).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"daloa-2__gynecologie-obstetrique__1\",\"num\":\"2\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"I. Questions à Choix Double (QCD : Q1 à Q40)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Dans l'accouchement de siège, en cas de rétention de la tête dernière, l'attitude de Vermelin est préconisée.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"La méthode de Vermelin est l'abstention totale de toute manœuvre lors d'un accouchement du siège eutocique. En cas de rétention de la tête dernière, l'abstention est formellement proscrite : il faut pratiquer d'urgence la manœuvre de Bracht (si la tête est dans l'excavation/partie basse) ou la manœuvre de Mauriceau (ou de Lovset + Mauriceau).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"daloa-2__gynecologie-obstetrique__2\",\"num\":\"3\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"I. Questions à Choix Double (QCD : Q1 à Q40)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Un liquide amniotique méconial pendant le travail d'accouchement traduit toujours une souffrance fœtale aiguë.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"Un liquide amniotique méconial ne traduit pas toujours une souffrance fœtale aiguë : il est physiologique dans la présentation du siège (par compression abdominale) et fréquent à terme dépassé par simple maturation du péristaltisme intestinal fœtal sans hypoxie.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"daloa-2__gynecologie-obstetrique__3\",\"num\":\"4\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"I. Questions à Choix Double (QCD : Q1 à Q40)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"La patiente VIH+ sous Cotrimoxazole peut recevoir le TPI dans le même temps.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"L'association de la Sulfadoxine-Pyriméthamine (TPI-SP) et du Cotrimoxazole (Sulfaméthoxazole-Triméthoprime) est formellement contre-indiquée en raison de la redondance d'action antifolique et de la toxicité cumulée des sulfamides (syndrome de Lyell/Stevens-Johnson, cytopénies graves).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"daloa-2__gynecologie-obstetrique__4\",\"num\":\"5\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"I. Questions à Choix Double (QCD : Q1 à Q40)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"L'AMIU est plus efficace que la méthode médicamenteuse dans la prise en charge des avortements avant 12 semaines.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"Selon les recommandations de l'OMS sur les Soins Après Avortement (SAA), l'évacuation utérine médicamenteuse (Misoprostol) et l'Aspiration Manuelle Intra-Utérine (AMIU) sont deux méthodes recommandées de haute efficacité comparable (> 95 %) pour les avortements incomplets du 1er trimestre (< 12 SA).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"daloa-2__gynecologie-obstetrique__5\",\"num\":\"6\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"I. Questions à Choix Double (QCD : Q1 à Q40)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Il est important de séparer la mère infectée par le COVID-19 du nouveau-né pour éviter sa contamination.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"L'OMS recommande de ne pas séparer la mère atteinte de COVID-19 de son nouveau-né : la cohabitation (rooming-in), le contact peau-à-peau et l'allaitement maternel doivent être encouragés en appliquant les mesures barrières d'hygiène (port du masque médical par la mère et lavage des mains).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"daloa-2__gynecologie-obstetrique__6\",\"num\":\"7\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"I. Questions à Choix Double (QCD : Q1 à Q40)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Le counseling sur une méthode de planification familiale est systématique dans les soins après avortement.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Vrai\",\"answerLetters\":[\"A\"],\"explanation\":\"La Planification Familiale post-abortum est l'une des 5 composantes fondamentales des Soins Après Avortement (SAA), car l'ovulation peut reprendre dès le 10e–14e jour suivant un avortement du 1er trimestre.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"daloa-2__gynecologie-obstetrique__7\",\"num\":\"8\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"I. Questions à Choix Double (QCD : Q1 à Q40)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"En cas d'HRP en début de travail, la césarienne est le plus souvent réalisée.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Vrai\",\"answerLetters\":[\"A\"],\"explanation\":\"L'Hématome Rétro-Placentaire (HRP) est une urgence obstétricale majeure mettant en jeu le pronostic vital maternel (choc, CIVD) et fœtal. En début de travail (surtout si l'enfant est vivant ou si l'accouchement par voie basse n'est pas imminent), la césarienne d'urgence permet l'évacuation utérine rapide.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"daloa-2__gynecologie-obstetrique__8\",\"num\":\"9\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"I. Questions à Choix Double (QCD : Q1 à Q40)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"La rubéole au cours de la grossesse est le plus souvent responsable d'embryopathies.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Vrai\",\"answerLetters\":[\"A\"],\"explanation\":\"Contractée au premier trimestre de la grossesse (période d'organogenèse), la primo-infection rubéoleuse traverse le placenta et provoque le syndrome de rubéole congénitale (embryopathie grave : triade de Gregg associant cardiopathie, cataracte et surdité neurosensorielle).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"daloa-2__gynecologie-obstetrique__9\",\"num\":\"10\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"I. Questions à Choix Double (QCD : Q1 à Q40)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"L'HTA gravidique est une complication de la grossesse apparaissant dès la 13ème semaine de celle-ci et disparaissant après l'accouchement.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"Sur le plan médical strict, l'HTA gravidique apparaît après 20 SA (≥ 20 SA) chez une femme jusque-là normotendue et disparaît dans les 6 à 12 semaines du post-partum ; une HTA découverte avant 20 SA (donc à 13 SA) est une HTA chronique préexistante. (NB : Le texte original de l'épreuve porte la lettre indicative 'V' si l'auteur n'a retenu que la disparition après l'accouchement).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"daloa-2__gynecologie-obstetrique__10\",\"num\":\"11\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"I. Questions à Choix Double (QCD : Q1 à Q40)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"L'administration de sulfate de magnésium est indiquée en première intention dans le traitement de l'éclampsie conformément aux recommandations nationales.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Vrai\",\"answerLetters\":[\"A\"],\"explanation\":\"Le sulfate de magnésium (MgSO4, protocole de Pritchard ou de Zuspan) est l'anticonvulsivant de référence en première intention pour la prévention et le traitement des crises d'éclampsie (SONU / OMS).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"daloa-2__gynecologie-obstetrique__11\",\"num\":\"12\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"I. Questions à Choix Double (QCD : Q1 à Q40)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Devant une MAP sur une grossesse à 32 SA, la maturation pulmonaire est indispensable.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Vrai\",\"answerLetters\":[\"A\"],\"explanation\":\"Devant toute Menace d'Accouchement Prématuré (MAP) entre 24 et 34 SA (ici 32 SA), la corticothérapie anténatale (Bétaméthasone ou Dexaméthasone : 12 mg IM à 24h d'intervalle × 2 doses, ou 6 mg/12h × 4 doses) est indispensable pour stimuler la synthèse de surfactant et prévenir la maladie des membranes hyalines.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"daloa-2__gynecologie-obstetrique__12\",\"num\":\"13\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"I. Questions à Choix Double (QCD : Q1 à Q40)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"L'épisiotomie est une intervention non systématique chez la primipare.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Vrai\",\"answerLetters\":[\"A\"],\"explanation\":\"Selon les recommandations de l'OMS et du CNGOF, l'épisiotomie ne doit plus être systématique, même chez la primipare (usage restrictif uniquement sur indication obstétricale ou périnéale). L'affirmation « l'épisiotomie est une intervention non systématique » est donc médicalement VRAIE (A), bien que l'annotation indicative 'F' sur le sujet provienne d'une confusion de lecture avec « est systématique ».\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"daloa-2__gynecologie-obstetrique__13\",\"num\":\"14\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"I. Questions à Choix Double (QCD : Q1 à Q40)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Le sexe génétique de l'embryon est déterminé dès la nidation.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"Le sexe génétique (chromosomique : XX ou XY) du zygote est déterminé dès la fécondation (dans le tiers externe de la trompe, selon que le spermatozoïde fécondant porte un chromosome X ou Y), et non au moment de la nidation (6 à 7 jours plus tard).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"daloa-2__gynecologie-obstetrique__14\",\"num\":\"15\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"I. Questions à Choix Double (QCD : Q1 à Q40)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"La CPN permet d'améliorer les indicateurs de santé maternelle et infantile.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Vrai\",\"answerLetters\":[\"A\"],\"explanation\":\"Les Consultations Prénatales recentrées permettent de dépister et prendre en charge précocement les grossesses à risque et les pathologies intercurrentes, réduisant ainsi la morbi-mortalité maternelle et périnatale.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"daloa-2__gynecologie-obstetrique__15\",\"num\":\"16\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"I. Questions à Choix Double (QCD : Q1 à Q40)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Le post-partum correspond à la période qui s'étend de l'accouchement jusqu'aux premières règles.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"En obstétrique moderne (OMS), le post-partum (suites de couches) est défini par une durée fixe de 6 semaines (42 jours) après l'accouchement, période nécessaire à l'involution utérine complète. Chez la femme allaitante, les premières règles (retour de couches) peuvent survenir plusieurs mois plus tard ; c'est pourquoi le corrigé indicatif de l'épreuve retient B = Faux.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"daloa-2__gynecologie-obstetrique__16\",\"num\":\"17\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"I. Questions à Choix Double (QCD : Q1 à Q40)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"La grossesse est dite prolongée lorsqu'elle excède 42 SA.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Vrai\",\"answerLetters\":[\"A\"],\"explanation\":\"Selon la définition internationale de l'OMS et de la FIGO, le dépassement de terme vrai (grossesse prolongée / post-terme) est défini par un âge gestationnel ≥ 42 SA révolues (≥ 294 jours) (la phase entre 41 SA et 41 SA + 6 j étant parfois appelée grossesse en voie de prolongation).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"daloa-2__gynecologie-obstetrique__17\",\"num\":\"18\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"I. Questions à Choix Double (QCD : Q1 à Q40)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Les fibromes utérins apparaissent toujours après la puberté.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Vrai\",\"answerLetters\":[\"A\"],\"explanation\":\"Les fibromes (myomes) utérins sont des tumeurs bénignes strictement œstrogéno-dépendantes : ils n'existent jamais avant la puberté, apparaissent durant la période d'activité génitale et régressent après la ménopause. (NB : Le corrigé indicatif du sujet porte 'F' si l'auteur a considéré que le mot « toujours » excluait l'apparition en périménopause).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"daloa-2__gynecologie-obstetrique__18\",\"num\":\"19\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"I. Questions à Choix Double (QCD : Q1 à Q40)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Le cancer du col de l'utérus est une infection non sexuellement transmissible.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"Le cancer du col de l'utérus est une tumeur maligne induite dans plus de 99 % des cas par une infection persistante à Papillomavirus Humain oncogène (HPV 16 et 18 principalement), qui est une Infection Sexuellement Transmissible (IST).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"daloa-2__gynecologie-obstetrique__19\",\"num\":\"20\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"I. Questions à Choix Double (QCD : Q1 à Q40)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Un cycle menstruel est considéré comme long si la durée est de 36 jours.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"En sémiologie gynécologique classique, un cycle menstruel normal dure de 21 à 35 jours (moyenne 28 j, cycle long entre 31 et 35 jours). Au-delà de 35 jours (donc à 36 jours et plus), il ne s'agit plus d'un simple cycle long physiologique mais d'une spanioménorrhée.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"daloa-2__gynecologie-obstetrique__20\",\"num\":\"21\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"I. Questions à Choix Double (QCD : Q1 à Q40)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"L'anesthésie péridurale ne peut pas supprimer la douleur des contractions utérines.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"L'analgésie péridurale obstétricale bloque la transmission sensitive douloureuse des racines rachidiennes (T10–L1 puis S2–S4) et supprime efficacement la douleur des contractions utérines tout en conservant la conscience maternelle.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"daloa-2__gynecologie-obstetrique__21\",\"num\":\"22\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"I. Questions à Choix Double (QCD : Q1 à Q40)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Dans la présentation de la face, le repère est la pyramide nasale.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"Le repère de la présentation de la face (présentation céphalique totalement défléchie) est le menton, et non la pyramide nasale (qui est le repère de la présentation du front).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"daloa-2__gynecologie-obstetrique__22\",\"num\":\"23\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"I. Questions à Choix Double (QCD : Q1 à Q40)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"La décision de procéder à un déclenchement artificiel du travail dépend uniquement du choix du médecin.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"Le déclenchement artificiel du travail ne dépend pas d'un choix arbitraire : il repose sur une indication médicale ou obstétricale précise, l'évaluation des conditions cervicales (score de Bishop), l'absence de contre-indication obstétricale et le consentement éclairé de la parturiente.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"daloa-2__gynecologie-obstetrique__23\",\"num\":\"24\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"I. Questions à Choix Double (QCD : Q1 à Q40)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Après la césarienne, la Sage-Femme doit établir une surveillance rapprochée toutes les 15 min durant les deux premières heures.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Vrai\",\"answerLetters\":[\"A\"],\"explanation\":\"Comme après tout accouchement et toute intervention chirurgicale obstétricale, la surveillance post-opératoire immédiate durant les 2 premières heures s'effectue toutes les 15 minutes (constantes hémodynamiques, globe de sécurité utérin, saignement vulvaire, pansement, diurèse).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"daloa-2__gynecologie-obstetrique__24\",\"num\":\"25\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"I. Questions à Choix Double (QCD : Q1 à Q40)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"La mortalité maternelle est définie par le décès d'une femme survenu au cours de la grossesse ou dans un délai de 32 jours après sa terminaison.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"Selon la définition officielle de l'OMS (CIM-10), la mort maternelle est le décès d'une femme survenu au cours de la grossesse ou dans un délai de 42 jours (6 semaines, et non 32 jours) après sa terminaison.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"daloa-2__gynecologie-obstetrique__25\",\"num\":\"26\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"I. Questions à Choix Double (QCD : Q1 à Q40)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"En périphérie, la sage-femme ou le maïeuticien peut effectuer un déclenchement artificiel du travail d'accouchement seulement en cas de rétention de mort in utero.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"Dans un centre de santé périphérique (ESPC / SONUB sans bloc chirurgical), le déclenchement artificiel du travail (ainsi que la prise en charge d'une MFIU qui comporte un risque majeur de trouble de la coagulation et d'hémorragie) est proscrit : la patiente doit être référée vers un centre SONUC disposant d'un plateau chirurgical et transfusionnel.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"daloa-2__gynecologie-obstetrique__26\",\"num\":\"27\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"I. Questions à Choix Double (QCD : Q1 à Q40)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"L'hémoglobinopathie SC est une forme majeure de la drépanocytose.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Vrai\",\"answerLetters\":[\"A\"],\"explanation\":\"Les syndromes drépanocytaires majeurs (SDM) regroupent les formes homozygotes SS, les hétérozygotes composites SC et les formes S/β-thalassémie, qui exposent toutes à des complications vaso-occlusives et obstétricales graves au cours de la grossesse.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"daloa-2__gynecologie-obstetrique__27\",\"num\":\"28\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"I. Questions à Choix Double (QCD : Q1 à Q40)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Dans les grossesses gémellaires monochoriales monoamniotiques, les fœtus sont toujours de même sexe.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Vrai\",\"answerLetters\":[\"A\"],\"explanation\":\"Une grossesse monochoriale monoamniotique provient toujours de la division tardive (entre J8 et J12 post-fécondation) d'un seul œuf fécondé (grossesse monozygote / uniovulaire). Les deux fœtus ont donc un patrimoine génétique identique et sont obligatoirement de même sexe.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"daloa-2__gynecologie-obstetrique__28\",\"num\":\"29\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"I. Questions à Choix Double (QCD : Q1 à Q40)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"La sérologie VIH fait partie des examens prénataux obligatoires.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Vrai\",\"answerLetters\":[\"A\"],\"explanation\":\"Dans le programme national de PTME en Côte d'Ivoire, le dépistage du VIH est systématiquement intégré au Bilan Prénatal (BPN) dès la CPN1 selon l'approche « opt-out » (conseil et dépistage à l'initiative du prestataire). (NB : Le corrigé indicatif de l'épreuve retient V = A).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"daloa-2__gynecologie-obstetrique__29\",\"num\":\"30\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"I. Questions à Choix Double (QCD : Q1 à Q40)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"L'avortement précoce est l'expulsion du produit de conception avant 28 SA.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"En Côte d'Ivoire, l'avortement (toutes formes confondues) est défini comme l'expulsion du produit de conception avant 28 SA (seuil de viabilité retenu dans les normes nationales, d'où l'indication 'V' sur le sujet). Toutefois, en sémiologie obstétricale stricte, on distingue l'avortement précoce (1er trimestre, < 12 ou 14 SA) et l'avortement tardif (2e trimestre, de 14 à 22/28 SA).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"daloa-2__gynecologie-obstetrique__30\",\"num\":\"31\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"I. Questions à Choix Double (QCD : Q1 à Q40)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"L'épreuve du travail est une tentative d'accouchement par voie basse sur un utérus cicatriciel.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"L'épreuve du travail (proprement dite) est un test dynamique de confrontation céphalo-pelvienne en cas de rétrécissement pelvien modéré (bassin limite) sur utérus sain. Sur un utérus cicatriciel, la tentative d'accouchement par voie basse est appelée « épreuve utérine » (ou tentative de voie basse après césarienne — TVBAC).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"daloa-2__gynecologie-obstetrique__31\",\"num\":\"32\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"I. Questions à Choix Double (QCD : Q1 à Q40)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"La grossesse molaire est associée à des taux très bas de β-HCG.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"La môle hydatiforme est une prolifération kystique du trophoblaste qui sécrète de façon anarchique et massive l'hormone chorionique gonadotrope : elle s'accompagne donc de taux plasmatiques très élevés de β-HCG (> 100 000 UI/L).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"daloa-2__gynecologie-obstetrique__32\",\"num\":\"33\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"I. Questions à Choix Double (QCD : Q1 à Q40)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"La surveillance post-évacuation d'une grossesse molaire repose exclusivement sur l'échographie.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"La surveillance post-molaire repose avant tout sur la clinique et sur le dosage quantitatif répété des β-HCG plasmatiques (hebdomadaire jusqu'à négativation sur 3 dosages consécutifs, puis mensuel pendant 6 à 12 mois sous contraception efficace) pour dépister une tumeur trophoblastique gestationnelle (choriocarcinome).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"daloa-2__gynecologie-obstetrique__33\",\"num\":\"34\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"I. Questions à Choix Double (QCD : Q1 à Q40)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Le fibrome utérin est une tumeur bénigne développée aux dépens de l'endomètre.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"Le fibrome (léiomyome) utérin est une tumeur bénigne développée aux dépens des fibres musculaires lisses du myomètre (muscle utérin), et non de l'endomètre (muqueuse utérine, dont les tumeurs bénignes sont les polypes endométriaux).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"daloa-2__gynecologie-obstetrique__34\",\"num\":\"35\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"I. Questions à Choix Double (QCD : Q1 à Q40)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Les leucorrhées physiologiques nécessitent un traitement.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"Les leucorrhées physiologiques (liées à la glaire cervicale et à la desquamation vaginale normale, blanches/translucides, inodores, sans prurit ni brûlure) assurent l'auto-nettoyage du vagin et la protection par la flore de Döderlein : elles ne nécessitent aucun traitement.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"daloa-2__gynecologie-obstetrique__35\",\"num\":\"36\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"I. Questions à Choix Double (QCD : Q1 à Q40)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"La vaginose bactérienne est causée par une prolifération des lactobacilles.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"Au contraire, la vaginose bactérienne est une dysbiose caractérisée par la disparition (effondrement) des lactobacilles protecteurs (flore de Döderlein) au profit d'une prolifération de germes anaérobies, principalement Gardnerella vaginalis.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"daloa-2__gynecologie-obstetrique__36\",\"num\":\"37\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"I. Questions à Choix Double (QCD : Q1 à Q40)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Trichomonas vaginalis provoque des leucorrhées verdâtres et spumeuses.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Vrai\",\"answerLetters\":[\"A\"],\"explanation\":\"La vaginite à Trichomonas vaginalis (protozoaire flagellé sexuellement transmissible) se manifeste typiquement par des leucorrhées abondantes, verdâtres, spumeuses (aérées/mousseuses), malodorantes (odeur de plâtre frais), associées à un prurit vulvaire et des brûlures intenses.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"daloa-2__gynecologie-obstetrique__37\",\"num\":\"38\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"I. Questions à Choix Double (QCD : Q1 à Q40)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Les infections à Chlamydia sont souvent symptomatiques.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"Les infections génitales à Chlamydia trachomatis sont le plus souvent asymptomatiques (silencieuses dans 70 à 80 % des cas chez la femme), ce qui explique leur évolution insidieuse vers des salpingites chroniques, des grossesses extra-utérines et une infertilité tubaire.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"daloa-2__gynecologie-obstetrique__38\",\"num\":\"39\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"I. Questions à Choix Double (QCD : Q1 à Q40)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Le traitement du partenaire est systématique dans la vaginose bactérienne.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"Sur le plan médical, la vaginose bactérienne à Gardnerella vaginalis est un déséquilibre de la flore vaginale (dysbiose) et non une IST stricte : le traitement du partenaire n'est donc pas systématique en première intention (contrairement à la trichomonase, la gonococcie et la chlamydiose). (NB : Le texte original du sujet porte l'annotation indicative 'V').\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"daloa-2__gynecologie-obstetrique__39\",\"num\":\"40\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"I. Questions à Choix Double (QCD : Q1 à Q40)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Le principal facteur favorisant du cancer du col est d'avoir des rapports sexuels précoces.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Vrai\",\"answerLetters\":[\"A\"],\"explanation\":\"La précocité des premiers rapports sexuels (avant 17 ans, sur une zone de jonction pavimento-cylindrique immature), la multiplicité des partenaires sexuels et le tabagisme sont les principaux cofacteurs favorisant l'acquisition et la persistance de l'infection à HPV oncogène responsable du cancer du col utérin.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"daloa-2__gynecologie-obstetrique__40\",\"num\":\"41\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"II. Questions à Choix Multiples (QCM : Q41 à Q82)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Concernant les grossesses gémellaires uniovulaires, deux propositions sont exactes : lesquelles ?\",\"options\":[{\"letter\":\"A\",\"text\":\"Les fœtus peuvent être de sexe différent\"},{\"letter\":\"B\",\"text\":\"Est toujours monochoriale et monoamniotique\"},{\"letter\":\"C\",\"text\":\"Peut aboutir à des siamois\"},{\"letter\":\"D\",\"text\":\"Ce sont les faux jumeaux\"},{\"letter\":\"E\",\"text\":\"Elle peut être bichoriale biamniotique\"}],\"mode\":\"mcq\",\"multi\":true,\"answer\":\"C et E\",\"answerLetters\":[\"C\",\"E\"],\"explanation\":\"Les grossesses gémellaires uniovulaires (monozygotes = vrais jumeaux, toujours de même sexe) dépendent de la date du clivage de l'œuf : - Clivage précoce entre J1 et J3 : grossesse bichoriale biamniotique (E, environ 30 % des monozygotes) ; - Clivage entre J4 et J8 : monochoriale biamniotique (≈ 70 %) ; - Clivage entre J8 et J12 : monochoriale monoamniotique ; - Clivage très tardif ≥ J13 : division incomplète du disque embryonnaire aboutissant à des jumeaux conjoints ou siamois (C).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"daloa-2__gynecologie-obstetrique__41\",\"num\":\"42\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"II. Questions à Choix Multiples (QCM : Q41 à Q82)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Parmi les médicaments suivants, deux ne traversent pas la barrière placentaire au cours de la grossesse : lesquels ?\",\"options\":[{\"letter\":\"A\",\"text\":\"L'insuline\"},{\"letter\":\"B\",\"text\":\"Les sulfamides\"},{\"letter\":\"C\",\"text\":\"Les anti-inflammatoires\"},{\"letter\":\"D\",\"text\":\"L'héparine\"},{\"letter\":\"E\",\"text\":\"La rifampicine\"}],\"mode\":\"mcq\",\"multi\":true,\"answer\":\"A et D\",\"answerLetters\":[\"A\",\"D\"],\"explanation\":\"En raison de leur poids moléculaire très élevé, l'insuline (A) et l'héparine (non fractionnée ou HBPM : D) ne franchissent pas la barrière hémato-placentaire, ce qui en fait l'antidiabétique et l'anticoagulant de choix pendant la grossesse.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"daloa-2__gynecologie-obstetrique__42\",\"num\":\"43\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"II. Questions à Choix Multiples (QCM : Q41 à Q82)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Parmi les propositions suivantes, deux sont des affections non immunisantes : lesquelles ?\",\"options\":[{\"letter\":\"A\",\"text\":\"Toxoplasmose\"},{\"letter\":\"B\",\"text\":\"Rubéole\"},{\"letter\":\"C\",\"text\":\"Syphilis\"},{\"letter\":\"D\",\"text\":\"Hépatite B\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"C. Syphilis\",\"answerLetters\":[\"C\"],\"explanation\":\"La syphilis (Treponema pallidum : C) n'est pas immunisante : une patiente guérie peut se réinfecter lors d'un nouveau contage malgré la persistance d'une cicatrice sérologique TPHA+. En revanche, la rubéole (B) et la toxoplasmose (A) chez l'immunocompétente confèrent une immunité définitive (et l'hépatite B guérie avec apparition d'Ac anti-HBs est également immunisante, sauf en cas de portage chronique non guéri D).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"daloa-2__gynecologie-obstetrique__43\",\"num\":\"44\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"II. Questions à Choix Multiples (QCM : Q41 à Q82)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Parmi les gestes suivants de réanimation du nouveau-né, lequel est le 2ème à mettre en place ?\",\"options\":[{\"letter\":\"A\",\"text\":\"Ventilation manuelle\"},{\"letter\":\"B\",\"text\":\"Désobstruction des voies aériennes\"},{\"letter\":\"C\",\"text\":\"Massage cardiaque externe\"},{\"letter\":\"D\",\"text\":\"Injection des solutés\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Ventilation manuelle\",\"answerLetters\":[\"A\"],\"explanation\":\"Dans la séquence ABCD de la réanimation néonatale : après l'accueil/réchauffement et la libération des voies aériennes (A = Airway : positionnement de la tête et désobstruction si sécrétions), l'étape essentielle suivante est la ventilation au ballon auto-gonflable et au masque (B = Breathing : A) dans la première minute de vie (« la minute d'or »). Le massage cardiaque externe (C) ne vient qu'en 3e position et les médicaments/solutés (D) en 4e position.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"daloa-2__gynecologie-obstetrique__44\",\"num\":\"45\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"II. Questions à Choix Multiples (QCM : Q41 à Q82)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Mme Q.T présente une grossesse de 41 SA + 2 jours (selon la DDR et l'échographie de 11 SA + 2 jours). S'agit-il :\",\"options\":[{\"letter\":\"A\",\"text\":\"D'une grossesse à terme\"},{\"letter\":\"B\",\"text\":\"D'un dépassement de terme\"},{\"letter\":\"C\",\"text\":\"D'une grossesse prolongée\"},{\"letter\":\"D\",\"text\":\"D'une grossesse avancée\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"C. D'une grossesse prolongée\",\"answerLetters\":[\"C\"],\"explanation\":\"Selon les recommandations du CNGOF, on parle de « grossesse prolongée » au-delà de 41 SA + 0 jour (donc à 41 SA + 2 j : C), et de « terme dépassé » à partir de 42 SA + 0 jour (B).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"daloa-2__gynecologie-obstetrique__45\",\"num\":\"46\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"II. Questions à Choix Multiples (QCM : Q41 à Q82)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Parmi les germes responsables de l'infection urinaire chez une femme enceinte, lequel est le plus fréquent ? Cochez la bonne réponse.\",\"options\":[{\"letter\":\"A\",\"text\":\"Klebsiella pneumoniae\"},{\"letter\":\"B\",\"text\":\"Escherichia coli\"},{\"letter\":\"C\",\"text\":\"Staphylocoque doré\"},{\"letter\":\"D\",\"text\":\"Streptocoque B\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Escherichia coli\",\"answerLetters\":[\"B\"],\"explanation\":\"Le colibacille (Escherichia coli, entérobactérie d'origine digestive) est responsable de 75 à 85 % des infections urinaires gravidiques (bactériurie asymptomatique, cystite aiguë et pyélonéphrite gravidique).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"daloa-2__gynecologie-obstetrique__46\",\"num\":\"47\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"II. Questions à Choix Multiples (QCM : Q41 à Q82)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Parmi les hormones suivantes, laquelle permet la maturation folliculaire ?\",\"options\":[{\"letter\":\"A\",\"text\":\"Œstrogène\"},{\"letter\":\"B\",\"text\":\"Progestérone\"},{\"letter\":\"C\",\"text\":\"LH\"},{\"letter\":\"D\",\"text\":\"FSH\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"D. FSH\",\"answerLetters\":[\"D\"],\"explanation\":\"La FSH (Follicle-Stimulating Hormone), gonadotrophine sécrétée par l'antéhypophyse durant la phase folliculaire, assure le recrutement, la croissance et la maturation du follicule ovarien dominant jusqu'au stade de follicule mûr de De Graaf.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"daloa-2__gynecologie-obstetrique__47\",\"num\":\"48\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"II. Questions à Choix Multiples (QCM : Q41 à Q82)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Parmi les éléments suivants, lesquels font partie des SONU complets (SONUC) et non des SONU de base (SONUB) :\",\"options\":[{\"letter\":\"A\",\"text\":\"Extraction des produits retenus de la conception\"},{\"letter\":\"B\",\"text\":\"Anticonvulsivants\"},{\"letter\":\"C\",\"text\":\"Césarienne (Chirurgie)\"},{\"letter\":\"D\",\"text\":\"Transfusion sanguine\"},{\"letter\":\"E\",\"text\":\"Accouchement par voie basse avec assistance (extraction instrumentale)\"},{\"letter\":\"F\",\"text\":\"Réanimation du nouveau-né\"}],\"mode\":\"mcq\",\"multi\":true,\"answer\":\"C et D\",\"answerLetters\":[\"C\",\"D\"],\"explanation\":\"Les SONU de base (SONUB) comprennent 7 fonctions signalétiques (antibiotiques parentéraux, utérotoniques parentéraux, anticonvulsivants parentéraux B, révision utérine/délivrance artificielle, évacuation des produits retenus A, extraction instrumentale E et réanimation néonatale au masque F). Les SONU complets (SONUC) comprennent ces 7 fonctions de base PLUS 2 fonctions spécifiques : la chirurgie obstétricale (césarienne, laparotomie : C) et la transfusion sanguine (D).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"daloa-2__gynecologie-obstetrique__48\",\"num\":\"49\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"II. Questions à Choix Multiples (QCM : Q41 à Q82)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"La supplémentation en fer ferreux recommandée en cas d'anémie sévère dans le post-partum est de :\",\"options\":[{\"letter\":\"A\",\"text\":\"60 mg/j\"},{\"letter\":\"B\",\"text\":\"100 mg/j\"},{\"letter\":\"C\",\"text\":\"150 mg/j\"},{\"letter\":\"D\",\"text\":\"200 mg/j\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"C. 150 mg/j\",\"answerLetters\":[\"C\"],\"explanation\":\"Alors que la dose prophylactique standard est de 60 mg/j de fer élémentaire (A), le traitement martial curatif d'une anémie ferriprive sévère ou modérée du post-partum repose sur une posologie doublée ou triplée de 120 à 200 mg/jour de fer élémentaire pendant 3 mois.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"daloa-2__gynecologie-obstetrique__49\",\"num\":\"50\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"II. Questions à Choix Multiples (QCM : Q41 à Q82)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Parmi les complications fœtales suivantes, trois (03) ne peuvent être dues au paludisme au cours de la grossesse : lesquelles ?\",\"options\":[{\"letter\":\"A\",\"text\":\"Avortement spontané\"},{\"letter\":\"B\",\"text\":\"RCIU (Retard de Croissance Intra-Utérin)\"},{\"letter\":\"C\",\"text\":\"Accouchement prématuré\"},{\"letter\":\"D\",\"text\":\"Paludisme néonatal\"},{\"letter\":\"E\",\"text\":\"Placenta prævia\"},{\"letter\":\"F\",\"text\":\"Présentation irrégulière\"}],\"mode\":\"mcq\",\"multi\":true,\"answer\":\"E et F\",\"answerLetters\":[\"E\",\"F\"],\"explanation\":\"Le paludisme gestationnel provoque des avortements spontanés (A), des retards de croissance intra-utérins / hypotrophies (B), des accouchements prématurés (C), des morts fœtales in utero et parfois un paludisme congénital/néonatal (D). En revanche, le placenta prævia (E) et les présentations irrégulières/dystociques (F) sont des anomalies mécaniques/anatomiques d'insertion sans aucun lien causal avec le paludisme.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"daloa-2__gynecologie-obstetrique__50\",\"num\":\"51\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"II. Questions à Choix Multiples (QCM : Q41 à Q82)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Parmi les examens biologiques ci-dessous, trois (03) ne sont pas obligatoires au cours du BPN en Côte d'Ivoire : lesquels ?\",\"options\":[{\"letter\":\"A\",\"text\":\"Groupe sanguin / Rhésus\"},{\"letter\":\"B\",\"text\":\"Électrophorèse de l'Hémoglobine\"},{\"letter\":\"C\",\"text\":\"Sérologie HBs\"},{\"letter\":\"D\",\"text\":\"NFS (Numération Formule Sanguine)\"},{\"letter\":\"E\",\"text\":\"ECBU\"},{\"letter\":\"F\",\"text\":\"Sérologie syphilitique A. Vivax\"},{\"letter\":\"B\",\"text\":\"Malariae\"},{\"letter\":\"C\",\"text\":\"Falciparum\"},{\"letter\":\"D\",\"text\":\"Ovale\"}],\"mode\":\"mcq\",\"multi\":true,\"answer\":\"B et C et E\",\"answerLetters\":[\"B\",\"C\",\"E\"],\"explanation\":\"Dans le Bilan Prénatal (BPN) standard de base : le Groupe sanguin/Rhésus (A), la NFS (D) et la sérologie syphilitique VDRL-TPHA (F) (ainsi que l'électrophorèse de l'hémoglobine B et la glycémie) sont systématiques, tandis que l'ECBU (E) est un examen orienté en cas de leucocyturie/nitriturie ou de brûlures mictionnelles. Q52 (non numérotée entre Q51 et Q53) — Le paludisme grave est le plus souvent dû au Plasmodium : Plasmodium falciparum est l'espèce plasmodiale la plus répandue en Afrique subsaharienne (Côte d'Ivoire) et la quasi-unique responsable des formes graves et mortelles de paludisme (neuropaludisme, anémie sévère, détresse respiratoire, paludisme placentaire) par cytoadhérence des hématies parasitées dans les capillaires profonds.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"daloa-2__gynecologie-obstetrique__51\",\"num\":\"53\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"II. Questions à Choix Multiples (QCM : Q41 à Q82)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Le traitement curatif du paludisme au cours de la grossesse ne se fait pas avec quelle molécule suivante :\",\"options\":[{\"letter\":\"A\",\"text\":\"Sel de Quinine\"},{\"letter\":\"B\",\"text\":\"Sulfadoxine-Pyriméthamine\"},{\"letter\":\"C\",\"text\":\"Combinaison thérapeutique à base d'artémisinine\"},{\"letter\":\"D\",\"text\":\"Artésunate\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Sulfadoxine-Pyriméthamine\",\"answerLetters\":[\"B\"],\"explanation\":\"La Sulfadoxine-Pyriméthamine (SP / Fansidar®) est exclusivement réservée au Traitement Préventif Intermittent (TPI) chez la femme enceinte asymptomatique à partir de 16 SA. Elle ne doit jamais être utilisée pour le traitement curatif d'un accès palustre confirmé (qui repose sur la Quinine ou les CTA au 1er trimestre pour le paludisme simple, et sur l'Artésunate injectable / Artéméther / Quinine injectable pour le paludisme grave).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"daloa-2__gynecologie-obstetrique__52\",\"num\":\"54\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"II. Questions à Choix Multiples (QCM : Q41 à Q82)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Parmi les affections suivantes pouvant survenir chez la femme enceinte, laquelle est d'origine virale ?\",\"options\":[{\"letter\":\"A\",\"text\":\"Syphilis\"},{\"letter\":\"B\",\"text\":\"Toxoplasmose\"},{\"letter\":\"C\",\"text\":\"Rubéole\"},{\"letter\":\"D\",\"text\":\"Paludisme\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"C. Rubéole\",\"answerLetters\":[\"C\"],\"explanation\":\"La rubéole (C) est une infection virale (Rubivirus). La syphilis (A) est bactérienne (Treponema pallidum), tandis que la toxoplasmose (B, Toxoplasma gondii) et le paludisme (D, Plasmodium) sont des infections parasitaires.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"daloa-2__gynecologie-obstetrique__53\",\"num\":\"55\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"II. Questions à Choix Multiples (QCM : Q41 à Q82)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Laquelle de ces structures constitue la couche interne de l'utérus ?\",\"options\":[{\"letter\":\"A\",\"text\":\"La séreuse\"},{\"letter\":\"B\",\"text\":\"Le péritoine\"},{\"letter\":\"C\",\"text\":\"Le myomètre\"},{\"letter\":\"D\",\"text\":\"La muqueuse\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"D. La muqueuse\",\"answerLetters\":[\"D\"],\"explanation\":\"De l'extérieur vers l'intérieur, la paroi utérine comprend trois tuniques : la séreuse péritonéale ou périmètre (externe : A/B), la musculeuse ou myomètre (moyenne : C) et la muqueuse ou endomètre (couche interne tapissant la cavité utérine : D).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"daloa-2__gynecologie-obstetrique__54\",\"num\":\"56\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"II. Questions à Choix Multiples (QCM : Q41 à Q82)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Parmi les éléments suivants, deux (02) n'interviennent pas dans le cycle menstruel : lesquels ?\",\"options\":[{\"letter\":\"A\",\"text\":\"Hypothalamus\"},{\"letter\":\"B\",\"text\":\"Myomètre\"},{\"letter\":\"C\",\"text\":\"Endomètre\"},{\"letter\":\"D\",\"text\":\"Ovaires\"},{\"letter\":\"E\",\"text\":\"Trompes\"}],\"mode\":\"mcq\",\"multi\":true,\"answer\":\"B et E\",\"answerLetters\":[\"B\",\"E\"],\"explanation\":\"Le cycle menstruel met en jeu l'axe hypothalamo-hypophyso-ovarien (Hypothalamus A → Hypophyse → Ovaires D) et son organe cible récepteur qui desquame lors des règles, l'endomètre (C). Le myomètre (B) et les trompes de Fallope (E) n'interviennent pas dans le déterminisme du cycle menstruel.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"daloa-2__gynecologie-obstetrique__55\",\"num\":\"57\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"II. Questions à Choix Multiples (QCM : Q41 à Q82)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Parmi les examens suivants, lequel permet de confirmer la mort fœtale in utero ?\",\"options\":[{\"letter\":\"A\",\"text\":\"Goutte épaisse\"},{\"letter\":\"B\",\"text\":\"NFS\"},{\"letter\":\"C\",\"text\":\"Échographie obstétricale\"},{\"letter\":\"D\",\"text\":\"Glycémie à jeun\"},{\"letter\":\"E\",\"text\":\"ECBU\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"C. Échographie obstétricale\",\"answerLetters\":[\"C\"],\"explanation\":\"L'échographie obstétricale est l'examen de référence qui confirme avec certitude la Mort Fœtale In Utero (MFIU) en objectivant l'absence totale d'activité cardiaque fœtale et de mouvements actifs fœtaux.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"daloa-2__gynecologie-obstetrique__56\",\"num\":\"58\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"II. Questions à Choix Multiples (QCM : Q41 à Q82)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Deux gestes ne font pas partie des soins essentiels au nouveau-né. Lesquels ?\",\"options\":[{\"letter\":\"A\",\"text\":\"Aspiration systématique du nouveau-né\"},{\"letter\":\"B\",\"text\":\"Désinfection oculaire\"},{\"letter\":\"C\",\"text\":\"Injection de dexaméthasone\"},{\"letter\":\"D\",\"text\":\"Soins du cordon\"},{\"letter\":\"E\",\"text\":\"Injection de vitamine K1\"}],\"mode\":\"mcq\",\"multi\":true,\"answer\":\"A et C\",\"answerLetters\":[\"A\",\"C\"],\"explanation\":\"L'aspiration nasopharyngée systématique d'un nouveau-né vigoureux qui crie est proscrite (A : elle ne se fait qu'en cas d'obstruction des voies aériennes ou de non-cri), et l'injection de dexaméthasone (C) est administrée à la mère en anténatal pour la maturation pulmonaire, jamais au nouveau-né. En revanche, la désinfection oculaire (B), les soins du cordon à la chlorhexidine (D) et la vitamine K1 (E) font partie des Soins Essentiels au Nouveau-Né (SENN).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"daloa-2__gynecologie-obstetrique__57\",\"num\":\"59\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"II. Questions à Choix Multiples (QCM : Q41 à Q82)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Dans la technique de l'épisiotomie, celle recommandée est : (Cochez la réponse juste)\",\"options\":[{\"letter\":\"A\",\"text\":\"L'épisiotomie médiane\"},{\"letter\":\"B\",\"text\":\"L'épisiotomie médio-latérale\"},{\"letter\":\"C\",\"text\":\"L'épisiotomie latérale\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. L'épisiotomie médio-latérale\",\"answerLetters\":[\"B\"],\"explanation\":\"L'épisiotomie médio-latérale (partant de la commissure vulvaire postérieure à 6h et dirigée obliquement à 45° vers la droite ou la gauche) est la technique recommandée car elle évite le risque de propagation au sphincter anal et au rectum (périnée complet compliqué) associé à l'épisiotomie médiane.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"daloa-2__gynecologie-obstetrique__58\",\"num\":\"60\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"II. Questions à Choix Multiples (QCM : Q41 à Q82)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Parmi les propositions suivantes, lequel n'est pas un facteur de risque du cancer du col de l'utérus ?\",\"options\":[{\"letter\":\"A\",\"text\":\"Tabac\"},{\"letter\":\"B\",\"text\":\"Multiparité\"},{\"letter\":\"D\",\"text\":\"Infection par HPV\"},{\"letter\":\"E\",\"text\":\"Puberté précoce\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"E. Puberté précoce\",\"answerLetters\":[\"E\"],\"explanation\":\"La puberté précoce (ménarche précoce : E), qui augmente la durée d'exposition hormonale aux œstrogènes, est un facteur de risque du cancer du sein et du cancer de l'endomètre, mais pas du cancer du col de l'utérus (dont les facteurs de risque sont l'infection persistante à HPV oncogène D, la précocité des rapports sexuels, les partenaires multiples, la multiparité B, le tabac A et l'immunodépression VIH).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"daloa-2__gynecologie-obstetrique__59\",\"num\":\"61\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"II. Questions à Choix Multiples (QCM : Q41 à Q82)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Parmi les propositions suivantes, deux sont des causes de coagulopathie : lesquelles ?\",\"options\":[{\"letter\":\"A\",\"text\":\"Mort fœtale depuis 5 semaines\"},{\"letter\":\"B\",\"text\":\"H.R.P\"},{\"letter\":\"C\",\"text\":\"Fibrome utérin\"},{\"letter\":\"D\",\"text\":\"Dystocie dynamique\"},{\"letter\":\"E\",\"text\":\"Infection urinaire\"}],\"mode\":\"mcq\",\"multi\":true,\"answer\":\"A et B\",\"answerLetters\":[\"A\",\"B\"],\"explanation\":\"La rétention prolongée d'un fœtus mort in utero (> 3 à 4 semaines, ici 5 semaines : A) et l'Hématome Rétro-Placentaire (HRP : B) provoquent le passage massif de thromboplastines tissulaires placentaires et déciduales dans la circulation maternelle, déclenchant une Coagulation Intravasculaire Disséminée (CIVD) et une défibrination.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"daloa-2__gynecologie-obstetrique__60\",\"num\":\"62\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"II. Questions à Choix Multiples (QCM : Q41 à Q82)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Quels sont les gestes à faire en cas de procidence du cordon battant en phase de latence de travail : (indiquer les deux mauvaises réponses)\",\"options\":[{\"letter\":\"A\",\"text\":\"Recouvrir le cordon avec des compresses sèches\"},{\"letter\":\"B\",\"text\":\"Installer la patiente en position de Trendelenburg\"},{\"letter\":\"C\",\"text\":\"Faire des TV pour surveiller la descente du fœtus\"},{\"letter\":\"D\",\"text\":\"Hospitaliser la patiente\"},{\"letter\":\"E\",\"text\":\"Indiquer une césarienne en urgence\"}],\"mode\":\"mcq\",\"multi\":true,\"answer\":\"A et C\",\"answerLetters\":[\"A\",\"C\"],\"explanation\":\"En cas de procidence du cordon battant : - Il ne faut jamais recouvrir le cordon de compresses sèches (A est faux : il faut l'envelopper de compresses imbibées de sérum physiologique tiède pour éviter le dessèchement et le vasospasme des vaisseaux ombilicaux) ; - On ne répète pas des TV pour « surveiller la descente » (C est faux : les deux doigts intravaginaux de la sage-femme restent en place pour refouler en permanence la présentation vers le haut jusqu'à l'extraction chirurgicale par césarienne d'extrême urgence E en position de Trendelenburg B).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"daloa-2__gynecologie-obstetrique__61\",\"num\":\"63\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"II. Questions à Choix Multiples (QCM : Q41 à Q82)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Parmi les propositions suivantes, deux sont des signes en faveur d'une GEU non rompue : lesquels ?\",\"options\":[{\"letter\":\"A\",\"text\":\"L'utérus est augmenté de volume (moins gros que l'âge gestationnel)\"},{\"letter\":\"B\",\"text\":\"Des métrorragies minimes sépia\"},{\"letter\":\"C\",\"text\":\"L'œuf est perçu sous la peau\"},{\"letter\":\"D\",\"text\":\"Masse latéro-utérine\"},{\"letter\":\"E\",\"text\":\"Les signes sympathiques de la grossesse sont exacerbés\"}],\"mode\":\"mcq\",\"multi\":true,\"answer\":\"B et D\",\"answerLetters\":[\"B\",\"D\"],\"explanation\":\"La triade clinique classique de la Grossesse Extra-Utérine (GEU) tubaire non rompue associe : des douleurs pelviennes latéralisées, des métrorragies minimes noirâtres « couleur sépia » (B) et, au toucher vaginal, un utérus plus petit que ne le voudrait l'aménorrhée accompagné d'une masse latéro-utérine douloureuse (« petite chose latéro-utérine » de Mondor : D).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"daloa-2__gynecologie-obstetrique__62\",\"num\":\"64\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"II. Questions à Choix Multiples (QCM : Q41 à Q82)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"La ménopause est l'absence de règles depuis au moins :\",\"options\":[{\"letter\":\"A\",\"text\":\"12 mois\"},{\"letter\":\"B\",\"text\":\"18 mois\"},{\"letter\":\"C\",\"text\":\"9 mois\"},{\"letter\":\"D\",\"text\":\"24 mois\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. 12 mois\",\"answerLetters\":[\"A\"],\"explanation\":\"Selon la définition clinique de l'OMS, la ménopause est confirmée rétrospectivement devant une aménorrhée secondaire physiologique d'au moins 12 mois consécutifs (1 an) chez une femme autour de la cinquantaine, liée à l'épuisement définitif du capital folliculaire ovarien.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"daloa-2__gynecologie-obstetrique__63\",\"num\":\"65\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"II. Questions à Choix Multiples (QCM : Q41 à Q82)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Parmi les assertions suivantes, deux sont des complications immédiates de l'avortement provoqué. Lesquelles ?\",\"options\":[{\"letter\":\"A\",\"text\":\"Septicémie\"},{\"letter\":\"B\",\"text\":\"Hémorragie\"},{\"letter\":\"C\",\"text\":\"Béance du col\"},{\"letter\":\"D\",\"text\":\"Douleurs pelviennes chroniques\"},{\"letter\":\"E\",\"text\":\"Perforation utérine\"}],\"mode\":\"mcq\",\"multi\":true,\"answer\":\"B et E\",\"answerLetters\":[\"B\",\"E\"],\"explanation\":\"Les complications immédiates (per-abortum ou dans les premières heures) d'un avortement provoqué clandestin sont l'hémorragie aiguë avec choc hypovolémique (B) et les lésions traumatiques mécaniques telles que la perforation utérine (E) et les déchirures cervico-vaginales. Les complications infectieuses (endométrite, pelvipéritonite, septicémie A) sont des complications secondaires/précoces, tandis que la béance cervico-isthmique (C), les synéchies et les douleurs pelviennes chroniques (D) sont des complications tardives (séquelles).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"daloa-2__gynecologie-obstetrique__64\",\"num\":\"66\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"II. Questions à Choix Multiples (QCM : Q41 à Q82)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Identifiez la série représentant l'ordre de déroulement du travail d'accouchement :\",\"options\":[{\"letter\":\"A\",\"text\":\"Formation de la poche des eaux – effacement du col – progression du fœtus – dilatation du col\"},{\"letter\":\"B\",\"text\":\"Effacement du col – dilatation du col – progression du fœtus – formation de la poche des eaux\"},{\"letter\":\"C\",\"text\":\"Dilatation du col – effacement du col – formation de la poche des eaux – progression du fœtus\"},{\"letter\":\"D\",\"text\":\"Effacement du col – dilatation du col – formation de la poche des eaux – progression du fœtus\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"D. Effacement du col – dilatation du col – formation de la poche des eaux – progression du fœtus\",\"answerLetters\":[\"D\"],\"explanation\":\"Sous l'effet des contractions utérines du travail (en particulier chez la primipare), les phénomènes dynamiques et mécaniques se succèdent dans l'ordre suivant : effacement du col utérin → dilatation cervicale → formation et bombement de la poche des eaux → progression du mobile fœtal (engagement, descente/rotation, dégagement).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"daloa-2__gynecologie-obstetrique__65\",\"num\":\"67\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"II. Questions à Choix Multiples (QCM : Q41 à Q82)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Deux éléments ne font pas partie de la prise en charge de la cystite isolée. Lesquels ?\",\"options\":[{\"letter\":\"A\",\"text\":\"Hospitalisation\"},{\"letter\":\"B\",\"text\":\"Traitement par voie orale\"},{\"letter\":\"C\",\"text\":\"Contrôle ECBU\"},{\"letter\":\"D\",\"text\":\"Fièvre à 40 degrés\"},{\"letter\":\"E\",\"text\":\"Cure hydrique\"}],\"mode\":\"mcq\",\"multi\":true,\"answer\":\"A et D\",\"answerLetters\":[\"A\",\"D\"],\"explanation\":\"La cystite aiguë gravidique isolée (infection urinaire basse) est strictement apyrétique (une fièvre à 40 °C [D] signe une pyélonéphrite aiguë gravidique et non une cystite) et se traite en ambulatoire sans hospitalisation (A) par une antibiothérapie orale adaptée (B), une cure de diurèse / boissons abondantes (E) et un ECBU de contrôle après traitement (C).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"daloa-2__gynecologie-obstetrique__66\",\"num\":\"68\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"II. Questions à Choix Multiples (QCM : Q41 à Q82)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Parmi les vaccins suivants, deux peuvent être administrés au cours de la grossesse. Lesquels ?\",\"options\":[{\"letter\":\"A\",\"text\":\"COVID-19\"},{\"letter\":\"B\",\"text\":\"L'hépatite A\"},{\"letter\":\"C\",\"text\":\"Le BCG\"},{\"letter\":\"D\",\"text\":\"L'hépatite B\"},{\"letter\":\"E\",\"text\":\"La fièvre jaune\"}],\"mode\":\"mcq\",\"multi\":true,\"answer\":\"A et D\",\"answerLetters\":[\"A\",\"D\"],\"explanation\":\"Les vaccins inactivés/recombinants ou à ARNm comme le vaccin contre la COVID-19 (A) et le vaccin contre l'Hépatite B (D) sont autorisés et recommandés au cours de la grossesse. En revanche, les vaccins vivants atténués comme le BCG (C) et le vaccin contre la fièvre jaune (E, sauf urgence épidémique majeure) sont contre-indiqués pendant la grossesse.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"daloa-2__gynecologie-obstetrique__67\",\"num\":\"69\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"II. Questions à Choix Multiples (QCM : Q41 à Q82)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Parmi les assertions suivantes, deux sont des complications maternelles de la drépanocytose majeure au cours de la grossesse : lesquelles ?\",\"options\":[{\"letter\":\"A\",\"text\":\"Les infections urinaires\"},{\"letter\":\"B\",\"text\":\"La prise de poids excessive\"},{\"letter\":\"C\",\"text\":\"Les thromboses\"},{\"letter\":\"D\",\"text\":\"Le placenta prævia\"},{\"letter\":\"E\",\"text\":\"La souffrance fœtale aiguë\"}],\"mode\":\"mcq\",\"multi\":true,\"answer\":\"A et C\",\"answerLetters\":[\"A\",\"C\"],\"explanation\":\"Chez la gestante atteinte d'un syndrome drépanocytaire majeur, les complications maternelles spécifiques incluent la recrudescence des crises vaso-occlusives, l'anémie hémolytique aiguë, les infections bactériennes fréquentes (notamment les infections urinaires et pulmonaires : A), les complications thromboemboliques (thromboses veineuses et embolie pulmonaire : C) et la pré-éclampsie. La SFA (E) est une complication fœtale.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"daloa-2__gynecologie-obstetrique__68\",\"num\":\"70\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"II. Questions à Choix Multiples (QCM : Q41 à Q82)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Concernant l'épisiotomie, quelle est la réponse exacte :\",\"options\":[{\"letter\":\"A\",\"text\":\"Doit être précédée d'une toilette périnéale\"},{\"letter\":\"B\",\"text\":\"Est le plus souvent médiane\"},{\"letter\":\"C\",\"text\":\"Est obligatoire chez une primigeste\"},{\"letter\":\"D\",\"text\":\"La technique de réparation la mieux indiquée est la technique 1 fil 1 nœud\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"D. La technique de réparation la mieux indiquée est la technique 1 fil 1 nœud\",\"answerLetters\":[\"D\"],\"explanation\":\"La réfection chirurgicale de l'épisiotomie en trois plans (muqueuse vaginale, plan musculaire périnéal, plan cutané intradermique) par un surjet continu résorbable selon la technique « un fil, un nœud » (D) est la technique de référence recommandée car elle réduit les douleurs périnéales du post-partum et la dyspareunie. (L'asepsie périnéale A est également de règle avant tout geste obstétrical).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"daloa-2__gynecologie-obstetrique__69\",\"num\":\"71\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"II. Questions à Choix Multiples (QCM : Q41 à Q82)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Au 6ème mois de la grossesse, la hauteur utérine normale doit être de :\",\"options\":[{\"letter\":\"A\",\"text\":\"20 cm\"},{\"letter\":\"B\",\"text\":\"22 cm\"},{\"letter\":\"C\",\"text\":\"24 cm\"},{\"letter\":\"D\",\"text\":\"28 cm\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"C. 24 cm\",\"answerLetters\":[\"C\"],\"explanation\":\"Selon la règle d'obstétrique classique de McDonald : du 2e au 7e mois de grossesse, la Hauteur Utérine (HU en cm) est égale à Nombre de mois × 4. Au 6e mois : HU = 6 × 4 = 24 cm (puis aux 8e et 9e mois, on ajoute 2 cm par mois : 28 + 2 = 30 cm au 8e mois et 32 cm au 9e mois).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"daloa-2__gynecologie-obstetrique__70\",\"num\":\"72\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"II. Questions à Choix Multiples (QCM : Q41 à Q82)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Parmi les propositions suivantes, 2 gestes sont essentiels lors de la réanimation néonatale : lesquels ?\",\"options\":[{\"letter\":\"A\",\"text\":\"Aspiration des voies aériennes\"},{\"letter\":\"B\",\"text\":\"Toilette à la chlorhexidine\"},{\"letter\":\"C\",\"text\":\"Réchauffement sous lampe chauffante\"},{\"letter\":\"D\",\"text\":\"Ventilation à l'Ambu\"},{\"letter\":\"E\",\"text\":\"Massage cardiaque externe\"}],\"mode\":\"mcq\",\"multi\":true,\"answer\":\"A et D\",\"answerLetters\":[\"A\",\"D\"],\"explanation\":\"Dans l'algorithme de réanimation néonatale (« Aider les bébés à respirer » / SONU), les gestes fondamentaux de la première minute de vie qui suffisent à réanimer plus de 90 % des nouveau-nés en détresse sont la libération des voies aériennes / maintien au chaud (A/C) et surtout la ventilation en pression positive au ballon auto-gonflable (Ambu) et au masque (D).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"daloa-2__gynecologie-obstetrique__71\",\"num\":\"73\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"II. Questions à Choix Multiples (QCM : Q41 à Q82)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"La SP ne doit pas être prise par lequel des groupes de femmes enceintes ?\",\"options\":[{\"letter\":\"A\",\"text\":\"Prennent de l'acide folique\"},{\"letter\":\"B\",\"text\":\"Prennent le cotrimoxazole\"},{\"letter\":\"C\",\"text\":\"Dorment sous une moustiquaire imprégnée\"},{\"letter\":\"D\",\"text\":\"Sont infectées par le COVID-19\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Prennent le cotrimoxazole\",\"answerLetters\":[\"B\"],\"explanation\":\"La Sulfadoxine-Pyriméthamine (SP) est formellement contre-indiquée chez les femmes enceintes séropositives au VIH sous prophylaxie par Cotrimoxazole (B), en raison du cumul de toxicité hématologique et cutanée grave des deux sulfamides antifoliques.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"daloa-2__gynecologie-obstetrique__72\",\"num\":\"74\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"II. Questions à Choix Multiples (QCM : Q41 à Q82)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Parmi les propositions suivantes, deux sont des causes directes de mortalité maternelle :\",\"options\":[{\"letter\":\"A\",\"text\":\"VIH/SIDA\"},{\"letter\":\"B\",\"text\":\"Accident de la circulation\"},{\"letter\":\"C\",\"text\":\"Éclampsie\"},{\"letter\":\"D\",\"text\":\"Anémie\"},{\"letter\":\"E\",\"text\":\"Avortement à risque\"}],\"mode\":\"mcq\",\"multi\":true,\"answer\":\"C et E\",\"answerLetters\":[\"C\",\"E\"],\"explanation\":\"L'éclampsie (C) et les complications des avortements à risque (E, hémorragie et sepsis post-abortum) sont des causes obstétricales directes de mortalité maternelle. Le VIH/SIDA (A) et l'anémie (D) sont des causes obstétricales indirectes, et l'accident de la circulation (B) est une mort accidentelle fortuite non obstétricale.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"daloa-2__gynecologie-obstetrique__73\",\"num\":\"75\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"II. Questions à Choix Multiples (QCM : Q41 à Q82)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Dans la présentation de sommet, le diamètre d'engagement est :\",\"options\":[{\"letter\":\"A\",\"text\":\"Sous-occipito-bregmatique\"},{\"letter\":\"B\",\"text\":\"Occipito-frontal\"},{\"letter\":\"C\",\"text\":\"Sous-mento-bregmatique\"},{\"letter\":\"D\",\"text\":\"Syncipito-mentonnier\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Sous-occipito-bregmatique\",\"answerLetters\":[\"A\"],\"explanation\":\"Dans la présentation du sommet (tête bien fléchie), le diamètre d'engagement antéro-postérieur céphalique est le diamètre sous-occipito-bregmatique (ou sous-occipito-frontal), qui mesure 9,5 cm.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"daloa-2__gynecologie-obstetrique__74\",\"num\":\"76\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"II. Questions à Choix Multiples (QCM : Q41 à Q82)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Dans la présentation du sommet, le repère est :\",\"options\":[{\"letter\":\"A\",\"text\":\"Le bregma\"},{\"letter\":\"B\",\"text\":\"Le menton\"},{\"letter\":\"C\",\"text\":\"Le sacrum\"},{\"letter\":\"D\",\"text\":\"La racine du nez\"}],\"mode\":\"open\",\"multi\":false,\"answer\":\"Aucune des propositions listées (le repère exact du sommet est l'OCCIPUT / la fontanelle postérieure lambda ; parmi les choix proposés, A = le bregma est le repère de la présentation du bregma)\",\"answerLetters\":[],\"explanation\":\"Rappel obstétrical fondamental : le repère de la présentation du sommet est l'occiput (reconnu au TV par la fontanelle postérieure triangulaire ou lambda). Les 4 items imprimés dans le QCM correspondent aux autres présentations : Bregma (A = présentation du bregma), Menton (B = face), Sacrum (C = siège), Racine du nez (D = front). Si une case devait être cochée par défaut sur la feuille de lecture optique pour une présentation céphalique proche, c'est A, mais le repère exact du sommet est l'occiput.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"daloa-2__gynecologie-obstetrique__75\",\"num\":\"77\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"II. Questions à Choix Multiples (QCM : Q41 à Q82)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Quelle est l'étiologie la plus rencontrée dans les HPPI ? Cochez la bonne réponse.\",\"options\":[{\"letter\":\"A\",\"text\":\"Rupture utérine\"},{\"letter\":\"B\",\"text\":\"Troubles de la coagulation\"},{\"letter\":\"C\",\"text\":\"Atonie utérine\"},{\"letter\":\"D\",\"text\":\"Rétention placentaire\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"C. Atonie utérine\",\"answerLetters\":[\"C\"],\"explanation\":\"Parmi les 4 « T » de l'Hémorragie du Post-Partum Immédiat (Tonus, Tissu, Traumatisme, Thrombine), l'atonie utérine (défaut de rétraction du myomètre : C) est de loin la cause la plus fréquente, représentant 70 à 80 % des HPPI.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"daloa-2__gynecologie-obstetrique__76\",\"num\":\"78\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"II. Questions à Choix Multiples (QCM : Q41 à Q82)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Parmi les propositions suivantes, deux signes sont en faveur d'un HRP :\",\"options\":[{\"letter\":\"A\",\"text\":\"Fœtus vivant\"},{\"letter\":\"B\",\"text\":\"Contracture utérine permanente\"},{\"letter\":\"C\",\"text\":\"BDCF présents\"},{\"letter\":\"D\",\"text\":\"Présentation inaccessible au TV\"},{\"letter\":\"E\",\"text\":\"Sang noirâtre, minime\"},{\"letter\":\"F\",\"text\":\"Utérus déformé en sablier\"}],\"mode\":\"mcq\",\"multi\":true,\"answer\":\"B et E\",\"answerLetters\":[\"B\",\"E\"],\"explanation\":\"L'Hématome Rétro-Placentaire (HRP) dans sa forme typique complète se caractérise par une contracture utérine permanente, douloureuse et généralisée (« utérus de bois » : B) et des métrorragies faites de sang noirâtre, incoagulable et de faible abondance (E), contrastant avec un état de choc maternel et une disparition fréquente des BDCF.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"daloa-2__gynecologie-obstetrique__77\",\"num\":\"79\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"II. Questions à Choix Multiples (QCM : Q41 à Q82)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Parmi les propositions suivantes, cocher les 2 indications de césarienne de nécessité :\",\"options\":[{\"letter\":\"A\",\"text\":\"Bassin généralement rétréci\"},{\"letter\":\"B\",\"text\":\"Présentation de l'épaule\"},{\"letter\":\"C\",\"text\":\"Syndrome de pré-rupture\"},{\"letter\":\"D\",\"text\":\"SFA\"},{\"letter\":\"E\",\"text\":\"Primipare âgée\"}],\"mode\":\"mcq\",\"multi\":true,\"answer\":\"A et B et C\",\"answerLetters\":[\"A\",\"B\",\"C\"],\"explanation\":\"En terminologie obstétricale : 1. Au sens classique des « indications absolues / de nécessité » (où l'accouchement par voie basse est anatomiquement ou mécaniquement impossible sans mort materno-fœtale) : le bassin généralement rétréci chirurgical (A), la présentation de l'épaule/transverse en travail (B) et le syndrome de pré-rupture utérine de Bandl-Frommel (C). 2. Si la question vise les deux urgences vitales aiguës imposant une césarienne de sauvetage immédiat au cours du travail : le syndrome de pré-rupture utérine (C) et la Souffrance Fœtale Aiguë (SFA : D).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"daloa-2__gynecologie-obstetrique__78\",\"num\":\"80\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"II. Questions à Choix Multiples (QCM : Q41 à Q82)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Parmi les propositions suivantes, deux font partie des complications secondaires des avortements provoqués : lesquelles ?\",\"options\":[{\"letter\":\"A\",\"text\":\"Endométrite\"},{\"letter\":\"B\",\"text\":\"Hémorragie\"},{\"letter\":\"C\",\"text\":\"Perforation utérine\"},{\"letter\":\"D\",\"text\":\"Dyspareunie\"},{\"letter\":\"E\",\"text\":\"Septicémie\"}],\"mode\":\"mcq\",\"multi\":true,\"answer\":\"A et E\",\"answerLetters\":[\"A\",\"E\"],\"explanation\":\"Les complications secondaires (précoces, survenant dans les jours suivant la manœuvre abortive septique) sont essentiellement infectieuses : locales (endométrite aiguë post-abortum : A), régionales (salpingite, pelvipéritonite, phlegmon du ligament large) et générales (septicémie, choc septique, tétanos post-abortum : E). L'hémorragie (B) et la perforation (C) sont des complications immédiates, et la dyspareunie (D) est une séquelle tardive.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"daloa-2__gynecologie-obstetrique__79\",\"num\":\"81\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"II. Questions à Choix Multiples (QCM : Q41 à Q82)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Quelles sont, parmi les étiologies ci-dessous, les deux principales causes d'un accouchement prématuré ?\",\"options\":[{\"letter\":\"A\",\"text\":\"La multiparité\"},{\"letter\":\"B\",\"text\":\"Les infections cervico-vaginales\"},{\"letter\":\"C\",\"text\":\"Le travail sédentaire\"},{\"letter\":\"D\",\"text\":\"Les infections urinaires\"},{\"letter\":\"E\",\"text\":\"Les trajets longs pour se rendre à l'INFAS\"}],\"mode\":\"mcq\",\"multi\":true,\"answer\":\"B et D\",\"answerLetters\":[\"B\",\"D\"],\"explanation\":\"Les causes infectieuses maternelles, au premier rang desquelles figurent les infections cervico-vaginales (B, favorisant la chorioamniotite et la rupture prématurée des membranes par libération de prostaglandines) et les infections urinaires gravidiques (D : bactériurie asymptomatique, cystite, pyélonéphrite), constituent les deux principales étiologies d'accouchement prématuré parmi les choix proposés.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"daloa-2__gynecologie-obstetrique__80\",\"num\":\"82\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"II. Questions à Choix Multiples (QCM : Q41 à Q82)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Deux gestes ne font pas partie des soins essentiels au nouveau-né. Lesquels ? (Question dupliquée de la Q58 avec lettres F à J)\",\"options\":[{\"letter\":\"F\",\"text\":\"Aspiration systématique du nouveau-né | G. Désinfection oculaire | H. Injection de dexaméthasone | I. Soins du cordon | J. Injection de vitamine K1\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"F. Aspiration systématique du nouveau-né | G. Désinfection oculaire | H. Injection de dexaméthasone | I. Soins du cordon | J. Injection de vitamine K1\",\"answerLetters\":[\"F\"],\"explanation\":\"Comme à la question 58, l'aspiration systématique du nouveau-né (F) et l'injection de dexaméthasone (H) ne font pas partie des Soins Essentiels au Nouveau-Né (SENN). ◆ III. CAS CLINIQUE 1 — GYNÉCOLOGIE : MADAME F, 29 ANS (Q84 à Q89) ----------------------------------------------------------------------- Énoncé du cas : Madame F, 29 ans, nulligeste, sans antécédents médico-chirurgicaux particuliers, vient consulter aux urgences gynécologiques ce jour pour des douleurs pelviennes évoluant depuis 3 jours, associées à des métrorragies et à des brûlures mictionnelles. L'interrogatoire retrouve une DDR (22 septembre 2025), avec une notion de vulvovaginite à répétition. Elle est apyrétique. Sa TA est normale. L'examen clinique retrouve une douleur à la palpation de la fosse iliaque droite, sans défense. L'examen au spéculum objective des traces de sang malodorant dans le vagin. Le col est sain. Il existe une douleur à la mobilisation utérine. Le toucher vaginal retrouve une douleur au niveau du cul-de-sac latéral droit, sans masse palpable. (Note : La numérotation du sujet original passe directement de Q82 à Q84). ----------------------------------------------------------------------- -----------------------------------------------------------------------\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"daloa-2__gynecologie-obstetrique__81\",\"num\":\"84\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"III. Cas Clinique 1 : Madame F, 29 ans (Q84 à Q89)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"À quelle pathologie faites-vous allusion ?\",\"options\":[{\"letter\":\"A\",\"text\":\"Appendicite aiguë\"},{\"letter\":\"B\",\"text\":\"Pyélonéphrite aiguë\"},{\"letter\":\"C\",\"text\":\"Salpingite aiguë\"},{\"letter\":\"D\",\"text\":\"Grossesse extra-utérine\"},{\"letter\":\"E\",\"text\":\"Vulvovaginite\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"C. Salpingite aiguë\",\"answerLetters\":[\"C\"],\"explanation\":\"Chez une jeune femme de 29 ans aux antécédents de vulvovaginites à répétition, l'association de douleurs pelviennes, de métrorragies malodorantes, de signes fonctionnels urinaires associés, d'une douleur provoquée à la mobilisation utérine et d'une douleur élective d'un cul-de-sac vaginal latéral au TV est caractéristique d'une Infection Génitale Haute (IGH) non compliquée, c'est-à-dire une salpingite aiguë (l'apyréxie est fréquente dans les salpingites subaiguës à Chlamydia trachomatis).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"daloa-2__gynecologie-obstetrique__82\",\"num\":\"85\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"III. Cas Clinique 1 : Madame F, 29 ans (Q84 à Q89)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Quels sont les deux examens complémentaires que vous demandez dans ce contexte ?\",\"options\":[{\"letter\":\"A\",\"text\":\"NFS avec dosage de la CRP\"},{\"letter\":\"B\",\"text\":\"Hémocultures\"},{\"letter\":\"C\",\"text\":\"Biopsie d'endomètre\"},{\"letter\":\"D\",\"text\":\"Hystérosalpingographie\"},{\"letter\":\"E\",\"text\":\"Échographie pelvienne\"}],\"mode\":\"mcq\",\"multi\":true,\"answer\":\"A et E\",\"answerLetters\":[\"A\",\"E\"],\"explanation\":\"Devant une suspicion de salpingite aiguë (en plus des prélèvements bactériologiques vaginaux/endocervicaux et des β-HCG pour éliminer une GEU), les deux examens complémentaires systématiques de première intention parmi la liste sont la NFS avec CRP (A, bilan inflammatoire) et l'échographie pelvienne sus-pubienne et endovaginale (E, pour rechercher une collection tubaire type pyosalpinx ou abcès tubo-ovarien et éliminer un diagnostic différentiel). L'hystérosalpingographie (D) est formellement contre-indiquée en période infectieuse aiguë.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"daloa-2__gynecologie-obstetrique__83\",\"num\":\"86\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"III. Cas Clinique 1 : Madame F, 29 ans (Q84 à Q89)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Quel est le germe le plus fréquemment responsable de cette pathologie ?\",\"options\":[{\"letter\":\"A\",\"text\":\"Escherichia coli\"},{\"letter\":\"B\",\"text\":\"Neisseria gonorrhoeae\"},{\"letter\":\"C\",\"text\":\"Mycoplasma genitalium\"},{\"letter\":\"D\",\"text\":\"Enterobacter cloacae\"},{\"letter\":\"E\",\"text\":\"Chlamydia trachomatis\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"E. Chlamydia trachomatis\",\"answerLetters\":[\"E\"],\"explanation\":\"Chlamydia trachomatis (bactérie intracellulaire obligatoire sexuellement transmissible) est le germe numéro 1 responsable des salpingites aiguës et subaiguës chez la femme jeune (suivi de Neisseria gonorrhoeae et des germes anaérobies/entérobactéries de la flore vaginale).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"daloa-2__gynecologie-obstetrique__84\",\"num\":\"87\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"III. Cas Clinique 1 : Madame F, 29 ans (Q84 à Q89)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Quel traitement antibiotique proposez-vous ?\",\"options\":[{\"letter\":\"A\",\"text\":\"Amoxicilline 3 g par jour per os\"},{\"letter\":\"B\",\"text\":\"Amoxicilline + acide clavulanique 3 g par jour en IV\"},{\"letter\":\"C\",\"text\":\"Ceftriaxone 500 mg en IM\"},{\"letter\":\"D\",\"text\":\"Ofloxacine 400 mg × 2 par jour + Métronidazole 500 mg × 2 par jour per os\"},{\"letter\":\"E\",\"text\":\"Érythromycine 1 g × 2 par jour per os\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"D. Ofloxacine 400 mg × 2 par jour + Métronidazole 500 mg × 2 par jour per os\",\"answerLetters\":[\"D\"],\"explanation\":\"Le traitement probabiliste ambulatoire de référence d'une salpingite aiguë non compliquée couvre Chlamydia, le gonocoque et les anaérobies : il repose sur l'association Ofloxacine 400 mg × 2/j per os + Métronidazole 500 mg × 2/j per os (D) (complétée par une injection unique de Ceftriaxone 500 mg IM [C]).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"daloa-2__gynecologie-obstetrique__85\",\"num\":\"88\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"III. Cas Clinique 1 : Madame F, 29 ans (Q84 à Q89)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Quelle est la durée du traitement antibiotique ?\",\"options\":[{\"letter\":\"A\",\"text\":\"3 jours\"},{\"letter\":\"B\",\"text\":\"7 jours\"},{\"letter\":\"C\",\"text\":\"14 jours\"},{\"letter\":\"D\",\"text\":\"1 mois\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"C. 14 jours\",\"answerLetters\":[\"C\"],\"explanation\":\"La durée standard de l'antibiothérapie d'une salpingite aiguë non compliquée (Ofloxacine + Métronidazole ou Doxycycline + Métronidazole) est de 14 jours (2 semaines).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"daloa-2__gynecologie-obstetrique__86\",\"num\":\"89\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"III. Cas Clinique 1 : Madame F, 29 ans (Q84 à Q89)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Vous la revoyez quelques jours plus tard. Les douleurs persistent. Elle est fébrile à 38,5 °C. Les autres constantes sont normales. Les examens que vous réalisez montrent une masse latéro-utérine hétérogène de 3,5 cm à droite. Quel est votre diagnostic ?\",\"options\":[{\"letter\":\"A\",\"text\":\"GEU rompue\"},{\"letter\":\"B\",\"text\":\"Cancer de l'ovaire\"},{\"letter\":\"C\",\"text\":\"Hydrosalpinx\"},{\"letter\":\"D\",\"text\":\"Abcès tubo-ovarien\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"D. Abcès tubo-ovarien\",\"answerLetters\":[\"D\"],\"explanation\":\"La persistance des douleurs pelviennes sous antibiothérapie avec apparition d'une fièvre à 38,5 °C et d'une masse latéro-utérine hétérogène de 3,5 cm à l'échographie signe l'évolution vers une Infection Génitale Haute compliquée de collection suppurée : un abcès tubo-ovarien (ou pyosalpinx : D) nécessitant une hospitalisation et une antibiothérapie parentérale (voire un drainage si > 4–5 cm ou non-réponse). +-----------------------------------------------------------------------+\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null}]},{\"name\":\"SSR / PF\",\"slug\":\"ssr-pf\",\"pages\":\"\",\"count\":60,\"session\":\"S2\",\"annee\":2025,\"source\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"questions\":[{\"id\":\"daloa-2__ssr-pf__0\",\"num\":\"1\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"I. Questions à Choix Multiples (QCM : Q1 à Q26)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Pour faire une bonne évaluation de l'état de stock, certains documents sont indispensables dont : (deux bonnes réponses)\",\"options\":[{\"letter\":\"A\",\"text\":\"Les documents relatifs à la consommation\"},{\"letter\":\"B\",\"text\":\"La carte de rendez-vous\"},{\"letter\":\"C\",\"text\":\"Les formulaires de réception\"},{\"letter\":\"D\",\"text\":\"Le carnet de commande\"},{\"letter\":\"E\",\"text\":\"Les documents de gestion de stock\"},{\"letter\":\"F\",\"text\":\"Le rapport de feedback\"}],\"mode\":\"mcq\",\"multi\":true,\"answer\":\"A et E\",\"answerLetters\":[\"A\",\"E\"],\"explanation\":\"En gestion logistique des produits contraceptifs, l'évaluation de l'état du stock (calcul des Mois de Stock Disponible : MSD = Stock Disponible et Utilisable / Consommation Moyenne Mensuelle) nécessite impérativement deux données issues de deux types de documents : les documents relatifs à la consommation (A : registres de prestations/journaux de consommation donnant la CMM) et les documents de gestion de stock (E : fiches de stock donnant le SDU).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"daloa-2__ssr-pf__1\",\"num\":\"2\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"I. Questions à Choix Multiples (QCM : Q1 à Q26)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"La méthode du collier comporte 33 perles réparties comme suit : (une bonne réponse)\",\"options\":[{\"letter\":\"A\",\"text\":\"10 perles blanches, 19 perles marrons, 1 perle rouge, 3 perles marron foncé\"},{\"letter\":\"B\",\"text\":\"19 perles marrons, 10 perles blanches, 3 perles marron foncé et 1 perle rouge\"},{\"letter\":\"C\",\"text\":\"12 perles blanches, 18 perles marrons, 2 perles rouges et 1 perle marron foncé\"},{\"letter\":\"D\",\"text\":\"19 perles marrons, 1 perle rouge, 12 perles blanches, 1 perle marron foncé\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"D. 19 perles marrons, 1 perle rouge, 12 perles blanches, 1 perle marron foncé\",\"answerLetters\":[\"D\"],\"explanation\":\"Dans la Méthode des Jours Fixes (MJF / Collier du cycle), les perles comprennent : 1 perle rouge (1er jour des règles), 12 perles blanches phosphorescentes (jours fertiles de J8 à J19 où le couple doit éviter tout rapport sexuel non protégé) et 19 perles marrons (jours non fertiles : 6 avant la fenêtre fertile de J2 à J7 et 13 après de J20 à J32, incluant 1 perle marron foncé à J26 pour vérifier que le cycle dure entre 26 et 32 jours).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"daloa-2__ssr-pf__2\",\"num\":\"3\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"I. Questions à Choix Multiples (QCM : Q1 à Q26)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"La durée du cycle menstruel le plus court d'Akissi est de 26 jours et celle du cycle menstruel le plus long est de 28 jours. Quelle est la durée de la période d'abstinence si elle ne veut pas contracter de grossesse ? (une bonne réponse)\",\"options\":[{\"letter\":\"A\",\"text\":\"6 jours\"},{\"letter\":\"B\",\"text\":\"10 jours\"},{\"letter\":\"C\",\"text\":\"15 jours\"},{\"letter\":\"D\",\"text\":\"12 jours\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. 10 jours\",\"answerLetters\":[\"B\"],\"explanation\":\"Selon la loi d'Ogino-Knaus (méthode du calendrier) : - Premier jour fertile = Cycle le plus court - 18 = 26 - 18 = 8e jour du cycle (J8). - Dernier jour fertile = Cycle le plus long - 11 = 28 - 11 = 17e jour du cycle (J17). - Durée totale de la période d'abstinence (de J8 à J17 inclus) = (17 - 8) + 1 = 10 jours.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"daloa-2__ssr-pf__3\",\"num\":\"4\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"I. Questions à Choix Multiples (QCM : Q1 à Q26)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Le cycle menstruel d'Oki varie entre 21 et 35 jours. Quand débute sa période fertile ? (une bonne réponse)\",\"options\":[{\"letter\":\"A\",\"text\":\"Le 24ème jour de son cycle menstruel\"},{\"letter\":\"B\",\"text\":\"Le 3ème jour de son cycle menstruel\"},{\"letter\":\"C\",\"text\":\"Le 21ème jour de son cycle menstruel\"},{\"letter\":\"D\",\"text\":\"Le 2ème jour de son cycle menstruel\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Le 3ème jour de son cycle menstruel\",\"answerLetters\":[\"B\"],\"explanation\":\"Selon la formule d'Ogino-Knaus, le début de la période fertile est donné par : Cycle le plus court - 18 = 21 - 18 = 3ème jour du cycle menstruel (J3).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"daloa-2__ssr-pf__4\",\"num\":\"5\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"I. Questions à Choix Multiples (QCM : Q1 à Q26)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Le fil manquant chez une utilisatrice de DIU doit faire penser à :\",\"options\":[{\"letter\":\"A\",\"text\":\"La migration du DIU\"},{\"letter\":\"B\",\"text\":\"L'ancrage du DIU\"},{\"letter\":\"C\",\"text\":\"La perforation utérine\"},{\"letter\":\"D\",\"text\":\"La grossesse\"}],\"mode\":\"mcq\",\"multi\":true,\"answer\":\"A et C et D\",\"answerLetters\":[\"A\",\"C\",\"D\"],\"explanation\":\"La disparition des fils repères du DIU à l'examen au spéculum doit faire évoquer 4 hypothèses classiques : 1) une grossesse évolutive (qui fait remonter les fils dans la cavité utérine : première chose à éliminer), 2) l'expulsion méconnue du DIU, 3) la remontée/migration intrautérine des fils dans le canal cervical, et 4) la perforation utérine avec migration intra-abdominale du DIU.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"daloa-2__ssr-pf__5\",\"num\":\"6\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"I. Questions à Choix Multiples (QCM : Q1 à Q26)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Le counseling sur la contraception est important parce que :\",\"options\":[{\"letter\":\"A\",\"text\":\"La cliente vous trouvera sympathique\"},{\"letter\":\"B\",\"text\":\"Il augmente la chance que la cliente utilise la méthode de manière efficace et continue\"},{\"letter\":\"C\",\"text\":\"La cliente ne sait pas ce qu'elle voudrait et c'est vous qui devez lui dire quelle méthode choisir\"},{\"letter\":\"D\",\"text\":\"Vous devez décrire à la cliente une mauvaise expérience que vous avez eue avec la méthode\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Il augmente la chance que la cliente utilise la méthode de manière efficace et continue\",\"answerLetters\":[\"B\"],\"explanation\":\"Un counseling de qualité centré sur la cliente permet un choix libre et éclairé, dissipe les rumeurs, prépare aux effets secondaires éventuels et augmente ainsi l'observance, l'efficacité et la continuité d'utilisation de la méthode contraceptive choisie.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"daloa-2__ssr-pf__6\",\"num\":\"7\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"I. Questions à Choix Multiples (QCM : Q1 à Q26)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Laquelle des méthodes suivantes de planification familiale est acceptable pour une femme qui a le VIH et la tuberculose et est sous thérapie antirétrovirale et rifampicine ?\",\"options\":[{\"letter\":\"A\",\"text\":\"Les contraceptifs oraux progestatifs (COP)\"},{\"letter\":\"B\",\"text\":\"Dispositif intra-utérin (DIU)\"},{\"letter\":\"C\",\"text\":\"Contraceptifs oraux combinés (COC)\"},{\"letter\":\"D\",\"text\":\"Anneau combiné\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Dispositif intra-utérin (DIU)\",\"answerLetters\":[\"B\"],\"explanation\":\"La rifampicine (antituberculeux majeur) est un puissant inducteur enzymatique hépatique (cytochrome P450) qui accélère la dégradation des contraceptifs hormonaux oraux ou vaginaux (COC, COP, anneau, patch : classe 3 OMS = déconseillés car perte d'efficacité contraceptive). En revanche, le DIU au cuivre (B) n'a aucune interaction médicamenteuse avec la rifampicine et est parfaitement utilisable chez une femme vivant avec le VIH cliniquement stable sous ARV.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"daloa-2__ssr-pf__7\",\"num\":\"8\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"I. Questions à Choix Multiples (QCM : Q1 à Q26)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Quelle est la méthode qui n'est pas utilisable dans le post-partum chez la femme allaitante ? (une bonne réponse)\",\"options\":[{\"letter\":\"A\",\"text\":\"La pilule à seul progestatif\"},{\"letter\":\"B\",\"text\":\"L'implant\"},{\"letter\":\"C\",\"text\":\"Le COC\"},{\"letter\":\"D\",\"text\":\"Le DIU\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"C. Le COC\",\"answerLetters\":[\"C\"],\"explanation\":\"Les Contraceptifs Oraux Combinés (COC, œstroprogestatifs : C) sont contre-indiqués chez la femme allaitante avant 6 mois du post-partum (classe 4 OMS avant 6 semaines, classe 3 de 6 semaines à 6 mois) car l'éthinylestradiol diminue la quantité et la qualité de la sécrétion lactée et expose au risque thromboembolique du post-partum.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"daloa-2__ssr-pf__8\",\"num\":\"9\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"I. Questions à Choix Multiples (QCM : Q1 à Q26)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Parmi les méthodes suivantes, quelle est celle qui assure la double protection ? (une bonne réponse)\",\"options\":[{\"letter\":\"A\",\"text\":\"Le spermicide\"},{\"letter\":\"B\",\"text\":\"La ligature des trompes\"},{\"letter\":\"C\",\"text\":\"La méthode du calendrier\"},{\"letter\":\"D\",\"text\":\"Le Fémidon\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"D. Le Fémidon\",\"answerLetters\":[\"D\"],\"explanation\":\"Les préservatifs masculins et féminins (Fémidon : D) sont les seules méthodes contraceptives qui assurent à la fois une protection contre les grossesses non désirées et une protection contre les IST et le VIH/SIDA (« double protection »).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"daloa-2__ssr-pf__9\",\"num\":\"10\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"I. Questions à Choix Multiples (QCM : Q1 à Q26)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Lorsqu'une utilisatrice de pilule a oublié de prendre sa pilule, laquelle des questions devrait vous orienter dans sa prise en charge ? (une bonne réponse)\",\"options\":[{\"letter\":\"A\",\"text\":\"Combien de comprimés avez-vous oublié ?\"},{\"letter\":\"B\",\"text\":\"Quel type de pilules utilisez-vous ?\"},{\"letter\":\"C\",\"text\":\"Avez-vous eu des rapports sexuels ?\"},{\"letter\":\"D\",\"text\":\"Quel est le nom commercial de la pilule ?\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Combien de comprimés avez-vous oublié ?\",\"answerLetters\":[\"A\"],\"explanation\":\"Devant un oubli de pilule, la conduite à tenir selon les guides OMS dépend directement du type de pilule (COC ou microprogestative) et surtout du nombre de comprimés actifs oubliés (1 ou 2 comprimés vs 3 comprimés ou plus : A).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"daloa-2__ssr-pf__10\",\"num\":\"11\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"I. Questions à Choix Multiples (QCM : Q1 à Q26)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Une personne asexuelle est celle qui : (une bonne réponse)\",\"options\":[{\"letter\":\"A\",\"text\":\"Ressent une attirance amoureuse, affective et/ou sexuelle plus ou moins exclusive pour les personnes du même sexe\"},{\"letter\":\"B\",\"text\":\"Ne ressent pas d'attirance sexuelle pour personne\"},{\"letter\":\"C\",\"text\":\"Ressent une attirance physique et émotionnelle pour autrui, peu importe son identité de genre\"},{\"letter\":\"D\",\"text\":\"Ressent une attirance amoureuse, affective et/ou sexuelle pour les hommes et pour les femmes\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Ne ressent pas d'attirance sexuelle pour personne\",\"answerLetters\":[\"B\"],\"explanation\":\"L'asexualité (B) se définit par l'absence d'attirance sexuelle envers autrui (quel que soit le sexe ou le genre). A définit l'homosexualité, C la pansexualité et D la bisexualité.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"daloa-2__ssr-pf__11\",\"num\":\"12\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"I. Questions à Choix Multiples (QCM : Q1 à Q26)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Le BERCER est un aide-mémoire qui nous aide à nous rappeler les : (une bonne réponse)\",\"options\":[{\"letter\":\"A\",\"text\":\"Buts du counseling\"},{\"letter\":\"B\",\"text\":\"Phases du counseling\"},{\"letter\":\"C\",\"text\":\"Limites du counseling\"},{\"letter\":\"D\",\"text\":\"Étapes du counseling\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"D. Étapes du counseling\",\"answerLetters\":[\"D\"],\"explanation\":\"L'acronyme BERCER (Bienvenue, Entretien, Renseignement, Choix, Explication, Retour/Rendez-vous — équivalent français de GATHER) désigne les 6 étapes du counseling en Planification Familiale.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"daloa-2__ssr-pf__12\",\"num\":\"13\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"I. Questions à Choix Multiples (QCM : Q1 à Q26)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Devant une migraine persistante sous pilule avec une tension artérielle normale, il faut dans un premier temps : (une bonne réponse)\",\"options\":[{\"letter\":\"A\",\"text\":\"Donner des antalgiques\"},{\"letter\":\"B\",\"text\":\"Référer\"},{\"letter\":\"C\",\"text\":\"Arrêter la pilule\"},{\"letter\":\"D\",\"text\":\"Diminuer la quantité d'œstrogène\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"C. Arrêter la pilule\",\"answerLetters\":[\"C\"],\"explanation\":\"L'apparition ou l'aggravation de céphalées migraineuses persistantes sous contraceptif oral combiné (COC) est un signe d'alarme neurovasculaire (risque d'AVC ischémique, classe 4 OMS si migraine avec aura ou après 35 ans) qui impose l'arrêt immédiat de la pilule œstroprogestative (C) et le relais par une méthode non œstrogénique.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"daloa-2__ssr-pf__13\",\"num\":\"14\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"I. Questions à Choix Multiples (QCM : Q1 à Q26)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Mme Doeu est intéressée par la méthode du calendrier, quel est l'élément qui va vous permettre de repérer le début de sa période fertile ? (une bonne réponse)\",\"options\":[{\"letter\":\"A\",\"text\":\"La durée de son cycle menstruel le plus long\"},{\"letter\":\"B\",\"text\":\"La durée de ses règles\"},{\"letter\":\"C\",\"text\":\"La durée de son cycle menstruel le plus court\"},{\"letter\":\"D\",\"text\":\"La durée de son premier cycle menstruel\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"C. La durée de son cycle menstruel le plus court\",\"answerLetters\":[\"C\"],\"explanation\":\"Dans la méthode du calendrier (Ogino-Knaus), le premier jour de la période fertile est calculé en soustrayant 18 à la durée du cycle menstruel le plus court (C) enregistré sur les 6 à 12 derniers mois (tandis que la fin de la période fertile se calcule en soustrayant 11 au cycle le plus long).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"daloa-2__ssr-pf__14\",\"num\":\"15\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"I. Questions à Choix Multiples (QCM : Q1 à Q26)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Quel est le dicton qui a un effet négatif sur le comportement et les aptitudes intellectuelles des femmes et des filles ? (une bonne réponse)\",\"options\":[{\"letter\":\"A\",\"text\":\"Quel que soit l'âge du garçon, il a de la valeur\"},{\"letter\":\"B\",\"text\":\"La femme est faite pour souffrir\"},{\"letter\":\"C\",\"text\":\"Le coq est le chef de la basse-cour\"},{\"letter\":\"D\",\"text\":\"Derrière un grand homme se trouve une grande femme\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. La femme est faite pour souffrir\",\"answerLetters\":[\"B\"],\"explanation\":\"Dans le module Genre, Droits Humains et SSR, les stéréotypes sexistes et dictons dévalorisants comme « La femme est faite pour souffrir » (B) ou « Quel que soit l'âge du garçon, il a de la valeur » (A) entretiennent la résignation face aux violences basées sur le genre (VBG), aux risques obstétricaux et à l'inégalité d'accès à l'éducation des filles.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"daloa-2__ssr-pf__15\",\"num\":\"16\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"I. Questions à Choix Multiples (QCM : Q1 à Q26)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"La gestion logistique est : (une bonne réponse)\",\"options\":[{\"letter\":\"A\",\"text\":\"La disponibilité des produits dans le circuit de distribution\"},{\"letter\":\"B\",\"text\":\"La gestion du flux des produits dans le circuit de distribution\"},{\"letter\":\"C\",\"text\":\"Le compte rendu des mouvements de stock\"},{\"letter\":\"D\",\"text\":\"L'évaluation de l'état de stock\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. La gestion du flux des produits dans le circuit de distribution\",\"answerLetters\":[\"B\"],\"explanation\":\"En logistique des produits de santé (cycle logistique), la gestion logistique se définit comme l'ensemble des activités permettant d'assurer la gestion du flux des produits et des informations associées tout au long du circuit d'approvisionnement et de distribution jusqu'au client final.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"daloa-2__ssr-pf__16\",\"num\":\"17\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"I. Questions à Choix Multiples (QCM : Q1 à Q26)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Le médecin de Davi lui a prescrit de la Griséofulvine alors qu'elle est sous COC minidosé. Quels conseils pouvez-vous lui donner ? (une bonne réponse)\",\"options\":[{\"letter\":\"A\",\"text\":\"Augmenter la dose de la Griséofulvine\"},{\"letter\":\"B\",\"text\":\"Continuer la pilule\"},{\"letter\":\"C\",\"text\":\"Utiliser une méthode d'appoint en cas de rapports sexuels\"},{\"letter\":\"D\",\"text\":\"S'abstenir d'avoir des rapports sexuels\"},{\"letter\":\"E\",\"text\":\"Réponse B et C\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"E. Réponse B et C\",\"answerLetters\":[\"E\"],\"explanation\":\"La griséofulvine (antifongique oral) est un inducteur enzymatique qui réduit l'efficacité des COC minidosés. Pour un traitement de courte durée, la cliente doit continuer à prendre sa pilule (B) tout en utilisant une méthode barrière d'appoint comme le préservatif (C) pendant toute la durée du traitement par griséofulvine et durant les 7 à 28 jours suivant son arrêt (soit E = B et C).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"daloa-2__ssr-pf__17\",\"num\":\"18\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"I. Questions à Choix Multiples (QCM : Q1 à Q26)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Pour prescrire une méthode contraceptive à une cliente, le prestataire se base sur : (deux bonnes réponses)\",\"options\":[{\"letter\":\"A\",\"text\":\"L'anamnèse de la cliente et son expérience en matière de contraception\"},{\"letter\":\"B\",\"text\":\"L'examen des seins et l'examen gynécologique seulement\"},{\"letter\":\"C\",\"text\":\"L'interrogatoire et l'anamnèse\"},{\"letter\":\"D\",\"text\":\"L'examen physique et l'examen gynécologique\"},{\"letter\":\"E\",\"text\":\"Les antécédents contraceptifs\"},{\"letter\":\"F\",\"text\":\"La gestité et la parité\"}],\"mode\":\"mcq\",\"multi\":true,\"answer\":\"A et D\",\"answerLetters\":[\"A\",\"D\"],\"explanation\":\"Le bilan clinique avant prescription d'une méthode contraceptive repose sur deux volets complémentaires : l'interrogatoire/anamnèse complète de la cliente (A ou C : antécédents médicaux, obstétricaux, contraceptifs, critères d'éligibilité) et l'examen clinique général (poids, TA, seins) et gynécologique (D).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"daloa-2__ssr-pf__18\",\"num\":\"19\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"I. Questions à Choix Multiples (QCM : Q1 à Q26)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Le moment idéal pour une nouvelle utilisatrice de COC pour débuter sa première plaquette de pilules est : (une bonne réponse)\",\"options\":[{\"letter\":\"A\",\"text\":\"Les sept premiers jours du cycle menstruel\"},{\"letter\":\"B\",\"text\":\"Le premier jour des menstrues\"},{\"letter\":\"C\",\"text\":\"La fin des menstrues\"},{\"letter\":\"D\",\"text\":\"Les cinq premiers jours du cycle menstruel\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"D. Les cinq premiers jours du cycle menstruel\",\"answerLetters\":[\"D\"],\"explanation\":\"Selon les recommandations de l'OMS, une nouvelle utilisatrice de COC peut débuter sa première plaquette avec une efficacité contraceptive immédiate (sans méthode d'appoint) dans les 5 premiers jours du cycle menstruel (D : du 1er au 5e jour des règles, l'idéal étant dès le 1er jour des menstrues B).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"daloa-2__ssr-pf__19\",\"num\":\"20\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"I. Questions à Choix Multiples (QCM : Q1 à Q26)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Au cours des activités sportives, le patch de Coucou s'est décollé avant le terme prévu, que doit-elle faire ? (une bonne réponse)\",\"options\":[{\"letter\":\"A\",\"text\":\"Attendre la date de remplacement avant de coller un nouveau patch\"},{\"letter\":\"B\",\"text\":\"Attendre les menstrues avant de poser un nouveau patch\"},{\"letter\":\"C\",\"text\":\"Coller un nouveau patch dans les 24 heures\"},{\"letter\":\"D\",\"text\":\"Changer de méthode\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"C. Coller un nouveau patch dans les 24 heures\",\"answerLetters\":[\"C\"],\"explanation\":\"Lorsqu'un patch contraceptif transdermique se décolle depuis moins de 24 heures, l'utilisatrice doit le recoller immédiatement ou appliquer un nouveau patch dans les 24 heures (C) : l'efficacité contraceptive est alors intégralement maintenue sans besoin de contraception d'appoint.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"daloa-2__ssr-pf__20\",\"num\":\"21\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"I. Questions à Choix Multiples (QCM : Q1 à Q26)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Ces contraceptifs suivants peuvent être utilisés comme contraception d'urgence : (deux bonnes réponses)\",\"options\":[{\"letter\":\"A\",\"text\":\"Implanon NXT\"},{\"letter\":\"B\",\"text\":\"Dépo-Provera\"},{\"letter\":\"C\",\"text\":\"DIU\"},{\"letter\":\"D\",\"text\":\"Acétate d'Ulipristal\"},{\"letter\":\"E\",\"text\":\"Sayana Press\"},{\"letter\":\"F\",\"text\":\"Cyclofem\"}],\"mode\":\"mcq\",\"multi\":true,\"answer\":\"C et D\",\"answerLetters\":[\"C\",\"D\"],\"explanation\":\"Les méthodes utilisables en Contraception d'Urgence (CU) sont : le DIU au cuivre (C, inséré dans les 5 jours suivant le rapport non protégé, méthode la plus efficace à > 99 %), l'Acétate d'Ulipristal 30 mg (EllaOne® : D, jusqu'à 120h), le Lévonorgestrel 1,5 mg (Norlevo®) et les pilules combinées selon la méthode de Yuzpe. Les implants (A) et les injectables (B, E, F) ne sont jamais des contraceptifs d'urgence.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"daloa-2__ssr-pf__21\",\"num\":\"22\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"I. Questions à Choix Multiples (QCM : Q1 à Q26)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"La DCI du SAYANA Press est : (une bonne réponse)\",\"options\":[{\"letter\":\"A\",\"text\":\"Énanthate de Noréthistérone\"},{\"letter\":\"B\",\"text\":\"Lévonorgestrel\"},{\"letter\":\"C\",\"text\":\"Étonogestrel\"},{\"letter\":\"D\",\"text\":\"Acétate de Médroxyprogestérone retard\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"D. Acétate de Médroxyprogestérone retard\",\"answerLetters\":[\"D\"],\"explanation\":\"Le Sayana® Press est un contraceptif progestatif injectable trimestriel par voie sous-cutanée (système Uniject prérempli) dont la Dénomination Commune Internationale (DCI) est l'Acétate de Médroxyprogestérone retard (DMPA-SC, dosé à 104 mg / 0,65 ml).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"daloa-2__ssr-pf__22\",\"num\":\"23\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"I. Questions à Choix Multiples (QCM : Q1 à Q26)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Dani vient d'accoucher d'un petit garçon ce jour par voie basse mais fait une hémorragie du post-partum, le DIU est classé : (une bonne réponse)\",\"options\":[{\"letter\":\"A\",\"text\":\"Catégorie 2\"},{\"letter\":\"B\",\"text\":\"Catégorie 4\"},{\"letter\":\"C\",\"text\":\"Catégorie différer\"},{\"letter\":\"D\",\"text\":\"Catégorie 3\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Catégorie 4\",\"answerLetters\":[\"B\"],\"explanation\":\"Une hémorragie du post-partum immédiat (HPPI) non résolue est une contre-indication absolue à l'insertion post-placentaire immédiate du DIU (Catégorie 4 OMS / à différer impérativement jusqu'à l'arrêt complet de l'hémorragie et la stabilisation de la patiente).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"daloa-2__ssr-pf__23\",\"num\":\"24\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"I. Questions à Choix Multiples (QCM : Q1 à Q26)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Parmi les propositions suivantes, relevez deux (2) éléments de la règle des « 6 Bons » : (deux bonnes réponses)\",\"options\":[{\"letter\":\"A\",\"text\":\"Bonnes pratiques\"},{\"letter\":\"B\",\"text\":\"Au bon endroit\"},{\"letter\":\"C\",\"text\":\"En bonne condition\"},{\"letter\":\"D\",\"text\":\"Bon stockage\"},{\"letter\":\"E\",\"text\":\"Bonne sécurité\"}],\"mode\":\"mcq\",\"multi\":true,\"answer\":\"B et C\",\"answerLetters\":[\"B\",\"C\"],\"explanation\":\"En logistique sanitaire, les « 6 Bons » (Six Rights of Logistics) sont : 1) Les bons produits, 2) En bonne quantité, 3) En bonne condition (bonne qualité : C), 4) Au bon endroit (B), 5) Au bon moment, et 6) Au bon coût.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"daloa-2__ssr-pf__24\",\"num\":\"25\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"I. Questions à Choix Multiples (QCM : Q1 à Q26)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Dans l'acronyme REDI, la prise de décision correspond à quelle lettre ? (une bonne réponse)\",\"options\":[{\"letter\":\"A\",\"text\":\"R\"},{\"letter\":\"B\",\"text\":\"E\"},{\"letter\":\"C\",\"text\":\"D\"},{\"letter\":\"D\",\"text\":\"I\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"C. D\",\"answerLetters\":[\"C\"],\"explanation\":\"L'approche de counseling REDI signifie : R = Rapport (établir de bons rapports), E = Exploration (explorer les besoins, le contexte et les risques), D = Décision (aider la cliente à prendre une décision libre et éclairée : C), et I = Implémentation / Mise en œuvre de la décision.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"daloa-2__ssr-pf__25\",\"num\":\"26\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"I. Questions à Choix Multiples (QCM : Q1 à Q26)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Les critères médicaux d'éligibilité permettent : (une bonne réponse)\",\"options\":[{\"letter\":\"A\",\"text\":\"Faire un bon counseling\"},{\"letter\":\"B\",\"text\":\"Prendre en charge les effets secondaires de la méthode\"},{\"letter\":\"C\",\"text\":\"Prescrire de manière appropriée les contraceptifs aux clientes\"},{\"letter\":\"D\",\"text\":\"Classer les méthodes en fonction de leur mode d'action\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"C. Prescrire de manière appropriée les contraceptifs aux clientes\",\"answerLetters\":[\"C\"],\"explanation\":\"Le disque et le guide des Critères de Recevabilité Médicale (CRM / CME) de l'OMS (catégories 1 à 4) permettent au prestataire de vérifier l'absence de contre-indication médicale et de prescrire en toute sécurité et de manière appropriée les méthodes contraceptives selon l'état de santé et les caractéristiques de chaque cliente (C). ◆ II. ÉTUDE DE CAS N°1 — SÉANCE DE CAUSERIE ÉDUCATIVE (Q27 à Q32) ----------------------------------------------------------------------- Énoncé du cas : La sage-femme du village vous invite à une séance de causerie éducative relative aux grossesses précoces. Vous trouvez devant la salle 38 femmes dont l'âge varie entre 12 et 62 ans. La salle est poussiéreuse avec un éclairage qui laisse à désirer ; en plus les sièges sont en mauvais état et insuffisants. La séance était prévue pour 8 heures 30 minutes mais la sage-femme s'est amenée à 9 heures 30 minutes ; pendant ce temps les participantes l'attendaient devant la salle. ----------------------------------------------------------------------- -----------------------------------------------------------------------\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"daloa-2__ssr-pf__26\",\"num\":\"27\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"II. Étude de cas N°1 : Séance de causerie éducative (Q27 à Q32)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Est-ce que le groupe que la sage-femme a invité est homogène ?\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"En Communication pour le Changement Social et de Comportement (CCSC / IEC), un groupe cible de causerie éducative doit être homogène en âge et en centres d'intérêt. Ici, réunir des fillettes de 12 ans et des femmes âgées de 62 ans sur un sujet sensible comme les grossesses précoces constitue un groupe totalement hétérogène qui bloque la libre expression des adolescentes.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"daloa-2__ssr-pf__27\",\"num\":\"28\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"II. Étude de cas N°1 : Séance de causerie éducative (Q27 à Q32)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Justifiez votre réponse : (une bonne réponse)\",\"options\":[{\"letter\":\"A\",\"text\":\"Les invités sont toutes des femmes\"},{\"letter\":\"B\",\"text\":\"Les invités sont toutes des adolescentes\"},{\"letter\":\"C\",\"text\":\"Les invités ont un âge compris entre 12 et 62 ans\"},{\"letter\":\"D\",\"text\":\"Les invités sont toutes du même village\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"C. Les invités ont un âge compris entre 12 et 62 ans\",\"answerLetters\":[\"C\"],\"explanation\":\"L'écart d'âge extrême allant de 12 à 62 ans (adolescentes, mères et grands-mères réunies) explique l'hétérogénéité générationnelle du groupe.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"daloa-2__ssr-pf__28\",\"num\":\"29\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"II. Étude de cas N°1 : Séance de causerie éducative (Q27 à Q32)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Combien devrait être le nombre d'invités ? (une bonne réponse)\",\"options\":[{\"letter\":\"A\",\"text\":\"30 invités\"},{\"letter\":\"B\",\"text\":\"38 invités\"},{\"letter\":\"C\",\"text\":\"10 invités\"},{\"letter\":\"D\",\"text\":\"20 invités\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"D. 20 invités\",\"answerLetters\":[\"D\"],\"explanation\":\"Selon les normes pédagogiques d'animation d'une séance de causerie éducative (discussion de groupe), l'effectif idéal est de 12 à 20 personnes (maximum 20 participants : D) afin de favoriser l'interaction et la prise de parole de chacun. Au-delà (38 personnes), la séance devient trop nombreuse pour une causerie participative.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"daloa-2__ssr-pf__29\",\"num\":\"30\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"II. Étude de cas N°1 : Séance de causerie éducative (Q27 à Q32)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"La situation décrit certaines étapes de la causerie ; lesquelles ? (deux bonnes réponses)\",\"options\":[{\"letter\":\"A\",\"text\":\"L'évaluation\"},{\"letter\":\"B\",\"text\":\"La préparation\"},{\"letter\":\"C\",\"text\":\"L'exécution\"},{\"letter\":\"D\",\"text\":\"La démonstration\"},{\"letter\":\"E\",\"text\":\"L'introduction\"}],\"mode\":\"mcq\",\"multi\":true,\"answer\":\"B et C\",\"answerLetters\":[\"B\",\"C\"],\"explanation\":\"Le texte met en évidence des défaillances au niveau de la préparation matérielle et organisationnelle (B : ciblage du groupe, nettoyage et aménagement de la salle, éclairage, sièges) et du démarrage/exécution (C : retard d'une heure de la sage-femme, participantes attendant dehors).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"daloa-2__ssr-pf__30\",\"num\":\"31\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"II. Étude de cas N°1 : Séance de causerie éducative (Q27 à Q32)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Une grossesse est dite précoce lorsque la gestante est âgée de : (une bonne réponse)\",\"options\":[{\"letter\":\"A\",\"text\":\"20 ans\"},{\"letter\":\"B\",\"text\":\"Moins de 18 ans\"},{\"letter\":\"C\",\"text\":\"36 ans\"},{\"letter\":\"D\",\"text\":\"Moins de 40 ans\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Moins de 18 ans\",\"answerLetters\":[\"B\"],\"explanation\":\"On appelle grossesse précoce toute grossesse survenant chez une adolescente mineure âgée de moins de 18 ans (avant la maturité anatomique pelvienne et psycho-sociale complète).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"daloa-2__ssr-pf__31\",\"num\":\"32\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"II. Étude de cas N°1 : Séance de causerie éducative (Q27 à Q32)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"À quel groupe la sage-femme devrait-elle s'adresser ? (une bonne réponse)\",\"options\":[{\"letter\":\"A\",\"text\":\"Les adolescents\"},{\"letter\":\"B\",\"text\":\"Les hommes célibataires\"},{\"letter\":\"C\",\"text\":\"Les femmes de plus de 35 ans\"},{\"letter\":\"D\",\"text\":\"Les jeunes filles scolarisées\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Les adolescents\",\"answerLetters\":[\"A\"],\"explanation\":\"Le thème portant sur les grossesses précoces, la cible principale à laquelle la sage-femme doit s'adresser est le groupe des adolescents et adolescentes (10–19 ans : A, scolarisés ou non). ◆ III. ÉTUDE DE CAS N°2 — MADAME DOUM / KOSSIA ET LA MAMA (Q33 à Q40) ----------------------------------------------------------------------- Énoncé du cas : Madame Doum, grande multipare, gestité 6, parité 4, veut pratiquer la MAMA. Son dernier enfant est né le 11 juillet 2022, nourri exclusivement au sein ; elle voudrait se reposer quelques années avant de contracter une nouvelle grossesse. Les grossesses précédentes l'ont toujours surprise. En effet, auparavant, chaque fois qu'elle décidait de prendre une méthode contraceptive, la sage-femme lui annonçait une nouvelle grossesse après l'examen gynécologique ; c'est pourquoi elle veut débuter assez tôt la contraception avec cette méthode (MAMA). ----------------------------------------------------------------------- -----------------------------------------------------------------------\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"daloa-2__ssr-pf__32\",\"num\":\"33\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"III. Étude de cas N°2 : Mme Doum et la MAMA (Q33 à Q40)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"À quel type de méthodes appartient la MAMA ? (une bonne réponse)\",\"options\":[{\"letter\":\"A\",\"text\":\"Méthodes d'auto-observation\"},{\"letter\":\"B\",\"text\":\"Méthodes hormonales\"},{\"letter\":\"C\",\"text\":\"Méthodes temporaires\"},{\"letter\":\"D\",\"text\":\"Méthodes naturelles\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"D. Méthodes naturelles\",\"answerLetters\":[\"D\"],\"explanation\":\"La Méthode de l'Allaitement Maternel et de l'Aménorrhée (MAMA) est classée parmi les méthodes contraceptives naturelles (D) et temporaires reposant sur l'inhibition physiologique de l'ovulation par l'hyperprolactinémie de la succion.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"daloa-2__ssr-pf__33\",\"num\":\"34\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"III. Étude de cas N°2 : Mme Doum et la MAMA (Q33 à Q40)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Quelle question allez-vous lui poser ? (une bonne réponse)\",\"options\":[{\"letter\":\"A\",\"text\":\"Avez-vous vu le retour de couches ?\"},{\"letter\":\"B\",\"text\":\"Quel est l'âge de votre enfant ?\"},{\"letter\":\"C\",\"text\":\"Est-ce que vous pratiquez l'allaitement exclusif ?\"},{\"letter\":\"D\",\"text\":\"Tout ce qui précède\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"D. Tout ce qui précède\",\"answerLetters\":[\"D\"],\"explanation\":\"L'éligibilité à la MAMA repose impérativement sur la vérification simultanée des 3 critères : 1) Aménorrhée (absence de retour de couches : A), 2) Nourrisson âgé de moins de 6 mois (B), et 3) Allaitement maternel exclusif ou quasi exclusif jour et nuit (C), soit « Tout ce qui précède » (D).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"daloa-2__ssr-pf__34\",\"num\":\"35\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"III. Étude de cas N°2 : Mme Doum et la MAMA (Q33 à Q40)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Dans quel groupe particulier classez-vous Mme Doum / Kossia ? (une bonne réponse)\",\"options\":[{\"letter\":\"A\",\"text\":\"Le post-abortum\"},{\"letter\":\"B\",\"text\":\"Le post-partum\"},{\"letter\":\"C\",\"text\":\"Les femmes de plus de 35 ans\"},{\"letter\":\"D\",\"text\":\"Les personnes à risque environnemental\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Le post-partum\",\"answerLetters\":[\"B\"],\"explanation\":\"Mme Doum vient d'accoucher et allaite son nourrisson : elle appartient au groupe particulier des femmes en période de post-partum / allaitantes (B).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"daloa-2__ssr-pf__35\",\"num\":\"36\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"III. Étude de cas N°2 : Mme Doum et la MAMA (Q33 à Q40)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"À partir de quelle période du post-partum elle ne pourra plus utiliser la méthode (MAMA) ? (une bonne réponse)\",\"options\":[{\"letter\":\"A\",\"text\":\"12 semaines et demie\"},{\"letter\":\"B\",\"text\":\"6 semaines\"},{\"letter\":\"C\",\"text\":\"12 mois\"},{\"letter\":\"D\",\"text\":\"6 mois\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"D. 6 mois\",\"answerLetters\":[\"D\"],\"explanation\":\"La MAMA n'est efficace que durant les 6 premiers mois suivant l'accouchement. Dès que l'enfant atteint l'âge de 6 mois (introduction de la diversification alimentaire : D), la mère ne peut plus utiliser la MAMA et doit passer à une autre méthode contraceptive moderne.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"daloa-2__ssr-pf__36\",\"num\":\"37\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"III. Étude de cas N°2 : Mme Doum et la MAMA (Q33 à Q40)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Est-ce que cette méthode comporte des inconvénients ? (une bonne réponse)\",\"options\":[{\"letter\":\"A\",\"text\":\"Hémorragie du post-partum\"},{\"letter\":\"B\",\"text\":\"Contraignant pour la mère\"},{\"letter\":\"C\",\"text\":\"Établit un rapport étroit entre la mère et l'enfant\"},{\"letter\":\"D\",\"text\":\"Risque de transmission du VIH à l'enfant\"},{\"letter\":\"E\",\"text\":\"N'interfère pas avec les rapports sexuels\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Contraignant pour la mère\",\"answerLetters\":[\"B\"],\"explanation\":\"Parmi les propositions, C et E sont des avantages de la MAMA. L'inconvénient pratique principal pour toutes les utilisatrices est le caractère contraignant du rythme d'allaitement exclusif à la demande jour et nuit (B) ainsi que sa durée limitée à 6 mois (et le risque de transmission verticale du VIH par le lait maternel si la mère est séropositive non substituée : D).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"daloa-2__ssr-pf__37\",\"num\":\"38\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"III. Étude de cas N°2 : Mme Doum et la MAMA (Q33 à Q40)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Quel contraceptif peut-elle prendre dans le cas où elle voudrait prendre une méthode hormonale ? (une bonne réponse)\",\"options\":[{\"letter\":\"A\",\"text\":\"Cyclo-Provera\"},{\"letter\":\"B\",\"text\":\"Mesigyna\"},{\"letter\":\"C\",\"text\":\"Microgynon\"},{\"letter\":\"D\",\"text\":\"Implanon NXT\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"D. Implanon NXT\",\"answerLetters\":[\"D\"],\"explanation\":\"Chez une femme allaitante qui souhaite espacer ses naissances de « quelques années », les méthodes œstroprogestatives combinées (Cyclo-Provera A, Mesigyna B, Microgynon C) sont contre-indiquées avant 6 mois car elles tarissent la sécrétion lactée. En revanche, l'Implanon NXT (D, implant sous-cutané purement progestatif de longue durée d'action — 3 ans) est compatible avec l'allaitement maternel dès le post-partum.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"daloa-2__ssr-pf__38\",\"num\":\"39\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"III. Étude de cas N°2 : Mme Doum et la MAMA (Q33 à Q40)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Nommez l'hormone contenue dans ce contraceptif (Implanon NXT) : (une bonne réponse)\",\"options\":[{\"letter\":\"A\",\"text\":\"Étonogestrel\"},{\"letter\":\"B\",\"text\":\"Lévonorgestrel\"},{\"letter\":\"C\",\"text\":\"Acétate de Médroxyprogestérone Retard\"},{\"letter\":\"D\",\"text\":\"Cypionate d'œstradiol\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Étonogestrel\",\"answerLetters\":[\"A\"],\"explanation\":\"L'Implanon NXT® est un implant contraceptif sous-cutané à bâtonnet unique contenant un progestatif de 3e génération : l'Étonogestrel (A) (tandis que le Jadelle® à 2 bâtonnets contient du Lévonorgestrel B).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"daloa-2__ssr-pf__39\",\"num\":\"40\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"III. Étude de cas N°2 : Mme Doum et la MAMA (Q33 à Q40)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Quel en est le dosage dans ce contraceptif (Implanon NXT) ? (une bonne réponse)\",\"options\":[{\"letter\":\"A\",\"text\":\"150 mg\"},{\"letter\":\"B\",\"text\":\"216 mg\"},{\"letter\":\"C\",\"text\":\"68 mg\"},{\"letter\":\"D\",\"text\":\"200 mg\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"C. 68 mg\",\"answerLetters\":[\"C\"],\"explanation\":\"Le bâtonnet unique de l'Implanon NXT® est dosé à 68 mg d'étonogestrel (C). (150 mg est le dosage du Dépo-Provera IM, et 2 × 75 mg = 150 mg est le dosage du Jadelle).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"daloa-2__ssr-pf__40\",\"num\":\"41\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"IV. Questions à Choix Double (QCD : Q41 à Q60)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Quand le DIU est inséré deux (2) semaines après l'accouchement, le risque d'expulsion est bas parce qu'il est facile d'atteindre le fond utérin.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"Le DIU du post-partum s'insère soit dans les 48 premières heures suivant l'accouchement (post-placentaire immédiat < 10 min ou post-partum immédiat < 48h), soit à partir de 4 à 6 semaines du post-partum. Entre 48 heures et 4 semaines (donc à 2 semaines), l'insertion du DIU est formellement contre-indiquée (classe 3/4) en raison du risque élevé de perforation utérine, d'infection et d'expulsion lié à l'involution utérine en cours.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"daloa-2__ssr-pf__41\",\"num\":\"42\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"IV. Questions à Choix Double (QCD : Q41 à Q60)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Il n'est pas nécessaire d'utiliser un antiseptique quand on insère le DIU immédiatement après l'accouchement parce que le prestataire porte encore les gants stériles.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"Les règles de Prévention des Infections (PI) et la technique « sans toucher » (no-touch) imposent toujours de badigeonner soigneusement le col et le vagin avec un antiseptique aqueux (polyvidone iodée / Bétadine ou chlorhexidine) avant toute insertion de DIU post-placentaire pour prévenir l'endométrite puerpérale.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"daloa-2__ssr-pf__42\",\"num\":\"43\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"IV. Questions à Choix Double (QCD : Q41 à Q60)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Le DIU du post-abortum doit être inséré dans les quatorze premiers jours qui suivent l'avortement.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Vrai\",\"answerLetters\":[\"A\"],\"explanation\":\"En l'absence d'infection pelvienne (avortement septique exclu), le DIU post-abortum peut être inséré immédiatement après l'évacuation utérine ou dans les 12 à 14 premiers jours suivant un avortement du 1er trimestre sans avoir besoin de tests supplémentaires.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"daloa-2__ssr-pf__43\",\"num\":\"44\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"IV. Questions à Choix Double (QCD : Q41 à Q60)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"À chaque contact avec l'utilisatrice de la méthode du collier, le prestataire doit vérifier si son cycle menstruel le plus récent a une durée de 26 à 32 jours.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Vrai\",\"answerLetters\":[\"A\"],\"explanation\":\"La Méthode des Jours Fixes (Collier du cycle) n'est fiable que chez les femmes dont les cycles menstruels durent entre 26 et 32 jours. Si la cliente a plus d'un cycle par an en dehors de cet intervalle (anneau arrivant avant la perle marron foncé J26 ou règles ne revenant pas après la dernière perle J32), elle doit changer de méthode.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"daloa-2__ssr-pf__44\",\"num\":\"45\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"IV. Questions à Choix Double (QCD : Q41 à Q60)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Au cours de la césarienne, les fils du DIU devraient être dirigés dans l'orifice vaginal à travers le col.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"Lors de la pose d'un DIU per-césarienne (trans-césarienne), après avoir placé le DIU au fond utérin, les fils sont simplement dirigés vers le segment inférieur / orifice interne du col mais ne doivent pas être poussés à travers le canal cervical jusque dans le vagin (afin d'éviter toute contamination rétrograde de la cavité utérine par la flore vaginale) ; ils descendront spontanément lors de l'involution utérine.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"daloa-2__ssr-pf__45\",\"num\":\"46\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"IV. Questions à Choix Double (QCD : Q41 à Q60)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Le DIU du post-abortum ne convient pas aux nullipares.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"Selon les critères de recevabilité médicale de l'OMS, la nulliparité n'est pas une contre-indication au DIU (y compris en post-abortum non septique).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"daloa-2__ssr-pf__46\",\"num\":\"47\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"IV. Questions à Choix Double (QCD : Q41 à Q60)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Après un avortement spontané, une période de repos de 6 mois devrait être observée avant de contracter une nouvelle grossesse.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Vrai\",\"answerLetters\":[\"A\"],\"explanation\":\"Selon les recommandations de l'OMS sur l'espacement optimal des grossesses (EOG), après une fausse couche ou un avortement induit, il est recommandé d'attendre au moins 6 mois avant de concevoir à nouveau afin de réduire les risques d'anémie maternelle, de prématurité et de faible poids de naissance.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"daloa-2__ssr-pf__47\",\"num\":\"48\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"IV. Questions à Choix Double (QCD : Q41 à Q60)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"La contraception orale combinée n'est pas indiquée pour les femmes qui allaitent six semaines après l'accouchement.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Vrai\",\"answerLetters\":[\"A\"],\"explanation\":\"Chez la femme allaitante, les Contraceptifs Oraux Combinés (COC) ne sont pas indiqués entre 6 semaines et 6 mois du post-partum (Catégorie 3 de l'OMS : les risques d'altération de la lactation l'emportent généralement sur les avantages) ; ils ne deviennent utilisables qu'à partir de 6 mois après l'accouchement.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"daloa-2__ssr-pf__48\",\"num\":\"49\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"IV. Questions à Choix Double (QCD : Q41 à Q60)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Lorsque la cliente utilise pour la première fois un contraceptif oral combiné, elle doit s'abstenir d'avoir des rapports sexuels non protégés les trois premiers jours.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"Si le COC est débuté dans les 5 premiers jours des règles, la protection est immédiate (0 jour d'abstinence). S'il est débuté après le 5e jour du cycle, la cliente doit s'abstenir ou utiliser une méthode barrière pendant les 7 premiers jours (et non 3 jours).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"daloa-2__ssr-pf__49\",\"num\":\"50\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"IV. Questions à Choix Double (QCD : Q41 à Q60)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Le coût et la sûreté sont des qualités d'une bonne méthode de contraception.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Vrai\",\"answerLetters\":[\"A\"],\"explanation\":\"Les qualités classiques d'une bonne méthode contraceptive sont : l'efficacité, l'innocuité (sûreté/tolérance), l'acceptabilité, la réversibilité et le coût abordable (accessibilité financière).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"daloa-2__ssr-pf__50\",\"num\":\"51\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"IV. Questions à Choix Double (QCD : Q41 à Q60)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Le moment propice pour le counseling initial se situe à la phase active du travail.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"En phase active du travail d'accouchement, la parturiente souffre de contractions intenses et n'est pas en mesure d'assimiler les informations ni de faire un choix libre et éclairé. Le counseling initial sur la PF du post-partum doit se faire pendant les Consultations Prénatales (CPN), éventuellement en début de phase de latence ou après l'accouchement.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"daloa-2__ssr-pf__51\",\"num\":\"52\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"IV. Questions à Choix Double (QCD : Q41 à Q60)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"L'utilisateur du préservatif doit toujours associer un spermicide.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"Le préservatif masculin ou féminin correctement utilisé se suffit à lui-même et ne nécessite pas l'adjonction systématique d'un spermicide (l'usage répété de nonoxynol-9 pouvant même irriter la muqueuse vaginale).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"daloa-2__ssr-pf__52\",\"num\":\"53\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"IV. Questions à Choix Double (QCD : Q41 à Q60)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Le counseling sur la contraception est important parce que la cliente ne sait pas ce qu'elle voudrait et c'est vous qui devez lui dire quelle méthode choisir.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"Le principe éthique fondamental du counseling en PF est le choix libre et éclairé de la cliente : le prestataire informe, conseille et vérifie l'éligibilité médicale, mais ne décide jamais à la place de la cliente.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"daloa-2__ssr-pf__53\",\"num\":\"54\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"IV. Questions à Choix Double (QCD : Q41 à Q60)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"La planification familiale résout tous les problèmes de développement.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"Bien que la planification familiale contribue fortement au dividende démographique, à la réduction de la mortalité maternelle/infantile et au bien-être socio-économique des familles, elle ne résout pas à elle seule « tous » les problèmes de développement.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"daloa-2__ssr-pf__54\",\"num\":\"55\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"IV. Questions à Choix Double (QCD : Q41 à Q60)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Si on planifie l'insertion du DIU post-placentaire après un accouchement par voie basse, il est conseillé de faire une délivrance artificielle.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"L'insertion d'un DIU post-placentaire (dans les 10 minutes suivant l'expulsion du placenta) se fait après une délivrance normale (GATPA : Gestion Active de la Troisième Période de l'Accouchement) ; on ne pratique jamais une délivrance artificielle sans indication obstétricale uniquement pour poser un DIU.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"daloa-2__ssr-pf__55\",\"num\":\"56\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"IV. Questions à Choix Double (QCD : Q41 à Q60)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"En cas de rupture de préservatif sans usage de spermicide, la cliente ne doit pas faire sa toilette intime avant six heures.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"Le délai de 6 heures avant toute douche vaginale concerne l'utilisation d'un spermicide ou d'un diaphragme avec spermicide (pour laisser au principe actif le temps d'immobiliser les spermatozoïdes). En cas de rupture de préservatif sans spermicide, la conduite à tenir est la prise rapide d'une Contraception d'Urgence (et l'évaluation du risque IST/VIH pour une prophylaxie post-exposition).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"daloa-2__ssr-pf__56\",\"num\":\"57\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"IV. Questions à Choix Double (QCD : Q41 à Q60)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Il n'y a aucun effet secondaire systémique lors de l'usage du préservatif.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Vrai\",\"answerLetters\":[\"A\"],\"explanation\":\"Le préservatif étant une méthode barrière purement mécanique et locale dépourvue d'hormones, il n'entraîne aucun effet secondaire systémique (général/métabolique) dans l'organisme (seule une allergie locale au latex ou au lubrifiant peut rarement s'observer).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"daloa-2__ssr-pf__57\",\"num\":\"58\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"IV. Questions à Choix Double (QCD : Q41 à Q60)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"À la puberté, les filles sont exposées au harcèlement sexuel.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Vrai\",\"answerLetters\":[\"A\"],\"explanation\":\"Avec l'apparition des caractères sexuels secondaires à la puberté, les adolescentes deviennent particulièrement vulnérables au harcèlement sexuel, aux abus, aux grossesses précoces et aux IST, ce qui justifie l'éducation complète à la sexualité et la protection des droits des adolescentes.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"daloa-2__ssr-pf__58\",\"num\":\"59\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"IV. Questions à Choix Double (QCD : Q41 à Q60)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Le processus d'adoption de nouveaux comportements comporte cinq étapes.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Vrai\",\"answerLetters\":[\"A\"],\"explanation\":\"En Communication pour le Changement de Comportement (CCC), le processus d'adoption d'un nouveau comportement comporte classiquement 5 étapes : 1) Prise de conscience / Connaissance, 2) Intérêt / Approbation, 3) Intention / Décision, 4) Essai / Pratique, et 5) Adoption durable / Plaidoyer.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"daloa-2__ssr-pf__59\",\"num\":\"60\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"IV. Questions à Choix Double (QCD : Q41 à Q60)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"La progestérone contenue dans le JADELLE est la même que celle de l'IMPLANON NXT.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"Le Jadelle® (2 bâtonnets, durée 5 ans) contient du Lévonorgestrel (150 mg au total, soit 2 × 75 mg), tandis que l'Implanon NXT® (1 bâtonnet, durée 3 ans) contient de l'Étonogestrel (68 mg). Ce ne sont donc pas les mêmes progestatifs. +-----------------------------------------------------------------------+ Épreuves : Santé Publique Version A (Q1-Q45) | Pédiatrie Bloc A (Q1-Q47) | Gynécologie (Q1-Q34) | Planification Familiale (Q1-Q53) +=======================================================================+ +-----------------------------------------------------------------------+ +-----------------------------------------------------------------------+\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null}]}]},{\"name\":\"KORHOGO (S2 : 2025)\",\"slug\":\"korhogo-2\",\"session\":\"S2\",\"annee\":2025,\"existe\":true,\"sujets\":[{\"name\":\"Gynéco-obstétrique\",\"slug\":\"gynecologie-obstetrique\",\"pages\":\"\",\"count\":34,\"session\":\"S2\",\"annee\":2025,\"source\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"questions\":[{\"id\":\"korhogo-2__gynecologie-obstetrique__0\",\"num\":\"1\",\"type\":\"CAS_CLINIQUE\",\"typeLabel\":\"Étude de cas / Cas clinique\",\"partieTitle\":null,\"caseTitle\":\"Cas clinique N°1 — Mme C.C.C. (Q1 à Q7)\",\"caseData\":null,\"text\":\"Chez Mme C.C.C., il s'agit de quel type de rupture spontanée des membranes ?\",\"options\":[{\"letter\":\"A\",\"text\":\"Rupture tempestive des membranes (à dilatation complète)\"},{\"letter\":\"B\",\"text\":\"Rupture précoce des membranes (pendant le travail avant dilatation complète)\"},{\"letter\":\"C\",\"text\":\"Rupture à temps des membranes\"},{\"letter\":\"D\",\"text\":\"Rupture prématurée des membranes (avant tout début de travail)\"}],\"mode\":\"mcq\",\"multi\":true,\"answer\":\"A et C\",\"answerLetters\":[\"A\",\"C\"],\"explanation\":\"Rappel des définitions obstétricales exactes selon le moment de la rupture spontanée des membranes : 1) Avant tout début de travail = Rupture Prématurée des Membranes (RPM : D) ; 2) Pendant le travail mais avant dilatation complète = Rupture précoce (B) ; 3) À dilatation complète (10 cm) = Rupture tempestive ou à temps (A/C).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"korhogo-2__gynecologie-obstetrique__1\",\"num\":\"2\",\"type\":\"CAS_CLINIQUE\",\"typeLabel\":\"Étude de cas / Cas clinique\",\"partieTitle\":null,\"caseTitle\":\"Cas clinique N°1 — Mme C.C.C. (Q1 à Q7)\",\"caseData\":null,\"text\":\"En fonction de l'histoire du travail d'accouchement de Mme C.C.C., relever les 2 affirmations exactes parmi les propositions ci-dessous :\",\"options\":[{\"letter\":\"A\",\"text\":\"Le nouveau-né de Mme C.C.C. a un bon score d'Apgar à la naissance\"},{\"letter\":\"B\",\"text\":\"Il y avait une procidence du cordon ombilical du 2ème degré ou stade 2\"},{\"letter\":\"C\",\"text\":\"Il y avait une procidence du cordon ombilical du 1er degré ou stade 1\"},{\"letter\":\"D\",\"text\":\"Le nouveau-né de Mme C.C.C. a un mauvais score d'Apgar à la naissance\"},{\"letter\":\"E\",\"text\":\"Devant toute procidence du cordon ombilical, il ne faut pas apprécier la vitalité du fœtus en palpant le cordon ombilical pour voir s'il bat\"},{\"letter\":\"F\",\"text\":\"Il y avait une procidence du cordon ombilical du 1er degré ou stade 1\"}],\"mode\":\"mcq\",\"multi\":true,\"answer\":\"C et F\",\"answerLetters\":[\"C\",\"F\"],\"explanation\":\"Rappel de la classification de la procidence du cordon après rupture des membranes : 1er degré (stade 1) = cordon dans le vagin sans franchir la vulve (C/F) ; 2e degré = cordon affleurant à la vulve (B) ; 3e degré = cordon extériorisé hors de la vulve. (E est faux car il faut toujours palper le cordon entre deux contractions pour vérifier s'il bat).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"korhogo-2__gynecologie-obstetrique__2\",\"num\":\"3\",\"type\":\"CAS_CLINIQUE\",\"typeLabel\":\"Étude de cas / Cas clinique\",\"partieTitle\":null,\"caseTitle\":\"Cas clinique N°1 — Mme C.C.C. (Q1 à Q7)\",\"caseData\":null,\"text\":\"À l'examen du placenta, vous avez noté dans le registre d'accouchement les phrases suivantes : (Relever les 2 affirmations qui sont justes)\",\"options\":[{\"letter\":\"A\",\"text\":\"Le poids du placenta est normal car il pèse 600 grammes\"},{\"letter\":\"B\",\"text\":\"Tous les cotylédons sont en place sur la face maternelle du placenta\"},{\"letter\":\"C\",\"text\":\"Tous les cotylédons sont en place sur la face fœtale du placenta\"},{\"letter\":\"D\",\"text\":\"Le poids du placenta est normal (1/6 du poids fœtal, ~500 g)\"},{\"letter\":\"E\",\"text\":\"Tous les cotylédons sont en place sur la face maternelle du placenta\"}],\"mode\":\"mcq\",\"multi\":true,\"answer\":\"B et D\",\"answerLetters\":[\"B\",\"D\"],\"explanation\":\"Anatomiquement, les cotylédons siègent exclusivement sur la FACE MATERNELLE (charnue) du placenta (B/E est vrai, C est faux), et le poids normal d'un placenta à terme est égal à 1/6 du poids de naissance du nouveau-né (soit 500 à 600 g : D/A).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"korhogo-2__gynecologie-obstetrique__3\",\"num\":\"4\",\"type\":\"CAS_CLINIQUE\",\"typeLabel\":\"Étude de cas / Cas clinique\",\"partieTitle\":null,\"caseTitle\":\"Cas clinique N°1 — Mme C.C.C. (Q1 à Q7)\",\"caseData\":null,\"text\":\"Vous voulez éviter que Mme C.C.C. saigne après l'accouchement. Parmi les propositions suivantes, relever celle qui est exacte :\",\"options\":[{\"letter\":\"A\",\"text\":\"La traction contrôlée sur le cordon ombilical (T.C.C.) est systématiquement recommandée durant la délivrance juste après la naissance de J1\"},{\"letter\":\"B\",\"text\":\"La délivrance dirigée avec le Syntocinon est recommandée juste après la naissance de J1\"},{\"letter\":\"C\",\"text\":\"La traction contrôlée sur le cordon ombilical (T.C.C.) est l'une des techniques de la G.A.T.P.A.\"},{\"letter\":\"D\",\"text\":\"La traction contrôlée sur le cordon ombilical (T.C.C.) n'est pas systématiquement recommandée durant la délivrance\"},{\"letter\":\"E\",\"text\":\"La T.C.C. est recommandée avant la naissance\"},{\"letter\":\"F\",\"text\":\"La T.C.C. n'est pas une technique de la G.A.T.P.A.\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"C. La traction contrôlée sur le cordon ombilical (T.C.C.) est l'une des techniques de la G.A.T.P.A.\",\"answerLetters\":[\"C\"],\"explanation\":\"En cas de grossesse gémellaire, on ne fait JAMAIS de Syntocinon ni de traction sur le cordon juste après la naissance de J1 (A et B sont faux car il faut d'abord exclure la présence d'un second jumeau et accoucher J2 !). En revanche, la Traction Contrôlée sur le Cordon (TCC) fait bien partie intégrante de la GATPA (C).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"korhogo-2__gynecologie-obstetrique__4\",\"num\":\"5\",\"type\":\"CAS_CLINIQUE\",\"typeLabel\":\"Étude de cas / Cas clinique\",\"partieTitle\":null,\"caseTitle\":\"Cas clinique N°1 — Mme C.C.C. (Q1 à Q7)\",\"caseData\":null,\"text\":\"Aussitôt après la G.A.T.P.A. correctement pratiquée, vous avez décidé de surveiller Mme C.C.C. (Relever l'affirmation correcte) :\",\"options\":[{\"letter\":\"A\",\"text\":\"Je surveille la montée laiteuse en cours chez Mme C.C.C.\"},{\"letter\":\"B\",\"text\":\"Je surveille la survenue d'un ictère et l'écoulement sanguin vulvaire\"},{\"letter\":\"C\",\"text\":\"Je surveille les varices, la TA, les œdèmes et la coloration de la muqueuse conjonctivale\"},{\"letter\":\"D\",\"text\":\"L'un des buts de cette surveillance est de dépister et traiter une hémorragie du post-partum immédiat\"},{\"letter\":\"E\",\"text\":\"L'un des buts de cette surveillance est de dépister et traiter une endométrite\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"D. L'un des buts de cette surveillance est de dépister et traiter une hémorragie du post-partum immédiat\",\"answerLetters\":[\"D\"],\"explanation\":\"Aussitôt après la délivrance, la surveillance rapprochée en salle de naissance (toutes les 15 minutes pendant 2 heures) a pour but principal de dépister précocement et de prendre en charge immédiatement une HÉMORRAGIE DU POST-PARTUM IMMÉDIAT (D). (La montée laiteuse A et l'endométrite E ne surviennent qu'à J3–J5).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"korhogo-2__gynecologie-obstetrique__5\",\"num\":\"6\",\"type\":\"CAS_CLINIQUE\",\"typeLabel\":\"Étude de cas / Cas clinique\",\"partieTitle\":null,\"caseTitle\":\"Cas clinique N°1 — Mme C.C.C. (Q1 à Q7)\",\"caseData\":null,\"text\":\"Je dois surveiller attentivement chez Mme C.C.C., dans les 3 heures qui suivent la délivrance, les éléments suivants : (Relever l'affirmation qui est juste)\",\"options\":[{\"letter\":\"A\",\"text\":\"La reprise du transit intestinal (voir si Mme C.C.C. a fait les gaz)\"},{\"letter\":\"B\",\"text\":\"La TA, la vulve et le poids de l'accouchée\"},{\"letter\":\"C\",\"text\":\"Le globe de sécurité\"},{\"letter\":\"D\",\"text\":\"La coloration des conjonctives et les œdèmes de Mme C.C.C.\"},{\"letter\":\"E\",\"text\":\"La reprise du transit intestinal (selles)\"},{\"letter\":\"F\",\"text\":\"Le globe de sécurité, la montée laiteuse chez Mme C.C.C. et son nouveau-né\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"C. Le globe de sécurité\",\"answerLetters\":[\"C\"],\"explanation\":\"Dans les heures qui suivent immédiatement la délivrance, l'élément clinique capital à surveiller (avec le pouls, la TA, la coloration des conjonctives et le saignement vulvaire) est la bonne rétraction utérine : le GLOBE DE SÉCURITÉ de Pinard (utérus dur, ligneux, sous-ombilical : C). Les autres propositions contiennent des intrus (gaz, selles, poids, montée laiteuse).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"korhogo-2__gynecologie-obstetrique__6\",\"num\":\"7\",\"type\":\"CAS_CLINIQUE\",\"typeLabel\":\"Étude de cas / Cas clinique\",\"partieTitle\":null,\"caseTitle\":\"Cas clinique N°1 — Mme C.C.C. (Q1 à Q7)\",\"caseData\":null,\"text\":\"Vers 20h30mn (après la délivrance), Mme C.C.C. saigne abondamment par voie vaginale ; l'utérus est très mou et son fond est situé au-dessus de l'ombilic. (Relever les 2 affirmations qui sont justes) :\",\"options\":[{\"letter\":\"A\",\"text\":\"Il s'agit d'une hémorragie de la délivrance par atonie utérine\"},{\"letter\":\"B\",\"text\":\"Aussitôt, j'organise très rapidement le transfert de Mme C.C.C.\"},{\"letter\":\"C\",\"text\":\"Je prescris rapidement le kit de césarienne en attendant l'arrivée du médecin\"},{\"letter\":\"D\",\"text\":\"Je réalise une délivrance artificielle suivie d'une révision utérine avec massage utérin\"},{\"letter\":\"E\",\"text\":\"Aussitôt, je réalise une révision utérine suivie d'une injection/perfusion intraveineuse de Syntocinon et de massage utérin\"},{\"letter\":\"F\",\"text\":\"Je réalise une délivrance artificielle suivie d'une révision utérine et d'une injection intraveineuse de Syntocinon\"}],\"mode\":\"mcq\",\"multi\":true,\"answer\":\"A et E\",\"answerLetters\":[\"A\",\"E\"],\"explanation\":\"Un saignement abondant après la délivrance avec un utérus gros (au-dessus de l'ombilic) et très mou (perte du globe de sécurité) signe une hémorragie du post-partum par ATONIE (INERTIE) UTÉRINE (A). Comme le placenta a déjà été expulsé, on ne fait pas de délivrance artificielle (D et F sont faux) : on réalise immédiatement une RÉVISION UTÉRINE pour évacuer les caillots/débris, un massage utérin et une perfusion d'ocytocine (Syntocinon : E).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"korhogo-2__gynecologie-obstetrique__7\",\"num\":\"8\",\"type\":\"CAS_CLINIQUE\",\"typeLabel\":\"Étude de cas / Cas clinique\",\"partieTitle\":null,\"caseTitle\":\"Cas clinique N°2 — Mme Y.Y.Y. (Q8 à Q14)\",\"caseData\":null,\"text\":\"En juillet 2014 (avant son opération pour myome utérin), Madame Y.Y.Y. présentait une anomalie de ses règles. Relever le trouble des règles classique du myome utérin :\",\"options\":[{\"letter\":\"A\",\"text\":\"Aménorrhée primaire\"},{\"letter\":\"B\",\"text\":\"Syndrome prémenstruel\"},{\"letter\":\"C\",\"text\":\"Aménorrhée secondaire\"},{\"letter\":\"D\",\"text\":\"Métrorragie\"},{\"letter\":\"E\",\"text\":\"Ménorragie (ou F : Ménométrorragies)\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"E. Ménorragie (ou F : Ménométrorragies)\",\"answerLetters\":[\"E\"],\"explanation\":\"Le trouble du cycle menstruel caractéristique du fibrome (myome) utérin est la MÉNORRAGIE (règles trop abondantes et prolongées : E) ou la ménométrorragie (F).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"korhogo-2__gynecologie-obstetrique__8\",\"num\":\"9\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":null,\"caseTitle\":\"Cas clinique N°2 — Mme Y.Y.Y. (Q8 à Q14)\",\"caseData\":null,\"text\":\"Madame Y.Y.Y., née le 1er septembre 1971, consulte ce jour. Une étudiante en 2e année estime que Mme Y.Y.Y. est ménopausée depuis le 10 septembre 2014 (date de son hystérectomie à 43 ans) et que c'est précoce. Est-ce que cette étudiante a raison ?\",\"options\":[{\"letter\":\"A\",\"text\":\"VRAI\"},{\"letter\":\"B\",\"text\":\"FAUX\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. FAUX\",\"answerLetters\":[\"B\"],\"explanation\":\"L'étudiante a FAUX (B) : l'arrêt des règles dès le 10 septembre 2014 est une aménorrhée chirurgicale définitive par ablation de l'organe cible (hystérectomie), mais pas une ménopause (puisque ses deux ovaires ont été laissés en place et continuaient de sécréter des hormones ovariennes à 43 ans ; de plus, une ménopause précoce ou IOP se définit avant 40 ans).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"korhogo-2__gynecologie-obstetrique__9\",\"num\":\"10\",\"type\":\"CAS_CLINIQUE\",\"typeLabel\":\"Étude de cas / Cas clinique\",\"partieTitle\":null,\"caseTitle\":\"Cas clinique N°2 — Mme Y.Y.Y. (Q8 à Q14)\",\"caseData\":null,\"text\":\"Si l'on suppose qu'une femme a une ménopause chirurgicale/définitive en septembre 2014 (ou une ménopause naturelle), relever la seule explication juste :\",\"options\":[{\"letter\":\"A\",\"text\":\"Madame Y.Y.Y. n'a plus de follicules ovariens fonctionnels à cet âge (définition de la ménopause naturelle)\"},{\"letter\":\"B\",\"text\":\"Le gynécologue a enlevé les 2 ovaires durant l'opération chirurgicale\"},{\"letter\":\"C\",\"text\":\"Le myome utérin a détruit tous les follicules ovariens\"},{\"letter\":\"D\",\"text\":\"Le gynécologue a pratiqué une hystérectomie totale\"},{\"letter\":\"E\",\"text\":\"Le gynécologue a pratiqué une hystérectomie totale en laissant le col utérin\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Madame Y.Y.Y. n'a plus de follicules ovariens fonctionnels à cet âge (définition de la ménopause naturelle)\",\"answerLetters\":[\"A\"],\"explanation\":\"La question demande pourquoi on parlerait de 'ménopause NATURELLE' : la ménopause naturelle résulte exclusivement de l'épuisement physiologique du capital de follicules ovariens fonctionnels (A). (L'ablation chirurgicale des deux ovaires en B donnerait une ménopause chirurgicale/artificielle et non naturelle).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"korhogo-2__gynecologie-obstetrique__10\",\"num\":\"11\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":null,\"caseTitle\":\"Cas clinique N°2 — Mme Y.Y.Y. (Q8 à Q14)\",\"caseData\":null,\"text\":\"Une étudiante en 1re année estime que Madame Y.Y.Y. est ménopausée depuis novembre 2015 (à 44 ans) car cela fait au moins 1 an qu'elle ne voit plus ses règles (depuis son hystérectomie de septembre 2014). Est-ce que cette étudiante a raison ?\",\"options\":[{\"letter\":\"A\",\"text\":\"VRAI\"},{\"letter\":\"B\",\"text\":\"FAUX\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. FAUX\",\"answerLetters\":[\"B\"],\"explanation\":\"L'étudiante a FAUX (B) : chez une femme hystérectomisée (qui n'a plus d'utérus), l'absence de règles depuis 1 an est due à l'absence d'utérus et ne signifie pas que ses ovaires ont cessé de fonctionner !\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"korhogo-2__gynecologie-obstetrique__11\",\"num\":\"12\",\"type\":\"CAS_CLINIQUE\",\"typeLabel\":\"Étude de cas / Cas clinique\",\"partieTitle\":null,\"caseTitle\":\"Cas clinique N°2 — Mme Y.Y.Y. (Q8 à Q14)\",\"caseData\":null,\"text\":\"On suppose que Madame Y.Y.Y. n'est pas ménopausée en novembre 2015, car : (Relever les 2 explications qui sont justes)\",\"options\":[{\"letter\":\"A\",\"text\":\"Madame Y.Y.Y. a encore des follicules ovariens fonctionnels durant cette période\"},{\"letter\":\"B\",\"text\":\"Le gynécologue a enlevé toutes les parties de l'utérus\"},{\"letter\":\"C\",\"text\":\"Le gynécologue n'a pas enlevé les 2 ovaires\"},{\"letter\":\"D\",\"text\":\"Le gynécologue a pratiqué une hystérectomie totale en laissant le col utérin\"}],\"mode\":\"mcq\",\"multi\":true,\"answer\":\"A et C\",\"answerLetters\":[\"A\",\"C\"],\"explanation\":\"Mme Y.Y.Y. n'était pas ménopausée sur le plan endocrinien en novembre 2015 (à 44 ans) parce que le chirurgien n'avait pas enlevé ses 2 ovaires lors de l'hystérectomie (C) et qu'elle possédait encore des follicules ovariens fonctionnels sécrétant des œstrogènes (A).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"korhogo-2__gynecologie-obstetrique__12\",\"num\":\"13\",\"type\":\"CAS_CLINIQUE\",\"typeLabel\":\"Étude de cas / Cas clinique\",\"partieTitle\":null,\"caseTitle\":\"Cas clinique N°2 — Mme Y.Y.Y. (Q8 à Q14)\",\"caseData\":null,\"text\":\"En juillet 2024 (ou après son hystérectomie alors que ses ovaires fonctionnaient encore), quel signe cyclique pouvait-elle encore présenter parmi les propositions ci-dessous ?\",\"options\":[{\"letter\":\"A\",\"text\":\"Aménorrhée primaire\"},{\"letter\":\"B\",\"text\":\"Ménorragies\"},{\"letter\":\"C\",\"text\":\"Ménorragie-métrorragies\"},{\"letter\":\"D\",\"text\":\"Métrorragies\"},{\"letter\":\"E\",\"text\":\"Syndrome prémenstruel (ou aucun saignement car plus d'utérus)\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"E. Syndrome prémenstruel (ou aucun saignement car plus d'utérus)\",\"answerLetters\":[\"E\"],\"explanation\":\"Comme Mme Y.Y.Y. n'a plus d'utérus (hystérectomie), elle ne peut présenter ni ménorragies (B) ni métrorragies d'origine utérine (C, D) ni aménorrhée primaire (A, car elle a déjà eu ses règles avant 2014). En revanche, tant que ses ovaires fonctionnent, elle peut ressentir un syndrome prémenstruel cyclique (tension mammaire : E).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"korhogo-2__gynecologie-obstetrique__13\",\"num\":\"14\",\"type\":\"CAS_CLINIQUE\",\"typeLabel\":\"Étude de cas / Cas clinique\",\"partieTitle\":null,\"caseTitle\":\"Cas clinique N°2 — Mme Y.Y.Y. (Q8 à Q14)\",\"caseData\":null,\"text\":\"En juillet 2024 (à 53 ans, désormais ménopausée avec bouffées de chaleur), Mme Y.Y.Y. (qui a subi une hystérectomie totale et n'a donc plus d'utérus) vous demande de lui proposer le traitement hormonal substitutif (THM) pour prévenir l'ostéoporose. Relever la proposition exacte :\",\"options\":[{\"letter\":\"A\",\"text\":\"Estrogènes associés à un progestatif\"},{\"letter\":\"B\",\"text\":\"Androgènes\"},{\"letter\":\"C\",\"text\":\"Estrogènes seuls\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"C. Estrogènes seuls\",\"answerLetters\":[\"C\"],\"explanation\":\"Règle pharmacologique essentielle du Traitement Hormonal de la Ménopause (THM) : chez une femme non hystérectomisée, on associe obligatoirement un progestatif aux œstrogènes dans l'unique but de protéger l'endomètre contre le cancer de l'endomètre. Mais chez une femme HYSTÉRECTOMISÉE (qui n'a plus d'utérus ni d'endomètre, comme Mme Y.Y.Y.), le progestatif est inutile et délétère (risque mammaire) : on prescrit donc des ŒSTROGÈNES SEULS (C) !\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"korhogo-2__gynecologie-obstetrique__14\",\"num\":\"15\",\"type\":\"CAS_CLINIQUE\",\"typeLabel\":\"Étude de cas / Cas clinique\",\"partieTitle\":null,\"caseTitle\":\"Cas clinique N°3 — Antécédent de déchirure périnéale du 3e degré (Q15\",\"caseData\":\"à Q18)\",\"text\":\"Vous constatez lors de l'examen à 27 SA qu'elle présente une cicatrice périanale douloureuse. Parmi les propositions suivantes, quel est l'élément local essentiel à surveiller pour vous ?\",\"options\":[{\"letter\":\"A\",\"text\":\"La dilatation du col\"},{\"letter\":\"B\",\"text\":\"La vitalité fœtale\"},{\"letter\":\"C\",\"text\":\"Les signes de l'infection (ou de fistule/abcès sur la cicatrice douloureuse, ainsi que la vitalité fœtale et les contractions)\"},{\"letter\":\"D\",\"text\":\"Les contractions utérines\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"C. Les signes de l'infection (ou de fistule/abcès sur la cicatrice douloureuse, ainsi que la vitalité fœtale et les contractions)\",\"answerLetters\":[\"C\"],\"explanation\":\"Devant une cicatrice périanale devenue douloureuse, l'examen local recherche avant tout des signes d'inflammation/infection locale (abcès périnéal, granulome sur fil ou fistule : C), comme le confirme explicitement la Q16.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"korhogo-2__gynecologie-obstetrique__15\",\"num\":\"16\",\"type\":\"CAS_CLINIQUE\",\"typeLabel\":\"Étude de cas / Cas clinique\",\"partieTitle\":null,\"caseTitle\":\"Cas clinique N°3 — Antécédent de déchirure périnéale du 3e degré (Q15\",\"caseData\":\"à Q18)\",\"text\":\"Pour cette patiente, une surveillance particulière est nécessaire en raison de son antécédent de déchirure du périnée. Parmi les propositions suivantes, laquelle est correcte ?\",\"options\":[{\"letter\":\"A\",\"text\":\"Surveiller la cicatrice pour des signes d'infection (et évaluer la continence anale et la souplesse périnéale)\"},{\"letter\":\"B\",\"text\":\"Éviter les examens vaginaux\"},{\"letter\":\"C\",\"text\":\"Assurer une prophylaxie antibiotique\"},{\"letter\":\"D\",\"text\":\"Surveiller uniquement la vitalité fœtale\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Surveiller la cicatrice pour des signes d'infection (et évaluer la continence anale et la souplesse périnéale)\",\"answerLetters\":[\"A\"],\"explanation\":\"La surveillance locale de la cicatrice périnéale et de sa symptomatologie douloureuse/infectieuse ou fonctionnelle sphinctérienne (A) est la seule proposition juste parmi les choix.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"korhogo-2__gynecologie-obstetrique__16\",\"num\":\"17\",\"type\":\"CAS_CLINIQUE\",\"typeLabel\":\"Étude de cas / Cas clinique\",\"partieTitle\":null,\"caseTitle\":\"Cas clinique N°3 — Antécédent de déchirure périnéale du 3e degré (Q15\",\"caseData\":\"à Q18)\",\"text\":\"La patiente exprime des douleurs pelviennes/périnéales importantes lors de la consultation. Quelle est la meilleure approche non invasive de gestion de la douleur pour cette patiente ?\",\"options\":[{\"letter\":\"A\",\"text\":\"Prescription d'analgésiques opiacés\"},{\"letter\":\"B\",\"text\":\"Techniques de relaxation et d'éducation périnéale (massage périnéal, rééducation)\"},{\"letter\":\"C\",\"text\":\"Administration d'antibiotiques\"},{\"letter\":\"D\",\"text\":\"Réalisation d'une échographie\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Techniques de relaxation et d'éducation périnéale (massage périnéal, rééducation)\",\"answerLetters\":[\"B\"],\"explanation\":\"La prise en charge des douleurs cicatricielles périnéales pendant la grossesse privilégie les techniques de relaxation, de massage d'assouplissement périnéal et d'éducation périnéale (B, les opiacés A étant évités).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"korhogo-2__gynecologie-obstetrique__17\",\"num\":\"18\",\"type\":\"CAS_CLINIQUE\",\"typeLabel\":\"Étude de cas / Cas clinique\",\"partieTitle\":null,\"caseTitle\":\"Cas clinique N°3 — Antécédent de déchirure périnéale du 3e degré (Q15\",\"caseData\":\"à Q18)\",\"text\":\"La patiente a des antécédents de déchirure périnéale du 3ème degré (et reste symptomatique avec cicatrice périanale douloureuse). Quels sont les conseils préventifs / modalités que vous pouvez lui donner ?\",\"options\":[{\"letter\":\"A\",\"text\":\"Encourager les exercices de Kegel (et rééducation périnéale D)\"},{\"letter\":\"B\",\"text\":\"Préconiser une césarienne programmée (en cas de périnée complet/3e-4e degré symptomatique ou séquellaire)\"},{\"letter\":\"C\",\"text\":\"Conseiller une épisiotomie prophylactique systématique\"},{\"letter\":\"D\",\"text\":\"Proposer des séances de rééducation périnéale postnatale\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Préconiser une césarienne programmée (en cas de périnée complet/3e-4e degré symptomatique ou séquellaire)\",\"answerLetters\":[\"B\"],\"explanation\":\"En obstétrique, chez une patiente ayant un antécédent de déchirure périnéale complète (3e ou 4e degré) restant symptomatique (douleurs périanales ou troubles de la continence), une césarienne programmée est recommandée pour éviter la récidive et l'incontinence anale définitive (B), associée aux exercices de renforcement pelvi-périnéal de Kegel (A) et à la rééducation postnatale (D).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"korhogo-2__gynecologie-obstetrique__18\",\"num\":\"19\",\"type\":\"CAS_CLINIQUE\",\"typeLabel\":\"Étude de cas / Cas clinique\",\"partieTitle\":null,\"caseTitle\":\"Cas clinique N°4 — Mme Z.Z.Z., 40 ans, infertilité primaire (Q19 à\",\"caseData\":\"Q22)\",\"text\":\"Mme Z.Z.Z., 40 ans, est en consultation pour une infertilité primaire avec cycles irréguliers et douleurs pelviennes. Quel est l'examen d'imagerie de première intention que vous recommanderiez ?\",\"options\":[{\"letter\":\"A\",\"text\":\"Hystérosalpingographie\"},{\"letter\":\"B\",\"text\":\"Échographie pelvienne\"},{\"letter\":\"C\",\"text\":\"Test de Hühner\"},{\"letter\":\"D\",\"text\":\"Laparoscopie\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Échographie pelvienne\",\"answerLetters\":[\"B\"],\"explanation\":\"L'échographie pelvienne (sus-pubienne et endovaginale : B) est l'examen d'imagerie de première intention indispensable pour explorer l'utérus, les ovaires (compte des follicules antraux, endométriomes) et les annexes devant une infertilité associée à des douleurs pelviennes.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"korhogo-2__gynecologie-obstetrique__19\",\"num\":\"20\",\"type\":\"CAS_CLINIQUE\",\"typeLabel\":\"Étude de cas / Cas clinique\",\"partieTitle\":null,\"caseTitle\":\"Cas clinique N°4 — Mme Z.Z.Z., 40 ans, infertilité primaire (Q19 à\",\"caseData\":\"Q22)\",\"text\":\"Mme Z.Z.Z. a un test de Hühner anormal. Quelle est la prochaine étape dans le bilan diagnostique féminin (exploration de la cavité utérine et des trompes / bilan hormonal) ?\",\"options\":[{\"letter\":\"A\",\"text\":\"Réaliser une hystérosalpingographie (et un spermogramme chez le conjoint)\"},{\"letter\":\"B\",\"text\":\"Effectuer un dosage hormonal\"},{\"letter\":\"C\",\"text\":\"Prescrire une laparoscopie\"},{\"letter\":\"D\",\"text\":\"Réaliser un bilan sanguin complet\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Réaliser une hystérosalpingographie (et un spermogramme chez le conjoint)\",\"answerLetters\":[\"A\"],\"explanation\":\"Dans le bilan d'infertilité féminine, l'exploration se poursuit par l'hystérosalpingographie (A, pour vérifier la cavité utérine et la perméabilité tubaire) et le bilan hormonal ovarien (B, FSH, LH, œstradiol, AMH devant des cycles irréguliers à 40 ans).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"korhogo-2__gynecologie-obstetrique__20\",\"num\":\"21\",\"type\":\"CAS_CLINIQUE\",\"typeLabel\":\"Étude de cas / Cas clinique\",\"partieTitle\":null,\"caseTitle\":\"Cas clinique N°4 — Mme Z.Z.Z., 40 ans, infertilité primaire (Q19 à\",\"caseData\":\"Q22)\",\"text\":\"Mme Z.Z.Z. a des douleurs pelviennes persistantes malgré une thérapie médicamenteuse. Quel examen complémentaire d'imagerie de seconde intention est le plus approprié pour évaluer précisément une pathologie pelvienne profonde (endométriose) ?\",\"options\":[{\"letter\":\"A\",\"text\":\"IRM pelvienne\"},{\"letter\":\"B\",\"text\":\"Échographie transabdominale\"},{\"letter\":\"C\",\"text\":\"Test de réserve ovarienne\"},{\"letter\":\"D\",\"text\":\"Hystéroscopie\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. IRM pelvienne\",\"answerLetters\":[\"A\"],\"explanation\":\"Devant des douleurs pelviennes chroniques faisant suspecter une endométriose (confirmée à la Q22), l'IRM pelvienne (A) est l'examen d'imagerie de référence pour cartographier les lésions d'endométriose pelvienne profonde et ovarienne.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"korhogo-2__gynecologie-obstetrique__21\",\"num\":\"22\",\"type\":\"CAS_CLINIQUE\",\"typeLabel\":\"Étude de cas / Cas clinique\",\"partieTitle\":null,\"caseTitle\":\"Cas clinique N°4 — Mme Z.Z.Z., 40 ans, infertilité primaire (Q19 à\",\"caseData\":\"Q22)\",\"text\":\"Pour Mme Z.Z.Z., le diagnostic final de l'infertilité a révélé une endométriose. Quelle est la prise en charge recommandée pour cette condition ?\",\"options\":[{\"letter\":\"A\",\"text\":\"Traitement hormonal et chirurgie laparoscopique (cœlioscopie)\"},{\"letter\":\"B\",\"text\":\"Traitement antibiotique et repos\"},{\"letter\":\"C\",\"text\":\"Thérapie par ovulation et insémination artificielle\"},{\"letter\":\"D\",\"text\":\"Thérapie physique et exercices de relaxation\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Traitement hormonal et chirurgie laparoscopique (cœlioscopie)\",\"answerLetters\":[\"A\"],\"explanation\":\"Le traitement classique de l'endométriose symptomatique repose sur le traitement médical hormonal (pour soulager les douleurs) et la chirurgie conservatrice par laparoscopie/cœlioscopie (exérèse des lésions et kystectomie d'endométriome pour restaurer la fertilité : A), complétée si besoin par l'assistance médicale à la procréation (C).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"korhogo-2__gynecologie-obstetrique__22\",\"num\":\"23\",\"type\":\"CAS_CLINIQUE\",\"typeLabel\":\"Étude de cas / Cas clinique\",\"partieTitle\":null,\"caseTitle\":\"Cas clinique N°5 — Pré-éclampsie à 32 SA (Q23 à Q26)\",\"caseData\":null,\"text\":\"Une femme de 28 ans, enceinte de 32 semaines, se présente avec des symptômes de pré-éclampsie. Quels sont les signes cliniques/paracliniques de la pré-éclampsie que vous devez surveiller ?\",\"options\":[{\"letter\":\"A\",\"text\":\"Hypertension artérielle, œdèmes, protéinurie\"},{\"letter\":\"B\",\"text\":\"Fièvre, leucorrhées, douleur abdominale\"},{\"letter\":\"C\",\"text\":\"Hypotension, perte de poids, vertiges\"},{\"letter\":\"D\",\"text\":\"Tachycardie, céphalées, hyperglycémie\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Hypertension artérielle, œdèmes, protéinurie\",\"answerLetters\":[\"A\"],\"explanation\":\"La triade classique de la pré-éclampsie (toxémie gravidique après 20 SA) associe : Hypertension artérielle (TA ≥ 140/90 mmHg), Protéinurie significative (≥ 300 mg/24h ou ≥ ++ à la bandelette) et Œdèmes d'apparition rapide (A).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"korhogo-2__gynecologie-obstetrique__23\",\"num\":\"24\",\"type\":\"CAS_CLINIQUE\",\"typeLabel\":\"Étude de cas / Cas clinique\",\"partieTitle\":null,\"caseTitle\":\"Cas clinique N°5 — Pré-éclampsie à 32 SA (Q23 à Q26)\",\"caseData\":null,\"text\":\"La patiente avec pré-éclampsie nécessite une surveillance étroite. Quelle est la meilleure option pour le suivi ?\",\"options\":[{\"letter\":\"A\",\"text\":\"Surveillance ambulatoire avec prise quotidienne de la TA\"},{\"letter\":\"B\",\"text\":\"Hospitalisation pour surveillance continue (maternelle et fœtale)\"},{\"letter\":\"C\",\"text\":\"Suivi hebdomadaire en consultation externe\"},{\"letter\":\"D\",\"text\":\"Surveillance à domicile avec un moniteur de TA\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Hospitalisation pour surveillance continue (maternelle et fœtale)\",\"answerLetters\":[\"B\"],\"explanation\":\"Toute pré-éclampsie diagnostiquée à 32 SA impose une HOSPITALISATION immédiate (B) pour bilan de gravité materno-fœtal, traitement antihypertenseur, maturation pulmonaire fœtale (corticothérapie) et surveillance étroite.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"korhogo-2__gynecologie-obstetrique__24\",\"num\":\"25\",\"type\":\"CAS_CLINIQUE\",\"typeLabel\":\"Étude de cas / Cas clinique\",\"partieTitle\":null,\"caseTitle\":\"Cas clinique N°5 — Pré-éclampsie à 32 SA (Q23 à Q26)\",\"caseData\":null,\"text\":\"Quelle est la complication majeure associée à la pré-éclampsie sévère que vous devez anticiper ?\",\"options\":[{\"letter\":\"A\",\"text\":\"Détachement placentaire (Hématome Rétroplacentaire - HRP)\"},{\"letter\":\"B\",\"text\":\"Hémorragie post-partum\"},{\"letter\":\"C\",\"text\":\"Infection urinaire\"},{\"letter\":\"D\",\"text\":\"Syndrome de Down\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Détachement placentaire (Hématome Rétroplacentaire - HRP)\",\"answerLetters\":[\"A\"],\"explanation\":\"L'Hématome Rétroplacentaire (HRP ou décollement prématuré d'un placenta normalement inséré : A), avec l'éclampsie et le HELLP syndrome, est la complication aiguë redoutable de la pré-éclampsie sévère.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"korhogo-2__gynecologie-obstetrique__25\",\"num\":\"26\",\"type\":\"CAS_CLINIQUE\",\"typeLabel\":\"Étude de cas / Cas clinique\",\"partieTitle\":null,\"caseTitle\":\"Cas clinique N°5 — Pré-éclampsie à 32 SA (Q23 à Q26)\",\"caseData\":null,\"text\":\"Quelle est la prise en charge initiale recommandée pour une patiente présentant une pré-éclampsie sévère ?\",\"options\":[{\"letter\":\"A\",\"text\":\"Administration de sulfate de magnésium (prévention de l'éclampsie), antihypertenseurs et extraction fœtale / induction selon le terme\"},{\"letter\":\"B\",\"text\":\"Prescription de diurétiques et repos au lit\"},{\"letter\":\"C\",\"text\":\"Traitement antibiotique et surveillance de la TA\"},{\"letter\":\"D\",\"text\":\"Prescription d'antihypertenseurs et suivi en consultation externe\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Administration de sulfate de magnésium (prévention de l'éclampsie), antihypertenseurs et extraction fœtale / induction selon le terme\",\"answerLetters\":[\"A\"],\"explanation\":\"En cas de pré-éclampsie sévère, la prise en charge d'urgence repose sur l'administration de Sulfate de Magnésium (pour prévenir la crise d'éclampsie), le contrôle tensionnel par antihypertenseur IV et l'arrêt de la grossesse (extraction fœtale : A). Les diurétiques (B) sont contre-indiqués sauf en cas d'OAP.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"korhogo-2__gynecologie-obstetrique__26\",\"num\":\"27\",\"type\":\"CAS_CLINIQUE\",\"typeLabel\":\"Étude de cas / Cas clinique\",\"partieTitle\":null,\"caseTitle\":\"Cas clinique N°6 — Diabète gestationnel (Q27 à Q30)\",\"caseData\":null,\"text\":\"Mme X.X.X. se présente pour une consultation prénatale avec des antécédents de diabète gestationnel. Quelle est l'option de dépistage de référence recommandée pour le diabète gestationnel ?\",\"options\":[{\"letter\":\"A\",\"text\":\"Test de tolérance au glucose (TTGO / HGPO à 75 g de glucose entre 24 et 28 SA, précédé d'une glycémie à jeun au 1er trimestre)\"},{\"letter\":\"B\",\"text\":\"Glycémie à jeun\"},{\"letter\":\"C\",\"text\":\"Dosage de l'hémoglobine glyquée\"},{\"letter\":\"D\",\"text\":\"Test de dépistage de la protéinurie\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Test de tolérance au glucose (TTGO / HGPO à 75 g de glucose entre 24 et 28 SA, précédé d'une glycémie à jeun au 1er trimestre)\",\"answerLetters\":[\"A\"],\"explanation\":\"Le test diagnostique de référence du diabète gestationnel est l'épreuve d'Hyperglycémie Provoquée par Voie Orale (HGPO / Test de tolérance au glucose à 75 g : A) réalisée entre 24 et 28 SA (après une glycémie à jeun dès le 1er trimestre).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"korhogo-2__gynecologie-obstetrique__27\",\"num\":\"28\",\"type\":\"CAS_CLINIQUE\",\"typeLabel\":\"Étude de cas / Cas clinique\",\"partieTitle\":null,\"caseTitle\":\"Cas clinique N°6 — Diabète gestationnel (Q27 à Q30)\",\"caseData\":null,\"text\":\"Mme X.X.X. a un test de tolérance au glucose anormal (diabète gestationnel confirmé). Quel est le traitement initial de première intention recommandé ?\",\"options\":[{\"letter\":\"A\",\"text\":\"Régime alimentaire (mesures hygiéno-diététiques) et exercice physique adapté\"},{\"letter\":\"B\",\"text\":\"Médication orale antidiabétique\"},{\"letter\":\"C\",\"text\":\"Insulinothérapie immédiatement\"},{\"letter\":\"D\",\"text\":\"Répétition du test de tolérance au glucose\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Régime alimentaire (mesures hygiéno-diététiques) et exercice physique adapté\",\"answerLetters\":[\"A\"],\"explanation\":\"La prise en charge de première intention de tout diabète gestationnel repose sur les mesures hygiéno-diététiques : régime alimentaire normocalorique fractionné à index glycémique bas et activité physique régulière adaptée (A) avec autosurveillance glycémique. L'insulinothérapie (C) n'est introduite qu'en seconde intention si les objectifs glycémiques ne sont pas atteints après 7 à 10 jours de régime (et les antidiabétiques oraux B sont contre-indiqués).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"korhogo-2__gynecologie-obstetrique__28\",\"num\":\"29\",\"type\":\"CAS_CLINIQUE\",\"typeLabel\":\"Étude de cas / Cas clinique\",\"partieTitle\":null,\"caseTitle\":\"Cas clinique N°6 — Diabète gestationnel (Q27 à Q30)\",\"caseData\":null,\"text\":\"Quel est le principal objectif du traitement du diabète gestationnel chez Mme X.X.X. ?\",\"options\":[{\"letter\":\"A\",\"text\":\"Prévenir les complications maternelles et fœtales\"},{\"letter\":\"B\",\"text\":\"Réduire les symptômes d'inconfort maternel\"},{\"letter\":\"C\",\"text\":\"Accélérer le travail\"},{\"letter\":\"D\",\"text\":\"Prévenir l'accouchement prématuré\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Prévenir les complications maternelles et fœtales\",\"answerLetters\":[\"A\"],\"explanation\":\"L'équilibration stricte des glycémies vise à prévenir les complications fœto-maternelles : macrosomie fœtale, hydramnios, dystocie des épaules, mort fœtale in utero, hypoglycémie néonatale, pré-éclampsie et césarienne (A).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"korhogo-2__gynecologie-obstetrique__29\",\"num\":\"30\",\"type\":\"CAS_CLINIQUE\",\"typeLabel\":\"Étude de cas / Cas clinique\",\"partieTitle\":null,\"caseTitle\":\"Cas clinique N°6 — Diabète gestationnel (Q27 à Q30)\",\"caseData\":null,\"text\":\"Quelle est la complication fœtale la plus fréquente associée au diabète gestationnel non contrôlé ?\",\"options\":[{\"letter\":\"A\",\"text\":\"Macrosomie fœtale\"},{\"letter\":\"B\",\"text\":\"Prématurité\"},{\"letter\":\"C\",\"text\":\"Hypotrophie fœtale\"},{\"letter\":\"D\",\"text\":\"Malformations congénitales\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Macrosomie fœtale\",\"answerLetters\":[\"A\"],\"explanation\":\"L'hyperglycémie maternelle traverse le placenta et provoque un hyperinsulinisme fœtal réactionnel (l'insuline agissant comme hormone de croissance anabolisante), ce qui entraîne une MACROSOMIE FŒTALE (poids de naissance > 4 000 g : A).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"korhogo-2__gynecologie-obstetrique__30\",\"num\":\"31\",\"type\":\"CAS_CLINIQUE\",\"typeLabel\":\"Étude de cas / Cas clinique\",\"partieTitle\":null,\"caseTitle\":\"Cas clinique N°7 — Infection urinaire pendant la grossesse (Q31 à Q34)\",\"caseData\":null,\"text\":\"Mme T.T.T. se présente avec une infection urinaire asymptomatique (bactériurie asymptomatique). Quelle est la gestion recommandée pour cette condition pendant la grossesse ?\",\"options\":[{\"letter\":\"A\",\"text\":\"Traitement antibiotique approprié après antibiogramme\"},{\"letter\":\"B\",\"text\":\"Surveillance sans traitement\"},{\"letter\":\"C\",\"text\":\"Prescription de diurétiques\"},{\"letter\":\"D\",\"text\":\"Repos au lit et hydratation\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Traitement antibiotique approprié après antibiogramme\",\"answerLetters\":[\"A\"],\"explanation\":\"Contrairement à la femme non enceinte, toute bactériurie asymptomatique chez la femme enceinte doit impérativement être traitée par une antibiothérapie adaptée à l'antibiogramme (A), car non traitée elle évolue dans 20 à 40 % des cas vers une pyélonéphrite aiguë gravidique.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"korhogo-2__gynecologie-obstetrique__31\",\"num\":\"32\",\"type\":\"CAS_CLINIQUE\",\"typeLabel\":\"Étude de cas / Cas clinique\",\"partieTitle\":null,\"caseTitle\":\"Cas clinique N°7 — Infection urinaire pendant la grossesse (Q31 à Q34)\",\"caseData\":null,\"text\":\"Mme T.T.T. a reçu un traitement antibiotique pour son infection urinaire. Quelle est la surveillance post-traitement essentielle ?\",\"options\":[{\"letter\":\"A\",\"text\":\"Répétition du test urinaire (ECBU de contrôle) pour s'assurer de l'éradication de l'infection\"},{\"letter\":\"B\",\"text\":\"Surveillance de la pression artérielle\"},{\"letter\":\"C\",\"text\":\"Suivi des mouvements fœtaux\"},{\"letter\":\"D\",\"text\":\"Évaluation de la fonction hépatique\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Répétition du test urinaire (ECBU de contrôle) pour s'assurer de l'éradication de l'infection\",\"answerLetters\":[\"A\"],\"explanation\":\"Après le traitement d'une infection urinaire gravidique, il est obligatoire de réaliser un ECBU de contrôle 8 à 10 jours après la fin de l'antibiothérapie (puis tous les mois jusqu'à l'accouchement) pour vérifier la stérilisation des urines (A).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"korhogo-2__gynecologie-obstetrique__32\",\"num\":\"33\",\"type\":\"CAS_CLINIQUE\",\"typeLabel\":\"Étude de cas / Cas clinique\",\"partieTitle\":null,\"caseTitle\":\"Cas clinique N°7 — Infection urinaire pendant la grossesse (Q31 à Q34)\",\"caseData\":null,\"text\":\"Quel est le principal facteur de risque anatomique/physiologique pour le développement d'une infection urinaire pendant la grossesse ?\",\"options\":[{\"letter\":\"A\",\"text\":\"Compression urinaire (urétérale) par l'utérus gravide (et hypotonie progestative)\"},{\"letter\":\"B\",\"text\":\"Antécédents familiaux d'infection urinaire\"},{\"letter\":\"C\",\"text\":\"Augmentation du pH vaginal\"},{\"letter\":\"D\",\"text\":\"Consommation excessive de caféine\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Compression urinaire (urétérale) par l'utérus gravide (et hypotonie progestative)\",\"answerLetters\":[\"A\"],\"explanation\":\"La compression mécanique des uretères (surtout à droite par dextrorotation utérine) par l'utérus gravide, associée au relâchement musculaire lisse induit par la progestérone, entraîne une stase urinaire pyélo-calicielle qui favorise la pullulation bactérienne (A).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"korhogo-2__gynecologie-obstetrique__33\",\"num\":\"34\",\"type\":\"CAS_CLINIQUE\",\"typeLabel\":\"Étude de cas / Cas clinique\",\"partieTitle\":null,\"caseTitle\":\"Cas clinique N°7 — Infection urinaire pendant la grossesse (Q31 à Q34)\",\"caseData\":null,\"text\":\"Quelle est la complication maternelle directe d'une infection urinaire basse (ou bactériurie asymptomatique) non traitée pendant la grossesse ?\",\"options\":[{\"letter\":\"A\",\"text\":\"Pyélonéphrite aiguë (et C : Prématurité comme complication obstétricale)\"},{\"letter\":\"B\",\"text\":\"Hyperemesis gravidarum\"},{\"letter\":\"C\",\"text\":\"Prématurité\"},{\"letter\":\"D\",\"text\":\"Décollement placentaire\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Pyélonéphrite aiguë (et C : Prématurité comme complication obstétricale)\",\"answerLetters\":[\"A\"],\"explanation\":\"Une bactériurie asymptomatique ou une cystite non traitée se complique directement par voie ascendante de PYÉLONÉPHRITE AIGUË (A), qui elle-même expose au risque obstétrical d'accouchement prématuré (C). +-----------------------------------------------------------------------+\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null}]},{\"name\":\"SSR / PF\",\"slug\":\"ssr-pf\",\"pages\":\"\",\"count\":53,\"session\":\"S2\",\"annee\":2025,\"source\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"questions\":[{\"id\":\"korhogo-2__ssr-pf__0\",\"num\":\"1\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"Questions à Choix Multiples de Planification Familiale (Q1 à Q53)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Madame SORO, 25 ans, a bénéficié d'une insertion de dispositif intra-utérin (DIU) après un avortement intentionnel. Trois semaines plus tard, elle se présente en consultation pour des pertes vaginales anormales accompagnées d'une légère fièvre. Quelle sera votre conduite à tenir en premier ?\",\"options\":[{\"letter\":\"A\",\"text\":\"Retirer le DIU\"},{\"letter\":\"B\",\"text\":\"Référer madame SORO\"},{\"letter\":\"C\",\"text\":\"Faire un examen gynécologique\"},{\"letter\":\"D\",\"text\":\"Rechercher les fils du DIU\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"C. Faire un examen gynécologique\",\"answerLetters\":[\"C\"],\"explanation\":\"Devant toute plainte gynécologique (leucorrhées anormales + fièvre) chez une porteuse de DIU, la première étape indispensable avant toute décision est de réaliser un examen gynécologique complet (examen au spéculum et toucher vaginal : c) pour poser le diagnostic (vaginite, cervicite ou endométrite/salpingite).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"korhogo-2__ssr-pf__1\",\"num\":\"2\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"Questions à Choix Multiples de Planification Familiale (Q1 à Q53)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"À la suite de votre investigation, le diagnostic de madame SORO est une endométrite (légère à modérée sous DIU). Quelles seront vos trois activités ? (Choisir 3 réponses)\",\"options\":[{\"letter\":\"A\",\"text\":\"Donner un antalgique et un antipyrétique\"},{\"letter\":\"B\",\"text\":\"Conseiller une autre méthode de contraception à la patiente\"},{\"letter\":\"C\",\"text\":\"Revoir la patiente aux prochaines règles\"},{\"letter\":\"D\",\"text\":\"Faire une antibiothérapie pendant 10 à 14 jours\"},{\"letter\":\"E\",\"text\":\"Surveiller la patiente pendant 48 à 72 heures puis prendre une décision (maintenir le DIU si amélioration ou le retirer sous couverture antibiotique si absence d'amélioration)\"}],\"mode\":\"mcq\",\"multi\":true,\"answer\":\"A et D et E\",\"answerLetters\":[\"A\",\"D\",\"E\"],\"explanation\":\"Selon les directives de l'OMS pour une infection génitale haute (endométrite/salpingite légère à modérée) chez une utilisatrice de DIU : on instaure immédiatement une antibiothérapie appropriée (d) associée à un antalgique/antipyrétique (a), et il n'est pas nécessaire de retirer d'emblée le DIU si la patiente souhaite le garder : on surveille l'évolution clinique à 48–72 heures (e) et on ne retire le DIU (après début des antibiotiques en conseillant une autre méthode b) que s'il n'y a pas d'amélioration clinique.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"korhogo-2__ssr-pf__2\",\"num\":\"3\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"Questions à Choix Multiples de Planification Familiale (Q1 à Q53)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Les contraceptifs oraux combinés (COC) monophasiques contiennent :\",\"options\":[{\"letter\":\"A\",\"text\":\"La même quantité d'œstrogène et de progestatif dans chaque pilule active\"},{\"letter\":\"B\",\"text\":\"Deux différentes combinaisons d'œstrogène et de progestatif\"},{\"letter\":\"C\",\"text\":\"Trois différentes combinaisons d'œstrogène et de progestatif\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. La même quantité d'œstrogène et de progestatif dans chaque pilule active\",\"answerLetters\":[\"A\"],\"explanation\":\"Une pilule combinée MONOPHASIQUE (ex. Lo-Femenal, Microgynon) contient exactement la même dose constante d'œstrogène et de progestatif dans chacun des 21 comprimés actifs de la plaquette (a). (b définit une pilule biphasique et c une pilule triphasique).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"korhogo-2__ssr-pf__3\",\"num\":\"4\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"Questions à Choix Multiples de Planification Familiale (Q1 à Q53)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"La MAMA est considérée comme une méthode contraceptive très efficace pendant les :\",\"options\":[{\"letter\":\"A\",\"text\":\"Trois premiers mois du post-partum\"},{\"letter\":\"B\",\"text\":\"Six premiers mois du post-partum\"},{\"letter\":\"C\",\"text\":\"Neuf premiers mois du post-partum\"},{\"letter\":\"D\",\"text\":\"Douze premiers mois du post-partum\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Six premiers mois du post-partum\",\"answerLetters\":[\"B\"],\"explanation\":\"La MAMA est efficace à 98 % durant les SIX (06) premiers mois du post-partum (b), tant que l'allaitement reste exclusif et que la mère est en aménorrhée.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"korhogo-2__ssr-pf__4\",\"num\":\"5\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"Questions à Choix Multiples de Planification Familiale (Q1 à Q53)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Parmi les méthodes suivantes, choisir celles qui agissent sur l'ovulation : (Choisir 2 réponses)\",\"options\":[{\"letter\":\"A\",\"text\":\"Le condom\"},{\"letter\":\"B\",\"text\":\"La MAMA\"},{\"letter\":\"C\",\"text\":\"La vasectomie\"},{\"letter\":\"D\",\"text\":\"L'implant\"}],\"mode\":\"mcq\",\"multi\":true,\"answer\":\"B et D\",\"answerLetters\":[\"B\",\"D\"],\"explanation\":\"La MAMA (par l'hyperprolactinémie lactée : b) et l'implant progestatif (par inhibition hypothalamo-hypophysaire du pic de LH : d) agissent tous deux en bloquant l'ovulation.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"korhogo-2__ssr-pf__5\",\"num\":\"6\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"Questions à Choix Multiples de Planification Familiale (Q1 à Q53)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Lors de la consultation d'une cliente en planification familiale, l'étape de la prise de décision consiste à : (Choisir 2 mauvaises réponses)\",\"options\":[{\"letter\":\"A\",\"text\":\"Expliquer les résultats de l'interrogatoire/l'anamnèse et de l'examen\"},{\"letter\":\"B\",\"text\":\"Procéder à l'analyse et à l'interprétation des données recueillies\"},{\"letter\":\"C\",\"text\":\"Discuter avec la cliente des méthodes non adaptées à sa situation\"},{\"letter\":\"D\",\"text\":\"Aider la cliente à prendre une décision si nécessaire\"},{\"letter\":\"E\",\"text\":\"Aider la cliente à mettre en application la décision\"}],\"mode\":\"mcq\",\"multi\":true,\"answer\":\"B et C\",\"answerLetters\":[\"B\",\"C\"],\"explanation\":\"Lors de l'étape de la prise de décision (avec la cliente), le prestataire explique les résultats de l'examen (a), discute des méthodes ADAPTÉES à sa situation (donc c 'discuter des méthodes non adaptées' est faux !), l'aide à choisir (d) et à appliquer sa décision (e). En revanche, 'procéder à l'analyse et à l'interprétation des données recueillies' (b) appartient à l'étape précédente du DIAGNOSTIC !\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"korhogo-2__ssr-pf__6\",\"num\":\"7\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"Questions à Choix Multiples de Planification Familiale (Q1 à Q53)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Les éléments suivants sont des critères de qualité d'une méthode contraceptive. Lesquels ? (Choisir 2 bonnes réponses — ou toutes : acceptabilité, sûreté, réversibilité, efficacité/fiabilité)\",\"options\":[{\"letter\":\"A\",\"text\":\"Fiabilité\"},{\"letter\":\"B\",\"text\":\"Acceptabilité\"},{\"letter\":\"C\",\"text\":\"Sûreté (innocuité)\"},{\"letter\":\"D\",\"text\":\"Réversibilité\"}],\"mode\":\"mcq\",\"multi\":true,\"answer\":\"B et C et D\",\"answerLetters\":[\"B\",\"C\",\"D\"],\"explanation\":\"L'acceptabilité (b), la sûreté/innocuité (c) et la réversibilité (d) [avec l'efficacité et le coût abordable] sont les critères classiques de qualité d'une méthode contraceptive.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"korhogo-2__ssr-pf__7\",\"num\":\"8\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"Questions à Choix Multiples de Planification Familiale (Q1 à Q53)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Dans la méthode du calendrier (Ogino-Knaus), le calcul de la période fertile est basé sur les constats suivants. Choisir la mauvaise réponse :\",\"options\":[{\"letter\":\"A\",\"text\":\"L'ovulation se produit toujours 14 jours avant le début des prochaines règles\"},{\"letter\":\"B\",\"text\":\"L'ovulation se produit en moyenne 14 jours (12 à 16 jours) avant le début des prochaines règles\"},{\"letter\":\"C\",\"text\":\"Les spermatozoïdes gardent leur capacité de fécondation pendant 3 jours (mais parfois jusqu'à 5-6 jours)\"},{\"letter\":\"D\",\"text\":\"L'ovule ne conserve la capacité d'être fécondé que pendant 24 heures après l'ovulation\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. L'ovulation se produit toujours 14 jours avant le début des prochaines règles\",\"answerLetters\":[\"A\"],\"explanation\":\"L'ovulation se produit EN MOYENNE 14 jours (entre 12 et 16 jours : b est vrai) avant les règles suivantes, et non 'toujours' exactement à 14 jours fixes (a est donc la mauvaise réponse).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"korhogo-2__ssr-pf__8\",\"num\":\"9\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"Questions à Choix Multiples de Planification Familiale (Q1 à Q53)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Les contraceptifs oraux combinés contiennent :\",\"options\":[{\"letter\":\"A\",\"text\":\"Des œstrogènes et un progestatif (de la progestérone synthétique)\"},{\"letter\":\"B\",\"text\":\"Uniquement de la progestérone\"},{\"letter\":\"C\",\"text\":\"Seulement des œstrogènes\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Des œstrogènes et un progestatif (de la progestérone synthétique)\",\"answerLetters\":[\"A\"],\"explanation\":\"Les Contraceptifs Oraux Combinés (COC) associent un œstrogène de synthèse (éthinylestradiol) et un progestatif de synthèse (a).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"korhogo-2__ssr-pf__9\",\"num\":\"10\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"Questions à Choix Multiples de Planification Familiale (Q1 à Q53)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Les phases du counseling sont : (Choisir 3 bonnes réponses)\",\"options\":[{\"letter\":\"A\",\"text\":\"Counseling initial (ou général)\"},{\"letter\":\"B\",\"text\":\"Counseling d'acceptation\"},{\"letter\":\"C\",\"text\":\"Counseling spécifique à la méthode\"},{\"letter\":\"D\",\"text\":\"Counseling de refus de la méthode\"},{\"letter\":\"E\",\"text\":\"Counseling de suivi\"}],\"mode\":\"mcq\",\"multi\":true,\"answer\":\"A et C et E\",\"answerLetters\":[\"A\",\"C\",\"E\"],\"explanation\":\"Les 3 phases officielles du counseling en PF sont : 1) le counseling initial ou général (a), 2) le counseling spécifique à la méthode choisie (c), et 3) le counseling de suivi ou de retour (e).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"korhogo-2__ssr-pf__10\",\"num\":\"11\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"Questions à Choix Multiples de Planification Familiale (Q1 à Q53)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Les contraceptifs hormonaux progestatifs désignent des produits contraceptifs qui diffusent :\",\"options\":[{\"letter\":\"A\",\"text\":\"Plus d'hormone progestative que d'œstrogène\"},{\"letter\":\"B\",\"text\":\"Uniquement une hormone progestative\"},{\"letter\":\"C\",\"text\":\"À la fois une hormone progestative et un œstrogène\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Uniquement une hormone progestative\",\"answerLetters\":[\"B\"],\"explanation\":\"Les contraceptifs progestatifs seuls ne contiennent qu'un progestatif de synthèse sans aucun œstrogène (b).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"korhogo-2__ssr-pf__11\",\"num\":\"12\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"Questions à Choix Multiples de Planification Familiale (Q1 à Q53)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"La sécurité (innocuité) est la mesure dans laquelle une utilisatrice :\",\"options\":[{\"letter\":\"A\",\"text\":\"Est satisfaite de la méthode contraceptive\"},{\"letter\":\"B\",\"text\":\"N'a pas d'effets secondaires défavorables ou dangereux lors de l'utilisation d'une méthode contraceptive\"},{\"letter\":\"C\",\"text\":\"Ne peut pas tomber enceinte en utilisant une méthode contraceptive\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. N'a pas d'effets secondaires défavorables ou dangereux lors de l'utilisation d'une méthode contraceptive\",\"answerLetters\":[\"B\"],\"explanation\":\"La sécurité (ou innocuité) d'une méthode contraceptive mesure l'absence de risques ou d'effets secondaires dangereux pour la santé de l'utilisatrice (b). (a définit l'acceptabilité et c définit l'efficacité).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"korhogo-2__ssr-pf__12\",\"num\":\"13\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"Questions à Choix Multiples de Planification Familiale (Q1 à Q53)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Au cours d'un counseling initial (général), le prestataire :\",\"options\":[{\"letter\":\"A\",\"text\":\"Décrit toutes les méthodes contraceptives disponibles\"},{\"letter\":\"B\",\"text\":\"Donne des instructions à la cliente pour une bonne utilisation de la méthode choisie\"},{\"letter\":\"C\",\"text\":\"S'assure de l'absence de problèmes survenus lors de l'utilisation de la méthode\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Décrit toutes les méthodes contraceptives disponibles\",\"answerLetters\":[\"A\"],\"explanation\":\"Lors du counseling initial (général), le prestataire présente l'ensemble des méthodes contraceptives disponibles (a) pour permettre un pré-choix éclairé. (b correspond au counseling spécifique et c au counseling de suivi).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"korhogo-2__ssr-pf__13\",\"num\":\"14\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"Questions à Choix Multiples de Planification Familiale (Q1 à Q53)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Lors d'un rapport sexuel, il peut se produire une rupture du préservatif. Si cela arrive pendant l'éjaculation sans usage de spermicide, quelle est la conduite à tenir ? (Choisir les bonnes réponses)\",\"options\":[{\"letter\":\"A\",\"text\":\"Dans les 72 heures : prescrire une contraception orale d'urgence\"},{\"letter\":\"B\",\"text\":\"Arrêter le coït et changer de préservatif\"},{\"letter\":\"C\",\"text\":\"Faire une toilette intime immédiate (ou ne pas faire de douche vaginale avant 6h)\"},{\"letter\":\"D\",\"text\":\"Pour la prévention du VIH : administrer un traitement prophylactique post-exposition (TPE) dans les 48 à 72 heures\"}],\"mode\":\"mcq\",\"multi\":true,\"answer\":\"A et B et D\",\"answerLetters\":[\"A\",\"B\",\"D\"],\"explanation\":\"En cas de rupture du condom, il faut arrêter immédiatement le rapport (b), prescrire une contraception d'urgence dans les 72 heures (a) et évaluer/instaurer une prophylaxie post-exposition (TPE) contre le VIH dans les 48 à 72 heures et le dépistage des IST (d). La douche vaginale (c) est déconseillée car elle chasse les spermatozoïdes vers le col et altère la muqueuse.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"korhogo-2__ssr-pf__14\",\"num\":\"15\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"Questions à Choix Multiples de Planification Familiale (Q1 à Q53)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Le mécanisme d'action du préservatif masculin est qu'il : (Choisir 2 bonnes réponses — ou les 3)\",\"options\":[{\"letter\":\"A\",\"text\":\"Recueille le sperme lors de l'éjaculation\"},{\"letter\":\"B\",\"text\":\"Empêche le spermatozoïde d'accéder aux voies génitales basses de la femme\"},{\"letter\":\"C\",\"text\":\"Empêche le passage des micro-organismes d'un partenaire à un autre (IST, y compris VIH et VHB)\"}],\"mode\":\"mcq\",\"multi\":true,\"answer\":\"B et C\",\"answerLetters\":[\"B\",\"C\"],\"explanation\":\"En retenant le sperme dans son réservoir (a), le préservatif masculin assure la double barrière mécanique : il empêche les spermatozoïdes d'entrer dans les voies génitales féminines (b) et bloque la transmission des agents infectieux des IST/VIH/VHB entre partenaires (c).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"korhogo-2__ssr-pf__15\",\"num\":\"16\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"Questions à Choix Multiples de Planification Familiale (Q1 à Q53)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Les inconvénients de la MAMA sont : (Choisir 2 bonnes réponses — parmi b, c, d)\",\"options\":[{\"letter\":\"A\",\"text\":\"Efficace uniquement après le retour de la menstruation ou pendant 6 mois\"},{\"letter\":\"B\",\"text\":\"Peut être contraignante pour la mère et l'enfant\"},{\"letter\":\"C\",\"text\":\"Ne protège pas contre les ITG, IST/VIH-Sida, VHB\"},{\"letter\":\"D\",\"text\":\"Dépend de l'utilisatrice : demande qu'on suive les instructions concernant les pratiques d'allaitement\"}],\"mode\":\"mcq\",\"multi\":true,\"answer\":\"B et C\",\"answerLetters\":[\"B\",\"C\"],\"explanation\":\"La MAMA est contraignante (tétées exclusives fréquentes jour et nuit : b, d) et ne protège pas contre les IST/VIH/VHB (c). La proposition (a) est fausse à cause du mot 'après' au lieu de 'avant'.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"korhogo-2__ssr-pf__16\",\"num\":\"17\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"Questions à Choix Multiples de Planification Familiale (Q1 à Q53)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Parmi les méthodes contraceptives suivantes, lesquelles sont utilisables immédiatement après l'accouchement si la femme allaite ?\",\"options\":[{\"letter\":\"A\",\"text\":\"Préservatifs\"},{\"letter\":\"B\",\"text\":\"Diaphragme\"},{\"letter\":\"C\",\"text\":\"DMPA (Injection de Progestatif — Catégorie 3 avant 6 semaines selon l'OMS, mais parfois citée dans les questionnaires à 3 réponses avec a et d)\"},{\"letter\":\"D\",\"text\":\"Dispositif Intra-Utérin (DIU post-partum immédiat dans les 48 h)\"}],\"mode\":\"mcq\",\"multi\":true,\"answer\":\"A et D\",\"answerLetters\":[\"A\",\"D\"],\"explanation\":\"Les préservatifs (a) et le DIU du post-partum inséré dans les 48 heures (d) sont de Catégorie 1 de l'OMS immédiatement après l'accouchement chez la femme allaitante. Le diaphragme (b) est inutilisable avant l'involution complète du col et du vagin à 6 semaines (Catégorie 4).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"korhogo-2__ssr-pf__17\",\"num\":\"18\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"Questions à Choix Multiples de Planification Familiale (Q1 à Q53)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"La Dénomination Commune Internationale (DCI) du SAYANA PRESS est :\",\"options\":[{\"letter\":\"A\",\"text\":\"Lévonorgestrel\"},{\"letter\":\"B\",\"text\":\"Étonogestrel\"},{\"letter\":\"C\",\"text\":\"Énanthate de Noréthistérone\"},{\"letter\":\"D\",\"text\":\"Acétate de Médroxyprogestérone retard (DMPA-SC 104 mg)\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"D. Acétate de Médroxyprogestérone retard (DMPA-SC 104 mg)\",\"answerLetters\":[\"D\"],\"explanation\":\"Le Sayana Press est la présentation injectable par voie sous-cutanée en système Uniject prérempli de l'Acétate de Médroxyprogestérone retard (DMPA-SC dosé à 104 mg / 0,65 ml : d).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"korhogo-2__ssr-pf__18\",\"num\":\"19\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"Questions à Choix Multiples de Planification Familiale (Q1 à Q53)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"L'efficacité du préservatif masculin dépend de : (Choisir 2 bonnes réponses)\",\"options\":[{\"letter\":\"A\",\"text\":\"La qualité du préservatif (et sa bonne conservation)\"},{\"letter\":\"B\",\"text\":\"Le suivi correct des instructions d'utilisation (lors de chaque rapport)\"},{\"letter\":\"C\",\"text\":\"La méthode de stockage\"}],\"mode\":\"mcq\",\"multi\":true,\"answer\":\"A et B\",\"answerLetters\":[\"A\",\"B\"],\"explanation\":\"L'efficacité pratique du condom dépend avant tout de son utilisation correcte et systématique à chaque rapport sexuel (b) ainsi que de l'intégrité/qualité du préservatif bien conservé (a/c).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"korhogo-2__ssr-pf__19\",\"num\":\"20\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"Questions à Choix Multiples de Planification Familiale (Q1 à Q53)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Parmi ces méthodes contraceptives, laquelle ne nécessite pas une visite médicale de contrôle post-mise en place ?\",\"options\":[{\"letter\":\"A\",\"text\":\"Stérilet\"},{\"letter\":\"B\",\"text\":\"Implant\"},{\"letter\":\"C\",\"text\":\"Injection trimestrielle\"},{\"letter\":\"D\",\"text\":\"Préservatif\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"D. Préservatif\",\"answerLetters\":[\"D\"],\"explanation\":\"Le préservatif (d) est une méthode de barrière en libre accès utilisée lors du rapport sexuel qui ne nécessite pas de visite médicale de contrôle post-insertion.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"korhogo-2__ssr-pf__20\",\"num\":\"21\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"Questions à Choix Multiples de Planification Familiale (Q1 à Q53)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Le mécanisme d'action du stérilet (DIU) au cuivre est principalement de :\",\"options\":[{\"letter\":\"A\",\"text\":\"Empêcher l'implantation de l'œuf\"},{\"letter\":\"B\",\"text\":\"Détruire / altérer les spermatozoïdes avant qu'ils ne rencontrent l'ovule (et empêcher l'implantation a)\"},{\"letter\":\"C\",\"text\":\"Empêcher l'ovulation\"},{\"letter\":\"D\",\"text\":\"Protéger contre les infections sexuellement transmissibles\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Détruire / altérer les spermatozoïdes avant qu'ils ne rencontrent l'ovule (et empêcher l'implantation a)\",\"answerLetters\":[\"B\"],\"explanation\":\"Selon l'OMS, le mécanisme d'action principal du DIU au cuivre est pré-fécondation (effet toxique spermicide des ions cuivre qui altèrent et immobilisent les spermatozoïdes, empêchant la fécondation : b), complété par une réaction inflammatoire locale endométriale anti-nidatoire (a).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"korhogo-2__ssr-pf__21\",\"num\":\"22\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"Questions à Choix Multiples de Planification Familiale (Q1 à Q53)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"L'injection contraceptive trimestrielle DMPA agit principalement en :\",\"options\":[{\"letter\":\"A\",\"text\":\"Supprimant l'ovulation (et en épaississant la glaire cervicale b)\"},{\"letter\":\"B\",\"text\":\"Épaississant la glaire cervicale\"},{\"letter\":\"C\",\"text\":\"Empêchant l'implantation de l'ovule\"},{\"letter\":\"D\",\"text\":\"Modifiant la muqueuse utérine\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Supprimant l'ovulation (et en épaississant la glaire cervicale b)\",\"answerLetters\":[\"A\"],\"explanation\":\"Le mécanisme d'action principal de l'injectable progestatif à forte dose (DMPA / Depo-Provera) est le blocage central de l'ovulation (suppression du pic de LH : a), associé à l'épaississement de la glaire cervicale et à l'atrophie de l'endomètre.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"korhogo-2__ssr-pf__22\",\"num\":\"23\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"Questions à Choix Multiples de Planification Familiale (Q1 à Q53)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Madame YAO souhaite arrêter sa contraception hormonale en raison de certains effets secondaires. Quelle est la première étape à suivre ?\",\"options\":[{\"letter\":\"A\",\"text\":\"Lui prescrire immédiatement une nouvelle méthode\"},{\"letter\":\"B\",\"text\":\"Discuter avec elle des raisons de son choix, l'écouter, prendre en charge les effets secondaires ou proposer des alternatives\"},{\"letter\":\"C\",\"text\":\"Continuer la méthode actuelle en ajustant la dose\"},{\"letter\":\"D\",\"text\":\"Ne pas intervenir et laisser la patiente décider\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Discuter avec elle des raisons de son choix, l'écouter, prendre en charge les effets secondaires ou proposer des alternatives\",\"answerLetters\":[\"B\"],\"explanation\":\"Lors du counseling de suivi devant une demande d'arrêt pour effets secondaires, le prestataire doit d'abord écouter la cliente avec empathie, explorer les effets ressentis, la rassurer ou les traiter, et si elle maintient son souhait de changer, l'aider à choisir une méthode alternative adaptée (b).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"korhogo-2__ssr-pf__23\",\"num\":\"24\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"Questions à Choix Multiples de Planification Familiale (Q1 à Q53)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Parmi les contraceptifs suivants, lesquels peuvent être utilisés en tant que contraception d'urgence ? (Choisir 2 bonnes réponses)\",\"options\":[{\"letter\":\"A\",\"text\":\"Préservatifs\"},{\"letter\":\"B\",\"text\":\"Pilule contraceptive d'urgence\"},{\"letter\":\"C\",\"text\":\"Implant\"},{\"letter\":\"D\",\"text\":\"Dispositif intra-utérin au cuivre\"}],\"mode\":\"mcq\",\"multi\":true,\"answer\":\"B et D\",\"answerLetters\":[\"B\",\"D\"],\"explanation\":\"Les deux méthodes utilisables en contraception d'urgence post-coïtale sont la pilule contraceptive d'urgence (Lévonorgestrel, Ulipristal ou méthode de Yuzpe : b) et le Dispositif Intra-Utérin au cuivre inséré dans les 5 jours suivant le rapport non protégé (d).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"korhogo-2__ssr-pf__24\",\"num\":\"25\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"Questions à Choix Multiples de Planification Familiale (Q1 à Q53)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"La contraception d'urgence est recommandée dans les situations suivantes : (Choisir 2 bonnes réponses — ou 3 avec c)\",\"options\":[{\"letter\":\"A\",\"text\":\"Rupture ou mauvaise utilisation d'un préservatif\"},{\"letter\":\"B\",\"text\":\"Rapport sexuel non protégé\"},{\"letter\":\"C\",\"text\":\"Début tardif ou oubli prolongé de la pilule contraceptive combinée\"},{\"letter\":\"D\",\"text\":\"Utilisation incorrecte du stérilet\"}],\"mode\":\"mcq\",\"multi\":true,\"answer\":\"A et B\",\"answerLetters\":[\"A\",\"B\"],\"explanation\":\"La contraception d'urgence est indiquée après tout rapport sexuel non protégé (b) ou mal protégé par suite d'un accident de préservatif (rupture/glissement : a) ou d'un oubli/retard de pilule (c).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"korhogo-2__ssr-pf__25\",\"num\":\"26\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"Questions à Choix Multiples de Planification Familiale (Q1 à Q53)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Les effets secondaires fréquents (mineurs) des contraceptifs oraux combinés incluent : (Choisir 2 bonnes réponses)\",\"options\":[{\"letter\":\"A\",\"text\":\"Maux de tête (céphalées légères)\"},{\"letter\":\"B\",\"text\":\"Prise de poids\"},{\"letter\":\"C\",\"text\":\"Nausées\"},{\"letter\":\"D\",\"text\":\"Anémie\"}],\"mode\":\"mcq\",\"multi\":true,\"answer\":\"A et C\",\"answerLetters\":[\"A\",\"C\"],\"explanation\":\"Les effets secondaires courants et bénins des COC (notamment au cours des 3 premiers cycles) sont les nausées (c), les céphalées légères (a), les tensions mammaires et de petites variations de poids (b).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"korhogo-2__ssr-pf__26\",\"num\":\"27\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"Questions à Choix Multiples de Planification Familiale (Q1 à Q53)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Une femme qui utilise un contraceptif injectable (DMPA) peut rencontrer l'effet secondaire fréquent suivant :\",\"options\":[{\"letter\":\"A\",\"text\":\"Perte de poids\"},{\"letter\":\"B\",\"text\":\"Troubles menstruels (spotting, saignements irréguliers puis aménorrhée)\"},{\"letter\":\"C\",\"text\":\"Douleurs abdominales\"},{\"letter\":\"D\",\"text\":\"Infections vaginales fréquentes\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Troubles menstruels (spotting, saignements irréguliers puis aménorrhée)\",\"answerLetters\":[\"B\"],\"explanation\":\"L'effet secondaire le plus fréquent des progestatifs injectables (DMPA, NET-EN) est la modification du profil de saignement menstruel (saignements irréguliers/spotting au début, puis aménorrhée fréquente au bout d'un an : b, ainsi qu'une prise de poids modérée).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"korhogo-2__ssr-pf__27\",\"num\":\"28\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"Questions à Choix Multiples de Planification Familiale (Q1 à Q53)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Les avantages de la méthode MAMA incluent : (Choisir 2 bonnes réponses — ou 3 : a, b, d)\",\"options\":[{\"letter\":\"A\",\"text\":\"Contribue à espacer les naissances\"},{\"letter\":\"B\",\"text\":\"Ne nécessite aucun matériel (ni coût financier)\"},{\"letter\":\"C\",\"text\":\"Peut être utilisée pendant une période prolongée\"},{\"letter\":\"D\",\"text\":\"N'affecte pas l'allaitement (au contraire, l'encourage)\"}],\"mode\":\"mcq\",\"multi\":true,\"answer\":\"B et D\",\"answerLetters\":[\"B\",\"D\"],\"explanation\":\"La MAMA ne nécessite aucun achat ni matériel (b), soutient l'allaitement maternel optimal sans aucun effet secondaire (d) et favorise la transition vers l'espacement des naissances (a). Elle ne peut en revanche pas être utilisée de façon prolongée au-delà de 6 mois (c est faux).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"korhogo-2__ssr-pf__28\",\"num\":\"29\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"Questions à Choix Multiples de Planification Familiale (Q1 à Q53)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Le counseling de planification familiale doit inclure : (Choisir 3 bonnes réponses)\",\"options\":[{\"letter\":\"A\",\"text\":\"Une explication détaillée des différentes méthodes disponibles\"},{\"letter\":\"B\",\"text\":\"La prise en compte des préférences et objectifs de la cliente\"},{\"letter\":\"C\",\"text\":\"Une évaluation médicale (anamnèse/critères d'éligibilité) complète de la cliente\"},{\"letter\":\"D\",\"text\":\"La mise en garde systématique contre les méthodes hormonales\"}],\"mode\":\"mcq\",\"multi\":true,\"answer\":\"A et B et C\",\"answerLetters\":[\"A\",\"B\",\"C\"],\"explanation\":\"Un counseling de qualité informe objectivement sur les méthodes (a), respecte les préférences et besoins de la cliente (b) et vérifie son éligibilité médicale (c), sans jamais dénigrer les méthodes hormonales (d est faux).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"korhogo-2__ssr-pf__29\",\"num\":\"30\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"Questions à Choix Multiples de Planification Familiale (Q1 à Q53)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"La méthode du diaphragme agit en : (Choisir 2 bonnes réponses)\",\"options\":[{\"letter\":\"A\",\"text\":\"Bloquant l'accès des spermatozoïdes à l'utérus (col utérin)\"},{\"letter\":\"B\",\"text\":\"Affectant la qualité de la glaire cervicale\"},{\"letter\":\"C\",\"text\":\"Tuant les spermatozoïdes grâce à un spermicide associé\"}],\"mode\":\"mcq\",\"multi\":true,\"answer\":\"A et C\",\"answerLetters\":[\"A\",\"C\"],\"explanation\":\"Le diaphragme est une coupole souple placée au fond du vagin devant le col utérin qui agit à la fois comme barrière mécanique bloquant l'entrée du col (a) et comme réservoir maintenant le gel spermicide au contact du col pour inactiver les spermatozoïdes (c).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"korhogo-2__ssr-pf__30\",\"num\":\"31\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"Questions à Choix Multiples de Planification Familiale (Q1 à Q53)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"L'implant contraceptif est inséré :\",\"options\":[{\"letter\":\"A\",\"text\":\"Par voie intraveineuse\"},{\"letter\":\"B\",\"text\":\"Sous la peau, dans le bras (en sous-cutané à la face interne du bras)\"},{\"letter\":\"C\",\"text\":\"Dans la cavité utérine\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Sous la peau, dans le bras (en sous-cutané à la face interne du bras)\",\"answerLetters\":[\"B\"],\"explanation\":\"L'implant contraceptif s'insère juste sous la peau (en sous-dermique) à la face interne du bras non dominant (b).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"korhogo-2__ssr-pf__31\",\"num\":\"32\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"Questions à Choix Multiples de Planification Familiale (Q1 à Q53)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Madame DIOMANDÉ vient d'accoucher et souhaite reprendre une méthode contraceptive. Vous lui recommandez de : (Choisir 2 bonnes réponses)\",\"options\":[{\"letter\":\"A\",\"text\":\"Commencer une pilule contraceptive combinée immédiatement\"},{\"letter\":\"B\",\"text\":\"Utiliser la méthode MAMA si elle allaite exclusivement\"},{\"letter\":\"C\",\"text\":\"Opter pour un DIU au cuivre (DIUPP dans les 48 heures)\"},{\"letter\":\"D\",\"text\":\"Attendre 6 mois avant de commencer une méthode hormonale\"}],\"mode\":\"mcq\",\"multi\":true,\"answer\":\"B et C\",\"answerLetters\":[\"B\",\"C\"],\"explanation\":\"Immédiatement après l'accouchement, l'accouchée peut pratiquer la MAMA si elle allaite exclusivement (b) ou bénéficier de la pose d'un DIU au cuivre du post-partum immédiat dans les 48 heures (c) [ou encore d'un implant progestatif].\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"korhogo-2__ssr-pf__32\",\"num\":\"33\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"Questions à Choix Multiples de Planification Familiale (Q1 à Q53)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Le retrait (coït interrompu) est une méthode contraceptive :\",\"options\":[{\"letter\":\"A\",\"text\":\"Efficace à 100 %\"},{\"letter\":\"B\",\"text\":\"Difficile à maîtriser (et peu efficace en utilisation courante)\"},{\"letter\":\"C\",\"text\":\"Qui ne nécessite aucune maîtrise/éducation\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Difficile à maîtriser (et peu efficace en utilisation courante)\",\"answerLetters\":[\"B\"],\"explanation\":\"Le coït interrompu (retrait avant l'éjaculation) exige un grand contrôle de soi de la part de l'homme, est difficile à maîtriser systématiquement et présente un taux d'échec élevé (~20 à 27 % en utilisation courante : b).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"korhogo-2__ssr-pf__33\",\"num\":\"34\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"Questions à Choix Multiples de Planification Familiale (Q1 à Q53)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"L'allaitement exclusif (MAMA) peut être considéré comme une méthode de contraception naturelle efficace durant :\",\"options\":[{\"letter\":\"A\",\"text\":\"1 mois\"},{\"letter\":\"B\",\"text\":\"3 mois\"},{\"letter\":\"C\",\"text\":\"6 mois\"},{\"letter\":\"D\",\"text\":\"12 mois\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"C. 6 mois\",\"answerLetters\":[\"C\"],\"explanation\":\"La MAMA est efficace pendant les 6 premiers mois post-partum (c).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"korhogo-2__ssr-pf__34\",\"num\":\"35\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"Questions à Choix Multiples de Planification Familiale (Q1 à Q53)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Le counseling dans la planification familiale vise à :\",\"options\":[{\"letter\":\"A\",\"text\":\"Informer uniquement sur les risques des méthodes contraceptives\"},{\"letter\":\"B\",\"text\":\"Aider à choisir librement une méthode adaptée à la situation personnelle\"},{\"letter\":\"C\",\"text\":\"Convaincre la patiente d'utiliser une méthode hormonale\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Aider à choisir librement une méthode adaptée à la situation personnelle\",\"answerLetters\":[\"B\"],\"explanation\":\"Le counseling est non directif et aide la cliente à faire un choix libre et éclairé adapté à sa santé et à ses projets (b).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"korhogo-2__ssr-pf__35\",\"num\":\"36\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"Questions à Choix Multiples de Planification Familiale (Q1 à Q53)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Parmi ces méthodes, lesquelles sont considérées comme des méthodes réversibles à longue durée d'action (LARC) ? (Choisir 2 bonnes réponses)\",\"options\":[{\"letter\":\"A\",\"text\":\"Pilule contraceptive\"},{\"letter\":\"B\",\"text\":\"Implant\"},{\"letter\":\"C\",\"text\":\"Stérilet (DIU)\"}],\"mode\":\"mcq\",\"multi\":true,\"answer\":\"B et C\",\"answerLetters\":[\"B\",\"C\"],\"explanation\":\"Les méthodes contraceptives réversibles à longue durée d'action (LARC) regroupent les IMPLANTS sous-cutanés (3 à 5 ans : b) et les DISPOSITIFS INTRA-UTÉRINS / stérilets (5 à 10–12 ans : c).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"korhogo-2__ssr-pf__36\",\"num\":\"37\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"Questions à Choix Multiples de Planification Familiale (Q1 à Q53)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Les contre-indications absolues (Catégorie 4 OMS) aux contraceptifs oraux combinés incluent :\",\"options\":[{\"letter\":\"A\",\"text\":\"Hypertension artérielle sévère non contrôlée (≥ 160/100 mmHg)\"},{\"letter\":\"B\",\"text\":\"Diabète non compliqué\"},{\"letter\":\"C\",\"text\":\"Maladies cardiaques ischémiques ou valvulaires compliquées\"},{\"letter\":\"D\",\"text\":\"Tabagisme (≥ 15 cigarettes/j) chez les femmes de 35 ans et plus\"}],\"mode\":\"mcq\",\"multi\":true,\"answer\":\"A et C et D\",\"answerLetters\":[\"A\",\"C\",\"D\"],\"explanation\":\"L'HTA sévère (a), les cardiopathies ischémiques/thrombogènes (c) et le tabagisme chez la femme de ≥ 35 ans (d) sont des contre-indications formelles aux COC.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"korhogo-2__ssr-pf__37\",\"num\":\"38\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"Questions à Choix Multiples de Planification Familiale (Q1 à Q53)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Les méthodes de contraception naturelles (auto-observation) incluent : (Choisir 2 bonnes réponses)\",\"options\":[{\"letter\":\"A\",\"text\":\"Le calendrier (Ogino-Knaus / Jours fixes)\"},{\"letter\":\"B\",\"text\":\"Le stérilet\"},{\"letter\":\"C\",\"text\":\"La méthode de la glaire cervicale (Billings)\"},{\"letter\":\"D\",\"text\":\"L'implant\"}],\"mode\":\"mcq\",\"multi\":true,\"answer\":\"A et C\",\"answerLetters\":[\"A\",\"C\"],\"explanation\":\"La méthode du calendrier (a) et la méthode d'observation de la glaire cervicale de Billings (c) [avec la température basale et la MAMA] sont des méthodes naturelles.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"korhogo-2__ssr-pf__38\",\"num\":\"39\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"Questions à Choix Multiples de Planification Familiale (Q1 à Q53)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Lors de la mise en place d'un DIU, quelle précaution doit être prise pour prévenir les infections ?\",\"options\":[{\"letter\":\"A\",\"text\":\"Administrer systématiquement des antibiotiques prophylactiques\"},{\"letter\":\"B\",\"text\":\"Utiliser une technique aseptique stricte (technique « sans toucher » et nettoyage antiseptique du col)\"},{\"letter\":\"C\",\"text\":\"Éviter tout rapport sexuel pendant une semaine\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Utiliser une technique aseptique stricte (technique « sans toucher » et nettoyage antiseptique du col)\",\"answerLetters\":[\"B\"],\"explanation\":\"La prévention des infections pelviennes lors de la pose d'un DIU repose sur le dépistage clinique préalable des IST, la désinfection antiseptique exocervicale et le respect d'une technique aseptique stricte dite « sans toucher » (no-touch technique : b).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"korhogo-2__ssr-pf__39\",\"num\":\"40\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"Questions à Choix Multiples de Planification Familiale (Q1 à Q53)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"La vasectomie est une méthode de stérilisation masculine qui :\",\"options\":[{\"letter\":\"A\",\"text\":\"Est réversible après quelques années\"},{\"letter\":\"B\",\"text\":\"Est immédiatement efficace\"},{\"letter\":\"C\",\"text\":\"Agit en coupant/obstruant les canaux déférents\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"C. Agit en coupant/obstruant les canaux déférents\",\"answerLetters\":[\"C\"],\"explanation\":\"La vasectomie est une méthode chirurgicale permanente (irréversible) qui consiste à sectionner et ligaturer les canaux déférents (c) pour empêcher le passage des spermatozoïdes dans l'éjaculat. Elle n'est PAS immédiatement efficace (il faut 3 mois d'attente).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"korhogo-2__ssr-pf__40\",\"num\":\"41\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"Questions à Choix Multiples de Planification Familiale (Q1 à Q53)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Quelle est la période pendant laquelle une femme est la plus fertile ?\",\"options\":[{\"letter\":\"A\",\"text\":\"Pendant les règles\"},{\"letter\":\"B\",\"text\":\"Quelques jours avant et le jour/lendemain de l'ovulation (fenêtre péri-ovulatoire)\"},{\"letter\":\"C\",\"text\":\"Uniquement le jour exact de l'ovulation\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Quelques jours avant et le jour/lendemain de l'ovulation (fenêtre péri-ovulatoire)\",\"answerLetters\":[\"B\"],\"explanation\":\"Compte tenu de la survie des spermatozoïdes (3 à 5 jours) et de celle de l'ovocyte (24 heures), la fenêtre de fertilité maximale s'étend sur les 5 jours précédant l'ovulation, le jour de l'ovulation et les 24 heures suivantes (b).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"korhogo-2__ssr-pf__41\",\"num\":\"42\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"Questions à Choix Multiples de Planification Familiale (Q1 à Q53)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Madame KONÉ souhaite commencer une méthode contraceptive hormonale, mais elle fume régulièrement (et a ≥ 35 ans). Quelle méthode devriez-vous éviter de lui proposer ?\",\"options\":[{\"letter\":\"A\",\"text\":\"Implant\"},{\"letter\":\"B\",\"text\":\"Pilules contraceptives combinées (COC)\"},{\"letter\":\"C\",\"text\":\"DIU au cuivre\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Pilules contraceptives combinées (COC)\",\"answerLetters\":[\"B\"],\"explanation\":\"Le tabagisme associé aux œstrogènes des pilules contraceptives combinées (COC : b) majore considérablement le risque d'infarctus du myocarde et d'AVC (Catégorie 3/4 après 35 ans), alors que l'implant progestatif (a) et le DIU au cuivre (c) sont de Catégorie 1.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"korhogo-2__ssr-pf__42\",\"num\":\"43\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"Questions à Choix Multiples de Planification Familiale (Q1 à Q53)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"La méthode de contraception naturelle appelée « méthode des températures » (TBC) consiste à :\",\"options\":[{\"letter\":\"A\",\"text\":\"Mesurer la température corporelle chaque matin au réveil avant le lever pour déterminer les jours fertiles (et la fin de la période fertile après 3 jours de décalage thermique)\"},{\"letter\":\"B\",\"text\":\"Observer les changements dans la glaire cervicale\"},{\"letter\":\"C\",\"text\":\"Compter les jours du cycle menstruel\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Mesurer la température corporelle chaque matin au réveil avant le lever pour déterminer les jours fertiles (et la fin de la période fertile après 3 jours de décalage thermique)\",\"answerLetters\":[\"A\"],\"explanation\":\"La méthode de la Température Basale du Corps (TBC) repose sur la prise quotidienne de la température chaque matin à la même heure avant de se lever pour repérer l'ascension thermique post-ovulatoire de +0,2°C à +0,5°C maintenue pendant 3 jours consécutifs (a).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"korhogo-2__ssr-pf__43\",\"num\":\"44\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"Questions à Choix Multiples de Planification Familiale (Q1 à Q53)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Un des avantages de l'implant contraceptif est :\",\"options\":[{\"letter\":\"A\",\"text\":\"Il est réversible rapidement après retrait\"},{\"letter\":\"B\",\"text\":\"Il protège contre les infections sexuellement transmissibles\"},{\"letter\":\"C\",\"text\":\"Il nécessite une prise quotidienne\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Il est réversible rapidement après retrait\",\"answerLetters\":[\"A\"],\"explanation\":\"Dès le retrait de l'implant sous-cutané, le retour à la fécondité antérieure est immédiat et rapide (a).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"korhogo-2__ssr-pf__44\",\"num\":\"45\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"Questions à Choix Multiples de Planification Familiale (Q1 à Q53)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"L'utilisation de contraceptifs hormonaux (combinés) peut augmenter légèrement le risque de :\",\"options\":[{\"letter\":\"A\",\"text\":\"Cancer du sein (ou b : accidents cardiovasculaires/thromboemboliques)\"},{\"letter\":\"B\",\"text\":\"Maladies cardiovasculaires / thromboemboliques\"},{\"letter\":\"C\",\"text\":\"Grossesse multiple\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Maladies cardiovasculaires / thromboemboliques\",\"answerLetters\":[\"B\"],\"explanation\":\"Les contraceptifs œstroprogestatifs augmentent légèrement le risque d'accidents thromboemboliques veineux et artériels / cardiovasculaires (b) [ainsi qu'un léger sur-risque relatif de cancer du sein en cours d'utilisation : a, tout en protégeant contre les cancers de l'ovaire et de l'endomètre].\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"korhogo-2__ssr-pf__45\",\"num\":\"46\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"Questions à Choix Multiples de Planification Familiale (Q1 à Q53)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Le DIU au cuivre est particulièrement recommandé pour :\",\"options\":[{\"letter\":\"A\",\"text\":\"Les femmes qui ne veulent pas (ou ont une contre-indication aux) d'hormones (ainsi que c : les femmes allaitantes)\"},{\"letter\":\"B\",\"text\":\"Les adolescentes\"},{\"letter\":\"C\",\"text\":\"Les femmes allaitantes\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Les femmes qui ne veulent pas (ou ont une contre-indication aux) d'hormones (ainsi que c : les femmes allaitantes)\",\"answerLetters\":[\"A\"],\"explanation\":\"Le DIU au cuivre étant totalement dépourvu d'hormones, c'est la méthode de longue durée idéale pour les femmes qui ne souhaitent pas ou ne peuvent pas utiliser d'hormones (a) ainsi que pour les femmes allaitantes (c).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"korhogo-2__ssr-pf__46\",\"num\":\"47\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"Questions à Choix Multiples de Planification Familiale (Q1 à Q53)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Après une vasectomie, combien de temps faut-il attendre (avec une méthode d'appoint/préservatif) avant d'être considéré comme stérile ?\",\"options\":[{\"letter\":\"A\",\"text\":\"Immédiatement après la procédure\"},{\"letter\":\"B\",\"text\":\"Environ 1 mois\"},{\"letter\":\"C\",\"text\":\"Environ 3 mois (ou 20 éjaculations)\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"C. Environ 3 mois (ou 20 éjaculations)\",\"answerLetters\":[\"C\"],\"explanation\":\"Après une vasectomie, des spermatozoïdes viables persistent en aval de la section dans les vésicules séminales et les canaux déférents : il faut attendre 3 MOIS (12 semaines, ou environ 20 éjaculations : c) en utilisant des préservatifs ou une autre méthode avant que l'azoospermie et la stérilité ne soient effectives.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"korhogo-2__ssr-pf__47\",\"num\":\"48\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"Questions à Choix Multiples de Planification Familiale (Q1 à Q53)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Parmi les méthodes suivantes, laquelle est la plus efficace pour prévenir les grossesses non désirées ?\",\"options\":[{\"letter\":\"A\",\"text\":\"Préservatif\"},{\"letter\":\"B\",\"text\":\"Stérilet (DIU)\"},{\"letter\":\"C\",\"text\":\"Retrait\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Stérilet (DIU)\",\"answerLetters\":[\"B\"],\"explanation\":\"Le stérilet (DIU : b) est une méthode de longue durée indépendante de l'observance quotidienne dont l'efficacité dépasse 99 % (indice de Pearl < 0,6 %), bien supérieure à celle du préservatif (85–98 %) et du retrait (73–80 %).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"korhogo-2__ssr-pf__48\",\"num\":\"49\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"Questions à Choix Multiples de Planification Familiale (Q1 à Q53)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"L'une des principales raisons de l'échec de la méthode du préservatif est :\",\"options\":[{\"letter\":\"A\",\"text\":\"La mauvaise qualité du latex\"},{\"letter\":\"B\",\"text\":\"L'utilisation incorrecte ou incohérente (non systématique)\"},{\"letter\":\"C\",\"text\":\"Le coût élevé\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. L'utilisation incorrecte ou incohérente (non systématique)\",\"answerLetters\":[\"B\"],\"explanation\":\"La grande majorité des échecs du préservatif est due à une utilisation incorrecte (pose tardive, absence de chasse d'air du réservoir, lubrifiant gras, retrait tardif) ou non systématique à chaque rapport (b).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"korhogo-2__ssr-pf__49\",\"num\":\"50\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"Questions à Choix Multiples de Planification Familiale (Q1 à Q53)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Madame ZOUMANIGUI prend une contraception orale combinée. Elle oublie de prendre sa pilule pendant 2 jours (2 comprimés actifs oubliés). Que doit-elle faire ?\",\"options\":[{\"letter\":\"A\",\"text\":\"Prendre immédiatement la pilule oubliée la plus récente et continuer normalement (selon les directives OMS, pour 1 ou 2 pilules oubliées à 30-35 µg d'EE, prendre un comprimé actif dès que possible et continuer la plaquette ; à partir de 3 pilules oubliées, ajouter 7 jours de préservatif et éventuellement une CU)\"},{\"letter\":\"B\",\"text\":\"Arrêter la plaquette et attendre les prochaines règles\"},{\"letter\":\"C\",\"text\":\"Utiliser une contraception d'urgence / méthode d'appoint et reprendre sa plaquette\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Prendre immédiatement la pilule oubliée la plus récente et continuer normalement (selon les directives OMS, pour 1 ou 2 pilules oubliées à 30-35 µg d'EE, prendre un comprimé actif dès que possible et continuer la plaquette ; à partir de 3 pilules oubliées, ajouter 7 jours de préservatif et éventuellement une CU)\",\"answerLetters\":[\"A\"],\"explanation\":\"Selon les directives OMS pour les COC à 30–35 µg d'EE (Lo-Femenal / Microgynon) : en cas d'oubli de 1 ou 2 comprimés actifs, la cliente doit prendre immédiatement un comprimé actif dès qu'elle s'en aperçoit et continuer le reste de la plaquette normalement à l'heure habituelle (a).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"korhogo-2__ssr-pf__50\",\"num\":\"51\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"Questions à Choix Multiples de Planification Familiale (Q1 à Q53)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Les effets secondaires possibles de l'utilisation du DIU hormonal (au Lévonorgestrel) incluent : (Choisir 2 bonnes réponses)\",\"options\":[{\"letter\":\"A\",\"text\":\"Diminution des règles (hypoménorrhée voire aménorrhée)\"},{\"letter\":\"B\",\"text\":\"Risque d'infection\"},{\"letter\":\"C\",\"text\":\"Grossesse multiple\"},{\"letter\":\"D\",\"text\":\"Saignements irréguliers (spotting les premiers mois)\"}],\"mode\":\"mcq\",\"multi\":true,\"answer\":\"A et D\",\"answerLetters\":[\"A\",\"D\"],\"explanation\":\"Le DIU hormonal au lévonorgestrel provoque des petits saignements irréguliers/spotting au cours des 3 à 6 premiers mois (d), suivis d'une diminution marquée du volume et de la durée des règles voire d'une aménorrhée bénéfique contre l'anémie (a).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"korhogo-2__ssr-pf__51\",\"num\":\"52\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"Questions à Choix Multiples de Planification Familiale (Q1 à Q53)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Les avantages de la stérilisation féminine (ligature des trompes / CCV) incluent :\",\"options\":[{\"letter\":\"A\",\"text\":\"Méthode réversible après quelques années\"},{\"letter\":\"B\",\"text\":\"Prévention des maladies sexuellement transmissibles\"},{\"letter\":\"C\",\"text\":\"Méthode permanente (et très efficace) de contraception\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"C. Méthode permanente (et très efficace) de contraception\",\"answerLetters\":[\"C\"],\"explanation\":\"La ligature des trompes est une méthode chirurgicale définitive/permanente (c) extrêmement efficace (> 99,5 %) pour les femmes ou couples qui sont certains de ne plus désirer d'enfants.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"korhogo-2__ssr-pf__52\",\"num\":\"53\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"Questions à Choix Multiples de Planification Familiale (Q1 à Q53)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"La méthode de contraception post-coïtale (d'urgence) est généralement utilisée après :\",\"options\":[{\"letter\":\"A\",\"text\":\"L'oubli prolongé d'une contraception régulière\"},{\"letter\":\"B\",\"text\":\"La rupture d'un préservatif\"},{\"letter\":\"C\",\"text\":\"Un rapport sexuel non protégé\"},{\"letter\":\"D\",\"text\":\"Une interruption volontaire de grossesse\"}],\"mode\":\"mcq\",\"multi\":true,\"answer\":\"A et B et C\",\"answerLetters\":[\"A\",\"B\",\"C\"],\"explanation\":\"La contraception post-coïtale d'urgence est indiquée après tout rapport sexuel non protégé (c), une rupture ou glissement de préservatif (b) ou un oubli de méthode régulière (a). +-----------------------------------------------------------------------+ Épreuves : Santé Publique (Q1-Q47) | Pédiatrie Bloc A (Q1-Q49) | Gynécologie-Obstétrique (Q1-Q17) | PF/SSR (Q1-Q50) +=======================================================================+ +-----------------------------------------------------------------------+ +-----------------------------------------------------------------------+\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null}]}]},{\"name\":\"MAN (S2 : 2025)\",\"slug\":\"man-2\",\"session\":\"S2\",\"annee\":2025,\"existe\":true,\"sujets\":[{\"name\":\"PÉDIATRIE\",\"slug\":\"pediatrie\",\"pages\":\"\",\"count\":49,\"session\":\"S2\",\"annee\":2025,\"source\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"questions\":[{\"id\":\"man-2__pediatrie__0\",\"num\":\"1\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"I. Questions à Choix Multiples (QCM : Q1 à Q34)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"La période néonatale précoce s'étend de :\",\"options\":[{\"letter\":\"A\",\"text\":\"Jour 0 à jour 30\"},{\"letter\":\"B\",\"text\":\"Jour 0 à jour 07\"},{\"letter\":\"C\",\"text\":\"Jour 0 à jour 28\"},{\"letter\":\"D\",\"text\":\"Jour 0 à jour 17\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Jour 0 à jour 07\",\"answerLetters\":[\"B\"],\"explanation\":\"La période néonatale précoce couvre la première semaine de vie, de J0 à J7 (B).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"man-2__pediatrie__1\",\"num\":\"2\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"I. Questions à Choix Multiples (QCM : Q1 à Q34)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Le vernix caseosa est :\",\"options\":[{\"letter\":\"A\",\"text\":\"Le fin duvet recouvrant les épaules et le dos du prématuré\"},{\"letter\":\"B\",\"text\":\"Une hypertrophie des glandes sébacées\"},{\"letter\":\"C\",\"text\":\"Un enduit gras recouvrant presque tout le corps\"},{\"letter\":\"D\",\"text\":\"Des taches sur le visage du nouveau-né\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"C. Un enduit gras recouvrant presque tout le corps\",\"answerLetters\":[\"C\"],\"explanation\":\"Le vernix caseosa est l'enduit sébacé blanchâtre protecteur recouvrant la peau du nouveau-né à terme (C).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"man-2__pediatrie__2\",\"num\":\"3\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"I. Questions à Choix Multiples (QCM : Q1 à Q34)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Parmi la liste d'hormones ci-dessous, cochez l'hormone responsable de l'éjection du lait dans les seins :\",\"options\":[{\"letter\":\"A\",\"text\":\"L'ocytocine\"},{\"letter\":\"B\",\"text\":\"La progestérone\"},{\"letter\":\"C\",\"text\":\"L'œstrogène\"},{\"letter\":\"D\",\"text\":\"La prolactine\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. L'ocytocine\",\"answerLetters\":[\"A\"],\"explanation\":\"L'ocytocine provoque la contraction des cellules myoépithéliales et l'éjection du lait (A).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"man-2__pediatrie__3\",\"num\":\"4\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"I. Questions à Choix Multiples (QCM : Q1 à Q34)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Parmi les propositions suivantes, cochez la proposition qui fait partie des critères d'une bonne prise de sein :\",\"options\":[{\"letter\":\"A\",\"text\":\"Le menton touche l'aréole et les succions sont profondes et lentes entrecoupées de pauses\"},{\"letter\":\"B\",\"text\":\"La bouche est grande ouverte et la lèvre inférieure est éversée vers l'extérieur\"},{\"letter\":\"C\",\"text\":\"L'aréole est plus visible en dessous qu'au-dessus de la bouche\"},{\"letter\":\"D\",\"text\":\"On entend l'enfant déglutir le lait maternel\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. La bouche est grande ouverte et la lèvre inférieure est éversée vers l'extérieur\",\"answerLetters\":[\"B\"],\"explanation\":\"Bouche grande ouverte et lèvre inférieure éversée (B) font partie des 4 critères anatomiques de bonne prise du sein.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"man-2__pediatrie__4\",\"num\":\"5\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"I. Questions à Choix Multiples (QCM : Q1 à Q34)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Lors d'une séance de diététique au centre de santé, l'agent de santé recommande aux mères l'ablactation chez le nourrisson à partir de l'âge de :\",\"options\":[{\"letter\":\"A\",\"text\":\"6 mois\"},{\"letter\":\"B\",\"text\":\"12 mois\"},{\"letter\":\"C\",\"text\":\"18 mois\"},{\"letter\":\"D\",\"text\":\"24 mois\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. 6 mois\",\"answerLetters\":[\"A\"],\"explanation\":\"L'introduction des aliments de complément (début de l'ablactation) commence à 6 mois révolus (A), et le sevrage définitif à 24 mois (D).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"man-2__pediatrie__5\",\"num\":\"6\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"I. Questions à Choix Multiples (QCM : Q1 à Q34)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Dans la malnutrition aiguë sévère avec complications, l'enfant :\",\"options\":[{\"letter\":\"A\",\"text\":\"Est très éveillé\"},{\"letter\":\"B\",\"text\":\"A un bon appétit\"},{\"letter\":\"C\",\"text\":\"Manifeste de l'intérêt\"},{\"letter\":\"D\",\"text\":\"A des œdèmes bilatéraux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"D. A des œdèmes bilatéraux\",\"answerLetters\":[\"D\"],\"explanation\":\"Les œdèmes bilatéraux nutritionnels (kwashiorkor / MAS compliquée : D) sont un signe majeur de MAS.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"man-2__pediatrie__6\",\"num\":\"7\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"I. Questions à Choix Multiples (QCM : Q1 à Q34)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Agent de santé au service de pédiatrie du CHU d'Angré, vous recevez en urgence un nourrisson présentant des convulsions. Les gestes d'urgence à poser sont :\",\"options\":[{\"letter\":\"A\",\"text\":\"Mettre le nourrisson en décubitus dorsal et le ventiler\"},{\"letter\":\"B\",\"text\":\"Mettre le nourrisson en position latérale de sécurité et arrêter les crises en lui administrant 0,5 mg - 1 mg/kg de Diazépam par voie intrarectale\"},{\"letter\":\"C\",\"text\":\"Mettre le nourrisson en PLS et administrer 2 - 3 mg/kg de Diazépam en IM\"},{\"letter\":\"D\",\"text\":\"Mettre le nourrisson en décubitus ventral\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Mettre le nourrisson en position latérale de sécurité et arrêter les crises en lui administrant 0,5 mg - 1 mg/kg de Diazépam par voie intrarectale\",\"answerLetters\":[\"B\"],\"explanation\":\"Mise en PLS + Diazépam 0,5 mg/kg par voie intrarectale (B).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"man-2__pediatrie__7\",\"num\":\"8\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"I. Questions à Choix Multiples (QCM : Q1 à Q34)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Devant la crise convulsive du nourrisson, le soin délégué de l'agent de santé se résume à :\",\"options\":[{\"letter\":\"A\",\"text\":\"Administrer le traitement prescrit par le médecin\"},{\"letter\":\"B\",\"text\":\"Assister le médecin à la réalisation de la ponction lombaire\"},{\"letter\":\"C\",\"text\":\"Accompagner le nourrisson chez le spécialiste\"},{\"letter\":\"D\",\"text\":\"Acheminer les prélèvements au laboratoire\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Administrer le traitement prescrit par le médecin\",\"answerLetters\":[\"A\"],\"explanation\":\"L'exécution d'une prescription médicale thérapeutique est un soin délégué (A).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"man-2__pediatrie__8\",\"num\":\"9\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"I. Questions à Choix Multiples (QCM : Q1 à Q34)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Pour confirmer le diagnostic du paludisme simple, l'agent de santé :\",\"options\":[{\"letter\":\"A\",\"text\":\"Réalise au lit du patient un test de diagnostic rapide (TDR)\"},{\"letter\":\"B\",\"text\":\"Réalise au lit du patient une goutte épaisse\"},{\"letter\":\"C\",\"text\":\"Réalise au lit du patient un frottis sanguin\"},{\"letter\":\"D\",\"text\":\"Réalise au lit du patient une NFS\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Réalise au lit du patient un test de diagnostic rapide (TDR)\",\"answerLetters\":[\"A\"],\"explanation\":\"Au lit du malade ou en salle de consultation, l'agent de santé réalise un TDR du paludisme (A).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"man-2__pediatrie__9\",\"num\":\"10\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"I. Questions à Choix Multiples (QCM : Q1 à Q34)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"BH est né à terme avec un poids de naissance de 3 750 grammes, son poids à l'âge de 24 mois est le suivant :\",\"options\":[{\"letter\":\"A\",\"text\":\"12 kg\"},{\"letter\":\"B\",\"text\":\"13 kg\"},{\"letter\":\"C\",\"text\":\"14 kg\"},{\"letter\":\"D\",\"text\":\"15 kg\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"D. 15 kg\",\"answerLetters\":[\"D\"],\"explanation\":\"À 24 mois (2 ans), l'enfant quadruple son poids de naissance : 3,75 kg × 4 = 15 kg (D).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"man-2__pediatrie__10\",\"num\":\"11\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"I. Questions à Choix Multiples (QCM : Q1 à Q34)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Lorsque l'agent de santé est en exercice dans un ESPC, ses soins propres en cas de paludisme grave sont :\",\"options\":[{\"letter\":\"A\",\"text\":\"Accueillir l'enfant et organiser la référence\"},{\"letter\":\"B\",\"text\":\"Administrer l'antipaludique et mettre l'enfant en observation\"},{\"letter\":\"C\",\"text\":\"Appeler le médecin pour le traitement à faire\"},{\"letter\":\"D\",\"text\":\"Participer à la réalisation du bilan biologique\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Accueillir l'enfant et organiser la référence\",\"answerLetters\":[\"A\"],\"explanation\":\"En ESPC, tout paludisme grave doit être accueilli, stabilisé et référé en urgence (A).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"man-2__pediatrie__11\",\"num\":\"12\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"I. Questions à Choix Multiples (QCM : Q1 à Q34)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"La malnutrition aiguë sévère sans complication est prise en charge en :\",\"options\":[{\"letter\":\"A\",\"text\":\"Unité nutritionnelle thérapeutique\"},{\"letter\":\"B\",\"text\":\"Unité nutritionnelle thérapeutique ambulatoire (UNTA)\"},{\"letter\":\"C\",\"text\":\"Unité nutritionnelle de supplémentation\"},{\"letter\":\"D\",\"text\":\"Unité nutritionnelle thérapeutique et à domicile\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Unité nutritionnelle thérapeutique ambulatoire (UNTA)\",\"answerLetters\":[\"B\"],\"explanation\":\"La MAS sans complication est prise en charge en UNTA (B).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"man-2__pediatrie__12\",\"num\":\"13\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"I. Questions à Choix Multiples (QCM : Q1 à Q34)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"L'enfant ayant le marasme présente les signes cliniques suivants :\",\"options\":[{\"letter\":\"A\",\"text\":\"Cheveux roux, cassants, clairsemés\"},{\"letter\":\"B\",\"text\":\"Peau sèche, craquelée et dépigmentée\"},{\"letter\":\"C\",\"text\":\"Un visage creusé, vieillot avec un regard vif et intéressé\"},{\"letter\":\"D\",\"text\":\"Anorexie\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"C. Un visage creusé, vieillot avec un regard vif et intéressé\",\"answerLetters\":[\"C\"],\"explanation\":\"Le marasme donne un faciès émacié vieillot mais avec un regard vif et un appétit conservé (C).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"man-2__pediatrie__13\",\"num\":\"14\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"I. Questions à Choix Multiples (QCM : Q1 à Q34)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"La prise en charge de la Malnutrition Aiguë Modérée (MAM) se fait en :\",\"options\":[{\"letter\":\"A\",\"text\":\"Unité de Nutrition Thérapeutique\"},{\"letter\":\"B\",\"text\":\"Centre Nutritionnel de Supplémentation (CNS)\"},{\"letter\":\"C\",\"text\":\"Unité de Nutrition Thérapeutique Ambulatoire\"},{\"letter\":\"D\",\"text\":\"UNT au CHU\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Centre Nutritionnel de Supplémentation (CNS)\",\"answerLetters\":[\"B\"],\"explanation\":\"La MAM est prise en charge en Centre Nutritionnel de Supplémentation (CNS / UNS : B).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"man-2__pediatrie__14\",\"num\":\"15\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"I. Questions à Choix Multiples (QCM : Q1 à Q34)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"La croissance qualitative est surveillée avec le paramètre suivant :\",\"options\":[{\"letter\":\"A\",\"text\":\"Le périmètre crânien\"},{\"letter\":\"B\",\"text\":\"La taille\"},{\"letter\":\"C\",\"text\":\"Les fontanelles\"},{\"letter\":\"D\",\"text\":\"Le poids\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"C. Les fontanelles\",\"answerLetters\":[\"C\"],\"explanation\":\"L'évolution des fontanelles (C) évalue la maturation osseuse (croissance qualitative).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"man-2__pediatrie__15\",\"num\":\"16\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"I. Questions à Choix Multiples (QCM : Q1 à Q34)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"QG a une surface corporelle à la naissance de 0,27 m², quelle est sa surface corporelle à 3 ans ?\",\"options\":[{\"letter\":\"A\",\"text\":\"0,81 m²\"},{\"letter\":\"B\",\"text\":\"0,54 m²\"},{\"letter\":\"C\",\"text\":\"0,92 m²\"},{\"letter\":\"D\",\"text\":\"1,21 m²\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. 0,81 m²\",\"answerLetters\":[\"A\"],\"explanation\":\"À 3 ans (36 mois), la surface corporelle de naissance triple : 0,27 × 3 = 0,81 m² (A).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"man-2__pediatrie__16\",\"num\":\"17\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"I. Questions à Choix Multiples (QCM : Q1 à Q34)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Les propositions suivantes sont des avantages de l'allaitement exclusif pour le nouveau-né sauf une. Cochez cette proposition :\",\"options\":[{\"letter\":\"A\",\"text\":\"Favorise la croissance harmonieuse\"},{\"letter\":\"B\",\"text\":\"Favorise le développement cérébral\"},{\"letter\":\"C\",\"text\":\"Favorise l'attachement à la mère\"},{\"letter\":\"D\",\"text\":\"Favorise les infections respiratoires\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"D. Favorise les infections respiratoires\",\"answerLetters\":[\"D\"],\"explanation\":\"L'allaitement maternel protège contre les infections respiratoires et ne les favorise jamais (D).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"man-2__pediatrie__17\",\"num\":\"18\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"I. Questions à Choix Multiples (QCM : Q1 à Q34)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Les séquelles neurologiques et neurosensorielles au cours du paludisme grave sont les suivantes sauf une, laquelle ?\",\"options\":[{\"letter\":\"A\",\"text\":\"Paralysie\"},{\"letter\":\"B\",\"text\":\"Hypotonie\"},{\"letter\":\"C\",\"text\":\"Hypoacousie\"},{\"letter\":\"D\",\"text\":\"Mastoïdite\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"D. Mastoïdite\",\"answerLetters\":[\"D\"],\"explanation\":\"La mastoïdite (D) est une complication d'otite moyenne aiguë et non une séquelle neurologique du neuropaludisme.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"man-2__pediatrie__18\",\"num\":\"19\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"I. Questions à Choix Multiples (QCM : Q1 à Q34)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Tous les facteurs suivants inhibent le réflexe ocytocique chez la mère, sauf un. Cocher l'intrus :\",\"options\":[{\"letter\":\"A\",\"text\":\"La vue de son bébé\"},{\"letter\":\"B\",\"text\":\"La douleur physique\"},{\"letter\":\"C\",\"text\":\"Le manque de confiance en soi\"},{\"letter\":\"D\",\"text\":\"La crise d'anxiété\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. La vue de son bébé\",\"answerLetters\":[\"A\"],\"explanation\":\"La vue de son bébé (A) stimule le réflexe d'éjection du lait au lieu de l'inhiber.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"man-2__pediatrie__19\",\"num\":\"20\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"I. Questions à Choix Multiples (QCM : Q1 à Q34)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"GH, sexe féminin, poids 12 kg, présente des convulsions. Pour arrêter ces convulsions, j'utilise du Diazépam. La dose maximale de Diazépam que je ne dois pas dépasser en une journée de traitement est de :\",\"options\":[{\"letter\":\"A\",\"text\":\"12 mg\"},{\"letter\":\"B\",\"text\":\"24 mg\"},{\"letter\":\"C\",\"text\":\"36 mg\"},{\"letter\":\"D\",\"text\":\"48 mg\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"C. 36 mg\",\"answerLetters\":[\"C\"],\"explanation\":\"Avec le plafond de 3 mg/kg/24h : 12 kg × 3 = 36 mg (C) [ou 12 mg à 1 mg/kg/j : A].\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"man-2__pediatrie__20\",\"num\":\"21\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"I. Questions à Choix Multiples (QCM : Q1 à Q34)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Dame ZP vient d'accoucher de son premier enfant et vous demande conseil pour avoir une bonne montée laiteuse. Je conseille à dame ZP :\",\"options\":[{\"letter\":\"A\",\"text\":\"De réduire la fréquence de tétée du bébé\"},{\"letter\":\"B\",\"text\":\"D'augmenter le nombre de tétées de son bébé\"},{\"letter\":\"C\",\"text\":\"De suivre un régime amaigrissant\"},{\"letter\":\"D\",\"text\":\"De confier son bébé à l'aide\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. D'augmenter le nombre de tétées de son bébé\",\"answerLetters\":[\"B\"],\"explanation\":\"Augmenter la fréquence des mises au sein (B) stimule la sécrétion de prolactine et la montée laiteuse.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"man-2__pediatrie__21\",\"num\":\"22\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"I. Questions à Choix Multiples (QCM : Q1 à Q34)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"FH est de 5 mois et orphelin de mère. Pour préparer son bol de lait infantile de 180 ml, j'utilise :\",\"options\":[{\"letter\":\"A\",\"text\":\"7 mesurettes rases de lait\"},{\"letter\":\"B\",\"text\":\"6 mesurettes rases de lait\"},{\"letter\":\"C\",\"text\":\"5 mesurettes rases de lait\"},{\"letter\":\"D\",\"text\":\"4 mesurettes rases de lait\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. 6 mesurettes rases de lait\",\"answerLetters\":[\"B\"],\"explanation\":\"1 mesurette rase pour 30 ml d'eau → 180 / 30 = 6 mesurettes rases (B).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"man-2__pediatrie__22\",\"num\":\"23\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"I. Questions à Choix Multiples (QCM : Q1 à Q34)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Vous consultez l'enfant JP âgé de 36 mois. Son Z-score Poids pour l'Âge est en dessous de moins 1 (entre -1 et -2 ET). Cela signifie que JP :\",\"options\":[{\"letter\":\"A\",\"text\":\"A un poids insuffisant pour son âge\"},{\"letter\":\"B\",\"text\":\"Est en surpoids pour son âge\"},{\"letter\":\"C\",\"text\":\"Est obèse pour son âge\"},{\"letter\":\"D\",\"text\":\"A un poids normal pour son âge\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"D. A un poids normal pour son âge\",\"answerLetters\":[\"D\"],\"explanation\":\"Entre −2 ET et +1 ET, le poids pour l'âge est normal (D).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"man-2__pediatrie__23\",\"num\":\"24\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"I. Questions à Choix Multiples (QCM : Q1 à Q34)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"EP est âgé de 18 mois. Il souffre du Kwashiorkor et est pris en charge à l'hôpital. L'allure de sa courbe de poids sous traitement décrit classiquement la forme de la lettre :\",\"options\":[{\"letter\":\"A\",\"text\":\"Y\"},{\"letter\":\"B\",\"text\":\"M\"},{\"letter\":\"C\",\"text\":\"V\"},{\"letter\":\"D\",\"text\":\"W\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"C. V\",\"answerLetters\":[\"C\"],\"explanation\":\"Fonte initiale des œdèmes (descente) puis reprise pondérale nutritionnelle (remontée) = courbe en V (C).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"man-2__pediatrie__24\",\"num\":\"25\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"I. Questions à Choix Multiples (QCM : Q1 à Q34)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Dame KJ allaite son nouveau-né depuis la naissance. Parmi les propositions suivantes relatives à l'avantage de l'allaitement pour dame KJ se trouve un intrus. Cochez l'intrus :\",\"options\":[{\"letter\":\"A\",\"text\":\"Favorise l'hémorragie de la délivrance\"},{\"letter\":\"B\",\"text\":\"Favorise l'attachement de KJ à son enfant\"},{\"letter\":\"C\",\"text\":\"Favorise l'espacement des naissances\"},{\"letter\":\"D\",\"text\":\"Favorise la contraction utérine du post-partum immédiat\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Favorise l'hémorragie de la délivrance\",\"answerLetters\":[\"A\"],\"explanation\":\"L'allaitement prévient l'hémorragie de la délivrance grâce aux contractions utérines induites par l'ocytocine ; A est donc l'intrus.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"man-2__pediatrie__25\",\"num\":\"26\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"I. Questions à Choix Multiples (QCM : Q1 à Q34)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"La complication redoutable à prévenir en urgence chez tout enfant sévèrement malnutri est :\",\"options\":[{\"letter\":\"A\",\"text\":\"Hypoglycémie\"},{\"letter\":\"B\",\"text\":\"Déshydratation\"},{\"letter\":\"C\",\"text\":\"Anémie sévère\"},{\"letter\":\"D\",\"text\":\"Défaillance cardiaque\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Hypoglycémie\",\"answerLetters\":[\"A\"],\"explanation\":\"L'hypoglycémie est la première complication métabolique mortelle à prévenir dès l'admission (A).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"man-2__pediatrie__26\",\"num\":\"27\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"I. Questions à Choix Multiples (QCM : Q1 à Q34)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"L'état de mal convulsif désigne une crise convulsive qui dure plus de :\",\"options\":[{\"letter\":\"A\",\"text\":\"05 minutes\"},{\"letter\":\"B\",\"text\":\"10 minutes\"},{\"letter\":\"C\",\"text\":\"20 minutes\"},{\"letter\":\"D\",\"text\":\"30 minutes\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"D. 30 minutes\",\"answerLetters\":[\"D\"],\"explanation\":\"Définition classique du cours = > 30 minutes (D) [et > 5 minutes en définition opérationnelle : A].\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"man-2__pediatrie__27\",\"num\":\"28\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"I. Questions à Choix Multiples (QCM : Q1 à Q34)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Pour la reconstitution de l'eau sucrée à 10% administrée à l'enfant malnutri à l'admission, j'utilise 2 carreaux de sucre pour :\",\"options\":[{\"letter\":\"A\",\"text\":\"200 ml d'eau potable\"},{\"letter\":\"B\",\"text\":\"150 ml d'eau potable\"},{\"letter\":\"C\",\"text\":\"100 ml d'eau potable\"},{\"letter\":\"D\",\"text\":\"50 ml d'eau potable\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"C. 100 ml d'eau potable\",\"answerLetters\":[\"C\"],\"explanation\":\"2 carreaux de sucre (10 g) pour 100 ml d'eau potable = eau sucrée à 10 % (C).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"man-2__pediatrie__28\",\"num\":\"29\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"I. Questions à Choix Multiples (QCM : Q1 à Q34)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Nourrisson GG, fillette de 18 mois, présente des pleurs incessants et un refus de téter. Elle n'est pas à jour de ses vaccins. À l'examen physique, la fontanelle antérieure est bombée, température de 40°C, poids 10 kg. GG souffre d'une méningite purulente. GG a :\",\"options\":[{\"letter\":\"A\",\"text\":\"1 donnée au niveau de sa réalité personnelle\"},{\"letter\":\"B\",\"text\":\"2 données au niveau de sa réalité personnelle\"},{\"letter\":\"C\",\"text\":\"3 données au niveau de sa réalité personnelle\"},{\"letter\":\"D\",\"text\":\"4 données au niveau de sa réalité personnelle\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"C. 3 données au niveau de sa réalité personnelle\",\"answerLetters\":[\"C\"],\"explanation\":\"Nourrisson GG, fillette, 18 mois = 3 données de réalité personnelle (C).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"man-2__pediatrie__29\",\"num\":\"30\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"I. Questions à Choix Multiples (QCM : Q1 à Q34)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Même énoncé (Nourrisson GG, fillette de 18 mois...). GG a :\",\"options\":[{\"letter\":\"A\",\"text\":\"4 données de dépendance\"},{\"letter\":\"B\",\"text\":\"5 données de dépendance\"},{\"letter\":\"C\",\"text\":\"6 données de dépendance\"},{\"letter\":\"D\",\"text\":\"7 données de dépendance\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"C. 6 données de dépendance\",\"answerLetters\":[\"C\"],\"explanation\":\"1) pleurs incessants, 2) refus de téter, 3) non à jour des vaccins, 4) fontanelle bombée, 5) T° 40°C, 6) méningite purulente = 6 données de dépendance (C).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"man-2__pediatrie__30\",\"num\":\"31\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"I. Questions à Choix Multiples (QCM : Q1 à Q34)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Même énoncé (GG fillette de 18 mois...). GG a :\",\"options\":[{\"letter\":\"A\",\"text\":\"3 données d'indépendance\"},{\"letter\":\"B\",\"text\":\"4 données d'indépendance\"},{\"letter\":\"C\",\"text\":\"5 données d'indépendance\"},{\"letter\":\"D\",\"text\":\"6 données d'indépendance\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. 3 données d'indépendance\",\"answerLetters\":[\"A\"],\"explanation\":\"Identique à Korhogo Q46 / Aboisso Q28 : Réponse A.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"man-2__pediatrie__31\",\"num\":\"32\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"I. Questions à Choix Multiples (QCM : Q1 à Q34)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Même énoncé (GG fillette de 18 mois...). L'interprétation des données de GG met en évidence :\",\"options\":[{\"letter\":\"A\",\"text\":\"Infection bactérienne des méninges et absence de protection\"},{\"letter\":\"B\",\"text\":\"Hypertension intracrânienne fébrile et absence de protection\"},{\"letter\":\"C\",\"text\":\"Trouble de la régulation thermique et menace sur l'intégrité physique et psychique\"},{\"letter\":\"D\",\"text\":\"Immaturité cérébrale et cutanée et absence de protection\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Infection bactérienne des méninges et absence de protection\",\"answerLetters\":[\"A\"],\"explanation\":\"Identique à Korhogo Q47 / Aboisso Q29 : Réponse A.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"man-2__pediatrie__32\",\"num\":\"33\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"I. Questions à Choix Multiples (QCM : Q1 à Q34)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Vous êtes dans un Établissement Sanitaire de Premier Contact (ESPC) et vous recevez un grand enfant qui a un paludisme grave. Le traitement antipaludique pré-transfert de 1re intention est :\",\"options\":[{\"letter\":\"A\",\"text\":\"Artésunate 2,4 mg/kg (en IM/IV ou suppositoire d'artésunate 10 mg/kg chez < 6 ans)\"},{\"letter\":\"B\",\"text\":\"Artéméther 3,2 mg/kg (en IM)\"},{\"letter\":\"C\",\"text\":\"Sels de quinine 8 mg/kg\"},{\"letter\":\"D\",\"text\":\"Amodiaquine 10 mg/kg\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Artésunate 2,4 mg/kg (en IM/IV ou suppositoire d'artésunate 10 mg/kg chez < 6 ans)\",\"answerLetters\":[\"A\"],\"explanation\":\"Selon les directives nationales du PNLP en Côte d'Ivoire, la molécule de 1re intention du paludisme grave (y compris en dose initiale pré-transfert en IM/IV chez le grand enfant ≥ 20 kg) est l'Artésunate injectable à la posologie de 2,4 mg/kg (A), l'Artéméther IM à 3,2 mg/kg (B) étant l'alternative de 2e intention.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"man-2__pediatrie__33\",\"num\":\"34\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"I. Questions à Choix Multiples (QCM : Q1 à Q34)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"À l'examen, vous retrouvez que J.B. est irritable, ses yeux sont enfoncés, les larmes sont absentes lors des pleurs, il est incapable de boire, sa bouche est très sèche et le pli cutané s'efface très lentement. Vous concluez chez J.B. à :\",\"options\":[{\"letter\":\"A\",\"text\":\"Signes évidents de déshydratation\"},{\"letter\":\"B\",\"text\":\"Pas de signes de déshydratation\"},{\"letter\":\"C\",\"text\":\"Signes légers de déshydratation\"},{\"letter\":\"D\",\"text\":\"Signes sévères de déshydratation\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"D. Signes sévères de déshydratation\",\"answerLetters\":[\"D\"],\"explanation\":\"Dans l'algorithme PCIME, la présence d'au moins deux des signes suivants — léthargique/inconscient, yeux enfoncés, INCAPABLE DE BOIRE (ou boit difficilement), et PLI CUTANÉ S'EFFAÇANT TRÈS LENTEMENT (≥ 2 secondes) — classe l'enfant en DÉSHYDRATATION SÉVÈRE (Signes sévères de déshydratation, Plan C : D) ! Ici J.B. a les yeux enfoncés + est incapable de boire + a un pli cutané qui s'efface très lentement.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"man-2__pediatrie__34\",\"num\":\"35\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"II. Questions à Choix Double (QCD : Q35 à Q49)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Le marasme est provoqué par une insuffisance d'apport de micronutriments.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"Le marasme est dû à une carence globale en MACRONUTRIMENTS (énergie/calories et protéines).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"man-2__pediatrie__35\",\"num\":\"36\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"II. Questions à Choix Double (QCD : Q35 à Q49)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Le sevrage définitif avant 24 mois est un facteur favorisant le déficit en macronutriments.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Vrai\",\"answerLetters\":[\"A\"],\"explanation\":\"L'arrêt précoce de l'allaitement maternel avant 24 mois favorise la malnutrition protéino-énergétique (déficit en macronutriments).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"man-2__pediatrie__36\",\"num\":\"37\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"II. Questions à Choix Double (QCD : Q35 à Q49)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Les cellules épithéliales du sein sont les cibles de l'hormone ocytocine.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"L'ocytocine cible les cellules MYOÉPITHÉLIALES ; les cellules épithéliales sont la cible de la prolactine.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"man-2__pediatrie__37\",\"num\":\"38\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"II. Questions à Choix Double (QCD : Q35 à Q49)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Au cours de la malnutrition aiguë, on observe un excès global et homogène en nutriments.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"La malnutrition aiguë est une carence (déficit) et non un excès.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"man-2__pediatrie__38\",\"num\":\"39\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"II. Questions à Choix Double (QCD : Q35 à Q49)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Les aliments énergétiques aident les enfants à effectuer toutes sortes d'activités physiques.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Vrai\",\"answerLetters\":[\"A\"],\"explanation\":\"Les aliments énergétiques (glucides, lipides) fournissent l'énergie nécessaire à l'activité physique.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"man-2__pediatrie__39\",\"num\":\"40\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"II. Questions à Choix Double (QCD : Q35 à Q49)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Les aliments de croissance ou de construction protègent contre les maladies.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"Ce sont les aliments de PROTECTION (vitamines et minéraux) qui protègent contre les maladies.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"man-2__pediatrie__40\",\"num\":\"41\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"II. Questions à Choix Double (QCD : Q35 à Q49)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"BK né à terme est à J2 de vie et présente une infection bactérienne néonatale. L'infection de BK est d'origine maternelle.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Vrai\",\"answerLetters\":[\"A\"],\"explanation\":\"Toute infection néonatale précoce (< J3/J7, ici à J2) est d'origine materno-fœtale.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"man-2__pediatrie__41\",\"num\":\"42\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"II. Questions à Choix Double (QCD : Q35 à Q49)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Le nouveau-né BK a une température à 35°C. Il présente une infection. L'hypothermie est un signe fréquent de l'infection bactérienne néonatale.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Vrai\",\"answerLetters\":[\"A\"],\"explanation\":\"L'hypothermie (< 35,5°C) est un signe majeur d'infection bactérienne grave chez le nouveau-né.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"man-2__pediatrie__42\",\"num\":\"43\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"II. Questions à Choix Double (QCD : Q35 à Q49)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Pour traiter l'hypothermie du nouveau-né BK, je le place en incubateur (couveuse). Cet acte de soins fait partie du rôle de conseils et prévention de l'agent de santé.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"C'est un soin curatif/de suppléance et de collaboration, et non un simple conseil préventif.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"man-2__pediatrie__43\",\"num\":\"44\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"II. Questions à Choix Double (QCD : Q35 à Q49)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Pendant l'hospitalisation, le nouveau-né BK présente une détresse respiratoire avec un indice de Silverman à 7. Pour la prise en charge, l'infirmier major vous conseille de ne pas le gaver. Ce conseil est pertinent.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Vrai\",\"answerLetters\":[\"A\"],\"explanation\":\"Devant une détresse respiratoire sévère (Silverman ≥ 5, ici 7), l'alimentation entérale/gavage est contre-indiquée en raison du risque d'inhalation et de gêne diaphragmatique.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"man-2__pediatrie__44\",\"num\":\"45\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"II. Questions à Choix Double (QCD : Q35 à Q49)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Jusqu'à 2 ans, j'utilise une toise verticale pour la mesure de la taille de l'enfant.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"Avant 2 ans, on mesure l'enfant couché avec une toise HORIZONTALE.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"man-2__pediatrie__45\",\"num\":\"46\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"II. Questions à Choix Double (QCD : Q35 à Q49)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"En Côte d'Ivoire, pour traiter le paludisme grave en 2025, les directives nationales préconisent d'utiliser en première intention l'artésunate per os.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"Le paludisme grave se traite en 1re intention par l'Artésunate INJECTABLE (IV ou IM) et non per os.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"man-2__pediatrie__46\",\"num\":\"47\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"II. Questions à Choix Double (QCD : Q35 à Q49)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Le nourrisson JC présente un muguet buccal. Pour réaliser ses soins buccaux, j'utilise du sérum bicarbonaté dosé à 14 pour 1 000.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Vrai\",\"answerLetters\":[\"A\"],\"explanation\":\"Le sérum bicarbonaté à 14 ‰ alcalinise la cavité buccale contre Candida albicans.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"man-2__pediatrie__47\",\"num\":\"48\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"II. Questions à Choix Double (QCD : Q35 à Q49)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Mme ZW doit reprendre le service après son congé de maternité. Pour nourrir son enfant, l'agent de santé conseille la poursuite de l'allaitement exclusif. Le conseil de l'agent de santé est impertinent.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"Le conseil est pertinent (par expression et conservation du lait maternel donné à la tasse).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"man-2__pediatrie__48\",\"num\":\"49\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"II. Questions à Choix Double (QCD : Q35 à Q49)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Le nourrisson KKA souffre d'une malnutrition aiguë sévère. Je lui administre à l'admission de l'eau sucrée dans l'attente du lait thérapeutique.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Vrai\",\"answerLetters\":[\"A\"],\"explanation\":\"L'administration de 50 ml d'eau sucrée à 10 % à l'admission prévient l'hypoglycémie immédiate. +-----------------------------------------------------------------------+\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null}]},{\"name\":\"Gynéco-obstétrique\",\"slug\":\"gynecologie-obstetrique\",\"pages\":\"\",\"count\":17,\"session\":\"S2\",\"annee\":2025,\"source\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"questions\":[{\"id\":\"man-2__gynecologie-obstetrique__0\",\"num\":\"1\",\"type\":\"CAS_CLINIQUE\",\"typeLabel\":\"Étude de cas / Cas clinique\",\"partieTitle\":null,\"caseTitle\":\"Étude de cas — Mme B.B.B.C. (Q1 à Q17)\",\"caseData\":null,\"text\":\"Selon vous, la sage-femme a-t-elle commis des fautes professionnelles ? Répondre soit par « OUI », soit par « NON ».\",\"options\":[{\"letter\":\"A\",\"text\":\"OUI\"},{\"letter\":\"B\",\"text\":\"NON\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. OUI\",\"answerLetters\":[\"A\"],\"explanation\":\"Oui, la sage-femme a commis plusieurs fautes professionnelles graves en ne réalisant aucun interrogatoire ni examen clinique, en renvoyant chez elle une gestante aux lourds antécédents obstétricaux (salpingectomie droite exposant au risque de GEU controlatérale, antécédent de fentes labio-palatines nécessitant de l'acide folique immédiat) et en différant la CPN1 jusqu'au 2e trimestre ('quand son ventre va sortir').\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"man-2__gynecologie-obstetrique__1\",\"num\":\"2\",\"type\":\"CAS_CLINIQUE\",\"typeLabel\":\"Étude de cas / Cas clinique\",\"partieTitle\":null,\"caseTitle\":\"Étude de cas — Mme B.B.B.C. (Q1 à Q17)\",\"caseData\":null,\"text\":\"Relever l'attitude positive de la sage-femme (mentionnée dans ce texte) qui indique l'exemple que toute sage-femme, digne de ce titre, devrait suivre :\",\"options\":[],\"mode\":\"open\",\"multi\":false,\"answer\":\"« La sage-femme accueille Mme B.B.B.C. » (et réalise le test de grossesse pour confirmer l'état gravidique).\",\"answerLetters\":[],\"explanation\":\"Comme indiqué dans le corrigé officiel de l'épreuve, le seul acte positif mentionné dans le texte est le fait que la sage-femme accueille la patiente à son arrivée.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"man-2__gynecologie-obstetrique__2\",\"num\":\"3\",\"type\":\"CAS_CLINIQUE\",\"typeLabel\":\"Étude de cas / Cas clinique\",\"partieTitle\":null,\"caseTitle\":\"Étude de cas — Mme B.B.B.C. (Q1 à Q17)\",\"caseData\":null,\"text\":\"On suppose que la sage-femme ait commis des fautes professionnelles. Relever ces fautes commises qui sont mentionnées dans ce texte :\",\"options\":[],\"mode\":\"open\",\"multi\":false,\"answer\":\"1) Réalisation d'un test de grossesse sans interrogatoire ni examen clinique préalable (alors qu'elle a un antécédent de salpingectomie droite pour pyosalpinx à haut risque de GEU). 2) Renvoi de la gestante à la maison en lui ordonnant de « revenir prendre son carnet plus tard quand son ventre va sortir » (refus de réaliser la CPN1 précoce du 1er trimestre). 3) Absence totale de prescription (notamment d'acide folique pourtant indispensable dès la période périconceptionnelle vu l'antécédent de bec-de-lièvre, de bilan prénatal, de MILDA et de vaccination Td).\",\"answerLetters\":[],\"explanation\":\"Ces trois fautes violent les normes nationales de la Consultation Prénatale Recentrée (CPNR) qui imposent que la CPN1 soit réalisée dès le 1er trimestre (dès le retard de règles) avec examen complet, dépistage d'une GEU, bilan prénatal, vaccination Td, remise de MILDA et supplémentation immédiate en acide folique.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"man-2__gynecologie-obstetrique__3\",\"num\":\"4\",\"type\":\"CAS_CLINIQUE\",\"typeLabel\":\"Étude de cas / Cas clinique\",\"partieTitle\":null,\"caseTitle\":\"Étude de cas — Mme B.B.B.C. (Q1 à Q17)\",\"caseData\":null,\"text\":\"Le test de grossesse est positif parce que : (Relever la réponse exacte)\",\"options\":[{\"letter\":\"A\",\"text\":\"Les urines de Mme B.B.B.C. contiennent l'hormone chorionique gonadotrope sécrétée par la morula\"},{\"letter\":\"B\",\"text\":\"Les urines ne contiennent pas d'albumine et de sucre\"},{\"letter\":\"C\",\"text\":\"Mme B.B.B.C. a une grossesse gémellaire\"},{\"letter\":\"D\",\"text\":\"Les urines de Mme B.B.B.C. contiennent l'hormone chorionique gonadotrope (HCG)\"},{\"letter\":\"E\",\"text\":\"Les urines contiennent la FSH et la LH\"},{\"letter\":\"F\",\"text\":\"Les urines contiennent une quantité très élevée d'œstrogènes et de progestérone\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"D. Les urines de Mme B.B.B.C. contiennent l'hormone chorionique gonadotrope (HCG)\",\"answerLetters\":[\"D\"],\"explanation\":\"Le test immunologique de grossesse détecte la présence dans les urines de l'Hormone Chorionique Gonadotrope humaine (HCG / β-HCG : D), qui est sécrétée par le trophoblaste (syncytiotrophoblaste) dès la nidation (et non par la morula, ce qui rend A faux).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"man-2__gynecologie-obstetrique__4\",\"num\":\"5\",\"type\":\"CAS_CLINIQUE\",\"typeLabel\":\"Étude de cas / Cas clinique\",\"partieTitle\":null,\"caseTitle\":\"Étude de cas — Mme B.B.B.C. (Q1 à Q17)\",\"caseData\":null,\"text\":\"La gestité antérieure de Mme B.B.B.C. (avant cette grossesse actuelle) est : (Relever la réponse exacte)\",\"options\":[{\"letter\":\"A\",\"text\":\"3\"},{\"letter\":\"B\",\"text\":\"2\"},{\"letter\":\"C\",\"text\":\"1\"},{\"letter\":\"D\",\"text\":\"0\"},{\"letter\":\"E\",\"text\":\"Impossible à relever\"},{\"letter\":\"F\",\"text\":\"Impossible à relever car Mme B.B.B.C. peut avorter encore\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. 2\",\"answerLetters\":[\"B\"],\"explanation\":\"Avant la grossesse actuelle, Mme B.B.B.C. a eu exactement DEUX (02) grossesses : 1) une 1re grossesse arrêtée à 2 mois (œuf clair), et 2) une 2e grossesse (gémellaire, qui compte pour une seule gestité !) arrêtée à 5 mois et demi. (Son pyosalpinx droit est une infection tubaire et non une grossesse). Sa gestité antérieure est donc de 2 (B, et sa gestité actuelle est G3).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"man-2__gynecologie-obstetrique__5\",\"num\":\"6\",\"type\":\"CAS_CLINIQUE\",\"typeLabel\":\"Étude de cas / Cas clinique\",\"partieTitle\":null,\"caseTitle\":\"Étude de cas — Mme B.B.B.C. (Q1 à Q17)\",\"caseData\":null,\"text\":\"La parité actuelle de Mme B.B.B.C. est : (Relever la réponse exacte)\",\"options\":[{\"letter\":\"A\",\"text\":\"3\"},{\"letter\":\"B\",\"text\":\"2\"},{\"letter\":\"C\",\"text\":\"1\"},{\"letter\":\"D\",\"text\":\"0\"},{\"letter\":\"E\",\"text\":\"Impossible à relever\"},{\"letter\":\"F\",\"text\":\"Impossible à relever car Mme B.B.B.C. peut avorter encore\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"D. 0\",\"answerLetters\":[\"D\"],\"explanation\":\"Dans la définition classique africaine/INFAS où le seuil d'accouchement (viabilité) est fixé à 28 SA (6 mois révolus : voir Daloa Gynéco Q30 'L'avortement est l'expulsion avant 28 SA'), l'expulsion à 2 mois et celle à 5 mois et demi (< 6 mois / < 28 SA) sont deux avortements : sa parité est donc égale à 0 (D : nullipare). (Si le barème applique le seuil OMS de 22 SA, l'expulsion à 5,5 mois compte pour P1 [C] ou P2 pour 2 fœtus [B]).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"man-2__gynecologie-obstetrique__6\",\"num\":\"7\",\"type\":\"CAS_CLINIQUE\",\"typeLabel\":\"Étude de cas / Cas clinique\",\"partieTitle\":null,\"caseTitle\":\"Étude de cas — Mme B.B.B.C. (Q1 à Q17)\",\"caseData\":null,\"text\":\"En fonction des antécédents obstétricaux de Mme B.B.B.C. (expulsion de 2 fœtus ayant des malformations dont le bec-de-lièvre suivie de la prise à forte dose d'acide folique), vous pensez à : (Relever la réponse exacte)\",\"options\":[{\"letter\":\"A\",\"text\":\"Une anomalie chromosomique chez Mme B.B.B.C.\"},{\"letter\":\"B\",\"text\":\"Une hémoglobinopathie majeure\"},{\"letter\":\"C\",\"text\":\"Une infection grave\"},{\"letter\":\"D\",\"text\":\"Une anémie par carence en fer\"},{\"letter\":\"E\",\"text\":\"Une anémie (ou déficit) par carence en acide folique\"},{\"letter\":\"F\",\"text\":\"Une anémie normochrome normocytaire\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"E. Une anémie (ou déficit) par carence en acide folique\",\"answerLetters\":[\"E\"],\"explanation\":\"L'antécédent de malformations embryonnaires de type fente labio-palatine (bec-de-lièvre, lié aux défauts de fermeture embryonnaire folato-dépendants) ayant motivé une supplémentation à forte dose d'acide folique oriente directement vers une carence en ACIDE FOLIQUE (vitamine B9 : E).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"man-2__gynecologie-obstetrique__7\",\"num\":\"8\",\"type\":\"CAS_CLINIQUE\",\"typeLabel\":\"Étude de cas / Cas clinique\",\"partieTitle\":null,\"caseTitle\":\"Étude de cas — Mme B.B.B.C. (Q1 à Q17)\",\"caseData\":null,\"text\":\"On suppose que votre amie vous ait téléphoné 2 jours après son aménorrhée secondaire. En fonction des antécédents obstétricaux de votre amie Mme B.B.B.C., vous auriez dû lui dire de : (Relever les 2 éléments sur lesquels vous devriez insister au cours de votre C.C.C.)\",\"options\":[{\"letter\":\"A\",\"text\":\"Commencer aussitôt à prendre du fer\"},{\"letter\":\"B\",\"text\":\"Commencer aussitôt à prendre du fer et de l'acide folique\"},{\"letter\":\"C\",\"text\":\"Commencer aussitôt à prendre de l'acide folique\"},{\"letter\":\"D\",\"text\":\"Commencer aussitôt à prendre du fer en dehors des repas\"},{\"letter\":\"E\",\"text\":\"Dormir sous moustiquaire imprégnée d'insecticide à longue durée d'action (MILDA) avec son mari dès la survenue d'une nouvelle grossesse\"},{\"letter\":\"F\",\"text\":\"Dormir sous MILDA avec son mari et ses enfants dès la survenue d'une nouvelle grossesse\"}],\"mode\":\"mcq\",\"multi\":true,\"answer\":\"C et E\",\"answerLetters\":[\"C\",\"E\"],\"explanation\":\"1) Compte tenu de son antécédent de malformations fœtales (bec-de-lièvre) et du fait qu'elle a arrêté son acide folique il y a 1 mois, il est urgentissime qu'elle reprenne AUSSITÔT L'ACIDE FOLIQUE (C, indispensable dès le 1er mois pour l'organogenèse). 2) Elle doit dormir sous MILDA avec son mari (E — notez le piège de la proposition F qui parle de 'ses enfants' alors que Mme B.B.B.C. n'a aucun enfant vivant !).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"man-2__gynecologie-obstetrique__8\",\"num\":\"9\",\"type\":\"CAS_CLINIQUE\",\"typeLabel\":\"Étude de cas / Cas clinique\",\"partieTitle\":null,\"caseTitle\":\"Étude de cas — Mme B.B.B.C. (Q1 à Q17)\",\"caseData\":null,\"text\":\"À 5 mois de grossesse (24 SA), Mme B.B.B.C. repart à la PMI. La sage-femme lui remet les bulletins de son bilan prénatal et lui dit de prendre la 1re dose de SP associée au fer et à l'acide folique sans autres précisions. Résultats : Rubéole IgG+ IgM- ; O Rhésus négatif ; Électrophorèse Hb = AS ; Toxoplasmose positive (sans précision IgG/IgM) ; Hb = 10,50 g/100 ml ; Alb = 0, Sucre = 0 ; Écho = grossesse monofœtale évolutive de 24 SA sans anomalie. Quelles sont les 2 fautes professionnelles commises par la sage-femme depuis le début parmi les propositions ci-dessous ?\",\"options\":[{\"letter\":\"A\",\"text\":\"La sage-femme accueille Mme B.B.B.C.\"},{\"letter\":\"B\",\"text\":\"Mme B.B.B.C. se retourne chez elle sans d'autre prescription de la part de la sage-femme (lors du 1er contact)\"},{\"letter\":\"C\",\"text\":\"La sage-femme remet un bulletin pour la sérologie de la rubéole (à 5 mois = 24 SA, alors que l'organogenèse du 1er trimestre est déjà terminée et que l'écho morphologique est normale, ou E)\"},{\"letter\":\"D\",\"text\":\"La sage-femme remet un bulletin pour la sérologie de la toxoplasmose\"},{\"letter\":\"E\",\"text\":\"La sage-femme réalise, dans les urines de Mme B.B.B.C., un test de grossesse qui est positif (sans examen préalable)\"},{\"letter\":\"F\",\"text\":\"La sage-femme remet un bulletin pour réaliser une échographie obstétricale\"}],\"mode\":\"mcq\",\"multi\":true,\"answer\":\"B et E\",\"answerLetters\":[\"B\",\"E\"],\"explanation\":\"En se référant directement au corrigé de la Question 3 imprimé à la page 220 du sujet : la faute n°1 est « La sage-femme, sans examen au préalable, réalise dans les urines de Mme B.B.B.C. un test de grossesse » (E) et la faute n°3 est « Mme B.B.B.C. se retourne chez elle sans d'autre prescription de la part de la sage-femme » (B).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"man-2__gynecologie-obstetrique__9\",\"num\":\"10\",\"type\":\"CAS_CLINIQUE\",\"typeLabel\":\"Étude de cas / Cas clinique\",\"partieTitle\":null,\"caseTitle\":\"Étude de cas — Mme B.B.B.C. (Q1 à Q17)\",\"caseData\":null,\"text\":\"Résumer, en 15 lignes manuscrites au maximum, les principales raisons de la nécessité de la prise en charge précoce dès la survenue de l'aménorrhée gravidique chez Mme B.B.B.C. :\",\"options\":[],\"mode\":\"open\",\"multi\":false,\"answer\":\"1) Antécédents obstétricaux lourds : œuf clair, avortement tardif gémellaire avec malformations (bec-de-lièvre) et salpingectomie droite pour pyosalpinx (imposant une échographie précoce pour éliminer une GEU gauche et vérifier l'évolutivité de l'œuf). 2) Nécessité de reprendre immédiatement l'acide folique à dose préventive/forte dose dès le début du 1er trimestre pour prévenir la récidive de malformations embryonnaires. 3) Réaliser précocement le bilan prénatal complet : Groupe sanguin / Rhésus (dépistage du Rhésus négatif), NFS, électrophorèse de l'Hb. 4) Après counseling, réaliser la sérologie du VIH (PTME), la sérologie de la syphilis (TPHA/VDRL), de la rubéole et de la toxoplasmose (IgG/IgM). 5) Débuter la prévention antipalustre par l'utilisation quotidienne de la MILDA. 6) Débuter la vaccination antitétanique et antidiphtérique (Td1 dès le 1er contact). 7) Prodiguer les conseils (CCC/IEC) et planifier le suivi régulier de cette grossesse à haut risque.\",\"answerLetters\":[],\"explanation\":\"Ces 8 points (reproduits dans la grille officielle page 222 du sujet) résument l'intégralité de la conduite à tenir lors de la CPN1 précoce du 1er trimestre chez cette gestante à haut risque.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"man-2__gynecologie-obstetrique__10\",\"num\":\"11\",\"type\":\"CAS_CLINIQUE\",\"typeLabel\":\"Étude de cas / Cas clinique\",\"partieTitle\":null,\"caseTitle\":\"Étude de cas — Mme B.B.B.C. (Q1 à Q17)\",\"caseData\":null,\"text\":\"La sage-femme conclut que Mme B.B.B.C. a une infestation toxoplasmique évolutive (sur la seule mention 'Sérologie de la toxoplasmose positive' sans titrage séparé des IgG et IgM) et elle prescrit de la spiramycine. Parmi les propositions ci-dessous, relever les 2 bonnes réponses :\",\"options\":[{\"letter\":\"A\",\"text\":\"La sage-femme a totalement raison\"},{\"letter\":\"B\",\"text\":\"La sage-femme peut avoir raison parce que Mme B.B.B.C. est une gestante\"},{\"letter\":\"C\",\"text\":\"La sage-femme a totalement tort (de conclure sans le détail IgG/IgM)\"},{\"letter\":\"D\",\"text\":\"La sage-femme peut avoir raison, d'où la nécessité de demander chez Mme B.B.B.C. le dosage séparé des IgG et des IgM dans le même laboratoire\"},{\"letter\":\"E\",\"text\":\"Nécessité de demander le dosage des IgG\"},{\"letter\":\"F\",\"text\":\"Nécessité de demander le dosage des IgM\"}],\"mode\":\"mcq\",\"multi\":true,\"answer\":\"C et D\",\"answerLetters\":[\"C\",\"D\"],\"explanation\":\"Une sérologie toxoplasmique simplement marquée 'positive' signifie le plus souvent une immunité ancienne protectrice (IgG+ et IgM−), mais ne permet pas d'exclure une séroconversion récente sans connaître le statut des IgM et l'avidité des IgG : il est donc indispensable de demander le dosage quantitatif séparé des IgG ET des IgM dans le même laboratoire (D).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"man-2__gynecologie-obstetrique__11\",\"num\":\"12\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":null,\"caseTitle\":\"Étude de cas — Mme B.B.B.C. (Q1 à Q17)\",\"caseData\":null,\"text\":\"À cause du résultat de l'électrophorèse de l'hémoglobine qui révèle une hémoglobine AS (S = 45 %, A = 55 %), je dois organiser la référence de Mme B.B.B.C. Répondre soit par « VRAI » soit par « FAUX ».\",\"options\":[{\"letter\":\"A\",\"text\":\"VRAI\"},{\"letter\":\"B\",\"text\":\"FAUX\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. FAUX\",\"answerLetters\":[\"B\"],\"explanation\":\"FAUX (B) : le phénotype hétérozygote AS (avec A > S : 55 % d'HbA et 45 % d'HbS) est un trait drépanocytaire mineur asymptomatique (porteur sain) qui ne nécessite pas de référence de la gestante pour drépanocytose majeure (il suffit de demander l'électrophorèse de l'Hb du mari pour le conseil génétique du couple).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"man-2__gynecologie-obstetrique__12\",\"num\":\"13\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":null,\"caseTitle\":\"Étude de cas — Mme B.B.B.C. (Q1 à Q17)\",\"caseData\":null,\"text\":\"À cause du résultat du taux d'hémoglobine qui révèle un taux d'hémoglobine = 10,50 g/100 ml (à 24 SA, soit au 2e trimestre), Mme B.B.B.C. n'a pas une anémie. Répondre soit par « VRAI » soit par « FAUX ».\",\"options\":[{\"letter\":\"A\",\"text\":\"VRAI\"},{\"letter\":\"B\",\"text\":\"FAUX\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. VRAI\",\"answerLetters\":[\"A\"],\"explanation\":\"VRAI (A) ! À 24 SA (2e trimestre de la grossesse), en raison de l'hémodilution physiologique maximale, le seuil inférieur normal de l'hémoglobine est de 10,50 g/dl (l'anémie au 2e trimestre se définissant par Hb < 10,5 g/dl). Avec Hb = 10,50 g/dl à 24 SA (cf. aussi Agboville Gynéco Q6), elle est juste à la limite normale et n'a pas d'anémie.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"man-2__gynecologie-obstetrique__13\",\"num\":\"14\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":null,\"caseTitle\":\"Étude de cas — Mme B.B.B.C. (Q1 à Q17)\",\"caseData\":null,\"text\":\"À cause du Rhésus qui est négatif (O Rhésus négatif), je dois demander à Mme B.B.B.C. de réaliser un test de Coombs direct. Répondre soit par « VRAI » soit par « FAUX ».\",\"options\":[{\"letter\":\"A\",\"text\":\"VRAI\"},{\"letter\":\"B\",\"text\":\"FAUX\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. FAUX\",\"answerLetters\":[\"B\"],\"explanation\":\"FAUX (B) ! Chez la femme enceinte Rhésus négatif, on prescrit un test de Coombs INDIRECT (Recherche d'Agglutinines Irrégulières — RAI dans le sérum maternel). Le test de Coombs DIRECT se pratique sur les hématies du NOUVEAU-NÉ (sang du cordon) à la naissance !\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"man-2__gynecologie-obstetrique__14\",\"num\":\"15\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":null,\"caseTitle\":\"Étude de cas — Mme B.B.B.C. (Q1 à Q17)\",\"caseData\":null,\"text\":\"À cause de la sérologie de la rubéole qui est positive à IgG et négative à IgM, je conclus que ce n'est pas une primo-infection rubéolique récente chez Mme B.B.B.C. Répondre soit par « VRAI » soit par « FAUX ».\",\"options\":[{\"letter\":\"A\",\"text\":\"VRAI\"},{\"letter\":\"B\",\"text\":\"FAUX\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. VRAI\",\"answerLetters\":[\"A\"],\"explanation\":\"VRAI (A) ! La présence d'anticorps IgG positifs associée à l'absence d'IgM (IgM négatives) prouve une immunité ancienne protectrice acquise avant la grossesse et écarte une primo-infection rubéolique aiguë.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"man-2__gynecologie-obstetrique__15\",\"num\":\"16\",\"type\":\"CAS_CLINIQUE\",\"typeLabel\":\"Étude de cas / Cas clinique\",\"partieTitle\":null,\"caseTitle\":\"Étude de cas — Mme B.B.B.C. (Q1 à Q17)\",\"caseData\":null,\"text\":\"La sage-femme dit à Mme B.B.B.C. de prendre, en sa présence, la 1re dose de SP*, associée au fer et à l'acide folique, sans autres précisions supplémentaires. Êtes-vous d'accord avec cette sage-femme ? Répondre soit par « OUI », soit par « NON ».\",\"options\":[{\"letter\":\"A\",\"text\":\"OUI\"},{\"letter\":\"B\",\"text\":\"NON\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. NON\",\"answerLetters\":[\"B\"],\"explanation\":\"NON (B) ! Comme l'explique la Question 17 ci-dessous, la sage-femme a omis deux précisions pharmacologiques capitales concernant l'interaction entre l'acide folique à forte dose et la SP ainsi que l'horaire de prise du fer.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"man-2__gynecologie-obstetrique__16\",\"num\":\"17\",\"type\":\"CAS_CLINIQUE\",\"typeLabel\":\"Étude de cas / Cas clinique\",\"partieTitle\":null,\"caseTitle\":\"Étude de cas — Mme B.B.B.C. (Q1 à Q17)\",\"caseData\":null,\"text\":\"Prière justifier votre réponse à la question 16 en apportant des précisions supplémentaires en 5 lignes manuscrites au maximum :\",\"options\":[],\"mode\":\"open\",\"multi\":false,\"answer\":\"1) Dès la prise de la Sulfadoxine-Pyriméthamine (SP*), Mme B.B.B.C. (qui prenait de l'acide folique à forte dose ≥ 5 mg/j) doit suspendre la prise d'acide folique pendant 15 jours (2 semaines) avant de le reprendre, car l'acide folique à forte dose inhibe par compétition l'action antipaludique de la SP. 2) Elle doit prendre le fer par voie orale en dehors des repas (soit à jeun, soit au moins 2 heures après ou 30-60 min avant le repas) pour optimiser son absorption intestinale.\",\"answerLetters\":[],\"explanation\":\"Ces deux règles pharmacologiques (imprimées dans le corrigé officiel page 223 du sujet) justifient pourquoi la prescription sans explication de la sage-femme était fautive. +-----------------------------------------------------------------------+\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null}]},{\"name\":\"SSR / PF\",\"slug\":\"ssr-pf\",\"pages\":\"\",\"count\":50,\"session\":\"S2\",\"annee\":2025,\"source\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"questions\":[{\"id\":\"man-2__ssr-pf__0\",\"num\":\"1\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"I. Questions à Choix Double (QCD : Q1 à Q20)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Fanta qui a raté le renouvellement de son injection de Depo-Provera le 10 septembre pourra le faire le 18 septembre.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Vrai\",\"answerLetters\":[\"A\"],\"explanation\":\"Médicalement (directives OMS), un retard de 8 jours pour le DMPA est largement dans le délai de grâce (14 à 28 jours) ; toutefois, dans le corrigé de la cellule de Bouaké/Man (voir Bouaké PF Q1), cette question était notée Faux (B).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"man-2__ssr-pf__1\",\"num\":\"2\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"I. Questions à Choix Double (QCD : Q1 à Q20)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Katérine qui utilise un contraceptif oral combiné de 28 comprimés peut ne pas prendre les comprimés de couleur marron.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"Elle doit prendre quotidiennement les 7 comprimés marron (fer) pour maintenir la régularité de la prise et apporter du fer.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"man-2__ssr-pf__2\",\"num\":\"3\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"I. Questions à Choix Double (QCD : Q1 à Q20)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Lorsque l'implant est inséré dans les 7 premiers jours du cycle, l'utilisatrice doit utiliser une méthode d'appoint.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"Posé dans les 5 à 7 premiers jours du cycle menstruel, l'implant est immédiatement efficace sans méthode d'appoint.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"man-2__ssr-pf__3\",\"num\":\"4\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"I. Questions à Choix Double (QCD : Q1 à Q20)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Une athlète qui pratique la natation ne peut pas utiliser le patch contraceptif.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"Le patch contraceptif résiste à l'eau et permet la pratique de la natation.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"man-2__ssr-pf__4\",\"num\":\"5\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"I. Questions à Choix Double (QCD : Q1 à Q20)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Les méthodes d'auto-observation ne prennent en compte que la période de l'ovulation.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"Elles prennent aussi en compte la durée de survie des spermatozoïdes (3 à 5 jours avant l'ovulation) et de l'ovule (24 h après).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"man-2__ssr-pf__5\",\"num\":\"6\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"I. Questions à Choix Double (QCD : Q1 à Q20)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Le dispositif intra-utérin du post-abortum ne convient pas aux nullipares.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"Le DIU post-abortum (après avortement non septique) peut être posé chez une nullipare.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"man-2__ssr-pf__6\",\"num\":\"7\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"I. Questions à Choix Double (QCD : Q1 à Q20)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Le coût et la sûreté sont des qualités d'une bonne méthode de contraception.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Vrai\",\"answerLetters\":[\"A\"],\"explanation\":\"Le coût abordable et la sûreté (innocuité) font partie des 5 critères de qualité d'une méthode contraceptive.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"man-2__ssr-pf__7\",\"num\":\"8\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"I. Questions à Choix Double (QCD : Q1 à Q20)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Le moment propice pour le counseling initial se situe à la phase active du travail.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"En PFPP, le counseling initial se fait pendant les CPN, en phase de latence ou en post-partum, et non pendant les douleurs de la phase active du travail.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"man-2__ssr-pf__8\",\"num\":\"9\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"I. Questions à Choix Double (QCD : Q1 à Q20)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"La contraception du post-partum concerne les 12 premiers mois après l'accouchement.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Vrai\",\"answerLetters\":[\"A\"],\"explanation\":\"Oui, la PFPP couvre les 12 premiers mois suivant l'accouchement.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"man-2__ssr-pf__9\",\"num\":\"10\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"I. Questions à Choix Double (QCD : Q1 à Q20)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Le DIU au cuivre peut être utilisé comme contraceptif d'urgence.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Vrai\",\"answerLetters\":[\"A\"],\"explanation\":\"Posé dans les 5 jours suivant le rapport non protégé, le DIU au cuivre est la méthode de contraception d'urgence la plus efficace (> 99 %).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"man-2__ssr-pf__10\",\"num\":\"11\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"I. Questions à Choix Double (QCD : Q1 à Q20)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Les contraceptifs hormonaux progestatifs contiennent une faible quantité d'œstrogène.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"Ils ne contiennent aucun œstrogène.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"man-2__ssr-pf__11\",\"num\":\"12\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"I. Questions à Choix Double (QCD : Q1 à Q20)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"La méthode de la température basale agit en empêchant les spermatozoïdes d'atteindre l'ovule.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Vrai\",\"answerLetters\":[\"A\"],\"explanation\":\"Par l'abstinence périodique durant la phase fertile repérée par la courbe thermique, elle évite la rencontre entre spermatozoïdes et ovule.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"man-2__ssr-pf__12\",\"num\":\"13\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"I. Questions à Choix Double (QCD : Q1 à Q20)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Le stock de roulement est la quantité nécessaire pour couvrir la période entre deux approvisionnements.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Vrai\",\"answerLetters\":[\"A\"],\"explanation\":\"C'est la définition exacte du stock de roulement.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"man-2__ssr-pf__13\",\"num\":\"14\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"I. Questions à Choix Double (QCD : Q1 à Q20)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Le counseling se concentre sur les besoins collectifs des clients.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"Le counseling se concentre sur les besoins INDIVIDUELS de chaque client(e).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"man-2__ssr-pf__14\",\"num\":\"15\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"I. Questions à Choix Double (QCD : Q1 à Q20)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"La planification familiale évite les grossesses (non désirées) et espace les naissances.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Vrai\",\"answerLetters\":[\"A\"],\"explanation\":\"Oui, c'est le but fondamental de la PF.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"man-2__ssr-pf__15\",\"num\":\"16\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"I. Questions à Choix Double (QCD : Q1 à Q20)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"À l'approche de l'ovulation, la consistance du mucus cervical est épaisse.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"À l'approche de l'ovulation, la glaire cervicale est fluide, filante et transparente.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"man-2__ssr-pf__16\",\"num\":\"17\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"I. Questions à Choix Double (QCD : Q1 à Q20)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Dans la méthode du calendrier, le cycle le plus long moins 11 détermine le début de la période fertile.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"Cycle le plus long − 11 détermine la FIN de la période fertile (le début est Cycle le plus court − 18).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"man-2__ssr-pf__17\",\"num\":\"18\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"I. Questions à Choix Double (QCD : Q1 à Q20)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Le test de Coombs indirect recherche des agglutinines irrégulières après injection d'immunoglobulines.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"Il se réalise AVANT toute injection d'immunoglobulines anti-D.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"man-2__ssr-pf__18\",\"num\":\"19\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"I. Questions à Choix Double (QCD : Q1 à Q20)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"La galactophorite se manifeste par du lait mêlé à du pus à l'expression mamelonnaire.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Vrai\",\"answerLetters\":[\"A\"],\"explanation\":\"Oui, c'est le signe de Budin positif, caractéristique de la galactophorite.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"man-2__ssr-pf__19\",\"num\":\"20\",\"type\":\"QCD\",\"typeLabel\":\"QCD\",\"partieTitle\":\"I. Questions à Choix Double (QCD : Q1 à Q20)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"La drépanocytose est une hémoglobinopathie quantitative.\",\"options\":[{\"letter\":\"A\",\"text\":\"Vrai\"},{\"letter\":\"B\",\"text\":\"Faux\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Faux\",\"answerLetters\":[\"B\"],\"explanation\":\"C'est une hémoglobinopathie QUALITATIVE (de structure).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"man-2__ssr-pf__20\",\"num\":\"21\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"II. Questions à Choix Multiples (QCM : Q21 à Q30)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Quel est le processus normal d'adoption d'un nouveau comportement ?\",\"options\":[{\"letter\":\"A\",\"text\":\"Information, approbation, décision, action, promotion\"},{\"letter\":\"B\",\"text\":\"Information, décision, approbation, action, promotion\"},{\"letter\":\"C\",\"text\":\"Approbation, décision, action, information, promotion\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Information, approbation, décision, action, promotion\",\"answerLetters\":[\"A\"],\"explanation\":\"Ordre séquentiel CCSC : Information → Approbation → Décision → Action → Promotion (A).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"man-2__ssr-pf__21\",\"num\":\"22\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"II. Questions à Choix Multiples (QCM : Q21 à Q30)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Dans quel délai doit-on administrer Ovrette en contraception d'urgence ?\",\"options\":[{\"letter\":\"A\",\"text\":\"120 heures\"},{\"letter\":\"B\",\"text\":\"72 heures\"},{\"letter\":\"C\",\"text\":\"48 heures\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. 72 heures\",\"answerLetters\":[\"B\"],\"explanation\":\"La contraception hormonale d'urgence par pilules progestatives (Ovrette / Lévonorgestrel) doit être débutée dans les 72 heures suivant le rapport non protégé (B).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"man-2__ssr-pf__22\",\"num\":\"23\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"II. Questions à Choix Multiples (QCM : Q21 à Q30)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Quelle question poser pour le suivi de la méthode MAMA ?\",\"options\":[{\"letter\":\"A\",\"text\":\"Avez-vous un engorgement mammaire ?\"},{\"letter\":\"B\",\"text\":\"Avez-vous ajouté d'autres aliments à l'enfant ?\"},{\"letter\":\"C\",\"text\":\"Combien d'enfants avez-vous ?\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Avez-vous ajouté d'autres aliments à l'enfant ?\",\"answerLetters\":[\"B\"],\"explanation\":\"On vérifie que l'allaitement est toujours strictement exclusif (B).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"man-2__ssr-pf__23\",\"num\":\"24\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"II. Questions à Choix Multiples (QCM : Q21 à Q30)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Quelle est la période d'abstinence dans la méthode des jours fixes (collier du cycle) ?\",\"options\":[{\"letter\":\"A\",\"text\":\"8e au 19e jour\"},{\"letter\":\"B\",\"text\":\"8e au 20e jour\"},{\"letter\":\"C\",\"text\":\"9e au 18e jour\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. 8e au 19e jour\",\"answerLetters\":[\"A\"],\"explanation\":\"Du 8e au 19e jour inclus du cycle (perles blanches du collier : A).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"man-2__ssr-pf__24\",\"num\":\"25\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"II. Questions à Choix Multiples (QCM : Q21 à Q30)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Quel est le mode d'action des spermicides ?\",\"options\":[{\"letter\":\"A\",\"text\":\"Empêchent la rencontre des gamètes\"},{\"letter\":\"B\",\"text\":\"Modifient la glaire cervicale\"},{\"letter\":\"C\",\"text\":\"Inactivent les spermatozoïdes\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"C. Inactivent les spermatozoïdes\",\"answerLetters\":[\"C\"],\"explanation\":\"Les spermicides détruisent la membrane des spermatozoïdes et les inactivent (C).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"man-2__ssr-pf__25\",\"num\":\"26\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"II. Questions à Choix Multiples (QCM : Q21 à Q30)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Quand retirer le préservatif masculin ?\",\"options\":[{\"letter\":\"A\",\"text\":\"Pendant l'éjaculation\"},{\"letter\":\"B\",\"text\":\"Avant la fin de l'érection\"},{\"letter\":\"C\",\"text\":\"Après la chute de l'érection\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Avant la fin de l'érection\",\"answerLetters\":[\"B\"],\"explanation\":\"Le retrait de la verge en maintenant le condom à sa base doit se faire immédiatement après l'éjaculation, avant la fin de l'érection (B).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"man-2__ssr-pf__26\",\"num\":\"27\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"II. Questions à Choix Multiples (QCM : Q21 à Q30)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Quand faire le 2e contrôle d'un implant ?\",\"options\":[{\"letter\":\"A\",\"text\":\"3 mois après\"},{\"letter\":\"B\",\"text\":\"3 semaines après\"},{\"letter\":\"C\",\"text\":\"3 jours après\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. 3 mois après\",\"answerLetters\":[\"A\"],\"explanation\":\"Après le 1er contrôle à 7 jours, le 2e contrôle d'un implant se fait à 3 mois (A).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"man-2__ssr-pf__27\",\"num\":\"28\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"II. Questions à Choix Multiples (QCM : Q21 à Q30)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Quelle cliente peut recevoir un DIU ?\",\"options\":[{\"letter\":\"A\",\"text\":\"28e jour du cycle\"},{\"letter\":\"B\",\"text\":\"Veille des règles\"},{\"letter\":\"C\",\"text\":\"18e jour du cycle\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. 28e jour du cycle\",\"answerLetters\":[\"A\"],\"explanation\":\"Identique à Bouaké PF Q38.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"man-2__ssr-pf__28\",\"num\":\"29\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"II. Questions à Choix Multiples (QCM : Q21 à Q30)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Quand vérifier les fils d'un DIU post-partum ?\",\"options\":[{\"letter\":\"A\",\"text\":\"14 semaines\"},{\"letter\":\"B\",\"text\":\"6 semaines\"},{\"letter\":\"C\",\"text\":\"12 semaines\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. 6 semaines\",\"answerLetters\":[\"B\"],\"explanation\":\"Le contrôle du DIUPP et la coupe éventuelle des fils se font à 4–6 semaines post-partum (B).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"man-2__ssr-pf__29\",\"num\":\"30\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"II. Questions à Choix Multiples (QCM : Q21 à Q30)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Quel contraceptif proscrire après un avortement septique ?\",\"options\":[{\"letter\":\"A\",\"text\":\"Ovrette\"},{\"letter\":\"B\",\"text\":\"DIU\"},{\"letter\":\"C\",\"text\":\"Jadelle\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. DIU\",\"answerLetters\":[\"B\"],\"explanation\":\"Le DIU est formellement contre-indiqué (Catégorie 4 OMS) après un avortement septique (B).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"man-2__ssr-pf__30\",\"num\":\"31\",\"type\":\"CAS_CLINIQUE\",\"typeLabel\":\"Étude de cas / Cas clinique\",\"partieTitle\":\"II. Questions à Choix Multiples (QCM : Q21 à Q30)\",\"caseTitle\":\"Étude de cas 1 — Mme Yéo (Q31 à Q35)\",\"caseData\":null,\"text\":\"Madame Yéo peut-elle être enceinte si elle a un rapport le 24/10 (pendant la semaine des comprimés marron) ?\",\"options\":[{\"letter\":\"A\",\"text\":\"Oui\"},{\"letter\":\"B\",\"text\":\"Non\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Non\",\"answerLetters\":[\"B\"],\"explanation\":\"Non (B), car les comprimés marron ne contiennent pas d'hormone et elle reste protégée pendant les 7 jours suivant le 21e comprimé actif.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"man-2__ssr-pf__31\",\"num\":\"32\",\"type\":\"CAS_CLINIQUE\",\"typeLabel\":\"Étude de cas / Cas clinique\",\"partieTitle\":\"II. Questions à Choix Multiples (QCM : Q21 à Q30)\",\"caseTitle\":\"Étude de cas 1 — Mme Yéo (Q31 à Q35)\",\"caseData\":null,\"text\":\"Que lui conseiller (pour l'oubli des comprimés marron) ?\",\"options\":[{\"letter\":\"A\",\"text\":\"Pilule du lendemain\"},{\"letter\":\"B\",\"text\":\"Méthode barrière\"},{\"letter\":\"C\",\"text\":\"Aucune disposition particulière (puis débuter une nouvelle plaquette au 8e jour)\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"C. Aucune disposition particulière (puis débuter une nouvelle plaquette au 8e jour)\",\"answerLetters\":[\"C\"],\"explanation\":\"L'oubli des comprimés marron (fer) est sans conséquence contraceptive tant que la nouvelle plaquette est reprise à la date prévue au bout des 7 jours (C).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"man-2__ssr-pf__32\",\"num\":\"33\",\"type\":\"CAS_CLINIQUE\",\"typeLabel\":\"Étude de cas / Cas clinique\",\"partieTitle\":\"II. Questions à Choix Multiples (QCM : Q21 à Q30)\",\"caseTitle\":\"Étude de cas 1 — Mme Yéo (Q31 à Q35)\",\"caseData\":null,\"text\":\"Mode d'action des pilules combinées ?\",\"options\":[{\"letter\":\"A\",\"text\":\"Blocage ovulation + tue les spermatozoïdes\"},{\"letter\":\"B\",\"text\":\"Blocage ovulation + épaississement glaire (+ atrophie endomètre)\"},{\"letter\":\"C\",\"text\":\"Blocage partiel + modification endomètre\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Blocage ovulation + épaississement glaire (+ atrophie endomètre)\",\"answerLetters\":[\"B\"],\"explanation\":\"Les COC bloquent l'ovulation, épaississent la glaire cervicale et rendent l'endomètre impropre à la nidation (B).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"man-2__ssr-pf__33\",\"num\":\"34\",\"type\":\"CAS_CLINIQUE\",\"typeLabel\":\"Étude de cas / Cas clinique\",\"partieTitle\":\"II. Questions à Choix Multiples (QCM : Q21 à Q30)\",\"caseTitle\":\"Étude de cas 1 — Mme Yéo (Q31 à Q35)\",\"caseData\":null,\"text\":\"Quand débuter une nouvelle plaquette ?\",\"options\":[{\"letter\":\"A\",\"text\":\"Lendemain du dernier comprimé marron\"},{\"letter\":\"B\",\"text\":\"Fin des règles\"},{\"letter\":\"C\",\"text\":\"Dès survenue des règles\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Lendemain du dernier comprimé marron\",\"answerLetters\":[\"A\"],\"explanation\":\"Sans aucun jour d'arrêt entre deux plaquettes de 28 comprimés, soit le lendemain du 7e comprimé marron (A).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"man-2__ssr-pf__34\",\"num\":\"35\",\"type\":\"CAS_CLINIQUE\",\"typeLabel\":\"Étude de cas / Cas clinique\",\"partieTitle\":\"II. Questions à Choix Multiples (QCM : Q21 à Q30)\",\"caseTitle\":\"Étude de cas 1 — Mme Yéo (Q31 à Q35)\",\"caseData\":null,\"text\":\"Quelle méthode associer pour éviter les IST ?\",\"options\":[{\"letter\":\"A\",\"text\":\"Implant\"},{\"letter\":\"B\",\"text\":\"Fémidon\"},{\"letter\":\"C\",\"text\":\"DIU\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Fémidon\",\"answerLetters\":[\"B\"],\"explanation\":\"Le Fémidon (préservatif féminin : B) protège contre les IST/VIH.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"man-2__ssr-pf__35\",\"num\":\"36\",\"type\":\"CAS_CLINIQUE\",\"typeLabel\":\"Étude de cas / Cas clinique\",\"partieTitle\":\"II. Questions à Choix Multiples (QCM : Q21 à Q30)\",\"caseTitle\":\"Étude de cas 2 — Mlle Cindy (Q36 à Q40)\",\"caseData\":null,\"text\":\"Catégorie OMS des contraceptifs combinés pour Cindy (allaitante à 6 semaines post-partum) ?\",\"options\":[{\"letter\":\"A\",\"text\":\"Catégorie 1\"},{\"letter\":\"B\",\"text\":\"Catégorie 2\"},{\"letter\":\"C\",\"text\":\"Catégorie 3\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"C. Catégorie 3\",\"answerLetters\":[\"C\"],\"explanation\":\"Entre 6 semaines et 6 mois post-partum chez la femme allaitante, les CHC sont de Catégorie 3 (C).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"man-2__ssr-pf__36\",\"num\":\"37\",\"type\":\"CAS_CLINIQUE\",\"typeLabel\":\"Étude de cas / Cas clinique\",\"partieTitle\":\"II. Questions à Choix Multiples (QCM : Q21 à Q30)\",\"caseTitle\":\"Étude de cas 2 — Mlle Cindy (Q36 à Q40)\",\"caseData\":null,\"text\":\"Méthode appropriée pour elle ?\",\"options\":[{\"letter\":\"A\",\"text\":\"COC\"},{\"letter\":\"B\",\"text\":\"POP (Pilule progestative / COP)\"},{\"letter\":\"C\",\"text\":\"Patch\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. POP (Pilule progestative / COP)\",\"answerLetters\":[\"B\"],\"explanation\":\"La pilule progestative seule (POP / COP : B) est de Catégorie 1 à 6 semaines post-partum et n'altère pas la lactation.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"man-2__ssr-pf__37\",\"num\":\"38\",\"type\":\"CAS_CLINIQUE\",\"typeLabel\":\"Étude de cas / Cas clinique\",\"partieTitle\":\"II. Questions à Choix Multiples (QCM : Q21 à Q30)\",\"caseTitle\":\"Étude de cas 2 — Mlle Cindy (Q36 à Q40)\",\"caseData\":null,\"text\":\"Retour de fécondité chez une femme allaitante (exclusivement) ?\",\"options\":[{\"letter\":\"A\",\"text\":\"Probabilité élevée d'ovulation avant 6 mois\"},{\"letter\":\"B\",\"text\":\"Infécondité plus courte\"},{\"letter\":\"C\",\"text\":\"Faible probabilité d'ovulation avant 6 mois\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"C. Faible probabilité d'ovulation avant 6 mois\",\"answerLetters\":[\"C\"],\"explanation\":\"En allaitement exclusif et aménorrhée, le risque d'ovulation avant 6 mois est très faible (< 2 % : C).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"man-2__ssr-pf__38\",\"num\":\"39\",\"type\":\"CAS_CLINIQUE\",\"typeLabel\":\"Étude de cas / Cas clinique\",\"partieTitle\":\"II. Questions à Choix Multiples (QCM : Q21 à Q30)\",\"caseTitle\":\"Étude de cas 2 — Mlle Cindy (Q36 à Q40)\",\"caseData\":null,\"text\":\"Conditions pour utiliser la MAMA ?\",\"options\":[{\"letter\":\"A\",\"text\":\"Allaitement exclusif, aménorrhée, bébé < 6 mois\"},{\"letter\":\"B\",\"text\":\"Allaitement partiel, retour de couches\"},{\"letter\":\"C\",\"text\":\"Allaitement exclusif uniquement\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Allaitement exclusif, aménorrhée, bébé < 6 mois\",\"answerLetters\":[\"A\"],\"explanation\":\"Les 3 critères cumulatifs de la MAMA sont : allaitement exclusif, aménorrhée et bébé < 6 mois (A).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"man-2__ssr-pf__39\",\"num\":\"40\",\"type\":\"CAS_CLINIQUE\",\"typeLabel\":\"Étude de cas / Cas clinique\",\"partieTitle\":\"II. Questions à Choix Multiples (QCM : Q21 à Q30)\",\"caseTitle\":\"Étude de cas 2 — Mlle Cindy (Q36 à Q40)\",\"caseData\":null,\"text\":\"Intervalle minimum OMS entre une naissance vivante et la prochaine grossesse ?\",\"options\":[{\"letter\":\"A\",\"text\":\"12 mois\"},{\"letter\":\"B\",\"text\":\"18 mois\"},{\"letter\":\"C\",\"text\":\"24 mois\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"C. 24 mois\",\"answerLetters\":[\"C\"],\"explanation\":\"L'OMS recommande d'attendre au moins 24 mois après une naissance vivante avant de concevoir à nouveau (C).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"man-2__ssr-pf__40\",\"num\":\"41\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"III. Questions Supplémentaires d'Obstétrique et PF (Q41 à Q50)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Quelle est l'infection urinaire la plus fréquente pendant la grossesse ?\",\"options\":[{\"letter\":\"A\",\"text\":\"Urétrite\"},{\"letter\":\"B\",\"text\":\"Pyélonéphrite\"},{\"letter\":\"C\",\"text\":\"Bactériurie asymptomatique\"},{\"letter\":\"D\",\"text\":\"Cystite aiguë\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"C. Bactériurie asymptomatique\",\"answerLetters\":[\"C\"],\"explanation\":\"La bactériurie asymptomatique est la forme la plus fréquente d'infection urinaire au cours de la grossesse (5 à 10 % : C).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"man-2__ssr-pf__41\",\"num\":\"42\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"III. Questions Supplémentaires d'Obstétrique et PF (Q41 à Q50)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Quelle présentation a pour diamètre d'engagement l'occipito-frontal (12 cm) ?\",\"options\":[{\"letter\":\"A\",\"text\":\"Front\"},{\"letter\":\"B\",\"text\":\"Sommet\"},{\"letter\":\"C\",\"text\":\"Bregma\"},{\"letter\":\"D\",\"text\":\"Face\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"C. Bregma\",\"answerLetters\":[\"C\"],\"explanation\":\"La présentation du bregma (tête en attitude indifférente) s'engage par le diamètre occipito-frontal de 12 cm (C).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"man-2__ssr-pf__42\",\"num\":\"43\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"III. Questions Supplémentaires d'Obstétrique et PF (Q41 à Q50)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Quels sont deux facteurs favorisant la procidence du cordon ?\",\"options\":[{\"letter\":\"A\",\"text\":\"Siège décomplété\"},{\"letter\":\"B\",\"text\":\"Céphalique\"},{\"letter\":\"C\",\"text\":\"Transverse (présentation de l'épaule)\"},{\"letter\":\"D\",\"text\":\"Hydramnios\"}],\"mode\":\"mcq\",\"multi\":true,\"answer\":\"C et D\",\"answerLetters\":[\"C\",\"D\"],\"explanation\":\"La présentation transverse (C) et l'hydramnios (D) favorisent au maximum la procidence du cordon.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"man-2__ssr-pf__43\",\"num\":\"44\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"III. Questions Supplémentaires d'Obstétrique et PF (Q41 à Q50)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Quelles sont deux causes classiques de coagulopathie (CIVD) en obstétrique ?\",\"options\":[{\"letter\":\"A\",\"text\":\"Mort fœtale in utero (rétention prolongée)\"},{\"letter\":\"B\",\"text\":\"Placenta praevia\"},{\"letter\":\"C\",\"text\":\"HRP (Hématome rétroplacentaire)\"},{\"letter\":\"D\",\"text\":\"Macrosomie\"}],\"mode\":\"mcq\",\"multi\":true,\"answer\":\"A et C\",\"answerLetters\":[\"A\",\"C\"],\"explanation\":\"La rétention de MFIU (A) et l'HRP (C) libèrent des thromboplastines tissulaires déclenchant une CIVD.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"man-2__ssr-pf__44\",\"num\":\"45\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"III. Questions Supplémentaires d'Obstétrique et PF (Q41 à Q50)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Quels sont deux organes érectiles chez la femme ?\",\"options\":[{\"letter\":\"A\",\"text\":\"Vulve\"},{\"letter\":\"B\",\"text\":\"Clitoris\"},{\"letter\":\"C\",\"text\":\"Petites lèvres\"},{\"letter\":\"D\",\"text\":\"Bulbe vestibulaire\"}],\"mode\":\"mcq\",\"multi\":true,\"answer\":\"B et D\",\"answerLetters\":[\"B\",\"D\"],\"explanation\":\"Le clitoris (B) et les bulbes vestibulaires (D) constituent les organes érectiles féminins.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"man-2__ssr-pf__45\",\"num\":\"46\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"III. Questions Supplémentaires d'Obstétrique et PF (Q41 à Q50)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Que faire en cas de décollement du patch contraceptif depuis moins de 24 heures (< 24 h) ?\",\"options\":[{\"letter\":\"A\",\"text\":\"Le recoller s'il adhère encore ou remettre immédiatement un nouveau patch (sans besoin de méthode d'appoint)\"},{\"letter\":\"B\",\"text\":\"Contraception d'urgence\"},{\"letter\":\"C\",\"text\":\"Attendre les règles\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Le recoller s'il adhère encore ou remettre immédiatement un nouveau patch (sans besoin de méthode d'appoint)\",\"answerLetters\":[\"A\"],\"explanation\":\"Si le patch est décollé depuis moins de 24 heures, l'effet contraceptif est maintenu : il suffit de le recoller fermement ou d'appliquer immédiatement un nouveau patch (A) et de conserver le jour habituel de changement.\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"man-2__ssr-pf__46\",\"num\":\"47\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"III. Questions Supplémentaires d'Obstétrique et PF (Q41 à Q50)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Que faire si l'anneau vaginal contraceptif glisse (est expulsé accidentellement pendant moins de 3 heures) ?\",\"options\":[{\"letter\":\"A\",\"text\":\"Nouvel anneau\"},{\"letter\":\"B\",\"text\":\"Rincer à l'eau froide/tiède et réinsérer immédiatement\"},{\"letter\":\"C\",\"text\":\"Attendre les règles\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Rincer à l'eau froide/tiède et réinsérer immédiatement\",\"answerLetters\":[\"B\"],\"explanation\":\"Si l'anneau vaginal est expulsé accidentellement, il doit être rincé à l'eau propre froide ou tiède (jamais d'eau chaude) et réinséré dès que possible dans le vagin (dans les 3 heures, l'efficacité contraceptive est intégralement maintenue : B).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"man-2__ssr-pf__47\",\"num\":\"48\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"III. Questions Supplémentaires d'Obstétrique et PF (Q41 à Q50)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Quel instrument spécifique est utilisé pour l'insertion d'un DIU du post-partum (DIUPP) au fond de l'utérus ?\",\"options\":[{\"letter\":\"A\",\"text\":\"Inséreur classique\"},{\"letter\":\"B\",\"text\":\"Hystéromètre\"},{\"letter\":\"C\",\"text\":\"Pince de Kelly (longue pince placentaire courbe de Kelly de 32 cm)\"},{\"letter\":\"D\",\"text\":\"Spéculum\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"C. Pince de Kelly (longue pince placentaire courbe de Kelly de 32 cm)\",\"answerLetters\":[\"C\"],\"explanation\":\"Pour déposer le DIU tout au fond d'un grand utérus du post-partum immédiat (où l'inséreur standard est trop court et où l'hystéromètre est proscrit), l'instrument spécifique de référence est la longue pince courbe placentaire dite PINCE DE KELLY (C, associée aux valves vaginales).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"man-2__ssr-pf__48\",\"num\":\"49\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"III. Questions Supplémentaires d'Obstétrique et PF (Q41 à Q50)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Comment réduire le risque d'infection lors de la pose d'un DIU ?\",\"options\":[{\"letter\":\"A\",\"text\":\"Technique « sans toucher » (no-touch technique : ne jamais toucher les branches du DIU ni l'extrémité utérine de l'inséreur/pince, et ne pas toucher les parois vaginales en franchissant le col)\"},{\"letter\":\"B\",\"text\":\"Gants stériles uniquement\"},{\"letter\":\"C\",\"text\":\"Antibiothérapie systématique\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"A. Technique « sans toucher » (no-touch technique : ne jamais toucher les branches du DIU ni l'extrémité utérine de l'inséreur/pince, et ne pas toucher les parois vaginales en franchissant le col)\",\"answerLetters\":[\"A\"],\"explanation\":\"Dans la formation clinique PF (Jhpiego/OMS), la mesure technique clé pour prévenir l'infection lors du chargement et de l'insertion du DIU est la technique « SANS TOUCHER » (charging du DIU à l'intérieur de son emballage stérile et franchissement du col nettoyé sans toucher les parois vaginales : A).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null},{\"id\":\"man-2__ssr-pf__49\",\"num\":\"50\",\"type\":\"QCM\",\"typeLabel\":\"QCM\",\"partieTitle\":\"III. Questions Supplémentaires d'Obstétrique et PF (Q41 à Q50)\",\"caseTitle\":null,\"caseData\":null,\"text\":\"Que faire en cas d'oubli d'une pilule microprogestative (COP ex. Ovrette/Microlut au lévonorgestrel) de plus de 3 heures (> 3 h) ?\",\"options\":[{\"letter\":\"A\",\"text\":\"Continuer sans changement\"},{\"letter\":\"B\",\"text\":\"Prendre la pilule oubliée dès que possible et utiliser une méthode d'appoint (préservatif/abstinence) pendant 48 heures (2 jours)\"},{\"letter\":\"C\",\"text\":\"Arrêter et attendre les règles\"},{\"letter\":\"D\",\"text\":\"Contraception d'urgence uniquement\"}],\"mode\":\"mcq\",\"multi\":false,\"answer\":\"B. Prendre la pilule oubliée dès que possible et utiliser une méthode d'appoint (préservatif/abstinence) pendant 48 heures (2 jours)\",\"answerLetters\":[\"B\"],\"explanation\":\"Contrairement aux COC qui tolèrent 12 à 24 h de décalage, les pilules microprogestatives classiques (au lévonorgestrel/norgestrel) exigent une prise à heure stricte (tolérance maximale de 3 heures) car leur effet sur la glaire cervicale s'estompe rapidement. En cas de retard > 3 heures, il faut prendre le comprimé oublié immédiatement et utiliser une méthode barrière d'appoint (ou s'abstenir) pendant les 48 heures suivantes (B).\",\"sourceDoc\":\"Corrigé intégral D.E blanc 2025 Sage-Femme (8 antennes)\",\"sourceFile\":\"Corrige_Integral_DE_Blanc_2025_Sage_Femme_INFAS.docx\",\"sourcePage\":null}]}]}]}";
